INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kynoptic/wikipedia-reliable-sources/Reviewing content governance', 'community', 'kynoptic', 'wikipedia-reliable-sources', 'kynoptic/wikipedia-reliable-sources', 'Reviewing content governance', 0, 0, 60, '2026-03-08T01:57:15.551Z', '2026-03-08T02:11:30.025Z', 'bddea924fc393e509d8cb83d6667d1c6669318abe667793f4504d611e414f62d', '{"id":"kynoptic/wikipedia-reliable-sources/Reviewing content governance","name":"Reviewing content governance","description":{"en":"Reviewing content governance analyzes content against comprehensive HMS IT standards to ensure consistency and compliance, benefiting developers and content creators","zh":"内容治理审查是一种基于HMS IT综合治理框架的AIエージェント技能，用于审查内容的一致性、专业性、清晰性和合规性","ja":"コンテンツガバナンスレビューは、HMS ITの包括的なガバナンスフレームワークに基づくAIエージェントスキルであり、コンテンツのの一貫性、専門性、明確性、コンプライアンスをレビューする","ko":"콘텐츠 거버넌스 리뷰는 HMS IT의 포괄적인 거버넌스 프레임워크를 기반으로 하는 AI 도구 스킬로 콘텐츠의 일관성, 전문성, 명확성 및 규정 준수를 리뷰합니다","es":"Revisar la gobernanza de contenido es crucial para mantener la consistencia y profesionalismo en las comunicaciones. Esta habilidad analiza el contenido contra un marco de gobierno integral.","fr":"La révision de la gouvernance de contenu est essentielle pour maintenir la cohérence et le professionnalisme dans les communications. Cette compétence analyse le contenu par rapport à un cadre de gouvernance complet.","de":"Die Überprüfung der Content-Governance ist entscheidend, um die Konsistenz und Professionalität in den Kommunikationen aufrechtzuerhalten. Diese Fähigkeit analysiert den Inhalt anhand eines umfassenden Regierungsfrahmens.","pt":"Revisão de governança de conteúdo com base em padrões abrangentes de HMS IT, garantindo consistência e profissionalismo","ru":"Проверка управления контентом на основе всесторонних стандартов HMS IT, обеспечивающая согласованность и профессионализм","ar":"مراجعة حوكمة المحتوى بناءً على معايير شاملة لشركة HMS IT، مما يضمن الاتساق والمهنية"},"seo":{"title":{"en":"Reviewing Content Governance: Setup Guide for AI Agents","zh":"内容治理审查指南 - AIエージェント","ja":"コンテンツガバナンスレビュー設定ガイド - AIエージェント","ko":"콘텐츠 거버넌스 리뷰 설정 가이드 - AI 도구","es":"Guía de configuración para revisar la gobernanza de conte...","fr":"Guide de mise en place pour la révision de la gouvernance...","de":"Einrichtungsleitfaden für die Überprüfung der Content-Gov...","pt":"Guia de Configuração para Revisão de Governança de Conteú...","ru":"ИИ Агенты: Руководство по настройке проверки управления к...","ar":"دليل إعداد أدوات الذكاء الاصطناعي لمراجعة حوكمة المحتوى"},"description":{"en":"Discover how to implement content governance standards with Brave Search Goggles and HMS IT framework - get started with our expert guide and optimize your c...","zh":"了解如何使用AIエージェント审查内容治理，确保所有通信的一致性、专业性、清晰性和合规性","ja":"コンテンツガバナンスレビューのベストプラクティスを学び、すべてのコミュニケーションで一貫性、専門性、明確性、コンプライアンスを確保する","ko":"AI 도구를 사용하여 콘텐츠 거버넌스를 리뷰하고 모든 커뮤니케이션에서 일관성, 전문성, 명확성 및 규정 준수를 보장하는 방법을 알아보세요","es":"Aprenda a revisar la gobernanza de contenido con AI Agent y mejore la consistencia y profesionalismo en sus comunicaciones","fr":"Découvrez comment réviser la gouvernance de contenu avec Outil IA et améliorez la cohérence et le professionnalisme de vos communications","de":"Erfahren Sie, wie Sie die Content-Governance mit KI-Tool überprüfen und die Konsistenz und Professionalität in Ihren Kommunikationen verbessern","pt":"Aprenda a revisar a governança de conteúdo com nosso guia de configuração e melhore a consistência e a profissionalismo em suas comunicações","ru":"Узнайте, как проверить управление контентом с помощью нашего руководства по настройке и улучшите согласованность и профессионализм в ваших коммуникациях","ar":"تعرف على كيفية مراجعة حوكمة المحتوى باستخدام دليل الإعداد الخاص بنا و تحسين الاتساق والمهنية في تواصلك"},"definition":{"en":"Reviewing content governance is a process of evaluating content against predefined standards to ensure quality, clarity, and professionalism","zh":"内容治理审查是一种AIエージェント技能，用于审查和确保内容的一致性、专业性、清晰性和合规性","ja":"コンテンツガバナンスレビューは、コンテンツの一貫性、専門性、明確性、コンプライアンスをレビューおよび確保するAIエージェントスキル","ko":"콘텐츠 거버넌스 리뷰는 콘텐츠의 일관성, 전문성, 명확성 및 규정 준수를 리뷰 및 보장하는 AI 도구 스킬","es":"La revisión de la gobernanza de contenido es el proceso de analizar y evaluar el contenido para asegurarse de que cumpla con los estándares de gobierno de una organización","fr":"La révision de la gouvernance de contenu est le processus d''analyse et d''évaluation du contenu pour s''assurer qu''il répond aux normes de gouvernance d''une organisation","de":"Die Überprüfung der Content-Governance ist der Prozess der Analyse und Bewertung von Inhalten, um sicherzustellen, dass sie den Regierungsvorgaben einer Organisation entsprechen","pt":"Revisão de governança de conteúdo é o processo de análise de conteúdo contra padrões abrangentes para garantir consistência e profissionalismo","ru":"Проверка управления контентом - это процесс анализа контента на основе всесторонних стандартов для обеспечения согласованности и профессионализма","ar":"مراجعة حوكمة المحتوى هي عملية تحليل المحتوى مقابل معايير شاملة لضمان الاتساق والمهنية"},"features":{"en":["Analyzes content against HMS IT''s comprehensive governance framework","Ensures consistency, professionalism, clarity, and compliance across communications","Utilizes Brave Search Goggles for reranking search results based on source reliability","Requires access to files for review","Supports claude-code platform","Integrates with editorial and quality-assurance processes"],"zh":["基于HMS IT综合治理框架的内容审查","确保所有通信的一致性、专业性、清晰性和合规性","支持多种文件格式的审查","集成Claude代码平台","提供详细的审查报告和建议"],"ja":["HMS ITの包括的なガバナンスフレームワークに基づくコンテンツレビュー","すべてのコミュニケーションの一貫性、専門性、明確性、コンプライアンスを確保","多種類のファイル形式のレビューをサポート","Claudeコードプラットフォームとの統合","詳細なレビューレポートと提案を提供"],"ko":["HMS IT의 포괄적인 거버넌스 프레임워크를 기반으로 하는 콘텐츠 리뷰","모든 커뮤니케이션의 일관성, 전문성, 명확성 및 규정 준수를 보장","다양한 파일 형식의 리뷰를 지원","Claude 코드 플랫폼과의 통합","詳細한 리뷰 보고서와 제안을 제공"],"es":["Análisis de contenido contra un marco de gobierno integral","Verificación de la consistencia y profesionalismo en las comunicaciones","Comprobación de la claridad y la calidad del contenido","Integración con la comunidad de Wikipedia para determinar la fiabilidad de las fuentes","Compatibilidad con la plataforma Claude Code"],"fr":["Analyse de contenu par rapport à un cadre de gouvernance complet","Vérification de la cohérence et du professionnalisme dans les communications","Vérification de la clarté et de la qualité du contenu","Intégration avec la communauté Wikipedia pour déterminer la fiabilité des sources","Compatibilité avec la plateforme Claude Code"],"de":["Inhaltsanalyse anhand eines umfassenden Regierungsfrahmens","Überprüfung der Konsistenz und Professionalität in den Kommunikationen","Überprüfung der Klarheit und Qualität des Inhalts","Integration mit der Wikipedia-Community zur Bestimmung der Zuverlässigkeit von Quellen","Kompatibilität mit der Plattform Claude Code"],"pt":["Análise de conteúdo contra padrões abrangentes de HMS IT","Verificação de consistência e profissionalismo em todas as comunicações","Avaliação de clareza e conformidade com os padrões editoriais","Revisão de estilo e governança de conteúdo com base em diretrizes de qualidade","Integração com plataformas de código, como Claude Code"],"ru":["Анализ контента на основе всесторонних стандартов HMS IT","Проверка согласованности и профессионализма во всех коммуникациях","Оценка ясности и соответствия редакторским стандартам","Проверка стиля и управления контентом на основе руководств по качеству","Интеграция с платформами кода, такими как Claude Code"],"ar":["تحليل المحتوى مقابل معايير شاملة لشركة HMS IT","التحقق من الاتساق والمهنية في جميع التواصل","تقييم الوضوح والامتثال للمعاييرEditorial","مراجعة أسلوب وحوكمة المحتوى بناءً على إرشادات الجودة","التكامل مع منصات الكود، مثل Claude Code"]},"keywords":{"en":["how to use reviewing content governance","what is reviewing content governance","reviewing content governance alternative","reviewing content governance vs claude-code","reviewing content governance install","reviewing content governance setup guide","content governance standards","HMS IT framework","Brave Search Goggles"],"zh":["内容治理审查","AIエージェント","HMS IT","综合治理框架","一致性","专业性","清晰性","合规性","Claude代码"],"ja":["コンテンツガバナンスレビュー","AIエージェント","HMS IT","包括的なガバナンスフレームワーク","一貫性","専門性","明確性","コンプライアンス","Claudeコード"],"ko":["콘텐츠 거버넌스 리뷰","AI 도구","HMS IT","포괄적인 거버넌스 프레임워크","일관성","전문성","명확성","규정 준수","Claude 코드"],"es":["revisar gobernanza de contenido","AI Agent para contenido","gobernanza de contenido en Claude Code","análisis de contenido","consistencia y profesionalismo en comunicaciones","integración con Wikipedia","herramientas de IA para contenido","mejora de la calidad del contenido"],"fr":["réviser la gouvernance de contenu","Outil IA pour contenu","gouvernance de contenu sur Claude Code","analyse de contenu","cohérence et professionnalisme dans les communications","intégration avec Wikipedia","outils IA pour contenu","amélioration de la qualité du contenu"],"de":["Überprüfung der Content-Governance","KI-Tool für Inhalte","Content-Governance auf Claude Code","Inhaltsanalyse","Konsistenz und Professionalität in Kommunikationen","Integration mit Wikipedia","KI-Tools für Inhalte","Verbesserung der Inhaltsqualität"],"pt":["revisão de governança de conteúdo","ferramentas de IA para revisão de conteúdo","guia de configuração para revisão de conteúdo","padrões de HMS IT para governança de conteúdo","análise de conteúdo com Claude Code","revisão de estilo e governança de conteúdo","qualidade de conteúdo","consistência de conteúdo"],"ru":["проверка управления контентом","ИИ инструменты для проверки контента","руководство по настройке для проверки контента","стандарты HMS IT для управления контентом","анализ контента с Claude Code","проверка стиля и управления контентом","качество контента","согласованность контента"],"ar":["مراجعة حوكمة المحتوى","أدوات الذكاء الاصطناعي لمراجعة المحتوى","دليل إعداد لمراجعة المحتوى","معايير شركة HMS IT لحوكمة المحتوى","تحليل المحتوى مع Claude Code","مراجعة أسلوب وحوكمة المحتوى","جودة المحتوى","اتساق المحتوى"]}},"owner":"kynoptic","repo":"wikipedia-reliable-sources","repoPath":"kynoptic/wikipedia-reliable-sources","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.551Z","topics":[],"category":"community","skillMd":{"name":"Reviewing content governance","description":"Reviews content against HMS IT governance standards including style guide, word list, and platform-specific guidelines. Checks voice and tone, word usage, formatting, structure, and compliance with content type requirements. Use when reviewing emails, knowledge base articles, website pages, or documents for style consistency, or when users mention content review, style guide check, governance compliance, editorial standards, content quality, or editorial review.","bodyPreview":"<!--\n  status: beta\n  platforms: [\"claude-code\"]\n  requires: [\"access to files for review\"]\n  tags: [\"content\", \"governance\", \"review\", \"style-guide\", \"quality-assurance\", \"editorial\"]\n-->\n\n# Content Governance Review\n\nReviews content against comprehensive HMS IT content governance standards to ensure consistency, professionalism, clarity, and compliance across all communications.\n\n## Overview\n\nThis skill analyzes content against HMS IT''s comprehensive governance framework, which includes:\n\n- **","body":"<!--\n  status: beta\n  platforms: [\"claude-code\"]\n  requires: [\"access to files for review\"]\n  tags: [\"content\", \"governance\", \"review\", \"style-guide\", \"quality-assurance\", \"editorial\"]\n-->\n\n# Content Governance Review\n\nReviews content against comprehensive HMS IT content governance standards to ensure consistency, professionalism, clarity, and compliance across all communications.\n\n## Overview\n\nThis skill analyzes content against HMS IT''s comprehensive governance framework, which includes:\n\n- **Core style guide**: Voice and tone, clarity and conciseness, formatting standards\n- **Word list**: 300+ specific usage rules and terminology standards\n- **Email guidelines**: Broadcast email composition, subject lines, messaging architecture\n- **Knowledge base standards**: Article types, evergreen content rules, metadata requirements\n- **Website and internal communications**: Page guidelines, intranet standards, policy templates\n\nThe skill identifies issues across multiple dimensions, categorizes them by severity, and can automatically fix many common violations with user approval.\n\n## What you should do\n\nWhen invoked to review content:\n\n1. **Understand the request**:\n   - Determine review mode: Quick Scan (fast, critical only), Comprehensive (complete analysis), or Targeted (specific aspect)\n   - If not specified, infer from user''s language: \"quick check\" → Quick Scan, \"full review\" → Comprehensive, \"check word list\" → Targeted\n   - Identify content type: email, KB article, web page, internal doc, or general documentation\n\n2. **Read the content**:\n   - Use Read tool to load the file\n   - Note file path for content type clues (/emails/, /kb/, /web/)\n   - Scan for structural indicators (subject lines, article metadata, policy format)\n\n3. **Detect content type** (if not obvious):\n   - Check file path patterns\n   - Look for content structure clues (email salutations, KB article types, SharePoint templates)\n   - Use AskUserQuestion only if truly ambiguous after analysis\n\n4. **Consult governance standards**:\n   - Core standards: `REFERENCE.md` (style guide, word list)\n   - Email-specific: `REFERENCE-EMAIL.md` (subject lines, phishing prevention)\n   - KB-specific: `REFERENCE-KB.md` (evergreen content, article types)\n   - Web/Internal: `REFERENCE-WEB-INTERNAL.md` (page guidelines, intranet)\n\n5. **Perform review**:\n   - **Voice/Tone**: Professional voice, active voice, present tense, no rhetorical questions\n   - **Word Usage**: Check against 300+ word list entries, inclusive language, terminology\n   - **Formatting**: Sentence case headings, monospace for code, straight quotes, date/time format\n   - **Structure**: Paragraph length (≤6 sentences), heading quality, list formatting, parallel phrasing\n   - **Platform-Specific**: Apply email/KB/web rules based on content type\n   - Categorize each finding: Critical (affects meaning) → Important (consistency) → Minor (polish)\n   - Flag auto-fixable issues: word replacements, capitalization, formatting\n\n6. **Present findings**:\n   - Organize by category (Voice/Tone, Word Usage, Formatting, Structure, Platform-Specific)\n   - Within each category, order by severity (Critical → Important → Minor)\n   - For each issue, provide:\n     - Line number and context\n     - Clear explanation of violation\n     - Specific fix recommendation with example\n     - Auto-fixable indicator (Yes/No)\n   - Summarize: Total issues, breakdown by severity, auto-fixable count\n\n7. **Offer batch fixes** (if auto-fixable issues exist):\n   - List all proposed changes with before/after examples\n   - Group by type (word list, capitalization, formatting)\n   - Request single user approval for entire batch\n   - Use AskUserQuestion only for genuinely ambiguous fixes (multiple valid options, context-dependent choices)\n   - Apply approved fixes using Edit tool\n   - Report summary: \"Fixed 15 issues: 8 word list, 4 capitalization, 3 formatting\"\n\n8. **Handle manual fixes**:\n   - For voice/tone, complex rewrites, and context-dependent issues\n   - Provide guidance but don''t auto-fix\n   - Explain why manual review is needed\n\n**Reference files structure**:\n- `REFERENCE.md`: Core style guide and complete word list\n- `REFERENCE-EMAIL.md`: Broadcast email standards\n- `REFERENCE-KB.md`: Knowledge base article guidelines\n- `REFERENCE-WEB-INTERNAL.md`: Website and internal communications\n- `governance/`: Complete source files (38 files) for deep reference\n\n## When to Use This Skill\n\nUse this skill when you need to:\n\n- Review content before publication (emails, KB articles, web pages, documentation)\n- Ensure compliance with HMS IT governance standards\n- Check for style guide violations or inconsistencies\n- Validate word usage against the official word list\n- Perform quality assurance on communications\n- Get editorial feedback on drafts\n\n**Trigger phrases**: \"review this content\", \"check against style guide\", \"validate governance\", \"content quality check\", \"editorial review\", \"style compliance\"\n\n## Content Types Supported\n\nThe skill adapts its review criteria based on content type:\n\n1. **Broadcast emails**: Subject lines, messaging architecture, unplanned outage format\n2. **Knowledge base articles**: Article type validation, evergreen content, metadata\n3. **Website pages**: Page-specific guidelines, strategic initiative content\n4. **Internal communications**: Intranet/SharePoint, Teams, policy documents\n5. **General documentation**: Core style guide and word list compliance\n\n## Review Modes\n\nThe skill offers flexible review depth based on user needs:\n\n### Quick Scan\n- Focuses on critical issues only\n- Checks voice/tone problems, major word list violations, and serious formatting errors\n- Ideal for rapid quality checks before publication\n- Typical output: 5-15 high-priority findings\n\n### Comprehensive Review\n- Line-by-line analysis covering all governance standards\n- Identifies critical, important, and minor issues\n- Provides severity ratings and context for each finding\n- Typical output: 20-100+ findings depending on content length\n\n### Targeted Review\n- Focuses on user-specified areas (e.g., just word usage, just formatting)\n- Useful when specific concerns exist or time is limited\n- User can request focus on: Voice/Tone, Word Usage, Formatting, Structure, or Platform-Specific\n\n**Default behavior**: The skill automatically selects the appropriate review mode based on user request. For example:\n- \"Quick check\" → Quick Scan\n- \"Full review\" → Comprehensive Review\n- \"Check the word list\" → Targeted Review (Word Usage)\n\n## Workflow\n\n### 1. Content Ingestion\n- User provides file path or content to review\n- Skill reads and analyzes content structure\n\n### 2. Content Type Detection\n- Automatically detects content type from:\n  - File path patterns (e.g., `/emails/`, `/kb/`, `/web/`)\n  - Content structure (subject lines, article metadata)\n  - Explicit user specification\n\n### 3. Review Execution\n- Applies appropriate governance rules based on content type\n- Checks against multiple dimensions:\n  - **Voice and Tone**: Professional voice, appropriate formality, positive language\n  - **Word Usage**: Word list compliance, terminology accuracy, inclusive language\n  - **Formatting**: Capitalization, monospace/bold/italics usage, dates/times\n  - **Structure**: Paragraph length, heading quality, list formatting\n  - **Platform-Specific**: Email subject lines, KB article types, metadata\n\n### 4. Present Findings\nFindings are organized by:\n- **Category**: Voice/Tone, Word Usage, Formatting, Structure, Platform-Specific\n- **Severity**: Critical (affects meaning/professionalism) → Important (consistency) → Minor (polish)\n- **Location**: Line numbers and context\n- **Recommendation**: Specific fix suggestions with examples\n\n### 5. Batch Fix Capability\nAfter presenting findings, the skill offers to automatically fix issues:\n\n**Auto-fixable issues** (can be batched):\n- Word list replacements (e.g., \"PC\" → \"computer\", \"click\" → \"select\")\n- Capitalization corrections (sentence case in headings, proper acronym casing)\n- Formatting fixes (straight quotes instead of curly quotes, proper date/time format)\n- Simple structure improvements (Oxford comma insertion, spacing corrections)\n\n**Manual review required**:\n- Voice and tone adjustments (requires judgment and context)\n- Complex sentence rewrites (clarity, conciseness)\n- Content reorganization (paragraph restructuring, heading improvements)\n- Context-dependent word choices\n\n**Batch fix process**:\n1. Skill identifies all auto-fixable issues\n2. Presents complete list of proposed changes with before/after examples\n3. Requests single user approval for batch execution\n4. Applies all approved fixes\n5. Reports summary of changes made\n\n**When AskUserQuestion is used**:\nThe skill uses `AskUserQuestion` **only when ambiguity exists during the fix process**, such as:\n- Multiple valid fix options (e.g., \"either/or\" → \"either and or\" vs \"either...or\" vs rewording)\n- Context-dependent choices (e.g., when \"application\" might be appropriate vs \"app\")\n- Uncertain content type detection (e.g., could be both email and KB article)\n\nThe skill does **not** use `AskUserQuestion` for basic review scope selection if the user''s request is clear.\n\n## Finding Categories and Severity Levels\n\n### Voice and Tone\n**Critical**:\n- Humor or unprofessional language\n- Unnecessarily negative framing\n- Rhetorical questions instead of statements\n- Inappropriate use of \"please\" or \"thank you\" (implying optional steps)\n\n**Important**:\n- Passive voice where active is clearer\n- Future tense instead of present tense/imperative\n- Lack of empathy or unhelpful tone\n\n**Minor**:\n- Overly formal or stuffy phrasing\n- Opportunities to be more direct\n\n### Word Usage\n**Critical**:\n- Insensitive or non-inclusive terms (blacklist, master/slave, crazy, dummy)\n- Incorrect product names or major terminology errors\n- Jargon without definition\n\n**Important**:\n- Word list violations (PC, click, application vs app)\n- Inconsistent terminology\n- Latin abbreviations (e.g., i.e., etc.)\n\n**Minor**:\n- Unnecessary modifiers (absolutely, actually, basically)\n- Roundabout expressions that could be condensed\n- Minor redundancies\n\n### Formatting\n**Critical**:\n- Title case in headings instead of sentence case\n- Missing monospace for code, file paths, or commands\n- Incorrect bold/italics usage that affects meaning\n\n**Important**:\n- Curly quotes instead of straight quotes\n- Incorrect date/time format\n- Improper acronym capitalization (2fa vs 2FA, vpn vs VPN)\n\n**Minor**:\n- Inconsistent spacing\n- Missing Oxford commas\n- Minor punctuation issues\n\n### Structure\n**Critical**:\n- Vague or non-descriptive headings\n- Tables used for layout instead of tabular data\n- Missing heading structure in long content\n\n**Important**:\n- Paragraphs longer than 6 sentences\n- Lists where prose would be better (or vice versa)\n- Non-parallel phrasing in lists or headings\n\n**Minor**:\n- Introductory material could be shorter\n- Opportunities for better section breaks\n\n### Platform-Specific\n**Critical** (Email):\n- Vague or non-action-oriented subject line\n- Missing required elements (e.g., time zones in outage notifications)\n\n**Critical** (Knowledge Base):\n- Temporal/non-evergreen content (e.g., \"next month\", \"recently\")\n- Incorrect article type classification\n\n**Important**:\n- Missing metadata\n- Inconsistent template usage\n\n## Output Format Examples\n\n### Quick Scan Output\n```markdown\n## Content Governance Review: Quick Scan\n\n**Content Type**: Broadcast Email\n**Critical Issues Found**: 3\n**Auto-fixable**: 2\n\n### Critical Issues\n\n#### Voice and Tone (Line 12)\n**Issue**: Rhetorical question found\n**Current**: \"Wondering how to update your password? Follow these steps:\"\n**Fix**: \"These steps explain how to update your password:\"\n**Severity**: Critical - Violates professional voice standards\n\n#### Word Usage (Line 23)\n**Issue**: Non-inclusive term \"blacklist\"\n**Current**: \"Add the sender to your blacklist\"\n**Fix**: \"Add the sender to your blocklist\"\n**Severity**: Critical - Violates inclusive language standards\n**Auto-fixable**: Yes\n```\n\n### Comprehensive Review Output\n```markdown\n## Content Governance Review: Comprehensive\n\n**Content Type**: Knowledge Base Article\n**Total Issues Found**: 42\n**Critical**: 2 | **Important**: 15 | **Minor**: 25\n**Auto-fixable**: 28\n\n### Critical Issues (2)\n\n[Detailed findings with line numbers, context, recommendations]\n\n### Important Issues (15)\n\n[Organized by category: Voice/Tone (3), Word Usage (7), Formatting (3), Structure (2)]\n\n### Minor Issues (25)\n\n[Brief listing with line numbers and quick fixes]\n\n---\n\n**Batch Fix Available**: 28 issues can be automatically corrected.\nWould you like me to apply these fixes?\n```\n\n## Progressive Disclosure\n\nFor detailed reference on specific standards, consult:\n\n- **`REFERENCE.md`**: Core HMS IT style guide and word list (complete reference)\n- **`REFERENCE-EMAIL.md`**: Broadcast email-specific guidelines and templates\n- **`REFERENCE-KB.md`**: Knowledge base article standards and best practices\n- **`REFERENCE-WEB-INTERNAL.md`**: Website and internal communications guidelines\n- **`governance/`**: Complete source files organized by category\n\n## Usage examples\n\nFor detailed usage examples including:\n- Quick email review with auto-fixes\n- Comprehensive KB article review with severity breakdown\n- Targeted word list checks\n- Ambiguous fixes requiring clarification\n- Phishing pattern detection\n- Structure and formatting checks\n\nSee [`EXAMPLES.md`](EXAMPLES.md) for complete walkthroughs with before/after examples and expected outputs.\n\n## Best Practices\n\n1. **Start with Quick Scan**: For time-sensitive reviews, start with Quick Scan to catch critical issues\n2. **Comprehensive for publication**: Use Comprehensive Review before final publication\n3. **Targeted for specific concerns**: If you know the area of concern, request Targeted Review\n4. **Review auto-fixes**: Always review the batch fix list before approving\n5. **Manual fixes for voice/tone**: Accept that voice and tone improvements require manual review\n6. **Iterative improvement**: Use the skill multiple times as content evolves\n\n## Limitations\n\n- **Context limitations**: The skill cannot fully understand domain-specific context or strategic communication goals\n- **Judgment calls**: Some style decisions involve judgment that requires human expertise\n- **Content quality**: The skill checks compliance, not overall content quality, accuracy, or completeness\n- **Platform features**: Platform-specific features (like SharePoint metadata) may not be fully detectable from markdown\n- **Updates lag**: Governance updates must be manually incorporated into the skill\n\n## Technical Notes\n\n- **Line number accuracy**: Line numbers refer to the file as read; editing may shift subsequent line numbers\n- **Pattern matching**: Word list checking uses exact and contextual pattern matching\n- **Severity algorithm**: Severity is determined by impact on meaning, professionalism, and user experience\n- **Batch fix safety**: Only deterministic, safe fixes are included in batch operations"},"lastSynced":"2026-03-08T02:11:30.025Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents needing advanced content analysis capabilities for compliance and style-guide adherence.","zh":"非常适合需要高级内容分析能力以确保合规性和风格指南遵循的语言代理。","ja":"コンプライアンスとスタイルガイドの遵守のために高度なコンテンツ分析機能を必要とする言語エージェントに最適です。","ko":"규정 준수 및 스타일 가이드 준수를 위해 고급 콘텐츠 분석 기능이 필요한 언어 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Lenguaje que necesitan capacidades de análisis de contenido avanzadas para el cumplimiento y la adherencia a las guías de estilo.","fr":"Parfait pour les Agents de Langage ayant besoin de capacités d''analyse de contenu avancées pour la conformité et le respect des guides de style.","de":"Perfekt für Sprachagenten, die erweiterte Inhaltsanalysefunktionen für die Einhaltung und die Einhaltung von Stilrichtlinien benötigen.","pt":"Perfeito para Agentes de Linguagem que necessitam de capacidades avançadas de análise de conteúdo para conformidade e aderência ao guia de estilo.","ru":"Идеально подходит для языковых агентов, которым требуются расширенные возможности анализа контента для обеспечения соответствия нормативным требованиям и правилам стиля.","ar":"مثالي لوكلاء اللغة الذين يحتاجون إلى قدرات تحليل محتوى متقدمة للامتثال والالتزام بدليل الأسلوب."},"recommendation":{"en":"Empowers agents to review content against comprehensive HMS IT standards, ensuring consistency, professionalism, and compliance across communications, utilizing access to files for review and adhering to quality-assurance and editorial guidelines.","zh":"使代理能够根据全面的HMS IT标准审查内容，确保通信的一致性、专业性和合规性，利用对文件的访问权限进行审查，并遵循质量保证和编辑指南。","ja":"エージェントが包括的なHMS IT標準に基づいてコンテンツをレビューし、一貫性、専門性、コンプライアンスを通信全体で確保できるようにします。レビューのためのファイルへのアクセスを利用し、品質保証および編集ガイドラインに従います。","ko":"에이전트가 포괄적인 HMS IT 표준에 대해 콘텐츠를 검토하여 커뮤니케이션 전반에 걸쳐 일관성, 전문성 및 규정 준수를 보장하도록 지원합니다. 검토를 위한 파일 접근을 활용하고 품질 보증 및 편집 가이드라인을 준수합니다.","es":"Habilita a los agentes a revisar el contenido frente a los estándares IT de HMS integrales, garantizando la coherencia, la profesionalidad y el cumplimiento en las comunicaciones, utilizando el acceso a archivos para la revisión y ajustándose a las pautas de garantía de calidad y editoriales.","fr":"Permet aux agents de réviser le contenu par rapport aux normes IT de HMS complètes, garantissant la cohérence, la professionnalité et la conformité dans les communications, en utilisant l''accès aux fichiers pour la révision et en respectant les lignes directrices de l''assurance qualité et éditoriales.","de":"Ermächtigt die Agenten, den Inhalt gegen die umfassenden HMS-IT-Standards zu überprüfen, um Konsistenz, Professionalität und Einhaltung in der Kommunikation sicherzustellen, indem sie den Zugriff auf Dateien für die Überprüfung nutzen und den Qualitäts- und Redaktionsrichtlinien entsprechen.","pt":"Capacita os agentes a revisar o conteúdo em relação aos padrões abrangentes de TI da HMS, garantindo consistência, profissionalismo e conformidade nas comunicações, utilizando o acesso a arquivos para revisão e aderindo às diretrizes de garantia de qualidade e editoriais.","ru":"Позволяет агентам проверять контент на соответствие комплексным стандартам ИТ HMS, обеспечивая согласованность, профессионализм и соответствие коммуникациям, используя доступ к файлам для проверки и соблюдая правила обеспечения качества и редакционные guidelines.","ar":"يمكّن الوكلاء من مراجعة المحتوى مقابل معايير تكنولوجيا المعلومات الشاملة لـ HMS، مما يضمن الاتساق والاحترافية والامتثال عبر الاتصالات، باستخدام الوصول إلى الملفات للمراجعة والالتزام بإرشادات ضمان الجودة والتوجيهات التحريرية."},"useCases":{"en":["Validating content against HMS IT governance frameworks","Ensuring clarity and professionalism in communications","Automating content reviews for style-guide compliance"],"zh":["根据HMS IT治理框架验证内容","确保通信的清晰度和专业性","自动化内容审查以实现风格指南合规性"],"ja":["HMS ITガバナンスフレームワークに対するコンテンツの検証","コミュニケーションにおける明確さと専門性の確保","スタイルガイド準拠のためのコンテンツレビューの自動化"],"ko":["HMS IT 거버넌스 프레임워크에 대한 콘텐츠 검증","커뮤니케이션의 명확성과 전문성 보장","스타일 가이드 준수를 위한 콘텐츠 검토 자동화"],"es":["Validar el contenido frente a los marcos de gobernanza de IT de HMS","Garantizar la claridad y la profesionalidad en las comunicaciones","Automatizar las revisiones de contenido para el cumplimiento de las guías de estilo"],"fr":["Valider le contenu par rapport aux cadres de gouvernance IT de HMS","Assurer la clarté et la professionnalité dans les communications","Automatiser les révisions de contenu pour la conformité aux guides de style"],"de":["Inhalte gegen die IT-Governance-Frameworks von HMS validieren","Klarheit und Professionalität in der Kommunikation sicherstellen","Inhaltsüberprüfungen für die Einhaltung von Stilrichtlinien automatisieren"],"pt":["Validação de conteúdo em relação aos frameworks de governança de TI da HMS","Garantia de clareza e profissionalismo nas comunicações","Automatização de revisões de conteúdo para conformidade com o guia de estilo"],"ru":["Проверка контента на соответствие frameworks управления ИТ HMS","Обеспечение ясности и профессионализма в коммуникациях","Автоматизация проверок контента на соответствие правилам стиля"],"ar":["التحقق من صحة المحتوى مقابل أطر حوكمة تكنولوجيا المعلومات لـ HMS","ضمان الوضوح والاحترافية في الاتصالات","أتمتة مراجعات المحتوى للامتثال لدليل الأسلوب"]},"limitations":{"en":["Requires access to files for review","Limited to HMS IT content governance standards","Currently in beta status"],"zh":["需要访问文件以供审查","仅限于HMS IT内容治理标准","目前处于测试阶段"],"ja":["レビューのためのファイルへのアクセスが必要","HMS ITコンテンツガバナンス標準に限定","現在ベータ版ステータス"],"ko":["검토를 위한 파일 접근 필요","HMS IT 콘텐츠 거버넌스 표준으로 제한됨","현재 베타 상태"],"es":["Requiere acceso a archivos para la revisión","Limitado a los estándares de gobernanza de contenido de IT de HMS","Actualmente en estado beta"],"fr":["Nécessite un accès aux fichiers pour la révision","Limité aux normes de gouvernance de contenu IT de HMS","Actuellement en statut bêta"],"de":["Erfordert Zugriff auf Dateien für die Überprüfung","Begrenzt auf die Inhalts-Governance-Standards von HMS-IT","Derzeit im Beta-Status"],"pt":["Requer acesso a arquivos para revisão","Limitado aos padrões de governança de conteúdo de TI da HMS","Atualmente em status beta"],"ru":["Требуется доступ к файлам для проверки","Ограничено стандартами управления контентом ИТ HMS","В настоящее время находится в статусе бета"],"ar":["يتطلب الوصول إلى الملفات للمراجعة","يقتصر على معايير حوكمة محتوى تكنولوجيا المعلومات لـ HMS","حاليًا في حالة تجريبية (بيتا)"]},"version":4},"contentHash":"bddea924fc393e509d8cb83d6667d1c6669318abe667793f4504d611e414f62d","qualityScore":60}');
