INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bybren-llc/safe-agentic-workflow/linear-sop', 'linear-sop', 'bybren-llc', 'safe-agentic-workflow', 'community', 'linear-sop bybren-llc safe-agentic-workflow community The linear-sop skill provides a production-validated SAFe multi-agent development methodology for AI agents, offering a complete whitepaper and working template. It benefits developers working with Linear issues and evidence policies. Linear SOP Skill是一种生产验证的SAFe多代理开发方法，包括Claude Code和11个角色。它提供了完整的白皮书和工作模板，用于指导一致的Linear票务管理 Linear SOP Skillは、SAFeマルチエージェント開発方法の一種で、Claude Codeと11の役割を含みます。完全な白書と作業テンプレートを提供し、一貫したLinearチケット管理を支援します Linear SOP Skill은 SAFe 멀티 에이전트 개발 방법 중 하나로, Claude Code와 11개의 역할을 포함합니다. 완전한 백서와 작업 템플릿을 제공하며, 일관된 Linear 티켓 관리를 지원합니다 linear-sop es una metodología de desarrollo de agentes múltiples validada para la producción con Claude Code, que proporciona plantillas de evidencia para la política de evidencia dev/staging/UAT linear-sop est une méthodologie de développement d''agents multiples validée pour la production avec Claude Code, qui fournit des modèles de preuve pour la politique de preuve dev/staging/UAT linear-sop ist eine für die Produktion validierte Mehragenten-Entwicklungsmethodik mit Claude Code, die Beweisvorlagen für die dev/staging/UAT-Beweispolitik bereitstellt O linear-sop é uma metodologia de desenvolvimento de agentes multi-IA validada para produção, que proporciona um guia para gerenciar tickets de forma consistente Linear-sop - это производственно-проверенная методология разработки многоагентных ИИ систем, обеспечивающая руководство для последовательного управления тикетами linear-sop هو منهجية تطوير وكلاء ذكاء اصطناعي متعددة تم التحقق منها للإنتاج، يوفر إرشادات لإدارة التذاكر بانتظام how to use linear-sop linear-sop setup guide SAFe multi-agent development methodology Linear ticket management linear-sop alternative linear-sop vs Gemini CLI what is linear-sop linear-sop install linear-sop for AI agents Linear SOP SAFe多代理开发 AI Tools Claude Code Linear票务管理 UUID解析 Gemini CLI Linear Web UI Provides a complete whitepaper for SAFe multi-agent development methodology Includes a working template for Linear ticket management Supports evidence templates for dev/staging/UAT policy Enables parsing of acceptance criteria and working with UUIDs and issue IDs Guides consistent Linear ticket management using the Linear web UI or CLI linear-sop is a SAFe multi-agent development methodology that treats AI agents as specialized team members, providing a structured approach to Linear ticket management and evidence policy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('amano--/call-center/burp-suite', 'community', 'amano--', 'call-center', 'amano--/call-center', 'burp-suite', 0, 0, 60, '2026-03-08T01:57:15.570Z', '2026-03-08T02:11:45.582Z', 'b02a04fc7cffc37f56eb93367954beb65f10b18d1693ecff3ae8aa59034e3344', '{"id":"amano--/call-center/burp-suite","name":"burp-suite","description":{"en":"Burp Suite Professional is an HTTP interception proxy that allows developers to view and manipulate HTTP requests and responses, ideal for security testing and web application analysis.","zh":"Burp Suite Professional 是一个 HTTP 拦截代理，具有多种安全测试功能。它允许你查看和操作 HTTP 请求和响应","ja":"Burp Suite Professional は、HTTP 拦截代理と多数のセキュリティテスト機能を備えたツールです。クライアントとサーバー間の HTTP リクエストとレスポンスを表示、操作できます","ko":"Burp Suite Professional은 HTTP 인터셉트 프록시와 다양한 보안 테스트 기능을 제공하는 도구입니다. 클라이언트와 서버 간의 HTTP 요청과 응답을 표시하고 조작할 수 있습니다","es":"Burp Suite es una herramienta de proxy de interceptación HTTP para pruebas de seguridad web que permite manipular solicitudes y respuestas","fr":"Burp Suite est un outil de proxy d''interception HTTP pour les tests de sécurité web qui permet de manipuler les requêtes et les réponses","de":"Burp Suite ist ein HTTP-Intercept-Proxy-Tool für Web-Sicherheitstests, das die Manipulation von Anfragen und Antworten ermöglicht","pt":"O Burp Suite é uma ferramenta de teste de segurança que permite interceptar e manipular requisições e respostas HTTP, ideal para testar aplicações web","ru":"Burp Suite Professional - это инструмент для тестирования безопасности, который позволяет перехватывать и манипулировать запросами и ответами HTTP, идеально подходящий для тестирования веб-приложений","ar":"أداة Burp Suite هي أداة لاختبار الأمن التي تمكن من اعتراض و تعديل الطلبات والاستجابات لبروتوكول HTTP، مثالية لاختبار التطبيقات الويب"},"seo":{"title":{"en":"Burp Suite: HTTP Interception Proxy Setup Guide | AI Agen...","zh":"B