INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('amano--/call-center/burp-suite', 'burp-suite', 'amano--', 'call-center', 'community', 'burp-suite amano-- call-center community Burp Suite Professional is an HTTP interception proxy that allows developers to view and manipulate HTTP requests and responses, ideal for security testing and web application analysis. Burp Suite Professional 是一个 HTTP 拦截代理，具有多种安全测试功能。它允许你查看和操作 HTTP 请求和响应 Burp Suite Professional は、HTTP 拦截代理と多数のセキュリティテスト機能を備えたツールです。クライアントとサーバー間の HTTP リクエストとレスポンスを表示、操作できます Burp Suite Professional은 HTTP 인터셉트 프록시와 다양한 보안 테스트 기능을 제공하는 도구입니다. 클라이언트와 서버 간의 HTTP 요청과 응답을 표시하고 조작할 수 있습니다 Burp Suite es una herramienta de proxy de interceptación HTTP para pruebas de seguridad web que permite manipular solicitudes y respuestas Burp Suite est un outil de proxy d''interception HTTP pour les tests de sécurité web qui permet de manipuler les requêtes et les réponses Burp Suite ist ein HTTP-Intercept-Proxy-Tool für Web-Sicherheitstests, das die Manipulation von Anfragen und Antworten ermöglicht O Burp Suite é uma ferramenta de teste de segurança que permite interceptar e manipular requisições e respostas HTTP, ideal para testar aplicações web Burp Suite Professional - это инструмент для тестирования безопасности, который позволяет перехватывать и манипулировать запросами и ответами HTTP, идеально подходящий для тестирования веб-приложений أداة Burp Suite هي أداة لاختبار الأمن التي تمكن من اعتراض و تعديل الطلبات والاستجابات لبروتوكول HTTP، مثالية لاختبار التطبيقات الويب how to use burp-suite burp-suite alternative burp-suite setup guide what is burp-suite burp-suite vs zap burp-suite professional install http interception proxy web application security testing burp-suite tutorial Burp Suite Professional HTTP 拦截代理 安全测试 Web 应用安全 AIエージェント 网络安全 Handles parallel requests for efficient testing Provides interactive tools for formulating and testing hypotheses Allows viewing and manipulation of HTTP requests and responses Enables security testing of web applications Supports analysis of web application behavior burp-suite is an HTTP interception proxy with numerous security testing features, enabling developers to test and analyze web application behavior');
