INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('asheshgoplani/agent-deck/session-share', 'session-share', 'asheshgoplani', 'agent-deck', 'community', 'session-share asheshgoplani agent-deck community session-share is a terminal session manager for AI coding agents, enabling developers to share sessions between Claude, Gemini, OpenCode, Codex, and more through portable file export and import. Session Share 是一个终端会话管理器，允许开发人员共享 Claude Code 会话。它支持多个 AI 编码代理，包括 Claude、Gemini、OpenCode 和 Codex。 Session Share は、開発者が Claude Code セッションを共有できるターミナルセッションマネージャーです。Claude、Gemini、OpenCode、Codex など、複数の AI コーディングエージェントをサポートしています。 Session Share는 개발자가 Claude Code 세션을 공유할 수 있는 터미널 세션 매니저입니다. Claude, Gemini, OpenCode, Codex 등 여러 개의 AI 코딩 에이전트를 지원합니다. Session-share es un administrador de sesiones de terminal para agentes de codificación de IA, permitiendo la compartición de sesiones entre desarrolladores Session-share est un gestionnaire de sessions de terminal pour les agents de codage IA, permettant le partage de sessions entre les développeurs Session-share ist ein Terminal-Sitzungs-Manager für KI-Coding-Agents, der die Freigabe von Sitzungen zwischen Entwicklern ermöglicht O Session Share é uma ferramenta de gerenciamento de sessões de terminal para agentes de codificação de IA, permitindo a exportação e importação de arquivos de sessão portáteis. Session Share - это терминальный менеджер сессий для ИИ агентов, позволяющий экспортировать и импортировать портативные файлы сессий. Session Share هو مدير جلسات طرفية لأدوات الكود الإي إيه، يسمح بالتصدير والاستيراد الملفات الجلسات المحمولة. how to use session-share session-share alternative session-share setup guide what is session-share session-share vs terminal multiplexers install session-share session-share for AI coding agents session-share and Claude Code session-share file export and import AI 编码代理 终端会话管理器 Session Share Claude Code AI 编码工具 会话共享 脚本路径解析 本地文件存储 Enables portable file export and import for shared coding sessions Supports multiple AI coding agents, including Claude, Gemini, OpenCode, and Codex Includes helper scripts in the scripts/ subdirectory for easy setup Provides a base directory path for script path resolution Allows files to be shared without uploading to the cloud unless chosen session-share is a terminal session manager that allows developers to share coding sessions between AI agents through file export and import.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('github/gh-aw-firewall/awf-debug-tools', 'community', 'github', 'gh-aw-firewall', 'github/gh-aw-firewall', 'awf-debug-tools', 0, 0, 60, '2026-03-08T01:57:15.579Z', '2026-03-08T02:11:50.617Z', '6345e65eb095068da09550737a80249d531504de915d4f38ddfb19ae13c31bd8', '{"id":"github/gh-aw-firewall/awf-debug-tools","name":"awf-debug-tools","description":{"en":"awf-debug-tools is a collection of Python scripts that help agents efficiently debug and operate the awf firewall, reducing verbose output and providing insights instead of raw data dumps.","zh":"AWF Debug Tools 是一套实用 Python 脚本，帮助 AI エージェント高效调试和操作 awf 防火墙","ja":"AWF Debug Tools は、AIエージェントが awf ファイアウォールを効率的にデバッグおよび操作できるように設計された Python スクリプトのコレクションです","ko":"AWF Debug Tools는 효율적인 디버깅과 작동을 위한 Python 스크립트 모음입니다","es":"AWF Debug Tools es una colección de scripts Python prácticos que ayudan a los agentes a depurar y operar el firewall AWF de manera eficiente.","fr":"AWF Debug Tools est une collection de scripts Python pratiques qui aident les agents à déboguer et à exploiter le pare-feu AWF de manière efficace.","de":"AWF-Debug-Tools ist eine Sammlung von praktischen Python-Skripten, die es Agents ermöglichen, den AWF-Firewall effizient zu debuggen und zu betreiben.","pt":"AWF Debug Tools é uma coleção de scripts Python práticos que ajudam agentes a depurar e operar o firewall AWF de forma eficiente","ru":"AWF Debug Tools - это коллекция практических скриптов Python, помогающих агентам эффективно отлаживать и эксплуатировать брандмауэр AWF","ar":"أدوات فحص AWF هي مجموعة من البرامج النصية Python العملية التي تساعد الوكلاء على فحص و تشغيل جدار الحماية AWF بفعالية"},"seo":{"title":{"en":"awf-debug-tools: Efficient Debugging for AI Agents | AI A...","zh":"AWF Debug Tools 设置指南 - Python 脚本高效调试","ja":"AWF Debug Tools のベストプラクティス - Docker ログ出力を最適化","ko":"AWF Debug Tools 사용자 가이드 - 파이썬 스크립트로 효율적인 디버깅","es":"Herramientas de depuración AWF: Guía de configuración par...","fr":"Outils de débogage AWF : Guide d''installation pour les ag...","de":"AWF-Debug-Tools: Einrichtungsleitfaden für KI-Agents","pt":"AWF Debug Tools: Guia de Configuração para Desenvolvedores","ru":"ИИ Агенты: AWF Debug Tools - Руководство по Настройке","ar":"أدوات فحص AWF: دليل الإعداد للبرمجة"},"description":{"en":"Streamline your debugging process with awf-debug-tools, reducing Docker/log output by 80%+ and providing actionable insights - learn how to get started today!","zh":"AWF Debug Tools 提供实用 Python 脚本，帮助 AI エージェント高效调试和操作 awf 防火墙，减少 80%+ 的 Docker 日志输出","ja":"AWF Debug Tools は、AIエージェントが awf ファイアウォールを効率的にデバッグおよび操作できるように設計された Python スクリプトのコレクションです","ko":"AWF Debug Tools는 효율적인 디버깅과 작동을 위한 Python 스크립트 모음으로, Docker 로그 출력을 80% 이상 감소시킵니다","es":"Optimice el rendimiento de los agentes de AI con herramientas de depuración AWF, reduciendo la salida verbose de Docker y log por 80%+.","fr":"Améliorez les performances des agents d''IA avec les outils de débogage AWF, en réduisant la sortie verbose de Docker et du journal de 80%+.","de":"Optimieren Sie die Leistung von KI-Agents mit AWF-Debug-Tools, indem Sie die verbose-Ausgabe von Docker und Log um 80%+ reduzieren.","pt":"Descubra como os scripts Python da AWF Debug Tools reduzem a saída verbose do Docker e fornecem insights ação para diagnósticos eficientes","ru":"Узнайте, как скрипты Python AWF Debug Tools снижают громоздкий вывод Docker и предоставляют действенные идеи для эффективной диагностики","ar":"اكتشف كيف تخفض أدوات فحص AWF الناتج الغير ضروري من Docker وتوفر رؤى مُفعمة بالافعال لتشخيص فعال"},"definition":{"en":"awf-debug-tools is a set of practical Python scripts designed to simplify the debugging process of the awf firewall, reducing manual commands and noisy output.","zh":"AWF Debug Tools 是一套帮助 AI エージェント高效调试和操作 awf 防火墙的 Python 脚本","ja":"AWF Debug Tools は、AIエージェントが awf ファイアウォールを効率的にデバッグおよび操作できるように設計された Python スクリプトのコレクション","ko":"AWF Debug Tools는 효율적인 디버깅과 작동을 위한 Python 스크립트 모음","es":"AWF Debug Tools es un conjunto de scripts que simplifican la depuración del firewall AWF para agentes de AI.","fr":"AWF Debug Tools est un ensemble de scripts qui simplifient le débogage du pare-feu AWF pour les agents d''IA.","de":"AWF-Debug-Tools ist ein Satz von Skripten, die die Fehlersuche im AWF-Firewall für KI-Agents vereinfachen.","pt":"AWF Debug Tools é um conjunto de ferramentas de depuração para o firewall AWF, baseado em scripts Python","ru":"AWF Debug Tools - это набор инструментов для отладки брандмауэра AWF, основанный на скриптах Python","ar":"أدوات فحص AWF هي مجموعة من أدوات الفحص لجدار الحماية AWF، مبنية على البرامج النصية Python"},"features":{"en":["Reduces verbose Docker/log output by 80%+","Provides actionable insights instead of raw data dumps","Replaces 5-10 manual commands with a single script","Simplifies diagnosing issues with the awf firewall","Supports efficient operation of the awf firewall"],"zh":["减少 80%+ 的 Docker 日志输出","提供实用 Python 脚本","高效调试和操作 awf 防火墙","替代 5-10 个手动命令","提供可行的见解"],"ja":["Docker ログ出力を 80% 以上削減","実用 Python スクリプトを提供","awf ファイアウォールの効率的なデバッグおよび操作","5-10 個の手動コマンドを置き換える","実行可能な洞察を提供"],"ko":["Docker 로그 출력을 80% 이상 감소","실용적 Python 스크립트를 제공","효율적인 디버깅과 작동","5-10개의 수동 명령어를 대체","실행 가능한 통찰력을 제공"],"es":["Reducción de la salida verbose de Docker y log por 80%+","Reemplazo de 5-10 comandos manuales con un solo script","Proporciona información acciónnable en lugar de volcados de datos brutos","Mejora la eficiencia de los agentes de AI","Scripts prácticos escritos en Python"],"fr":["Réduction de la sortie verbose de Docker et du journal de 80%+","Remplacement de 5-10 commandes manuelles par un seul script","Fournit des informations actionnables au lieu de dumps de données brutes","Améliore l''efficacité des agents d''IA","Scripts pratiques écrits en Python"],"de":["Reduzierung der verbose-Ausgabe von Docker und Log um 80%+","Ersetzen von 5-10 manuellen Befehlen durch ein einzelnes Skript","Bietet handhabbare Informationen anstelle von Rohdatendumps","Verbesserung der Effizienz von KI-Agents","Praktische Skripte in Python"],"pt":["Reduz a saída verbose do Docker em 80%+","Fornecem insights ação para diagnósticos eficientes","Substituem 5-10 comandos manuais com um único script","São baseados em scripts Python","São projetados para agentes de IA","Melhoram a eficiência do diagnóstico"],"ru":["Снижают громоздкий вывод Docker на 80%+","Предоставляют действенные идеи для эффективной диагностики","Заменяют 5-10 ручных команд одним скриптом","Основаны на скриптах Python","Разработаны для ИИ агентов","Улучшают эффективность диагностики"],"ar":["تخفض الناتج الغير ضروري من Docker بنسبة 80%+","توفر رؤى مُفعمة بالافعال لتشخيص فعال","تحل محل 5-10 أوامر يدوية ببرنامج نصي واحد","مبنية على البرامج النصية Python","مصممة للوكلاء الذكية","تحسن كفاءة التشخيص"]},"keywords":{"en":["how to use awf-debug-tools","awf-debug-tools setup guide","awf-debug-tools alternative","awf-debug-tools vs traditional debugging methods","awf-debug-tools install","what is awf-debug-tools","awf-debug-tools for AI agents","efficient debugging with awf-debug-tools","awf-debug-tools tutorial"],"zh":["AWF Debug Tools","Python 脚本","AI エージェント","awf 防火墙","Docker 日志输出","高效调试","实用工具"],"ja":["AWF Debug Tools","Python スクリプト","AIエージェント","awf ファイアウォール","Docker ログ出力","効率的なデバッグ","実用ツール"],"ko":["AWF Debug Tools","Python 스크립트","AI 에이전트","awf 방화벽","Docker 로그 출력","효율적인 디버깅","실용 도구"],"es":["herramientas de depuración AWF","agentes de AI","Python","Docker","firewall AWF","depuración de firewall","optimización de rendimiento","reducción de salida verbose"],"fr":["outils de débogage AWF","agents d''IA","Python","Docker","pare-feu AWF","débogage de pare-feu","optimisation des performances","réduction de la sortie verbose"],"de":["AWF-Debug-Tools","KI-Agents","Python","Docker","AWF-Firewall","Fehlersuche im Firewall","Leistungsoptimierung","Reduzierung der verbose-Ausgabe"],"pt":["AWF Debug Tools","ferramentas de depuração","scripts Python","Docker","firewall AWF","agentes de IA","desenvolvedores","programação","depuração","diagnóstico"],"ru":["AWF Debug Tools","инструменты отладки","скрипты Python","Docker","брандмауэр AWF","ИИ агенты","разработчики","программирование","отладка","диагностика"],"ar":["أدوات فحص AWF","أدوات الفحص","البرامج النصية Python","Docker","جدار الحماية AWF","الوكلاء الذكية","المبرمجين","البرمجة","الفحص","التشخيص"]}},"owner":"github","repo":"gh-aw-firewall","repoPath":"github/gh-aw-firewall","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.579Z","topics":[],"category":"community","skillMd":{"name":"awf-debug-tools","description":"Practical Python scripts for debugging awf - parse logs, diagnose issues, inspect containers, test domains","bodyPreview":"# AWF Debug Tools\n\nA collection of practical Python scripts that help agents efficiently debug and operate the awf firewall. These scripts reduce verbose Docker/log output by 80%+ and provide actionable insights instead of raw data dumps.\n\n## Why These Scripts?\n\n**Problem:** Docker commands and log files are verbose and hard for agents to parse. Diagnosing issues requires 10+ manual commands and produces noisy output that wastes tokens.\n\n**Solution:** One script replaces 5-10 manual commands wit","body":"# AWF Debug Tools\n\nA collection of practical Python scripts that help agents efficiently debug and operate the awf firewall. These scripts reduce verbose Docker/log output by 80%+ and provide actionable insights instead of raw data dumps.\n\n## Why These Scripts?\n\n**Problem:** Docker commands and log files are verbose and hard for agents to parse. Diagnosing issues requires 10+ manual commands and produces noisy output that wastes tokens.\n\n**Solution:** One script replaces 5-10 manual commands with clean, filtered output optimized for agent consumption. All scripts support JSON format for easy parsing.\n\n## Available Scripts\n\nAll scripts are located in `.claude/skills/awf-debug-tools/scripts/`:\n\n1. **parse-squid-logs.py** - Parse Squid logs and extract blocked domains with counts\n2. **diagnose-awf.py** - Run automated diagnostic checks on container health and configuration\n3. **inspect-containers.py** - Show concise container status without verbose docker output\n4. **test-domain.py** - Test if specific domain is reachable through the firewall\n\n## Quick Start\n\n### Parse Logs to Find Blocked Domains\n\n```bash\n# Auto-discover logs and show all domains\npython .claude/skills/awf-debug-tools/scripts/parse-squid-logs.py\n\n# Show only blocked domains\npython .claude/skills/awf-debug-tools/scripts/parse-squid-logs.py --blocked-only\n\n# Filter by domain\npython .claude/skills/awf-debug-tools/scripts/parse-squid-logs.py --domain github.com\n\n# Show top 10, JSON output\npython .claude/skills/awf-debug-tools/scripts/parse-squid-logs.py --top 10 --format json\n```\n\n### Run Automated Diagnostics\n\n```bash\n# Quick health check\npython .claude/skills/awf-debug-tools/scripts/diagnose-awf.py\n\n# Detailed output\npython .claude/skills/awf-debug-tools/scripts/diagnose-awf.py --verbose\n\n# JSON output for agent parsing\npython .claude/skills/awf-debug-tools/scripts/diagnose-awf.py --format json\n```\n\n### Inspect Container Status\n\n```bash\n# Inspect all containers\npython .claude/skills/awf-debug-tools/scripts/inspect-containers.py\n\n# Specific container only\npython .claude/skills/awf-debug-tools/scripts/inspect-containers.py --container awf-squid\n\n# Show only logs\npython .claude/skills/awf-debug-tools/scripts/inspect-containers.py --logs-only\n\n# JSON output\npython .claude/skills/awf-debug-tools/scripts/inspect-containers.py --format json\n```\n\n### Test Domain Reachability\n\n```bash\n# Test if domain is allowed\npython .claude/skills/awf-debug-tools/scripts/test-domain.py github.com\n\n# Test blocked domain with fix suggestion\npython .claude/skills/awf-debug-tools/scripts/test-domain.py npmjs.org --suggest-fix\n\n# Check allowlist only (no log lookup)\npython .claude/skills/awf-debug-tools/scripts/test-domain.py api.github.com --check-allowlist\n\n# JSON output\npython .claude/skills/awf-debug-tools/scripts/test-domain.py github.com --format json\n```\n\n## Common Workflows\n\n### Workflow 1: Debugging Blocked Requests\n\nWhen a command fails due to blocked domain:\n\n```bash\n# 1. Run diagnostics to check overall health\npython .claude/skills/awf-debug-tools/scripts/diagnose-awf.py\n\n# 2. Parse logs to find which domains were blocked\npython .claude/skills/awf-debug-tools/scripts/parse-squid-logs.py --blocked-only\n\n# 3. Test specific domain and get fix suggestion\npython .claude/skills/awf-debug-tools/scripts/test-domain.py npmjs.org --suggest-fix\n\n# 4. Apply the suggested fix\nsudo awf --allow-domains github.com,npmjs.org ''your-command''\n```\n\n### Workflow 2: Container Health Check\n\nWhen containers aren''t starting or behaving unexpectedly:\n\n```bash\n# 1. Check container status and recent logs\npython .claude/skills/awf-debug-tools/scripts/inspect-containers.py\n\n# 2. Run full diagnostics\npython .claude/skills/awf-debug-tools/scripts/diagnose-awf.py --verbose\n\n# 3. If issues found, check Squid logs for errors\npython .claude/skills/awf-debug-tools/scripts/parse-squid-logs.py\n```\n\n### Workflow 3: Agent Automated Debugging\n\nFor agents to diagnose issues without human intervention:\n\n```bash\n# Run all checks with JSON output\npython .claude/skills/awf-debug-tools/scripts/diagnose-awf.py --format json | jq .\n\n# Parse blocked domains\npython .claude/skills/awf-debug-tools/scripts/parse-squid-logs.py --blocked-only --format json | jq .\n\n# Test each blocked domain\npython .claude/skills/awf-debug-tools/scripts/test-domain.py npmjs.org --format json | jq .\n```\n\n## Output Formats\n\nAll scripts support two output formats:\n\n- **table/text** (default): Human-readable format with clear sections and alignment\n- **json**: Machine-readable format optimized for agent parsing\n\nUse `--format json` to get structured output that''s easy to parse programmatically.\n\n## Exit Codes\n\nAll scripts use consistent exit codes:\n\n- **0**: Success (no issues found, domain allowed, etc.)\n- **1**: Issues found (blocked domains, failed checks, domain blocked)\n- **2**: Error (missing logs, invalid arguments, etc.)\n\n## No Dependencies\n\nAll scripts use Python 3.8+ stdlib only. No `pip install` required. They work out of the box on any system with Python 3.8+.\n\n## Script Reference\n\n### parse-squid-logs.py\n\n**Purpose:** Extract blocked domains from Squid logs with counts and statistics.\n\n**Key Options:**\n- `--blocked-only` - Show only blocked domains\n- `--domain DOMAIN` - Filter by specific domain\n- `--top N` - Show top N domains by request count\n- `--format {table,json}` - Output format\n\n**Auto-discovers logs** from running containers, preserved logs, or work directories.\n\n### diagnose-awf.py\n\n**Purpose:** Run automated diagnostic checks and report issues with fixes.\n\n**Checks:**\n- Container status (running/stopped/missing)\n- Container health (Squid healthcheck)\n- Network connectivity (Squid reachable from agent)\n- DNS configuration\n- Squid config validation\n- Common issues (port conflicts, orphaned containers)\n\n**Key Options:**\n- `--verbose` - Show detailed check output\n- `--format {text,json}` - Output format\n\n### inspect-containers.py\n\n**Purpose:** Show concise container status without verbose docker output.\n\n**Shows:**\n- Container status and exit codes\n- IP addresses and network info\n- Health check status\n- Top 5 processes\n- Recent logs (last 5 lines)\n\n**Key Options:**\n- `--container NAME` - Inspect specific container only\n- `--logs-only` - Show only recent logs\n- `--tail N` - Number of log lines (default: 5)\n- `--format {text,json}` - Output format\n\n### test-domain.py\n\n**Purpose:** Test if domain is reachable through the firewall.\n\n**Checks:**\n- If domain is in Squid allowlist\n- If domain appears in recent Squid logs\n- Whether requests were allowed or blocked\n\n**Key Options:**\n- `--check-allowlist` - Only check allowlist, don''t check logs\n- `--suggest-fix` - Show suggested --allow-domains flag\n- `--format {text,json}` - Output format\n\n## Integration with Existing Skills\n\n- For manual debugging commands, see the `debug-firewall` skill\n- For MCP Gateway integration, see the `awf-mcp-gateway` skill\n- For general troubleshooting, see `docs/troubleshooting.md`\n\n## Performance\n\nAll scripts are designed for fast execution:\n\n- `parse-squid-logs.py`: <2 seconds for typical log files\n- `diagnose-awf.py`: <3 seconds for all checks\n- `inspect-containers.py`: <2 seconds for both containers\n- `test-domain.py`: <1 second for domain check\n\n## Examples\n\n### Example 1: Find Blocked Domains\n\n```bash\n$ python .claude/skills/awf-debug-tools/scripts/parse-squid-logs.py --blocked-only\n\nBlocked Domains (sorted by count):\n\n  Domain                  Blocked  Allowed  Total\n  =================================================\n  registry.npmjs.org      45       0        45\n  example.com             12       0        12\n\nTotal requests: 1234\nBlocked: 57 (4.6%)\nAllowed: 1177 (95.4%)\n```\n\n### Example 2: Diagnose Issues\n\n```bash\n$ python .claude/skills/awf-debug-tools/scripts/diagnose-awf.py\n\nAWF Diagnostic Report\n========================================\n[✓] Containers: awf-squid (running), awf-agent (exited:0)\n[✓] Health: Squid healthy\n[✓] Network: awf-net exists ([{Subnet:172.30.0.0/24 Gateway:172.30.0.1}])\n[✓] Connectivity: Squid reachable on 172.30.0.10:3128\n[✓] DNS: DNS servers: 127.0.0.11, 8.8.8.8, 8.8.4.4\n[✓] Config: 3 domains in allowlist (github.com, .github.com, api.github.com)\n\nSummary: All checks passed ✓\n```\n\n### Example 3: Test Domain\n\n```bash\n$ python .claude/skills/awf-debug-tools/scripts/test-domain.py npmjs.org --suggest-fix\n\nTesting: npmjs.org\n\n[✗] Allowlist check: Not in allowlist\n[✗] Reachability: Blocked (403 TCP_DENIED:HIER_NONE)\n[✗] Status: BLOCKED\n\nSuggested fix:\n  awf --allow-domains github.com,npmjs.org ''your-command''\n```\n\n## Tips for Agents\n\n1. **Use JSON output** for easy parsing: `--format json | jq .`\n2. **Chain commands** to get complete picture: diagnose → parse logs → test domain\n3. **Check exit codes** to determine if action needed (0 = ok, 1 = issues)\n4. **Use --suggest-fix** to get ready-to-use awf commands\n5. **Scripts auto-discover logs** - no need to specify paths in most cases\n\n## Troubleshooting\n\n**Script not found:**\n```bash\n# Use absolute path\npython /home/mossaka/developer/gh-aw-repos/gh-aw-firewall/.claude/skills/awf-debug-tools/scripts/parse-squid-logs.py\n```\n\n**Permission denied on logs:**\n```bash\n# Squid logs require sudo to read\nsudo python .claude/skills/awf-debug-tools/scripts/parse-squid-logs.py --log-file /tmp/squid-logs-*/access.log\n```\n\n**No logs found:**\n```bash\n# Run awf first to generate logs\nsudo awf --allow-domains github.com ''curl https://api.github.com''\n\n# Then parse\npython .claude/skills/awf-debug-tools/scripts/parse-squid-logs.py\n```\n\n## Future Enhancements\n\nPlanned scripts for future versions:\n- `analyze-traffic.py` - Analyze traffic patterns over time\n- `generate-allowlist.py` - Auto-generate allowlist from logs\n- `cleanup-awf.py` - Clean up orphaned resources\n- `benchmark-awf.py` - Performance testing utilities\n"},"lastSynced":"2026-03-08T02:11:50.617Z","agentAnalysis":{"suitability":{"en":"Perfect for Network Security Agents needing efficient awf firewall debugging and operation capabilities.","zh":"非常适合需要高效 awf 防火墙调试和操作能力的网络安全代理。","ja":"ネットワークセキュリティエージェントが効率的なawfファイアウォールのデバッグと操作機能を必要とする場合に最適です。","ko":"効率的な awf 방화벽 디버깅 및 운영 기능이 필요한 네트워크 보안 에이전트에 적합합니다.","es":"Perfecto para Agentes de Seguridad de Red que necesitan capacidades de depuración y operación de firewall awf eficientes.","fr":"Parfait pour les agents de sécurité réseau ayant besoin de capacités de débogage et d''exploitation de pare-feu awf efficaces.","de":"Perfekt für Netzwerksicherheitsagenten, die effiziente awf-Feuerwand-Debugging- und Betriebsfunktionen benötigen.","pt":"Perfeito para Agentes de Segurança de Rede que necessitam de capacidades de depuração e operação de firewall awf eficientes.","ru":"Идеально подходит для агентов сетевой безопасности, которым необходимы эффективные возможности отладки и эксплуатации брандмауэра awf.","ar":"مثالي لعميل أمان الشبكة الذي يحتاج إلى قدرات فحص وإدارة جدار الحماية awf فعالة."},"recommendation":{"en":"Empowers agents to reduce verbose Docker/log output by 80%+ and provide actionable insights instead of raw data dumps, utilizing Python scripts to streamline the debugging process with Docker and log files.","zh":"使代理能够通过使用Python脚本简化Docker和日志文件的调试过程，将冗长的Docker/日志输出减少80%以上，并提供可行的见解而不是原始数据转储。","ja":"エージェントがPythonスクリプトを使用してDockerおよびログファイルのデバッグプロセスを簡素化し、冗長なDocker/ログ出力を80%以上削減し、生データダンプの代わりに実行可能なインサイトを提供できるようにします。","ko":"에이전트가 Python 스크립트를 사용하여 Docker 및 로그 파일의 디버깅 프로세스를 간소화하여冗長한 Docker/로그 출력을 80% 이상 줄이고, 원시 데이터 덤프 대신 실행 가능한 인사이트를 제공할 수 있도록 합니다.","es":"Habilita a los agentes a reducir la salida verbose de Docker/log en un 80%+ y a proporcionar información valiosa en lugar de volcados de datos sin procesar, utilizando scripts de Python para simplificar el proceso de depuración con Docker y archivos de registro.","fr":"Permet aux agents de réduire la sortie verbose de Docker/log de 80%+ et de fournir des informations exploitables au lieu de décharger des données brutes, en utilisant des scripts Python pour rationaliser le processus de débogage avec Docker et les fichiers journaux.","de":"Ermächtigt Agenten, die verbose Ausgabe von Docker/Log um 80%+ zu reduzieren und anstelle von Rohdatendumps handhabbare Erkenntnisse zu liefern, indem Python-Skripte verwendet werden, um den Debugging-Prozess mit Docker und Log-Dateien zu rationalisieren.","pt":"Habilita os agentes a reduzir a saída verbose do Docker/log em 