operation of the awf firewall awf-debug-tools is a set of practical Python scripts designed to simplify the debugging process of the awf firewall, reducing manual commands and noisy output.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OleksandrKucherenko/e-bash/shellspec', 'community', 'OleksandrKucherenko', 'e-bash', 'OleksandrKucherenko/e-bash', 'shellspec', 0, 0, 60, '2026-03-08T01:57:15.579Z', '2026-03-08T02:11:50.821Z', 'd77f66933def4a44e841e3b972341967c4fbc0783f7b350c27cc3ce053da9762', '{"id":"OleksandrKucherenko/e-bash/shellspec","name":"shellspec","description":{"en":"shellspec is a BDD unit testing framework for POSIX shells, enabling professional-grade Test-Driven Development for bash, ksh, zsh, and dash scripts. It benefits developers and DevOps teams by providing a translator between natural language test intentions and shell execution verification.","zh":"ShellSpec 是一个用于 Bash 和 POSIX shell 的全功能 BDD 单元测试框架，支持测试驱动开发","ja":"ShellSpec は、Bash および POSIX シェル用のフル機能 BDD ユニットテスト フレームワークです","ko":"ShellSpec은 Bash 및 POSIX 셸을 위한 완전한 기능의 BDD 유닛 테스트 프레임워크입니다","es":"ShellSpec es un framework de pruebas unitarias para bash y otros shells POSIX. Permite desarrollar pruebas unitarias de manera eficiente","fr":"ShellSpec est un framework de tests unitaires pour bash et d''autres shells POSIX. Il permet de développer des tests unitaires de manière efficace","de":"ShellSpec ist ein Framework für Unit-Tests von bash und anderen POSIX-Shells. Es ermöglicht die effiziente Entwicklung von Unit-Tests","pt":"O ShellSpec é um framework de teste unitário BDD para shells que facilita a manutenção de projetos","ru":"ShellSpec - это фреймворк для модульного тестирования BDD для shells, который упрощает обслуживание проектов для ИИ Агентов","ar":"ShellSpec هو إطار اختبار وحدة BDD لشيلز يسهل صيانة المشاريع لمنصات الإي آي"},"seo":{"title":{"en":"shellspec: BDD Unit Testing Framework Setup Guide | AI Ag...","zh":"ShellSpec 测试框架安装与设置指南","ja":"ShellSpec ユニットテストフレームワークの設定方法","ko":"ShellSpec 유닛 테스트 프레임워크 설정 가이드","es":"Guía de configuración de ShellSpec para pruebas