INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OleksandrKucherenko/e-bash/shellspec', 'shellspec', 'OleksandrKucherenko', 'e-bash', 'community', 'shellspec OleksandrKucherenko e-bash community shellspec is a BDD unit testing framework for POSIX shells, enabling professional-grade Test-Driven Development for bash, ksh, zsh, and dash scripts. It benefits developers and DevOps teams by providing a translator between natural language test intentions and shell execution verification. ShellSpec 是一个用于 Bash 和 POSIX shell 的全功能 BDD 单元测试框架，支持测试驱动开发 ShellSpec は、Bash および POSIX シェル用のフル機能 BDD ユニットテスト フレームワークです ShellSpec은 Bash 및 POSIX 셸을 위한 완전한 기능의 BDD 유닛 테스트 프레임워크입니다 ShellSpec es un framework de pruebas unitarias para bash y otros shells POSIX. Permite desarrollar pruebas unitarias de manera eficiente ShellSpec est un framework de tests unitaires pour bash et d''autres shells POSIX. Il permet de développer des tests unitaires de manière efficace ShellSpec ist ein Framework für Unit-Tests von bash und anderen POSIX-Shells. Es ermöglicht die effiziente Entwicklung von Unit-Tests O ShellSpec é um framework de teste unitário BDD para shells que facilita a manutenção de projetos ShellSpec - это фреймворк для модульного тестирования BDD для shells, который упрощает обслуживание проектов для ИИ Агентов ShellSpec هو إطار اختبار وحدة BDD لشيلز يسهل صيانة المشاريع لمنصات الإي آي how to use shellspec shellspec install shellspec setup guide what is shellspec shellspec alternative shellspec vs pytest bash unit testing posix shell testing test-driven development for shell scripts ShellSpec BDD 单元测试 Bash 测试 POSIX shell 测试 测试驱动开发 AI 工具 自动化测试 Provides a translator between natural language test intentions and shell execution verification Supports Test-Driven Development (TDD) practices for bash, ksh, zsh, and dash scripts Enables unit testing for POSIX shells Includes a quick start guide for easy installation and setup Works with multiple shell types, including bash, ksh, zsh, and dash shellspec is a full-featured BDD unit testing framework for bash, ksh, zsh, dash, and all POSIX shells, bringing Test-Driven Development practices to shell scripting.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('practical-stack/ai-lab/learning-content-creator', 'community', 'practical-stack', 'ai-lab', 'practical-stack/ai-lab', 'learning-content-creator', 0, 0, 60, '2026-03-08T01:57:15.580Z', '2026-03-08T02:11:52.983Z', 'b94c1ce2b8b0b87514859df0620bb34c6b2da5452583c7f2d4bda2492dbbc48f', '{"id":"practical-stack/ai-lab/learning-content-creator","name":"learning-content-creator","description":{"en":"The learning-content-creator skill transforms multi-model research materials into structured learning content with bilingual support. It benefits developers and educators seeking to organize and translate research materials efficiently.","zh":"AI智能助手学习内容创建工具可以将研究材料转化为结构化的学习内容，支持中英文双语","ja":"AIエージェントによる学習コンテンツ作成ツールは、研究資料を学習パスに変換し、英語と韓国語をサポートする","ko":"AI 에이전트 학습 콘텐츠 생성 도구는 연구 자료를 구조화된 학습 콘텐츠로 변환하고, 영어와 한국어를 지원합니다","es":"El creador de contenido de aprendizaje transforma materiales de investigación en contenido estructurado con soporte bilingüe","fr":"Le créateur de contenu d''apprentissage transforme des matériaux de recherche en contenu structuré avec support bilingue","de":"Der Lerninhalts-Ersteller wandelt Forschungsmaterialien in strukturierten Lerninhalt mit zweisprachiger Unterstützung um","pt":"O Learning Content Creator é uma ferramenta que transforma materiais de pesquisa em conteúdo de aprendizado estruturado com suporte bilíngue em inglês e coreano.","ru":"ИИ Агент для создания обучаемого контента преобразует исследовательские материалы в структурированный обучаемый контент с двуязычной поддержкой английского и корейского языков.","ar":"عامل إنشاء المحتوى التعليمي هو أداة تحول مواد البحث إلى محتوى تعليمي منظم بدعم ثنائي اللغة الإنجليزية والكورية."},"seo":{"title":{"en":"Learning Content Creator: Structured Learning Setup Guide...","zh":"AI智能助手学习内容创建工具 Setup Guide","ja":"AIエージェントによる学習コンテンツ作成ツール Best Practices","ko":"AI 에이전트 학습 콘텐츠 생성 도구 Setup Guide","es":"Guía de configuración del creador de contenido de aprendi...","fr":"Guide de démarrage rapide pour le créateur de contenu d''a...","de":"Einrichtungsleitfaden für den Lerninhalts-Ersteller","pt":"Guia de Configuração do Learning Content Creator","ru":"Настройка ИИ Агента для Создания Обучаемого Контента","ar":"دليل إعداد عامل إنشاء المحتوى التعليمي"},"description":{"en":"Discover how to transform research materials into bilingual learning content with the learning-content-creator skill - get started now and streamline your wo...","zh":"使用AI智能助手学习内容创建工具，轻松将研究材料转化为结构化的学习内容，支持中英文双语","ja":"AIエージェントを活用した学習コンテンツ作成ツールで、研究資料を効率的に学習パスに変換する","ko":"AI 에이전트 학습 콘텐츠 생성 도구를 사용하여 연구 자료를 구조화된 학습 콘텐츠로 변환하고, 영어와 한국어를 지원합니다","es":"Aprende a transformar materiales de investigación en contenido de aprendizaje estructurado con soporte bilingüe","fr":"Découvrez comment transformer des matériaux de recherche en contenu d''apprentissage structuré avec support bilingue","de":"Erfahren Sie, wie Sie Forschungsmaterialien in strukturierten Lerninhalt mit zweisprachiger Unterstützung umwandeln","pt":"Aprenda a configurar o Learning Content Creator para transformar materiais de pesquisa em conteúdo de aprendizado estruturado com suporte bilíngue","ru":"Узнайте, как настроить ИИ Агент для создания обучаемого контента из исследовательских материалов с двуязычной поддержкой","ar":"تعلم كيفية إعداد عامل إنشاء المحتوى التعليمي لتحويل مواد البحث إلى محتوى تعليمي منظم بدعم ثنائي اللغة"},"definition":{"en":"learning-content-creator is a skill that transforms research materials into structured learning content, supporting both English and Korean languages through a phased workflow.","zh":"AI智能助手学习内容创建工具是一种可以将研究材料转化为结构化的学习内容的工具","ja":"AIエージェントによる学習コンテンツ作成ツールは、研究資料を学習パスに変換するためのツールです","ko":"AI 에이전트 학습 콘텐츠 생성 도구는 연구 자료를 구조화된 학습 콘텐츠로 변환하는 도구입니다","es":"Herramienta de inteligencia artificial para crear contenido de aprendizaje","fr":"Outil d''intelligence artificielle pour créer du contenu d''apprentissage","de":"Künstliche Intelligenz-Tool zum Erstellen von Lerninhalten","pt":"O que é Learning Content Creator? É uma ferramenta que cria conteúdo de aprendizado estruturado a partir de materiais de pesquisa.","ru":"Что такое ИИ Агент для создания обучаемого контента? Это инструмент, создающий структурированный обучаемый контент из исследовательских материалов.","ar":"ما هو عامل إنشاء المحتوى التعليمي? هو أداة تخلق محتوى تعليمي منظم من مواد البحث."},"features":{"en":["Analyzes research materials in Markdown (.md) files to create a content outline","Generates synthesized insights in English, outputting to learning/*.en.md files","Translates English content to Korean, producing learning/*.ko.md files","Utilizes a phased workflow: Research Materials → Learning Path (EN) → Translation (KO) → Frontmatter"],"zh":["支持中英文双语","将研究材料转化为结构化的学习内容","使用Markdown文件作为输入","输出学习路径和前置内容","支持CLI命令行工具","提供学习内容创建工作流"],"ja":["英語と韓国語をサポート","研究資料を学習パスに変換","Markdownファイルを入力として使用","学習パスとフロントマターを出力","CLIコマンドラインツールをサポート","学習コンテンツ作成ワークフローを提供"],"ko":["영어와 한국어를 지원","연구 자료를 구조화된 학습 콘텐츠로 변환","Markdown 파일을 입력으로 사용","학습 경로와 프론트매터를 출력","CLI 명령줄 도구를 지원","학습 콘텐츠 생성 워크플ロー를 제공"],"es":["Análisis de materiales de investigación","Creación de contenido en inglés","Traducción al coreano","Soporte bilingüe","Estructuración de contenido de aprendizaje"],"fr":["Analyse de matériaux de recherche","Création de contenu en anglais","Traduction en coréen","Support bilingue","Structuration de contenu d''apprentissage"],"de":["Analyse von Forschungsmaterialien","Erstellung von Inhalten in Englisch","Übersetzung ins Koreanische","Zweisprachige Unterstützung","Strukturierung von Lerninhalten"],"pt":["Análise de materiais de pesquisa em arquivos Markdown","Criação de conteúdo de aprendizado em inglês e coreano","Suporte bilíngue para conteúdo de aprendizado","Utilização de frontmatter para organização de conteúdo","Transformação de insights em conteúdo de aprendizado estruturado"],"ru":["Анализ исследовательских материалов в файлах Markdown","Создание обучаемого контента на английском и корейском языках","Двуязычная поддержка для обучаемого контента","Использование frontmatter для организации контента","Преобразование инсайтов в структурированный обучаемый контент"],"ar":["تحليل مواد البحث في ملفات Markdown","إنشاء محتوى تعليمي باللغة الإنجليزية والكورية","دعم ثنائي اللغة لمحتوى التعلم","استخدام frontmatter لتنظيم المحتوى","تحويل الاطلاعات إلى محتوى تعليمي منظم"]},"keywords":{"en":["how to use learning-content-creator","learning-content-creator alternative","learning-content-creator setup guide","what is learning-content-creator","learning-content-creator vs competitors","learning-content-creator install","bilingual learning content creation","research material organization","structured learning content"],"zh":["AI智能助手","学习内容创建工具","研究材料转化","结构化学习内容","中英文双语","Markdown文件","CLI命令行工具","学습内容创建工作流"],"ja":["AIエージェント","学習コンテンツ作成ツール","研究資料変換","学習パス","英語と韓国語","Markdownファイル","CLIコマンドラインツール","学習コンテンツ作成ワークフロー"],"ko":["AI 에이전트","학습 콘텐츠 생성 도구","연구 자료 변환","구조화된 학습 콘텐츠","영어와 한국어","Markdown 파일","CLI 명령줄 도구","학습 콘텐츠 생성 워크플ロー"],"es":["creador de contenido de aprendizaje","herramientas de inteligencia artificial","materiales de investigación","contenido estructurado","soporte bilingüe","traducción automática","desarrollo de contenido"],"fr":["créateur de contenu d''apprentissage","outils d''intelligence artificielle","matériaux de recherche","contenu structuré","support bilingue","traduction automatique","développement de contenu"],"de":["Lerninhalts-Ersteller","künstliche Intelligenz-Tools","Forschungsmaterialien","strukturierter Lerninhalt","zweisprachige Unterstützung","automatische Übersetzung","Lerninhalts-Entwicklung"],"pt":["Learning Content Creator","criação de conteúdo de aprendizado","materiais de pesquisa","suporte bilíngue","frontmatter","Markdown","desenvolvimento de conteúdo educacional"],"ru":["ИИ Агент для создания обучаемого контента","создание обучаемого контента","исследовательские материалы","двуязычная поддержка","frontmatter","Markdown","разработка образовательного контента"],"ar":["عامل إنشاء المحتوى التعليمي","إنشاء محتوى تعليمي","مواد البحث","دعم ثنائي اللغة","frontmatter","Markdown","تطوير المحتوى التعليمي"]}},"owner":"practical-stack","repo":"ai-lab","repoPath":"practical-stack/ai-lab","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.580Z","topics":[],"category":"community","skillMd":{"name":"learning-content-creator","description":"Transform research materials into structured learning content with","bodyPreview":"# Learning Content Creator\n\nTransform multi-model research materials into structured learning content, with bilingual support (English + Korean).\n\n## Quick Start\n\n### Workflow Overview\n\n```\nResearch Materials → Learning Path (EN) → Translation (KO) → Frontmatter\n```\n\n| Phase | Input | Output |\n|-------|-------|--------|\n| 1. Analyze | `research/*.md` files | Content outline |\n| 2. Create EN | Synthesized insights | `learning/*.en.md` |\n| 3. Translate KO | English content | `learning/*.ko.md` |\n|","body":"# Learning Content Creator\n\nTransform multi-model research materials into structured learning content, with bilingual support (English + Korean).\n\n## Quick Start\n\n### Workflow Overview\n\n```\nResearch Materials → Learning Path (EN) → Translation (KO) → Frontmatter\n```\n\n| Phase | Input | Output |\n|-------|-------|--------|\n| 1. Analyze | `research/*.md` files | Content outline |\n| 2. Create EN | Synthesized insights | `learning/*.en.md` |\n| 3. Translate KO | English content | `learning/*.ko.md` |\n| 4. Frontmatter | All files | YAML metadata added |\n\n## Workflow Routing\n\n| Intent | Workflow |\n|--------|----------|\n| Create learning content from research | [workflows/create-learning.md](workflows/create-learning.md) |\n| Translate EN to KO | [workflows/translate.md](workflows/translate.md) |\n\n> **Note**: Phase 4 (Frontmatter) uses the `doc-frontmatter` schema. The calling command coordinates the multi-skill pipeline.\n\n## Phase 1: ANALYZE Research\n\n**Goal**: Understand and synthesize multi-model research.\n\n### Input Structure\n\n```\ndocs/NN-topic/\n├── research/\n│   ├── 00-research-prompt.en.md   # Original prompt\n│   ├── 01-claude.en.md            # Claude''s response\n│   ├── 02-gpt/                    # GPT''s response (may be multi-file)\n│   │   ├── 01-concepts.en.md\n│   │   ├── 02-relationships.en.md\n│   │   └── ...\n│   └── 03-gemini.en.md            # Gemini''s response\n```\n\n### Analysis Checklist\n\n| Check | Question |\n|-------|----------|\n| Coverage | What topics do all models agree on? |\n| Unique | What unique insights does each model provide? |\n| Conflicts | Where do models disagree? How to resolve? |\n| Gaps | What''s missing? What questions remain? |\n\n### Output: Content Outline\n\n```markdown\n# Learning Content Outline\n\n## Modules (6-8 recommended)\n\n| # | Module | Topics | Sources |\n|---|--------|--------|---------|\n| 1 | Fundamentals | Definitions, core concepts | All models |\n| 2 | Relationships | How parts connect | GPT, Claude |\n| ... | ... | ... | ... |\n\n## Key Insights by Source\n\n- **Claude**: [unique insights]\n- **GPT**: [unique insights]\n- **Gemini**: [unique insights]\n\n## Synthesis Strategy\n\n[How to combine insights without redundancy]\n```\n\n## Phase 2: CREATE English Content\n\n**Goal**: Create structured learning modules in English.\n\n### Directory Structure\n\n```\ndocs/NN-topic/\n└── learning/\n    ├── README.en.md           # Course overview, learning path\n    ├── 01-module-name.en.md   # Module 1\n    ├── 02-module-name.en.md   # Module 2\n    └── ...\n```\n\n### Module Template\n\n```markdown\n# Module N: Title\n\n> One-sentence module summary\n\n## Learning Objectives\n\nAfter completing this module, you will:\n- [Objective 1]\n- [Objective 2]\n- [Objective 3]\n\n---\n\n## N.1 First Section\n\n[Content]\n\n## N.2 Second Section\n\n[Content]\n\n---\n\n## Key Takeaways\n\n- [Takeaway 1]\n- [Takeaway 2]\n- [Takeaway 3]\n\n## Exercises\n\n### Exercise N.1: [Name]\n\n[Exercise description]\n\n---\n\n## Next Steps\n\nContinue to [Module N+1: Title](./0N+1-title.en.md)\n```\n\n### README Template\n\n```markdown\n# Course Title\n\n> Course tagline (one sentence)\n\n## Course Overview\n\n[2-3 paragraph description]\n\n## Who This Is For\n\n- [Audience 1]\n- [Audience 2]\n\n## Prerequisites\n\n- [Prerequisite 1]\n- [Prerequisite 2]\n\n---\n\n## Course Modules\n\n| # | Module | Duration | Description |\n|---|--------|----------|-------------|\n| 1 | [Title](./01-name.en.md) | NN min | Description |\n| 2 | [Title](./02-name.en.md) | NN min | Description |\n\n**Total Time:** ~N hours\n\n---\n\n## Learning Path\n\n### Beginner Track\n[Visual flow diagram]\n\n### Advanced Track\n[Visual flow diagram]\n\n---\n\n## Source Materials\n\n| Source | Description |\n|--------|-------------|\n| [Research Prompt](../research/00-research-prompt.en.md) | Original prompt |\n| [Claude](../research/01-claude.en.md) | Claude''s response |\n| [GPT](../research/02-gpt/) | GPT''s response |\n| [Gemini](../research/03-gemini.en.md) | Gemini''s response |\n```\n\n### Writing Guidelines\n\n| Guideline | Description |\n|-----------|-------------|\n| **Synthesize** | Don''t copy verbatim; synthesize insights |\n| **Attribute** | Note which model contributed which insight |\n| **Practical** | Focus on actionable knowledge |\n| **Consistent** | Use same terminology throughout |\n| **Progressive** | Build complexity gradually |\n\n## Phase 3: TRANSLATE to Korean\n\n**Goal**: Create high-quality Korean translations.\n\n### Naming Convention\n\n| English | Korean |\n|---------|--------|\n| `*.en.md` | `*.ko.md` |\n| `README.en.md` | `README.ko.md` |\n| `01-fundamentals.en.md` | `01-fundamentals.ko.md` |\n\n### Translation Guidelines\n\n| Aspect | Guideline |\n|--------|-----------|\n| **Technical terms** | Keep English for universally used terms (e.g., Command, Skill, Agent) |\n| **Headers** | Translate headers |\n| **Code blocks** | Keep code in English, translate comments |\n| **Tables** | Translate content, keep structure |\n| **Links** | Update to point to `.ko.md` counterparts |\n\n### Do NOT Translate\n\n- Code snippets\n- File paths\n- Command examples\n- Technical identifiers (kebab-case names, etc.)\n\n### Translation Checklist\n\n- [ ] All `.en.md` files have `.ko.md` counterparts\n- [ ] Internal links updated to `.ko.md` versions\n- [ ] Technical terms consistently handled\n- [ ] Tables and diagrams preserved\n- [ ] Exercises and examples localized where appropriate\n\n## Phase 4: ADD Frontmatter\n\n**Goal**: Add YAML frontmatter to all learning documents.\n\n### Frontmatter Schema\n\nUse the frontmatter schema from `doc-frontmatter` skill (see `.claude/skills/doc-frontmatter/references/schema.md`).\n\n### Frontmatter Template for Learning Content\n\n```yaml\n---\ntitle: \"Module Title\"\ndescription: \"50-160 char summary of what this module teaches\"\ntype: tutorial\ntags: [AI, Architecture, BestPractice]\norder: 1\ndepends_on: [./prerequisite-module.en.md]\nrelated: [./related-module.en.md]\n---\n```\n\n### Type Selection for Learning\n\n| Content Type | `type` Value |\n|--------------|--------------|\n| Course overview (README) | `index` |\n| Step-by-step module | `tutorial` |\n| Reference/spec | `reference` |\n| Concept explanation | `explanation` |\n\n### Execution\n\nFor each file:\n1. Extract title from H1\n2. Generate description from first paragraph\n3. Determine type based on content\n4. Select relevant tags (max 5)\n5. Set order from filename prefix\n6. Add depends_on/related if applicable\n\n## Quality Checklist\n\n### Phase 1: Analyze\n- [ ] All research files read\n- [ ] Key insights extracted from each model\n- [ ] Conflicts identified and resolved\n- [ ] Content outline created\n\n### Phase 2: Create EN\n- [ ] All modules follow template\n- [ ] Learning objectives are measurable\n- [ ] Content synthesizes (not copies) sources\n- [ ] Exercises included in each module\n- [ ] Links work correctly\n\n### Phase 3: Translate KO\n- [ ] All files translated\n- [ ] Technical terms consistent\n- [ ] Links updated to .ko.md\n- [ ] Natural Korean (not machine-translation quality)\n\n### Phase 4: Frontmatter\n- [ ] All files have frontmatter\n- [ ] Required fields present (title, description, type)\n- [ ] Tags from controlled vocabulary\n- [ ] Dependencies correctly specified\n\n## Example Output\n\nSee `docs/01-structure-organizer/learning/` for a complete example:\n\n```\ndocs/01-structure-organizer/learning/\n├── README.en.md              # Course index (EN)\n├── README.ko.md              # Course index (KO)\n├── 01-fundamentals.en.md     # Module 1 (EN)\n├── 01-fundamentals.ko.md     # Module 1 (KO)\n├── 02-relationships.en.md    # Module 2 (EN)\n├── 02-relationships.ko.md    # Module 2 (KO)\n├── 03-decision-framework.en.md\n├── 03-decision-framework.ko.md\n├── 04-templates.en.md\n├── 04-templates.ko.md\n├── 05-examples.en.md\n├── 05-examples.ko.md\n├── 06-anti-patterns.en.md\n└── 06-anti-patterns.ko.md\n```\n"},"lastSynced":"2026-03-08T02:11:52.983Z","agentAnalysis":{"suitability":{"en":"Perfect for Educational Agents needing to transform multi-model research materials into structured learning content with bilingual support.","zh":"非常适合需要将多模型研究材料转换为结构化学习内容的教育代理，支持中英双语。","ja":"教育エージェントが多モデル研究資料を構造化された学習コンテンツに変換する必要がある場合に最適で、英語と日本語の両方をサポートします。","ko":"교육 에이전트가 멀티 모델 연구 자료를 구조화된 학습 콘텐츠로 변환해야 하는 경우에 적합하며, 영한 双语를 지원합니다.","es":"Perfecto para Agentes Educativos que necesitan transformar materiales de investigación multi-modelo en contenido de aprendizaje estructurado con soporte bilingüe.","fr":"Parfait pour les Agents Éducatifs ayant besoin de transformer des matériaux de recherche multi-modèles en contenu d''apprentissage structuré avec un support bilingue.","de":"Perfekt für Bildungsagenten, die Forschungsmaterialien mit mehreren Modellen in strukturierten Lerninhalten mit zweisprachiger Unterstützung umwandeln müssen.","pt":"Perfeito para Agentes Educacionais que precisam transformar materiais de pesquisa multi-modelo em conteúdo de aprendizado estruturado com suporte bilíngue.","ru":"Идеально подходит для образовательных агентов, которым необходимо преобразовывать многомодельные исследовательские материалы в структурированный учебный контент с двуязычной поддержкой.","ar":"مثالي لعمіл एजنتس التربوية التي تحتاج إلى تحويل مواد البحث متعددة النماذج إلى محتوى تعليمي منظم بدعم ثنائي اللغة."},"recommendation":{"en":"Empowers agents to synthesize insights from research materials, create English learning paths, and translate content into Korean, utilizing markdown files and frontmatter for efficient organization.","zh":"赋予代理人从研究材料中提取见解、创建英语学习路径并将内容翻译成韩语的能力，利用markdown文件和frontmatter进行高效的组织。","ja":"エージェントが研究資料から洞察を統合し、英語の学習パスを作成し、コンテンツを韓国語に翻訳する機能を提供し、Markdownファイルとfrontmatterを使用して効率的な組織化を行います。","ko":"에이전트가 연구 자료에서 통찰력을 합성하고, 영어 학습 경로를 생성하고, 마크다운 파일과 프론트 매터를 사용하여 효율적인 구성으로 콘텐츠를 한국어로 번역할 수 있는 기능을 제공합니다.","es":"Empodera a los agentes para sintetizar información de los materiales de investigación, crear rutas de aprendizaje en inglés y traducir contenido al coreano, utilizando archivos markdown y frontmatter para una organización eficiente.","fr":"Permet aux agents de synthétiser des informations à partir de matériaux de recherche, de créer des parcours d''apprentissage en anglais et de traduire du contenu en coréen, en utilisant des fichiers markdown et frontmatter pour une organisation efficace.","de":"Ermächtigt Agenten, Erkenntnisse aus Forschungsmaterialien zu synthetisieren, Lernpfade in Englisch zu erstellen und Inhalte ins Koreanische zu übersetzen, unter Verwendung von Markdown-Dateien und Frontmatter für eine effiziente Organisation.","pt":"Habilita os agentes a sintetizar insights dos materiais de pesquisa, criar caminhos de aprendizado de inglês e traduzir o conteúdo para coreano, utilizando arquivos markdown e frontmatter para organização eficiente.","ru":"Наделяет агентов возможностью синтезировать идеи из исследовательских материалов, создавать пути английского обучения и переводить контент на корейский язык, используя файлы markdown и frontmatter для эффективной организации.","ar":"يمنح الوكلاء القدرة على دمج Informationen من مواد البحث، وإنشاء مسارات تعلم اللغة الإنجليزية، وترجمة المحتوى إلى الكورية، باستخدام ملفات markdown وfrontmatter من أجل التنظيم الفعال."},"useCases":{"en":["Automating the creation of bilingual learning content from research materials","Generating structured learning paths in English and Korean","Translating existing English content into Korean for expanded accessibility"],"zh":["从研究材料自动创建中英双语学习内容","生成英语和韩语的结构化学习路径","将现有的英语内容翻译成韩语以扩大可访问性"],"ja":["研究資料から英語と日本語のバイリンガル学習コンテンツを自動生成する","英語と韓国語の構造化された学習パスを生成する","既存の英語コンテンツを韓国語に翻訳してアクセス範囲を拡大する"],"ko":["연구 자료에서 영한 이중 언어 학습 콘텐츠를 자동으로 생성하는 것","영어와 한국어의 구조화된 학습 경로를 생성하는 것","既存의 영어 콘텐츠를 한국어로 번역하여 접근 범위를 확장하는 것"],"es":["Automatizar la creación de contenido de aprendizaje bilingüe a partir de materiales de investigación","Generar rutas de aprendizaje estructuradas en inglés y coreano","Traducir contenido existente en inglés al coreano para una mayor accesibilidad"],"fr":["Automatiser la création de contenu d''apprentissage bilingue à partir de matériaux de recherche","Générer des parcours d''apprentissage structurés en anglais et en coréen","Traduire le contenu existant en anglais en coréen pour une accessibilité accrue"],"de":["Automatisieren der Erstellung von zweisprachigem Lerninhalt aus Forschungsmaterialien","Erstellen strukturierter Lernpfade in Englisch und Koreanisch","Übersetzen bestehenden englischen Inhalts ins Koreanische für eine verbesserte Zugänglichkeit"],"pt":["Automatizar a criação de conteúdo de aprendizado bilíngue a partir de materiais de pesquisa","Gerar caminhos de aprendizado estruturados em inglês e coreano","Traduzir o conteúdo existente em inglês para coreano para acessibilidade expandida"],"ru":["Автоматизировать создание двуязычного учебного контента из исследовательских материалов","Генерировать структурированные пути обучения на английском и корейском языках","Переводить существующий английский контент на корейский язык для расширенной доступности"],"ar":["تحويل Materials البحث إلى محتوى تعليمي منظم ثنائي اللغة تلقائيًا","إنشاء مسارات تعلم منظم في اللغة الإنجليزية والكورية","ترجمة المحتوى الإنجليزي الحالي إلى الكورية لتوسيع إمكانية الوصول"]},"limitations":{"en":["Requires markdown files as input","Limited to English and Korean bilingual support","Dependent on frontmatter for content organization"],"zh":["需要markdown文件作为输入","仅限英语和韩语的双语支持","依赖frontmatter进行内容组织"],"ja":["入力としてMarkdownファイルを必要とする","英語と韓国語のバイリンガルサポートのみ","コンテンツの組織化にfrontmatterに依存する"],"ko":["입력으로 마크다운 파일이 필요","영어와 한국어의雙語 지원만 가능","콘텐츠 조직화에 프론트 매터에 의존"],"es":["Requiere archivos markdown como entrada","Limitado a soporte bilingüe inglés-coreano","Dependiente de frontmatter para la organización de contenido"],"fr":["Nécessite des fichiers markdown comme entrée","Limité au support bilingue anglais-coréen","Dépendant de frontmatter pour l''organisation de contenu"],"de":["Benötigt Markdown-Dateien als Eingabe","Begrenzt auf zweisprachige Unterstützung Englisch-Koreanisch","Abhängig von Frontmatter für die Inhaltsorganisation"],"pt":["Requer arquivos markdown como entrada","Limitado ao suporte bilíngue em inglês e coreano","Dependente de frontmatter para organização de conteúdo"],"ru":["Требует файлов markdown в качестве входных данных","Ограничен двуязычной поддержкой английского и корейского языков","Зависит от frontmatter для организации контента"],"ar":["يتطلب ملفات markdown كمدخل","محدود بالدعم اللغوي الثنائي للغة الإنجليزية والكورية","يعتمد على frontmatter لتنظيم المحتوى"]},"version":4},"contentHash":"b94c1ce2b8b0b87514859df0620bb34c6b2da5452583c7f2d4bda2492dbbc48f","qualityScore":60}');
