INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('practical-stack/ai-lab/learning-content-creator', 'learning-content-creator', 'practical-stack', 'ai-lab', 'community', 'learning-content-creator practical-stack ai-lab community The learning-content-creator skill transforms multi-model research materials into structured learning content with bilingual support. It benefits developers and educators seeking to organize and translate research materials efficiently. AI智能助手学习内容创建工具可以将研究材料转化为结构化的学习内容，支持中英文双语 AIエージェントによる学習コンテンツ作成ツールは、研究資料を学習パスに変換し、英語と韓国語をサポートする AI 에이전트 학습 콘텐츠 생성 도구는 연구 자료를 구조화된 학습 콘텐츠로 변환하고, 영어와 한국어를 지원합니다 El creador de contenido de aprendizaje transforma materiales de investigación en contenido estructurado con soporte bilingüe Le créateur de contenu d''apprentissage transforme des matériaux de recherche en contenu structuré avec support bilingue Der Lerninhalts-Ersteller wandelt Forschungsmaterialien in strukturierten Lerninhalt mit zweisprachiger Unterstützung um O Learning Content Creator é uma ferramenta que transforma materiais de pesquisa em conteúdo de aprendizado estruturado com suporte bilíngue em inglês e coreano. ИИ Агент для создания обучаемого контента преобразует исследовательские материалы в структурированный обучаемый контент с двуязычной поддержкой английского и корейского языков. عامل إنشاء المحتوى التعليمي هو أداة تحول مواد البحث إلى محتوى تعليمي منظم بدعم ثنائي اللغة الإنجليزية والكورية. how to use learning-content-creator learning-content-creator alternative learning-content-creator setup guide what is learning-content-creator learning-content-creator vs competitors learning-content-creator install bilingual learning content creation research material organization structured learning content AI智能助手 学习内容创建工具 研究材料转化 结构化学习内容 中英文双语 Markdown文件 CLI命令行工具 学습内容创建工作流 Analyzes research materials in Markdown (.md) files to create a content outline Generates synthesized insights in English, outputting to learning/*.en.md files Translates English content to Korean, producing learning/*.ko.md files Utilizes a phased workflow: Research Materials → Learning Path (EN) → Translation (KO) → Frontmatter learning-content-creator is a skill that transforms research materials into structured learning content, supporting both English and Korean languages through a phased workflow.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vorsocom/mugen/acp-http-e2e-tester', 'community', 'vorsocom', 'mugen', 'vorsocom/mugen', 'acp-http-e2e-tester', 0, 0, 60, '2026-03-08T01:57:15.586Z', '2026-03-08T02:11:58.049Z', 'c6ffb9e6437f799b03d52287fd573a3f690b3f1af7d759353f0b27905352f5dc', '{"id":"vorsocom/mugen/acp-http-e2e-tester","name":"acp-http-e2e-tester","description":{"en":"The acp-http-e2e-tester skill enables developers to run deterministic ACP HTTP test flows from a JSON spec, covering auth, tenant discovery, and entity creation. It benefits developers working with HTTP protocols and JSON specifications.","zh":"ACP HTTP E2E 测试器是一种基于 GenAI Microframework 的测试工具，支持 JSON 规范和 Hypercorn 集成。它可以实现端到端测试的自动化和效率提升","ja":"ACP HTTP E2E テスターは、GenAI Microframework を基盤とするテストツールです。JSON仕様とHypercornの統合をサポートし、テスト自動化と効率化を実現します","ko":"ACP HTTP E2E 테스터는 GenAI Microframework 기반의 테스트 도구로 JSON 규격 및 Hypercorn 통합을 지원합니다. 엔드 투 엔드 테스트의 자동화 및 효율성을 높여줍니다","es":"El framework de microservicios GenAI permite ejecutar pruebas E2E determinísticas con especificaciones JSON","fr":"Le microframework GenAI permet d''exécuter des tests E2E déterministes avec des spécifications JSON","de":"Das GenAI-Mikroframework ermöglicht die Ausführung deterministischer E2E-Tests mit JSON-Spezifikationen","pt":"O ACP HTTP E2E Tester é um microframework GenAI para execução de testes de ponta a ponta HTTP. Ele permite a automação de testes com um único script","ru":"ACP HTTP E2E Tester - это микрофреймворк GenAI для автоматизации тестирования HTTP. Он позволяет использовать один скрипт для проверки","ar":"ACP HTTP E2E Tester هو إطار عمل دقيق للآلات الذكية لتشغيل اختبارات نهاية إلى نهاية HTTP. يمكنه توفير automação الاختبارات باستخدام سكريبت واحد"},"seo":{"title":{"en":"acp-http-e2e-tester: End-to-End Testing Setup Guide | AI ...","zh":"ACP HTTP E2E 测试器 Setup Guide - 基于 GenAI Microframework","ja":"ACP HTTP E2E テスターのベストプラクティス - AIエージェントを使用したテスト自動化","ko":"ACP HTTP E2E 테스터 설정 가이드 - GenAI Microframework 기반","es":"Guía de configuración de acp-http-e2e-tester para pruebas...","fr":"Configurer acp-http-e2e-tester pour les tests E2E","de":"Einrichtungsleitfaden für acp-http-e2e-tester für E2E-Tests","pt":"Guia de Configuração do ACP HTTP E2E Tester","ru":"Настройка ACP HTTP E2E Tester: ИИ Агенты для тестирования","ar":"دليل إعداد ACP HTTP E2E Tester للآلات الذكية"},"description":{"en":"Streamline your testing workflow with acp-http-e2e-tester. Learn how to run deterministic ACP HTTP tests from a JSON spec and simplify your development process.","zh":"使用 ACP HTTP E2E 测试器进行端到端测试，实现测试自动化和效率提升。基于 GenAI Microframework，支持 JSON 规范和 Hypercorn 集成","ja":"AIエージェントを使用したACP HTTP E2Eテスターによるテスト自動化。GenAI Microframeworkを基盤とし、JSON仕様とHypercornの統合をサポート","ko":"ACP HTTP E2E 테스터를 사용하여 엔드 투 엔드 테스트를 자동화하고 효율성을 높여보세요. GenAI Microframework 기반으로 JSON 규격 및 Hypercorn 통합을 지원합니다","es":"Aprende a utilizar acp-http-e2e-tester para ejecutar pruebas E2E determinísticas con especificaciones JSON","fr":"Découvrez comment utiliser acp-http-e2e-tester pour exécuter des tests E2E déterministes avec des spécifications JSON","de":"Erfahren Sie, wie Sie acp-http-e2e-tester verwenden, um deterministische E2E-Tests mit JSON-Spezifikationen durchzuführen","pt":"Execute testes de ponta a ponta HTTP com o ACP HTTP E2E Tester, um microframework GenAI para automação de testes","ru":"Используйте ACP HTTP E2E Tester для автоматизации тестирования: ИИ Агенты для проверки HTTP","ar":"اجري اختبارات نهاية إلى نهاية HTTP باستخدام ACP HTTP E2E Tester، إطار عمل دقيق للآلات الذكية"},"definition":{"en":"acp-http-e2e-tester is a GenAI Microframework that allows running deterministic ACP HTTP tests from a JSON spec, covering various aspects of the HTTP protocol.","zh":"ACP HTTP E2E 测试器是一种测试工具，用于基于 JSON 规范运行确定性的 ACP HTTP 测试流程","ja":"ACP HTTP E2E テスターは、JSON仕様に基づいて確定的ACP HTTPテストフローを実行するテストツールです","ko":"ACP HTTP E2E 테스터는 JSON 규격에 따라 결정적인 ACP HTTP 테스트 흐름을 실행하는 테스트 도구입니다","es":"acp-http-e2e-tester es una herramienta de pruebas E2E que utiliza especificaciones JSON para ejecutar flujos de pruebas determinísticas","fr":"acp-http-e2e-tester est un outil de test E2E qui utilise des spécifications JSON pour exécuter des flux de test déterministes","de":"acp-http-e2e-tester ist ein E2E-Testtool, das JSON-Spezifikationen verwendet, um deterministische Testflüsse auszuführen","pt":"O ACP HTTP E2E Tester é um microframework para testes de ponta a ponta HTTP","ru":"ACP HTTP E2E Tester - это микрофреймворк для автоматизации тестирования HTTP","ar":"ACP HTTP E2E Tester هو إطار عمل دقيق لاختبارات نهاية إلى نهاية HTTP"},"features":{"en":["Runs deterministic ACP HTTP test flows from a JSON spec","Supports auth, tenant discovery, entity create/lookup, and action execution","Enables event assertions and negative/positive create checks","Allows for one-command runs with optional Hypercorn spawn","Provides status lines and assertion output for easy review"],"zh":["支持 JSON 规范","Hypercorn 集成","确定性的 ACP HTTP 测试流程","支持 auth、tenant discovery、entity create/lookup、action execution、event assertions 和 negative/positive create checks"],"ja":["JSON仕様のサポート","Hypercornの統合","確定的ACP HTTPテストフロー","auth、tenant discovery、entity create/lookup、action execution、event assertionsおよびnegative/positive create checksのサポート"],"ko":["JSON 규격 지원","Hypercorn 통합","결정적인 ACP HTTP 테스트 흐름","auth, tenant discovery, entity create/lookup, action execution, event assertions 및 negative/positive create checks 지원"],"es":["Ejecución de pruebas E2E determinísticas con especificaciones JSON","Soporte para autenticación y descubrimiento de inquilinos","Creación y búsqueda de entidades","Ejecución de acciones y afirmaciones de eventos","Comprobaciones de creación positivas y negativas"],"fr":["Exécution de tests E2E déterministes avec des spécifications JSON","Prise en charge de l''authentification et de la découverte de locataires","Création et recherche d''entités","Exécution d''actions et d''assertions d''événements","Vérifications de création positives et négatives"],"de":["Ausführung deterministischer E2E-Tests mit JSON-Spezifikationen","Unterstützung für Authentifizierung und Mandantenerkennung","Erstellung und Suche von Entitäten","Ausführung von Aktionen und Ereignisassertionen","Überprüfung von Erstellungen positiv und negativ"],"pt":["Execução de testes de ponta a ponta HTTP com um único script","Suporte à autenticação e descoberta de locatário","Criação e busca de entidades","Execução de ações e verificação de eventos","Verificação de criação positiva e negativa"],"ru":["Автоматизация тестирования HTTP с помощью одного скрипта","Поддержка аутентификации и обнаружения арендатора","Создание и поиск сущностей","Выполнение действий и проверка событий","Проверка создания положительного и отрицательного"],"ar":["تشغيل اختبارات نهاية إلى نهاية HTTP باستخدام سكريبت واحد","دعم التوثيق والاكتشاف الإيجار","إنشاء وبحث الكيانات","تنفيذ الإجراءات ومراجعة الأحداث","مراجعة إنشاء إيجابي وسلبي"]},"keywords":{"en":["how to use acp-http-e2e-tester","acp-http-e2e-tester setup guide","acp-http-e2e-tester alternative","acp-http-e2e-tester vs other testing frameworks","acp-http-e2e-tester install","JSON spec testing with acp-http-e2e-tester"],"zh":["ACP HTTP E2E 测试器","GenAI Microframework","JSON 规范","Hypercorn","测试自动化","AIエージェント","端到端测试"],"ja":["ACP HTTP E2E テスター","GenAI Microframework","JSON仕様","Hypercorn","テスト自動化","AIエージェント","エンドツーエンドテスト"],"ko":["ACP HTTP E2E 테스터","GenAI Microframework","JSON 규격","Hypercorn","테스트 자동화","AI 에이전트","엔드 투 엔드 테스트"],"es":["acp-http-e2e-tester","pruebas E2E","especificaciones JSON","framework de microservicios GenAI","herramientas de pruebas AI","desarrollo de software","pruebas automatizadas"],"fr":["acp-http-e2e-tester","tests E2E","spécifications JSON","microframework GenAI","outils de test AI","développement de logiciels","tests automatisés"],"de":["acp-http-e2e-tester","E2E-Tests","JSON-Spezifikationen","GenAI-Mikroframework","AI-Testtools","Softwareentwicklung","automatisierte Tests"],"pt":["ACP HTTP E2E Tester","testes de ponta a ponta HTTP","microframework GenAI","automação de testes","script de teste","autenticação","descoberta de locatário","criação de entidades"],"ru":["ACP HTTP E2E Tester","автоматизация тестирования HTTP","микрофреймворк GenAI","ИИ Агенты","скрипт тестирования","аутентификация","обнаружение арендатора","создание сущностей"],"ar":["ACP HTTP E2E Tester","اختبارات نهاية إلى نهاية HTTP","إطار عمل دقيق للآلات الذكية","آلات ذكية","سكريبت الاختبار","توثيق","اكتشاف الإيجار","إنشاء الكيانات"]}},"owner":"vorsocom","repo":"mugen","repoPath":"vorsocom/mugen","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.586Z","topics":[],"category":"community","skillMd":{"name":"acp-http-e2e-tester","description":"Run repeatable ACP plugin HTTP end-to-end checks in mugen using Hypercorn and curl. Use when validating a new or changed ACP-based plugin resource/action surface, reproducing API behavior regressions, or confirming expected HTTP status/body behavior for tenant-scoped CRUD and `$action` transitions.","bodyPreview":"# ACP HTTP E2E Tester\n\n## Overview\n\nRun a deterministic ACP HTTP test flow from a JSON spec.\nUse one script for auth, tenant discovery, entity create/lookup, action execution, event assertions, and negative/positive create checks.\n\n## Workflow\n\n1. Create or copy a spec JSON file.\n2. Optionally enable Hypercorn spawn in the spec for one-command runs.\n3. Run the script and review the status lines and assertion output.\n4. Treat any non-zero exit as a failing e2e check.\n\n## Commands\n\nRun from reposi","body":"# ACP HTTP E2E Tester\n\n## Overview\n\nRun a deterministic ACP HTTP test flow from a JSON spec.\nUse one script for auth, tenant discovery, entity create/lookup, action execution, event assertions, and negative/positive create checks.\n\n## Workflow\n\n1. Create or copy a spec JSON file.\n2. Optionally enable Hypercorn spawn in the spec for one-command runs.\n3. Run the script and review the status lines and assertion output.\n4. Treat any non-zero exit as a failing e2e check.\n\n## Commands\n\nRun from repository root:\n\n```bash\nbash .codex/skills/acp-http-e2e-tester/scripts/run_acp_http_e2e.sh \\\n  --spec .codex/skills/acp-http-e2e-tester/references/ops-case-example.json\n```\n\nPrint effective config without executing HTTP calls:\n\n```bash\nbash .codex/skills/acp-http-e2e-tester/scripts/run_acp_http_e2e.sh \\\n  --spec .codex/skills/acp-http-e2e-tester/references/spec-template.json \\\n  --print-config\n```\n\n## Spec Format\n\nStart from:\n`references/spec-template.json`\n\nUse:\n`references/ops-case-example.json`\n\nKey fields:\n- `runtime.spawn_hypercorn`: start/stop Hypercorn inside the script.\n- `runtime.hypercorn_cmd`: exact command used when spawn is enabled.\n- `base_url`: ACP API base path, usually `http://127.0.0.1:8081/api/core/acp/v1`.\n- `credentials`: login username/password (inject test credentials at runtime; do\n  not commit real secrets).\n- `tenant_id`: optional; if null, first tenant from `Tenants` is used.\n- `entity_set`: target collection under tenant route.\n- `create_payload`: JSON payload for entity create.\n- `lookup`: identify created entity by field/value.\n- `actions`: ordered entity `$action` calls; payload supports placeholders:\n  `__ROW_VERSION__`, `__ENTITY_ID__`, `__TENANT_ID__`, `__USER_ID__`.\n- `assertions`: optional final checks (`final_status`, expected event sequence).\n- `negative_creates` and `positive_creates`: optional create-path checks on any entity set.\n\n## Output Expectations\n\nThe script prints one line per step:\n- HTTP status for each endpoint\n- entity id / row-version / status progression\n- assertion pass/fail lines for final status and event sequence\n\nExit code:\n- `0`: all checks passed\n- non-zero: one or more HTTP or assertion failures\n\n## Operating Rules\n\n- Keep specs plugin-specific; do not hardcode business routing policy in the script.\n- Use `negative_creates` to verify validation behavior (expected 4xx) for newly added schemas.\n- Keep `lookup.value` unique per run (timestamp suffix) to avoid selecting stale rows.\n- If running with spawned Hypercorn, confirm the command uses the correct interpreter and `PYTHONPATH` for local dependencies.\n- Keep reference specs sanitized; avoid committing machine-specific absolute\n  paths or real credentials.\n"},"lastSynced":"2026-03-08T02:11:58.049Z","agentAnalysis":{"suitability":{"en":"Perfect for API Testing Agents needing automated ACP HTTP test flow execution from JSON specs.","zh":"适用于需要从JSON规范自动执行ACP HTTP测试流的API测试代理。","ja":"JSON仕様から自動でACP HTTPテストフローを実行する必要があるAPIテストエージェントに適しています。","ko":"JSON 사양에서 자동으로 ACP HTTP 테스트 흐름을 실행해야 하는 API 테스트 에이전트에 적합합니다.","es":"Perfecto para Agentes de Pruebas de API que necesitan ejecución automática de flujos de prueba de ACP HTTP desde especificaciones JSON.","fr":"Parfait pour les agents de test d''API nécessitant l''exécution automatisée de flux de test ACP HTTP à partir de spécifications JSON.","de":"Perfekt für API-Testagenten, die eine automatisierte Ausführung von ACP-HTTP-Testflüssen aus JSON-Spezifikationen benötigen.","pt":"Perfeito para Agentes de Teste de API que precisam de execução automática de fluxo de teste HTTP ACP a partir de especificações JSON.","ru":"Идеально подходит для агентов тестирования API, которым требуется автоматизированная обработка потока тестирования HTTP ACP из спецификаций JSON.","ar":"مثالي لعميل اختبار واجهة برمجة التطبيقات التي تحتاج إلى تنفيذ تلقائي لتدفق اختبار HTTP ACP من المواصفات JSON."},"recommendation":{"en":"Empowers agents to run deterministic ACP HTTP test flows covering auth, tenant discovery, entity creation, and event assertions using JSON specifications and Hypercorn spawn for one-command runs.","zh":"赋予代理运行确定性的ACP HTTP测试流，涵盖身份验证、租户发现、实体创建和事件断言，使用JSON规范和Hypercorn spawn进行一键运行。","ja":"エージェントが決定的なACP HTTPテストフローを実行できるようにし、認証、テナントの検出、エンティティの作成、およびイベントのアサーションをJSON仕様とHypercornスパーンを使用して一つのコマンドで実行します。","ko":"에이전트가 결정적인 ACP HTTP 테스트 흐름을 실행할 수 있도록 하며, 인증, 테넌트 검색, 엔티티 생성 및 이벤트斷言을 JSON 사양 및 Hypercorn 스폰을 사용하여 한 번의 명령으로 실행합니다.","es":"Habilita a los agentes a ejecutar flujos de prueba de ACP HTTP deterministas que cubren autenticación, descubrimiento de inquilinos, creación de entidades y afirmaciones de eventos utilizando especificaciones JSON y Hypercorn spawn para ejecuciones de un solo comando.","fr":"Permet aux agents d''exécuter des flux de test ACP HTTP déterministes couvrant l''authentification, la découverte de locataires, la création d''entités et les assertions d''événements en utilisant des spécifications JSON et Hypercorn spawn pour des exécutions en un seul commande.","de":"Ermächtigt die Agenten, deterministische ACP-HTTP-Testflüsse auszuführen, die Authentifizierung, Mandantenerkennung, Entitätenerstellung und Ereignisbehauptungen abdecken, indem JSON-Spezifikationen und Hypercorn-Spawn für Ausführungen in einem einzigen Befehl verwendet werden.","pt":"Habilita os agentes a executar fluxos de teste HTTP ACP determinísticos que abordam autenticação, descoberta de locatário, criação de entidade e afirmações de eventos usando especificações JSON e spawn do Hypercorn para execuções de um comando.","ru":"Наделяет агентов возможностью запускать детерминированные потоки тестирования HTTP ACP, охватывающие аутентификацию, обнаружение арендатора, создание сущности и утверждения событий, используя спецификации JSON и spawn Hypercorn для однокомандных запусков.","ar":"يمنح الوكلاء khảية تشغيل تدفقات اختبار HTTP ACP محددة التي تغطي المصادقة واكتشاف المستأجر وإنشاء الكيان وإفادات الأحداث باستخدام المواصفات JSON وspawn Hypercorn لتشغيل الأوامر واحدة."},"useCases":{"en":["Automating ACP HTTP protocol testing","Validating JSON specs for entity creation","Debugging auth and tenant discovery issues"],"zh":["自动化ACP HTTP协议测试","验证实体创建的JSON规范","调试身份验证和租户发现问题"],"ja":["ACP HTTPプロトコルテストの自動化","エンティティの作成のためのJSON仕様の検証","認証およびテナントの検出に関する問題のデバッグ"],"ko":["ACP HTTP 프로토콜 테스트 자동화","엔티티 생성을 위한 JSON 사양 확인","인증 및 테넌트 검색 관련 문제 디버깅"],"es":["Automatización de pruebas de protocolo ACP HTTP","Validación de especificaciones JSON para la creación de entidades","Depuración de problemas de autenticación y descubrimiento de inquilinos"],"fr":["Automatisation des tests de protocole ACP HTTP","Validation des spécifications JSON pour la création d''entités","Débogage des problèmes d''authentification et de découverte de locataires"],"de":["Automatisierung von ACP-HTTP-Protokolltests","Validierung von JSON-Spezifikationen für die Entitätenerstellung","Fehlerbehebung bei Authentifizierungs- und Mandantenerkennungsproblemen"],"pt":["Automatizar testes de protocolo HTTP ACP","Validar especificações JSON para criação de entidade","Depurar problemas de autenticação e descoberta de locatário"],"ru":["Автоматизировать тестирование протокола HTTP ACP","Проверять спецификации JSON для создания сущности","Отлаживать проблемы аутентификации и обнаружения арендатора"],"ar":["أتمتة اختبار بروتوكول HTTP ACP","التحقق من صحة مواصفات JSON لإنشاء الكيان","تصحيح أخطاء المصادقة واكتشاف المستأجر"]},"limitations":{"en":["Requires JSON spec file","Limited to ACP HTTP protocol testing"],"zh":["需要JSON规范文件","仅限ACP HTTP协议测试"],"ja":["JSON仕様ファイルが必要","ACP HTTPプロトコルテストに限定"],"ko":["JSON 사양 파일이 필요","ACP HTTP 프로토콜 테스트에만 제한"],"es":["Requiere archivo de especificación JSON","Limitado a pruebas de protocolo ACP HTTP"],"fr":["Nécessite un fichier de spécification JSON","Limité aux tests de protocole ACP HTTP"],"de":["Benötigt eine JSON-Spezifikationsdatei","Begrenzt auf ACP-HTTP-Protokolltests"],"pt":["Requer arquivo de especificação JSON","Limitado ao teste de protocolo HTTP ACP"],"ru":["Требует файла спецификации JSON","Ограничен тестированием протокола HTTP ACP"],"ar":["يتطلب ملف مواصفات JSON","محدود باختبار بروتوكول HTTP ACP"]},"version":4},"contentHash":"c6ffb9e6437f799b03d52287fd573a3f690b3f1af7d759353f0b27905352f5dc","qualityScore":60}');
