INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vorsocom/mugen/acp-http-e2e-tester', 'acp-http-e2e-tester', 'vorsocom', 'mugen', 'community', 'acp-http-e2e-tester vorsocom mugen community The acp-http-e2e-tester skill enables developers to run deterministic ACP HTTP test flows from a JSON spec, covering auth, tenant discovery, and entity creation. It benefits developers working with HTTP protocols and JSON specifications. ACP HTTP E2E 测试器是一种基于 GenAI Microframework 的测试工具，支持 JSON 规范和 Hypercorn 集成。它可以实现端到端测试的自动化和效率提升 ACP HTTP E2E テスターは、GenAI Microframework を基盤とするテストツールです。JSON仕様とHypercornの統合をサポートし、テスト自動化と効率化を実現します ACP HTTP E2E 테스터는 GenAI Microframework 기반의 테스트 도구로 JSON 규격 및 Hypercorn 통합을 지원합니다. 엔드 투 엔드 테스트의 자동화 및 효율성을 높여줍니다 El framework de microservicios GenAI permite ejecutar pruebas E2E determinísticas con especificaciones JSON Le microframework GenAI permet d''exécuter des tests E2E déterministes avec des spécifications JSON Das GenAI-Mikroframework ermöglicht die Ausführung deterministischer E2E-Tests mit JSON-Spezifikationen O ACP HTTP E2E Tester é um microframework GenAI para execução de testes de ponta a ponta HTTP. Ele permite a automação de testes com um único script ACP HTTP E2E Tester - это микрофреймворк GenAI для автоматизации тестирования HTTP. Он позволяет использовать один скрипт для проверки ACP HTTP E2E Tester هو إطار عمل دقيق للآلات الذكية لتشغيل اختبارات نهاية إلى نهاية HTTP. يمكنه توفير automação الاختبارات باستخدام سكريبت واحد how to use acp-http-e2e-tester acp-http-e2e-tester setup guide acp-http-e2e-tester alternative acp-http-e2e-tester vs other testing frameworks acp-http-e2e-tester install JSON spec testing with acp-http-e2e-tester ACP HTTP E2E 测试器 GenAI Microframework JSON 规范 Hypercorn 测试自动化 AIエージェント 端到端测试 Runs deterministic ACP HTTP test flows from a JSON spec Supports auth, tenant discovery, entity create/lookup, and action execution Enables event assertions and negative/positive create checks Allows for one-command runs with optional Hypercorn spawn Provides status lines and assertion output for easy review acp-http-e2e-tester is a GenAI Microframework that allows running deterministic ACP HTTP tests from a JSON spec, covering various aspects of the HTTP protocol.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AcidicSoil/DSPyTeach/flow-builder', 'community', 'AcidicSoil', 'DSPyTeach', 'AcidicSoil/DSPyTeach', 'flow-builder', 0, 0, 60, '2026-03-08T01:57:15.593Z', '2026-03-08T02:12:04.377Z', 'a58aca684fcc6f06dbc24995beb903799717a2a31447c7374d290bbbc3873d4e', '{"id":"AcidicSoil/DSPyTeach/flow-builder","name":"flow-builder","description":{"en":"The flow-builder skill guides the build phase of implementation, helping developers execute action items and verify completion. It''s ideal for developers looking to start coding and implement features efficiently.","zh":"Flow Builder 是一个实现工作流自动化的工具，通过验证准备、开始实现、执行操作项、验证完成和标记完成等步骤来指导构建阶段","ja":"Flow Builder は、実装自動化を実現するツールです。準備の検証、実装の開始、操作項目の実行、完了の検証、完了のマークなど、ビルド段階を導きます","ko":"Flow Builder는 워크플로 자동화를 구현하는 도구로, 준비 확인, 구현 시작, 작업 항목 실행, 완료 확인 및 완료 표시 등으로 구축 단계를 안내합니다","es":"Flow Builder es una habilidad que guía la fase de implementación siguiendo los patrones del marco de flujo de trabajo","fr":"Flow Builder est une compétence qui guide la phase de mise en œuvre en suivant les modèles du cadre de flux de travail","de":"Flow Builder ist eine Fähigkeit, die die Implementierungsphase nach den Mustern des Arbeitsablaufrahmens leitet","pt":"O Flow Builder é uma habilidade que guia a fase de build, verificando a prontidão, iniciando a implementação e executando ações até a conclusão","ru":"Flow Builder — это навык, который руководит фазой построения, проверяя готовность, запуская реализацию и выполняя действия до завершения","ar":"Flow Builder هو مهارة توجيهية للطور الإنشائي، وتحقق من الجاهزية، وتبدأ التنفيذ، وتنفذ العناصر حتى الإكمال"},"seo":{"title":{"en":"flow-builder: Implementation Setup Guide | AI Agent Skill","zh":"Flow Builder 设置指南：实现工作流自动化","ja":"Flow Builder 導入ガイド：AIエージェントを使用した実装自動化","ko":"Flow Builder 설정 가이드: 워크플로 자동화 구현","es":"Guía de Configuración de Flow Builder para Desarrolladores","fr":"Guide d''Installation de Flow Builder pour les Développeurs","de":"Einrichtungsleitfaden für Flow Builder-Entwickler","pt":"Guia de Configuração do Flow Builder para Desenvolvedores","ru":"Настройка Flow Builder: Руководство для Разработчиков ИИ ...","ar":"دليل إعداد Flow Builder للמطورين باستخدام أدوات الذكاء ال..."},"description":{"en":"Get started with flow-builder and streamline your implementation process - learn how to execute action items and verify completion with ease","zh":"了解 Flow Builder 的功能和实现原理，自动化工作流和提高开发效率","ja":"Flow Builder を使用して AIエージェントを実装し、開発効率を向上させる","ko":"Flow Builder의 기능과 구현 원리를 알아보고 워크플로 자동화와 개발 효율성을 높여보세요","es":"Aprende a implementar el patrón de flujo de trabajo con Flow Builder, la herramienta de AI para desarrolladores","fr":"Découvrez comment mettre en œuvre le modèle de flux de travail avec Flow Builder, l''outil d''IA pour les développeurs","de":"Erfahren Sie, wie Sie das Arbeitsablaufmuster mit Flow Builder implementieren, dem AI-Tool für Entwickler","pt":"Aprenda a implementar o Flow Builder com eficiência, seguindo os padrões do framework Flow e melhorando sua produtividade como desenvolvedor","ru":"Освойте Flow Builder и повысьте свою продуктивность как разработчика, следуя рекомендациям ИИ Агентов и шаблонам Flow","ar":"تعلم كيفية تطبيق Flow Builder بفعالية، باتباع نمط إطار العمل Flow وتحسين إنتاجيتك كمتطور باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"flow-builder is a skill that executes implementation work following Flow framework patterns, guiding the build phase from readiness to completion","zh":"Flow Builder 是一个实现工作流自动化的工具，通过一系列步骤来指导构建阶段","ja":"Flow Builder は、実装自動化を実現するツールです","ko":"Flow Builder는 워크플로 자동화를 구현하는 도구로, 구축 단계를 안내합니다","es":"Flow Builder es una herramienta de AI que ayuda a los desarrolladores a implementar patrones de flujo de trabajo","fr":"Flow Builder est un outil d''IA qui aide les développeurs à mettre en œuvre des modèles de flux de travail","de":"Flow Builder ist ein AI-Tool, das Entwicklern hilft, Arbeitsablaufmuster zu implementieren","pt":"Flow Builder é uma habilidade que executa trabalho de implementação seguindo padrões do framework Flow","ru":"Flow Builder — это навык, который выполняет работу реализации, следуя шаблонам Flow","ar":"Flow Builder هو مهارة تنفذ عمل التطبيق متبعةً أنماط إطار العمل Flow"},"features":{"en":["Guides the build phase: verify readiness → start implementation → execute action items → verify completion → mark complete","Executes implementation work following Flow framework patterns","Supports commands like ''Let''s implement this'', ''Start coding'', and ''Execute the action items''","Helps developers start coding and implement features efficiently","Verifies completion and marks tasks as complete","Follows Flow''s Core Principles for implementation"],"zh":["验证准备和开始实现","执行操作项和验证完成","标记完成和跟踪进度","支持 Flow 框架模式","提高开发效率和自动化程度"],"ja":["準備の検証と実装の開始","操作項目の実行と完了の検証","完了のマークと進度の追跡","Flow フレームワークパターンのサポート","開発効率と自動化度の向上"],"ko":["준비 확인과 구현 시작","작업 항목 실행과 완료 확인","완료 표시와 진행 상황 추적","Flow 프레임워크 패턴 지원","개발 효율성과 자동화 정도 향상"],"es":["Verificación de la preparación para la implementación","Inicio de la implementación siguiendo el patrón de flujo de trabajo","Ejecución de elementos de acción","Verificación de la finalización de la implementación","Marcado de la implementación como completada"],"fr":["Vérification de la préparation pour la mise en œuvre","Lancement de la mise en œuvre en suivant le modèle de flux de travail","Exécution des éléments d''action","Vérification de la fin de la mise en œuvre","Marquage de la mise en œuvre comme terminée"],"de":["Überprüfung der Vorbereitung für die Implementierung","Starten der Implementierung nach dem Arbeitsablaufmuster","Ausführung von Aktionselementen","Überprüfung der Fertigstellung der Implementierung","Markierung der Implementierung als abgeschlossen"],"pt":["Verificação de prontidão para implementação","Início da implementação com base nos padrões do framework Flow","Execução de ações até a conclusão","Verificação de conclusão e marcação como completa","Integração com o ciclo de vida do desenvolvimento de software"],"ru":["Проверка готовности для реализации","Запуск реализации на основе шаблонов Flow","Выполнение действий до завершения","Проверка завершения и маркировка как завершенной","Интеграция с циклом жизни разработки программного обеспечения"],"ar":["تحقق من الجاهزية للتنفيذ","بدء التنفيذ بالاعتماد على أنماط إطار العمل Flow","تنفيذ العناصر حتى الإكمال","تحقق من الإكمال ووضع العلامة على أنها مكتملة","التكامل مع دورة حياة تطوير البرمجيات"]},"keywords":{"en":["how to use flow-builder","flow-builder setup guide","what is flow-builder","flow-builder alternative","flow-builder vs other implementation tools","flow-builder install","flow-builder implementation philosophy","flow-builder for AI agents","flow-builder best practices"],"zh":["Flow Builder","工作流自动化","实现工作流","开发效率","自动化工具","Flow 框架模式","AI工具","开发自动化"],"ja":["Flow Builder","実装自動化","AIエージェント","開発効率","自動化ツール","Flow フレームワークパターン","開発自動化","AIツール"],"ko":["Flow Builder","워크플로 자동화","구현 워크플로","개발 효율성","자동화 도구","Flow 프레임워크 패턴","AI 에이전트","개발 자동화"],"es":["herramientas de AI para desarrolladores","patrones de flujo de trabajo","implementación de software","desarrollo de aplicaciones","Flow Builder","guía de configuración"],"fr":["outils d''IA pour les développeurs","modèles de flux de travail","mise en œuvre de logiciels","développement d''applications","Flow Builder","guide d''installation"],"de":["AI-Tools für Entwickler","Arbeitsablaufmuster","Implementierung von Software","Anwendungsentwicklung","Flow Builder","Einrichtungsleitfaden"],"pt":["Flow Builder","desenvolvimento de software","framework Flow","implementação de código","produtividade de desenvolvedores","ferramentas de desenvolvimento","guia de configuração"],"ru":["Flow Builder","ИИ Агенты","разработка программного обеспечения","шаблоны Flow","реализация кода","продуктивность разработчиков","инструменты разработки","руководство по настройке"],"ar":["Flow Builder","أدوات الذكاء الاصطناعي","تطوير البرمجيات","أنماط إطار العمل Flow","تنفيذ الكود","إنتاجية المطورين","أدوات التطوير","دليل الإعداد"]}},"owner":"AcidicSoil","repo":"DSPyTeach","repoPath":"AcidicSoil/DSPyTeach","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.593Z","topics":[],"category":"community","skillMd":{"name":"flow-builder","description":"Execute implementation work with gate checks and verification. Use when user wants to code, build features, implement iterations, or execute action items. Enforces gates, guides workflow, tracks progress.","bodyPreview":"# Flow Builder\n\nExecute implementation work following Flow framework patterns. This skill guides the build phase: verify readiness → start implementation → execute action items → verify completion → mark complete.\n\n## When to Use This Skill\n\nActivate when the user wants to start coding:\n- \"Let''s implement this\"\n- \"Start coding\"\n- \"Build the feature\"\n- \"Time to write code\"\n- \"Ready to implement\"\n- \"Execute the action items\"\n- \"Begin implementation\"\n\n## Implementation Philosophy\n\n**Flow''s Core Pri","body":"# Flow Builder\n\nExecute implementation work following Flow framework patterns. This skill guides the build phase: verify readiness → start implementation → execute action items → verify completion → mark complete.\n\n## When to Use This Skill\n\nActivate when the user wants to start coding:\n- \"Let''s implement this\"\n- \"Start coding\"\n- \"Build the feature\"\n- \"Time to write code\"\n- \"Ready to implement\"\n- \"Execute the action items\"\n- \"Begin implementation\"\n\n## Implementation Philosophy\n\n**Flow''s Core Principle**: Design before code. Implementation happens AFTER brainstorming is complete (if needed) and pre-implementation tasks are done.\n\n**Key Gates**:\n- **Pre-Implementation Gate**: Brainstorming must be ✅ COMPLETE (if iteration had brainstorming)\n- **Pre-Tasks Gate**: All pre-implementation tasks must be ✅ COMPLETE\n- **Verification Gate**: All action items done, tests passing, ready for next work\n\n**Implementation Pattern**: Start → Execute → Verify → Complete\n\n## Pre-Implementation Gate Check\n\nBefore starting ANY implementation, verify readiness:\n\n### Check 1: Brainstorming Status (if applicable)\n\n```\nIF iteration has brainstorming section:\n    IF brainstorming status ≠ ✅ COMPLETE:\n        ❌ BLOCK implementation\n        SUGGEST: \"Brainstorming must be completed first. Use `/flow-next-subject` to continue brainstorming.\"\n    ELSE:\n        ✅ PASS gate\nELSE:\n    ✅ PASS gate (no brainstorming needed)\n```\n\n### Check 2: Pre-Implementation Tasks (if applicable)\n\n```\nIF iteration has \"Pre-Implementation Tasks\" section:\n    IF any pre-task status ≠ ✅ COMPLETE:\n        ❌ BLOCK implementation\n        LIST incomplete pre-tasks\n        SUGGEST: \"Complete pre-tasks first, then use `/flow-implement-start`\"\n    ELSE:\n        ✅ PASS gate\nELSE:\n    ✅ PASS gate (no pre-tasks)\n```\n\n### Check 3: Iteration Status\n\n```\nIF iteration status = 🚧 IN PROGRESS:\n    ✅ PASS (already implementing)\nIF iteration status = 🎨 READY or ⏳ PENDING:\n    SUGGEST: \"Use `/flow-implement-start` to begin implementation\"\n```\n\n## Implementation Workflow\n\n### Step 1: Start Implementation\n\n**Command**: `/flow-implement-start`\n\n**What it does**:\n- Marks iteration 🚧 IN PROGRESS\n- Creates \"Implementation\" section in task file\n- Updates DASHBOARD.md current work\n\n**When to suggest**: User is ready to code and gates passed\n\n### Step 2: Execute Action Items\n\n**Sequential Execution**:\n1. Read action items from iteration (or brainstorming Type D subjects)\n2. Execute each action item in order\n3. Check off items as completed: `- [x] Action item`\n4. Document progress in \"Implementation Notes\"\n\n**Parallel Execution** (when safe):\n- If action items are independent (no dependencies)\n- Example: Creating multiple unrelated files\n- Still check off sequentially for tracking\n\n**Handling Blockers**:\n```\nIF encounter blocker during implementation:\n    DOCUMENT blocker in Implementation Notes\n    ASSESS severity:\n        - Minor (< 15 min fix): Handle and continue\n        - Major (> 15 min, out of scope): STOP and notify user\n        - Blocking (cannot proceed): Mark iteration ❌ BLOCKED, notify user\n```\n\n### Step 3: Verify Completion\n\nBefore marking iteration complete, verify:\n\n**Verification Checklist**:\n- [ ] All action items checked off (✅)\n- [ ] Code compiles/runs without errors\n- [ ] Tests passing (if applicable)\n- [ ] Files modified documented\n- [ ] Implementation notes updated\n- [ ] No unresolved blockers\n\n**Testing Strategy** (from PLAN.md):\n- Follow Testing Strategy section in PLAN.md\n- Run tests according to project conventions\n- Document test results in Implementation Notes\n\n### Step 4: Complete Implementation\n\n**Command**: `/flow-implement-complete`\n\n**What it does**:\n- Marks iteration ✅ COMPLETE\n- Updates completion date\n- Updates DASHBOARD.md progress\n- Advances to next iteration\n\n**When to suggest**: All verification criteria met\n\n## Implementation Slash Commands\n\n### `/flow-implement-start`\n\n**Use when**: Starting implementation for current iteration\n\n**Prerequisites**:\n- Brainstorming ✅ COMPLETE (if applicable)\n- Pre-tasks ✅ COMPLETE (if applicable)\n- Iteration status = 🎨 READY or ⏳ PENDING\n\n**Effect**:\n- Changes iteration status to 🚧 IN PROGRESS\n- Creates implementation section in task file\n- Updates DASHBOARD.md\n\n### `/flow-implement-complete`\n\n**Use when**: All action items done and verified\n\n**Prerequisites**:\n- All action items checked off\n- Verification criteria met\n- No unresolved blockers\n\n**Effect**:\n- Marks iteration ✅ COMPLETE\n- Updates completion date\n- Advances to next iteration or task\n\n## Action Item Execution Patterns\n\n### Pattern 1: Sequential Implementation\n\n**Use when**: Action items depend on each other\n\n```markdown\nAction Items:\n- [x] Create database schema\n- [x] Implement data access layer (depends on schema)\n- [x] Add service layer (depends on DAL)\n- [x] Create API endpoints (depends on service)\n```\n\n**Approach**:\n1. Complete item 1\n2. Verify item 1 works\n3. Move to item 2\n4. Repeat until all done\n\n### Pattern 2: Parallel Implementation\n\n**Use when**: Action items are independent\n\n```markdown\nAction Items:\n- [ ] Create logger utility\n- [ ] Create validator utility\n- [ ] Create formatter utility\n```\n\n**Approach**:\n1. Create all three files\n2. Verify each works independently\n3. Check off all items\n\n### Pattern 3: Incremental Verification\n\n**Use when**: Complex implementation with multiple steps\n\n```markdown\nAction Items:\n- [x] Implement basic authentication (VERIFY: can login)\n- [x] Add JWT token generation (VERIFY: tokens valid)\n- [x] Add token refresh (VERIFY: refresh works)\n- [x] Add logout (VERIFY: tokens invalidated)\n```\n\n**Approach**:\n1. Complete one action item\n2. Test/verify immediately\n3. Document verification in notes\n4. Move to next item\n\n## Pre-Implementation Tasks Pattern\n\n### What Are Pre-Implementation Tasks?\n\nSmall blocking tasks (< 30 min) that must be completed BEFORE main iteration work starts.\n\n**Examples**:\n- Refactor interface to support new pattern\n- Update enum with missing values\n- Fix bug in legacy code\n- Rename file to match convention\n\n### When to Complete Pre-Tasks\n\n```\nIF iteration has \"Pre-Implementation Tasks\" section:\n    FOR EACH pre-task:\n        Complete pre-task\n        Mark ✅ COMPLETE with date\n        Document changes in pre-task section\n    ONLY AFTER ALL PRE-TASKS DONE:\n        Run /flow-implement-start for main iteration\n```\n\n### Pre-Task Structure\n\n```markdown\n#### Pre-Implementation Tasks\n\n##### ⏳ Pre-Task 1: Update ErrorHandler to support async\n\n**Why Blocking**: Retry logic requires async error handling\n\n**Scope** (< 30 min):\n- Update ErrorHandler.ts with async support\n- Add retryAsync() method\n- Update 3 call sites\n\n**Files**:\n- src/utils/ErrorHandler.ts\n\n---\n\n##### ✅ Pre-Task 1: Update ErrorHandler to support async\n\n**Completed**: 2025-10-30\n\n**Changes Made**:\n- Added async support to ErrorHandler class\n- Implemented retryAsync() method with exponential backoff\n- Updated call sites in BillingService, PaymentService, OrderService\n- Added unit tests for async error handling\n\n**Files Modified**:\n- src/utils/ErrorHandler.ts (+42 lines)\n- tests/utils/ErrorHandler.test.ts (+28 lines)\n```\n\n## Verification Best Practices\n\n### What to Verify\n\n**Code Quality**:\n- [ ] No syntax errors\n- [ ] No linting errors\n- [ ] Follows project conventions\n- [ ] Code is readable and well-structured\n\n**Functionality**:\n- [ ] Feature works as intended\n- [ ] Edge cases handled\n- [ ] Error handling implemented\n- [ ] No regressions introduced\n\n**Testing**:\n- [ ] Unit tests pass\n- [ ] Integration tests pass (if applicable)\n- [ ] Manual testing done (if no automated tests)\n\n**Documentation**:\n- [ ] Implementation notes updated\n- [ ] Files modified list complete\n- [ ] Verification results documented\n\n### When to Mark ❌ BLOCKED\n\nMark iteration ❌ BLOCKED when:\n- External dependency not available\n- Blocker requires > 1 hour to resolve\n- Need user decision before proceeding\n- Technical limitation discovered\n\n**Blocked Pattern**:\n```markdown\n### ❌ Iteration 2: Error Handling\n\n**Status**: ❌ BLOCKED\n\n**Blocker**: Stripe SDK doesn''t support custom retry logic in v12\n\n**Options**:\nA) Downgrade to Stripe SDK v11 (supports custom retry)\nB) Wait for v13 release (eta 2 weeks)\nC) Implement wrapper around SDK calls\n\n**Waiting for**: User decision on approach\n```\n\n## Detailed Verification Guidance\n\nFor comprehensive guidance on verification, testing patterns, completion criteria, bug documentation, and decision-making, see **[VERIFICATION.md](VERIFICATION.md)**.\n\nThat resource includes:\n- **Testing Patterns**: Unit testing, integration testing, manual testing checklists, and TDD patterns with complete code examples\n- **What \"Done\" Looks Like**: 6 detailed completion criteria with examples\n- **When to Document Bugs and Issues**: Bug documentation templates, severity levels, and fix-immediately vs defer guidance\n- **Deciding: ❌ BLOCKED vs Continue**: Decision flowchart, 8 scenarios with examples, and real-world case studies\n\n## Scope Boundary Rules\n\n### When You Discover New Work\n\nDuring implementation, if you discover issues NOT in current action items:\n\n1. **STOP** - Don''t make assumptions\n2. **ASSESS** - Categorize the issue:\n   - Syntax error in file you''re editing? Fix and document\n   - Missing functionality? Discuss with user\n   - New feature idea? Defer to future iteration\n   - Blocking bug? Propose pre-implementation task\n\n3. **NOTIFY** user with structured options:\n   - **Option A**: Create pre-implementation task (< 30 min, blocking)\n   - **Option B**: Add as new brainstorming subject (design needed)\n   - **Option C**: Handle immediately (if user approves)\n   - **Option D**: Defer to separate iteration (after current work)\n\n4. **AWAIT** user decision before proceeding\n\n### Example: Scope Boundary Alert\n\n```\n⚠️ SCOPE BOUNDARY ALERT\n\nDuring implementation of Iteration 2 (Error Handling), discovered:\n\n**Issue**: PaymentService.ts uses deprecated error format that conflicts with new retry logic\n\n**Impact**: Cannot complete current action item without addressing this\n\n**Options**:\nA) Create pre-implementation task (estimated 20 min):\n   - Update PaymentService error format\n   - Update 2 call sites\n   - Add to Pre-Implementation Tasks section\n\nB) Add as brainstorming subject:\n   - Need to design error format standard across all services\n   - Affects more than just PaymentService\n\nC) Handle immediately:\n   - Fix PaymentService.ts now as part of current work\n   - Document change in Implementation Notes\n\nD) Defer to separate iteration:\n   - Work around issue for now\n   - Create new iteration for error format standardization\n\nWhich approach would you prefer?\n```\n\n\n## 🧾 UNPAIRED REQUEST CAPTURE + PLAN INSERTION RULE (CRITICAL)\n\n**Definition (unpaired request)**:\nAny user request (or sub-request) that is NOT explicitly mapped to:\n- a recognized Flow slash command (/flow-...), and/or\n- a recognized skill invocation / skill-owned workflow\n\n**Required behavior (always)**:\n1. **Do not drop it.** Capture it immediately so it becomes part of official planning.\n2. **Do not derail the current run.** Continue executing the currently selected flow command/skill as the primary task unless the user explicitly asks to switch.\n\n---\n\n### A) Immediate capture (during the run)\n\nCapture each unpaired request into the most relevant location:\n\n- **Future work / out-of-scope / “later”** → append to `.flow/BACKLOG.md`. \n- **Needs design/discussion** → add to the current iteration’s “Subjects to Discuss” list in `phase-N/task-M.md` (same format as `/flow-brainstorm-subject`). \n- **Concrete action to plan** → append to `.flow/USER_NOTES.md` under `## Action Items` (or `## Decisions` if it’s a decision), as intake material for formalization.\n\n---\n\n### B) End-of-run plan insertion (after completing the primary task)\n\nAfter finishing the current command/skill output, **promote each captured unpaired request into the active Flow plan artifacts** (planning-only; do not start implementation).\n\n**Navigation (required)**:\n- Use dashboard-first: read `.flow/DASHBOARD.md` → find current Phase/Task/Iteration → locate `phase-N/task-M.md`. \n\n**Promotion targets (choose exactly one per item):**\n1. **Belongs in the current iteration as work to do** →\n   - Add as an unchecked checkbox under the current iteration’s **single** `#### Action Items` section. \n2. **Belongs in the current iteration but needs design first** →\n   - Add as a new ⏳ entry in **Subjects to Discuss** (brainstorming), per `/flow-brainstorm-subject` format. \n3. **Too large for current iteration; should be a new iteration under the current task** →\n   - Add a new ⏳ iteration using the `/flow-iteration-add` structure (update both task file + DASHBOARD iteration counts/listing, but do not change “Current Work” pointer).\n4. **A distinct new task under the current phase** →\n   - Add a new task using `/flow-task-add` structure (create `phase-N/task-M.md` + update DASHBOARD, but do not change “Current Work” pointer). \n5. **Explicitly deferred beyond current scope/version** →\n   - Ensure it is represented in `.flow/BACKLOG.md` (and referenced from PLAN only if the user explicitly wants V2/V3 tracked there).\n\n---\n\n### End-of-run reporting (mandatory)\n\nAt the end of the response/run, include a short section:\n\n**Captured & Added to Plan**:\n- [Item] → captured in [file/section] → promoted to [DASHBOARD/Task/Iteration/Action Items/Backlog location]\n\n## Common Implementation Patterns\n\n### Pattern: Feature Implementation\n\n```\nUser: \"Let''s implement the authentication system\"\n\nAI Response:\nI''ll help you implement the authentication system. Let me check readiness:\n\n✅ Brainstorming Session - COMPLETE (4 subjects resolved)\n✅ Pre-Implementation Tasks - COMPLETE (updated User model)\n✅ Iteration Status - 🎨 READY\n\nReady to implement! Use `/flow-implement-start` to begin.\n\nAction items from brainstorming:\n1. Create AuthService class\n2. Implement login/logout methods\n3. Add JWT token generation\n4. Integrate with API endpoints\n5. Add authentication middleware\n\nEstimated time: 3-4 hours\n\nShould I start implementation?\n```\n\n### Pattern: Handling Blockers\n\n```\nUser: \"Start implementing the payment integration\"\n\nAI Response:\nI''ll help you implement payment integration. Let me check readiness:\n\n❌ Pre-Implementation Tasks - INCOMPLETE\n\nFound 2 incomplete pre-tasks:\n1. ⏳ Pre-Task 1: Refactor PaymentConfig interface\n2. ⏳ Pre-Task 2: Update environment variables\n\nThese tasks must be completed before main implementation. Should I help you complete them now?\n```\n\n### Pattern: Verification Before Completion\n\n```\nUser: \"Are we done with this iteration?\"\n\nAI Response:\nLet me verify completion criteria:\n\n✅ All action items checked off (5/5)\n✅ Code compiles without errors\n✅ Tests passing (unit: 12/12, integration: 3/3)\n✅ Files modified documented (4 files)\n✅ Implementation notes updated\n✅ No unresolved blockers\n\nVerification complete! All criteria met.\n\nUse `/flow-implement-complete` to mark this iteration done and move to the next one.\n```\n\n### Pattern: Incremental Progress\n\n```\nUser: \"How''s the implementation going?\"\n\nAI Response:\nImplementation progress for Iteration 2: Error Handling\n\nCompleted (3/5):\n- [x] Create RetryPolicy class\n- [x] Implement exponential backoff algorithm\n- [x] Add configuration for max retries\n\nIn Progress (1/5):\n- [ ] Integrate with StripeClient ← CURRENT (60% done)\n\nPending (1/5):\n- [ ] Add tests for retry scenarios\n\nEstimated completion: 1 hour\n\nWorking on integrating RetryPolicy with StripeClient.ts. Will move to tests next.\n```\n\n## Examples\n\n### Example 1: Starting Implementation After Brainstorming\n\n```\nUser: \"Let''s start building the retry logic\"\n\nAI Process:\n1. Read current iteration from task file\n2. Check brainstorming status: ✅ COMPLETE (4 subjects resolved)\n3. Check pre-tasks: ✅ COMPLETE (updated ErrorHandler.ts)\n4. Verify iteration status: 🎨 READY\n\nAI Response:\n\"Ready to start implementation! All gates passed:\n✅ Brainstorming complete (4 subjects resolved)\n✅ Pre-tasks complete (ErrorHandler updated)\n✅ Iteration status: READY\n\nAction items from brainstorming (Type D):\n- [ ] Create RetryPolicy class\n- [ ] Implement exponential backoff algorithm\n- [ ] Add configuration for max retries\n- [ ] Integrate with StripeClient\n- [ ] Add tests for retry scenarios\n\nUse `/flow-implement-start` to begin, then I''ll execute these action items.\"\n```\n\n### Example 2: Handling Incomplete Pre-Tasks\n\n```\nUser: \"Start implementing the payment flow\"\n\nAI Process:\n1. Read current iteration from task file\n2. Check brainstorming: ✅ COMPLETE\n3. Check pre-tasks: Found 2 incomplete pre-tasks\n\nAI Response:\n\"Cannot start implementation yet. Pre-tasks must be completed first:\n\n❌ Pre-Implementation Tasks - INCOMPLETE\n\nBlocking tasks:\n1. ⏳ Pre-Task 1: Update PaymentStatus enum - Add PENDING_RETRY and FAILED_PERMANENT states\n2. ⏳ Pre-Task 2: Refactor PaymentService.process() - Extract validation logic to separate method\n\nThese must be done BEFORE main implementation. Should I complete these pre-tasks now?\"\n\nUser: \"Yes, complete them\"\n\nAI Process:\n1. Complete Pre-Task 1 (update enum, update switch statements)\n2. Mark Pre-Task 1 ✅ COMPLETE with date and changes\n3. Complete Pre-Task 2 (extract validation method)\n4. Mark Pre-Task 2 ✅ COMPLETE with date and changes\n5. Verify all pre-tasks done\n\nAI Response:\n\"All pre-tasks completed:\n✅ Pre-Task 1: PaymentStatus enum updated (4 files modified)\n✅ Pre-Task 2: Validation logic extracted (2 files modified)\n\nNow ready for main implementation. Use `/flow-implement-start` to begin.\"\n```\n\n### Example 3: Verification Before Marking Complete\n\n```\nUser: \"I think we''re done with this iteration\"\n\nAI Process:\n1. Read current iteration action items\n2. Check completion status\n3. Verify each completion criterion\n\nAI Response:\n\"Let me verify completion criteria:\n\n✅ Action Items (5/5):\n  - [x] Create RetryPolicy class\n  - [x] Implement exponential backoff algorithm\n  - [x] Add configuration for max retries\n  - [x] Integrate with StripeClient\n  - [x] Add tests for retry scenarios\n\n✅ Code Quality:\n  - No syntax errors\n  - Linting passed\n  - Follows project conventions\n\n✅ Tests:\n  - Unit tests: 8/8 passing\n  - Integration tests: 2/2 passing\n\n✅ Documentation:\n  - Files modified documented (4 files)\n  - Implementation notes updated\n\nAll verification criteria met! Use `/flow-implement-complete` to mark this iteration complete.\"\n```\n\n### Example 4: Scope Boundary During Implementation\n\n```\nUser: [AI is implementing action items]\n\nAI Process:\n1. Working on \"Integrate RetryPolicy with StripeClient\"\n2. Discovers PaymentService.ts uses deprecated error format\n3. Realizes this is out of scope\n\nAI Response:\n\"⚠️ SCOPE BOUNDARY ALERT\n\nWhile integrating RetryPolicy with StripeClient, I discovered:\n\n**Issue**: PaymentService.ts uses deprecated error format that conflicts with new retry logic\n\n**Impact**: Current action item can continue, but this will cause issues when we add retry to PaymentService later\n\n**Options**:\nA) Create pre-implementation task for NEXT iteration:\n   - Estimated: 20-30 minutes\n   - Update PaymentService error format\n   - Update 3 call sites\n\nB) Add as new brainstorming subject:\n   - Design error format standard across all services\n   - Affects PaymentService, BillingService, OrderService\n\nC) Handle immediately (expand current scope):\n   - Fix PaymentService.ts now\n   - Document as scope expansion\n\nD) Defer to separate iteration:\n   - Work around for now (document workaround)\n   - Create new task for error format standardization\n\nI recommend Option A (pre-task for next iteration) as it''s small and blocking for future work. Which approach would you prefer?\"\n```\n\n## Interaction with Other Flow Skills\n\n**Design Stage** (flow-designer Skill):\n- `/flow-brainstorm-start` - Design decisions\n- `/flow-brainstorm-complete` - Generate action items\n\n**Build Stage** (This Skill):\n- `/flow-implement-start` - Begin work ← YOU ARE HERE\n- `/flow-implement-complete` - Finish iteration ← YOU ARE HERE\n\n**Navigation Stage** (flow-navigator Skill):\n- `/flow-status` - Check progress\n- `/flow-next` - What to do next\n\n## References\n\n- **Implementation Pattern**: DEVELOPMENT_FRAMEWORK.md lines 1798-1836\n- **Status Markers**: DEVELOPMENT_FRAMEWORK.md lines 1872-1968\n- **Brainstorming Pattern**: DEVELOPMENT_FRAMEWORK.md lines 1167-1797\n- **Pre-Implementation Tasks**: DEVELOPMENT_FRAMEWORK.md lines 1683-1723\n- **Scope Boundary Rules**: DEVELOPMENT_FRAMEWORK.md lines 339-540\n\n## Implementation Gate Checklist\n\nBefore implementing, verify ALL gates passed:\n\n```\n[ ] Brainstorming complete (if applicable)\n[ ] Pre-implementation tasks complete (if applicable)\n[ ] Current iteration status = 🎨 READY or ⏳ PENDING\n[ ] User confirmed ready to implement\n```\n\nIf ALL checked → Use `/flow-implement-start`\n\nIf ANY unchecked → Address blockers first\n\n## Completion Checklist\n\nBefore marking complete, verify ALL criteria met:\n\n```\n[ ] All action items checked off\n[ ] Code compiles/runs\n[ ] Tests passing\n[ ] Files modified documented\n[ ] Implementation notes updated\n[ ] No unresolved blockers\n[ ] Verification completed\n```\n\nIf ALL checked → Use `/flow-implement-complete`\n\nIf ANY unchecked → Continue implementation\n"},"lastSynced":"2026-03-08T02:12:04.377Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring structured implementation workflows, such as those utilizing Flow framework patterns.","zh":"适合需要结构化实现工作流的开发代理，例如使用Flow框架模式的代理。","ja":"Flowフレームワークパターンを使用する開発エージェントなどの構造化された実装ワークフローを必要とする開発エージェントに適しています。","ko":"Flow 프레임워크 패턴을 사용하는 개발 에이전트와 같은 구조화된 구현 워크플로가 필요한 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo que requieren flujos de trabajo de implementación estructurados, como aquellos que utilizan patrones de framework de Flow.","fr":"Idéal pour les agents de développement nécessitant des flux de travail d''implémentation structurés, tels que ceux utilisant des modèles de framework Flow.","de":"Ideal für Entwicklungsmittel, die strukturierte Implementierungsworkflows erfordern, wie z.B. solche, die Muster des Flow-Frameworks verwenden.","pt":"Ideal para Agentes de Desenvolvimento que requerem fluxos de trabalho de implementação estruturados, como aqueles que utilizam padrões de framework Flow.","ru":"Идеально подходит для агентов разработки, требующих структурированных потоков реализации, таких как те, которые используют шаблоны фреймворка Flow.","ar":"مثالي لوكلاء التطوير الذين يحتاجون إلى سير عمل تنفيذية منظمة، مثل تلك التي تستخدم أنماط إطار Flow."},"recommendation":{"en":"Empowers agents to execute implementation work efficiently by verifying readiness, starting implementation, executing action items, verifying completion, and marking tasks as complete, all while following the Flow framework, enabling streamlined development processes and enhanced productivity.","zh":"通过验证准备就绪、启动实现、执行操作项、验证完成并将任务标记为完成，所有这些都遵循Flow框架，从而使代理能够高效地执行实现工作，实现流畅的开发过程和提高生产力。","ja":"実装作業を効率的に実行するために、準備就绪の確認、実装の開始、行動アイテムの実行、完了の確認、タスクの完了のマークを行い、Flowフレームワークに従って開発プロセスを合理化し、生産性を高めます。","ko":"준비 완료 확인, 구현 시작, 액션 항목 실행, 완료 확인 및 작업 완료 표시 등 모든 작업을 Flow 프레임워크에 따라 수행하여 에이전트가 효율적으로 구현 작업을 수행할 수 있도록 하며, 개발 프로세스를 간소화하고 생산성을 향상합니다.","es":"Habilita a los agentes a ejecutar el trabajo de implementación de forma eficiente verificando la preparación, iniciando la implementación, ejecutando elementos de acción, verificando la finalización y marcando las tareas como completadas, todo siguiendo el framework de Flow, lo que permite procesos de desarrollo optimizados y una mayor productividad.","fr":"Permet aux agents d''exécuter les travaux d''implémentation de manière efficiente en vérifiant la préparation, en lançant l''implémentation, en exécutant les éléments d''action, en vérifiant l''achèvement et en marquant les tâches comme complètes, le tout en suivant le framework Flow, ce qui permet des processus de développement rationalisés et une productivité améliorée.","de":"Ermöglicht es Agenten, Implementierungsarbeiten effizient auszuführen, indem sie die Bereitschaft überprüfen, die Implementierung starten, Aktivitäten ausführen, den Abschluss überprüfen und Aufgaben als abgeschlossen markieren, und zwar unter Einhaltung des Flow-Frameworks, wodurch optimierte Entwicklungsprozesse und eine erhöhte Produktivität ermöglicht werden.","pt":"Habilita os agentes a executar o trabalho de implementação de forma eficiente, verificando a prontidão, iniciando a implementação, executando itens de ação, verificando a conclusão e marcando tarefas como concluídas, tudo seguindo o framework Flow, permitindo processos de desenvolvimento otimizados e produtividade aprimorada.","ru":"Наделяет агентов возможностью выполнять реализационную работу эффективно, проверяя готовность, запуская реализацию, выполняя пункты действий, проверяя завершение и помечая задачи как завершенные, все при этом следуя фреймворку Flow, что позволяет оптимизировать процессы разработки и повысить производительность.","ar":"تمكن الوكلاء من تنفيذ عمل التنفيذ بفعالية من خلال التحقق من الجاهزية، وبدء التنفيذ، وتنفيذ بنود العمل، والتحقق من الاستكمال، وتحديد المهام على أنها مكتملة، كل ذلك مع اتباع إطار Flow، مما يتيح عمليات تطوير منسقة وزيادة الإنتاجية."},"useCases":{"en":["Automating the build phase of feature implementation","Generating step-by-step action items for complex development tasks","Verifying the completion of implementation tasks to ensure project milestones are met"],"zh":["自动化功能实现的构建阶段","为复杂的开发任务生成分步操作项","验证实现任务的完成以确保项目里程碑的实现"],"ja":["機能実装のビルド段階の自動化","複雑な開発タスクのための分ステップの行動アイテムの生成","実装タスクの完了の確認によるプロジェクトのマイルストーンの達成"],"ko":["기능 구현의 빌드 단계 자동화","복잡한 개발 작업을 위한 단계별 액션 항목 생성","구현 작업 완료 확인을 통해 프로젝트 마일스톤 달성"],"es":["Automatizar la fase de compilación de la implementación de características","Generar elementos de acción paso a paso para tareas de desarrollo complejas","Verificar la finalización de las tareas de implementación para asegurarse de que se cumplan los hitos del proyecto"],"fr":["Automatiser la phase de construction de l''implémentation des fonctionnalités","Générer des éléments d''action étape par étape pour des tâches de développement complexes","Vérifier l''achèvement des tâches d''implémentation pour s''assurer que les jalons de projet soient atteints"],"de":["Automatisieren der Build-Phase der Implementierung von Funktionen","Erzeugen von schrittweisen Aktivitäten für komplexe Entwicklungsaufgaben","Überprüfen des Abschlusses von Implementierungsaufgaben, um sicherzustellen, dass die Projektmeilensteine erreicht werden"],"pt":["Automatizar a fase de compilação da implementação de recursos","Gerar itens de ação passo a passo para tarefas de desenvolvimento complexas","Verificar a conclusão das tarefas de implementação para garantir que os marcos do projeto sejam atendidos"],"ru":["Автоматизировать фазу сборки реализации функций","Генерировать пошаговые пункты действий для сложных задач разработки","Проверить завершение задач реализации, чтобы гарантировать, что вехи проекта выполнены"],"ar":["تحويل مرحلة بناء تنفيذ الميزات إلى آلية","توليد عناصر عمل خطوة بخطوة للمهام التطويرية المعقدة","التحقق من استكمال مهام التنفيذ لضمان تحقيق أهداف المشروع"]},"limitations":{"en":["Requires understanding of Flow framework patterns","Limited to development tasks that can be structured into actionable steps"],"zh":["需要理解Flow框架模式","仅限于可以结构化为可执行步骤的开发任务"],"ja":["Flowフレームワークパターンの理解が必要","実行可能なステップに構造化できる開発タスクに限定される"],"ko":["Flow 프레임워크 패턴의 이해가 필요","실행 가능한 단계로 구조화할 수 있는 개발 작업에 한정"],"es":["Requiere comprensión de los patrones de framework de Flow","Limitado a tareas de desarrollo que se pueden estructurar en pasos ejecutables"],"fr":["Nécessite une compréhension des modèles de framework Flow","Limité aux tâches de développement qui peuvent être structurées en étapes exécutables"],"de":["Benötigt Verständnis für Muster des Flow-Frameworks","Begrenzt auf Entwicklungsaufgaben, die in ausführbare Schritte strukturiert werden können"],"pt":["Exige compreensão dos padrões de framework Flow","Limitado a tarefas de desenvolvimento que possam ser estruturadas em etapas realizáveis"],"ru":["Требует понимания шаблонов фреймворка Flow","Ограничен задачами разработки, которые можно структурировать в действенные шаги"],"ar":["يتطلب فهم أنماط إطار Flow","محدود بمهام التطوير التي يمكن تنظيمها في خطوات قابلة للتنفيذ"]},"version":4},"contentHash":"a58aca684fcc6f06dbc24995beb903799717a2a31447c7374d290bbbc3873d4e","qualityScore":60}');
