INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AcidicSoil/DSPyTeach/flow-builder', 'flow-builder', 'AcidicSoil', 'DSPyTeach', 'community', 'flow-builder AcidicSoil DSPyTeach community The flow-builder skill guides the build phase of implementation, helping developers execute action items and verify completion. It''s ideal for developers looking to start coding and implement features efficiently. Flow Builder 是一个实现工作流自动化的工具，通过验证准备、开始实现、执行操作项、验证完成和标记完成等步骤来指导构建阶段 Flow Builder は、実装自動化を実現するツールです。準備の検証、実装の開始、操作項目の実行、完了の検証、完了のマークなど、ビルド段階を導きます Flow Builder는 워크플로 자동화를 구현하는 도구로, 준비 확인, 구현 시작, 작업 항목 실행, 완료 확인 및 완료 표시 등으로 구축 단계를 안내합니다 Flow Builder es una habilidad que guía la fase de implementación siguiendo los patrones del marco de flujo de trabajo Flow Builder est une compétence qui guide la phase de mise en œuvre en suivant les modèles du cadre de flux de travail Flow Builder ist eine Fähigkeit, die die Implementierungsphase nach den Mustern des Arbeitsablaufrahmens leitet O Flow Builder é uma habilidade que guia a fase de build, verificando a prontidão, iniciando a implementação e executando ações até a conclusão Flow Builder — это навык, который руководит фазой построения, проверяя готовность, запуская реализацию и выполняя действия до завершения Flow Builder هو مهارة توجيهية للطور الإنشائي، وتحقق من الجاهزية، وتبدأ التنفيذ، وتنفذ العناصر حتى الإكمال how to use flow-builder flow-builder setup guide what is flow-builder flow-builder alternative flow-builder vs other implementation tools flow-builder install flow-builder implementation philosophy flow-builder for AI agents flow-builder best practices Flow Builder 工作流自动化 实现工作流 开发效率 自动化工具 Flow 框架模式 AI工具 开发自动化 Guides the build phase: verify readiness → start implementation → execute action items → verify completion → mark complete Executes implementation work following Flow framework patterns Supports commands like ''Let''s implement this'', ''Start coding'', and ''Execute the action items'' Helps developers start coding and implement features efficiently Verifies completion and marks tasks as complete Follows Flow''s Core Principles for implementation flow-builder is a skill that executes implementation work following Flow framework patterns, guiding the build phase from readiness to completion');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nicanac/airecord/create-slash-commands', 'community', 'nicanac', 'airecord', 'nicanac/airecord', 'create-slash-commands', 0, 0, 60, '2026-03-08T01:57:15.595Z', '2026-03-08T02:12:04.891Z', '09682e024e9b3a84cda9e9771275223388512ab64e36ba77b06edbc9d2f80e5a', '{"id":"nicanac/airecord/create-slash-commands","name":"create-slash-commands","description":{"en":"The create-slash-commands skill enables developers to create effective slash commands for Antigravity, standardizing workflows and operations. It benefits teams by allowing them to trigger reusable prompts with /command-name syntax.","zh":"创建斜杠命令，以触发可重用的提示，并标准化工作流程和操作。支持全局和项目特定命令。","ja":"スラッシュコマンドを作成して、再利用可能なプロンプトをトリガーし、ワークフローと操作を標準化します。グローバルコマンドとプロジェクト特有のコマンドをサポートしています。","ko":"슬래시 명령을 생성하여 재사용 가능한 프로ンプ트를 트리거하고 워크플ロー 및 운영을 표준화합니다. 글로벌 명령과 프로젝트 특정 명령을 지원합니다.","es":"Crea comandos de barra personalizados para Antigravity y mejora tus flujos de trabajo. Aprende a estructurar comandos con formato Markdown y YAML","fr":"Créez des commandes de barre oblique personnalisées pour Antigravity et améliorez vos flux de travail. Apprenez à structurer des commandes avec le format Markdown et YAML","de":"Erstellen Sie benutzerdefinierte Slash-Befehle für Antigravity und verbessern Sie Ihre Workflows. Lernen Sie, Befehle mit Markdown- und YAML-Format zu strukturieren","pt":"Criar comandos de barra personalizados para Antigravity com suporte a Markdown e YAML","ru":"Создание индивидуальных слэш-команд для Антигравитации с поддержкой Markdown и YAML","ar":"إنشاء أوامر شرطة مخصصة لبرنامج Antigravity مع دعم Markdown و YAML"},"seo":{"title":{"en":"create-slash-commands: Setup Guide for AI Agents","zh":"创建斜杠命令 Setup Guide - AIエージェント","ja":"スラッシュコマンドを作成する Best Practices - AIエージェント","ko":"슬래시 명령을 생성하는 방법 - AI 도구","es":"Guía de configuración de comandos de barra para Agentes d...","fr":"Configurer des commandes de barre oblique pour les outils...","de":"Einrichtungsanleitung für Slash-Befehle für KI-Agenten","pt":"Criar Comandos de Barra: Guia de Configuração para Desenv...","ru":"ИИ Агенты: Создание Слэш-Команд для Антигравитации","ar":"إنشاء أوامر شرطة: دليل الإعداد للمطورين"},"description":{"en":"Master the art of creating reusable prompts with slash commands. Learn how to structure commands with Markdown and YAML frontmatter for Antigravity.","zh":"学习如何创建有效的斜杠命令，以触发可重用的提示，并标准化工作流程和操作 - AIエージェント","ja":"スラッシュコマンドの作成方法を学び、ワークフローと操作を標準化する - AIエージェント","ko":"슬래시 명령을 생성하여 워크플ロー와 운영을 표준화하는 방법을 알아보세요 - AI 도구","es":"Aprende a crear comandos de barra efectivos para Antigravity con nuestra guía de configuración. Mejora tus flujos de trabajo con comandos personalizados","fr":"Découvrez comment configurer des commandes de barre oblique pour Antigravity avec notre guide. Améliorez vos flux de travail avec des commandes personnalisées","de":"Erfahren Sie, wie Sie effektive Slash-Befehle für Antigravity erstellen. Verbessern Sie Ihre Workflows mit benutzerdefinierten Befehlen","pt":"Aprenda a criar comandos de barra eficazes para Antigravity com Markdown e YAML frontmatter","ru":"Освойте создание слэш-команд для Антигравитации с использованием Markdown и YAML frontmatter","ar":"تعلم كيفية إنشاء أوامر شرطة فعالة لبرنامج Antigravity باستخدام Markdown و YAML frontmatter"},"definition":{"en":"create-slash-commands is a skill that enables the creation of effective slash commands for Antigravity, using Markdown and YAML frontmatter for structuring commands.","zh":"斜杠命令是一种触发可重用的提示的方式，用于标准化工作流程和操作","ja":"スラッシュコマンドは、再利用可能なプロンプトをトリガーしてワークフローと操作を標準化する方法です","ko":"슬래시 명령은 재사용 가능한 프로ンプ트를 트리거하여 워크플ロー 및 운영을 표준화하는 방법입니다","es":"Un comando de barra es una instrucción que se ejecuta en Antigravity con la sintaxis /command-name","fr":"Une commande de barre oblique est une instruction qui s''exécute dans Antigravity avec la syntaxe /command-name","de":"Ein Slash-Befehl ist eine Anweisung, die in Antigravity mit der Syntax /command-name ausgeführt wird","pt":"Comandos de barra são prompts reutilizáveis ativados por sintaxe /command-name","ru":"Слэш-команды - это повторно используемые промпты, активируемые синтаксисом /command-name","ar":"الأوامر الشرطة هي محفزات قابلة لإعادة الاستخدام يتم تنشيطها بواسطة بناء الجملة /command-name"},"features":{"en":["Supports global commands available everywhere in ~/.agent/commands/","Allows project-specific commands shared with teams in .agent/commands/","Enables structuring commands with proper formatting using Markdown","Utilizes YAML frontmatter for command configuration","Expands as prompts in the current conversation for seamless integration","Supports dynamic command execution for flexible workflows"],"zh":["支持全局和项目特定命令","使用Markdown和YAML frontmatter格式化命令","动态命令结构","标准化工作流程和操作","触发可重用的提示"],"ja":["グローバルコマンドとプロジェクト特有のコマンドをサポート","MarkdownとYAML frontmatterを使用したコマンドのフォーマット","動的なコマンド構造","ワークフローと操作の標準化","再利用可能なプロンプトのトリガー"],"ko":["글로벌 명령과 프로젝트 특정 명령을 지원","Markdown과 YAML frontmatter를 사용한 명령 형식","동적 명령 구조","워크플ロー 및 운영의 표준화","재사용 가능한 프로ンプ트의 트리거"],"es":["Comandos globales y específicos de proyecto","Estructura de comandos con formato Markdown","Compatibilidad con YAML frontmatter","Capacidad para expandir comandos en la conversación actual","Compartir comandos con el equipo en .agent/commands/"],"fr":["Commandes globales et spécifiques au projet","Structure de commandes avec format Markdown","Compatibilité avec YAML frontmatter","Capacité à étendre les commandes dans la conversation actuelle","Partage de commandes avec l''équipe dans .agent/commands/"],"de":["Globale und projektspezifische Befehle","Befehlsstruktur mit Markdown-Format","Unterstützung für YAML-Frontmatter","Fähigkeit, Befehle in der aktuellen Konversation zu erweitern","Teilen von Befehlen mit dem Team in .agent/commands/"],"pt":["Suporte a Markdown para formatação de comandos","Uso de YAML frontmatter para estruturação de comandos","Comandos globais e específicos de projeto","Integração com Antigravity para workflows personalizados","Suporte a dynami para comandos dinâmicos"],"ru":["Поддержка Markdown для форматирования команд","Использование YAML frontmatter для структурирования команд","Глобальные и проектные команды","Интеграция с Антигравитацией для индивидуальных рабочих процессов","Поддержка dynami для динамических команд"],"ar":["دعم Markdown لتنسيق الأوامر","استخدام YAML frontmatter لهيكلة الأوامر","أوامر عالمية وأوامر محددة للمشروع","التكامل مع برنامج Antigravity لWORKFLOWS مخصصة","دعم dynami لأوامر ديناميكية"]},"keywords":{"en":["how to use create-slash-commands","create-slash-commands setup guide","create-slash-commands alternative","create-slash-commands vs custom commands","what is create-slash-commands","create-slash-commands install","Antigravity slash commands","Markdown formatting for commands","YAML frontmatter for command configuration"],"zh":["AIエージェント","斜杠命令","可重用提示","工作流程标准化","操作标准化","Markdown","YAML frontmatter","动态命令结构"],"ja":["AIエージェント","スラッシュコマンド","再利用可能なプロンプト","ワークフロー標準化","操作標準化","Markdown","YAML frontmatter","動的なコマンド構造"],"ko":["AI 도구","슬래시 명령","재사용 가능한 프로ンプ트","워크플ロー 표준화","운영 표준화","Markdown","YAML frontmatter","동적 명령 구조"],"es":["comandos de barra","Agentes de IA","Antigravity","configuración de comandos","Markdown","YAML","flujos de trabajo","comandos personalizados"],"fr":["commandes de barre oblique","outils d''IA","Antigravity","configuration de commandes","Markdown","YAML","flux de travail","commandes personnalisées"],"de":["Slash-Befehle","KI-Agenten","Antigravity","Einrichtung von Befehlen","Markdown","YAML","Workflows","benutzerdefinierte Befehle"],"pt":["comandos de barra","Antigravity","Markdown","YAML frontmatter","comandos globais","comandos específicos de projeto","dynami","workflows personalizados"],"ru":["ИИ Агенты","слэш-команды","Антигравитация","Markdown","YAML frontmatter","глобальные команды","проектные команды","dynami","индивидуальные рабочие процессы"],"ar":["أدوات الذكاء الاصطناعي","أوامر شرطة","برنامج Antigravity","Markdown","YAML frontmatter","أوامر عالمية","أوامر محددة للمشروع","dynami","WORKFLOWS مخصصة"]}},"owner":"nicanac","repo":"airecord","repoPath":"nicanac/airecord","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.595Z","topics":[],"category":"community","skillMd":{"name":"create-slash-commands","description":"Expert guidance for creating Antigravity slash commands. Use when working with slash commands, creating custom commands, understanding command structure, or learning YAML configuration.","bodyPreview":"## Objective\n\nCreate effective slash commands for Antigravity that enable users to trigger reusable prompts with `/command-name` syntax. Slash commands expand as prompts in the current conversation, allowing teams to standardize workflows and operations.\n\nCommands can be **global** (available everywhere in `~/.agent/commands/`) or **project-specific** (shared with team in `.agent/commands/`). This skill teaches you to structure commands with proper formatting (Markdown), YAML frontmatter, dynami","body":"## Objective\n\nCreate effective slash commands for Antigravity that enable users to trigger reusable prompts with `/command-name` syntax. Slash commands expand as prompts in the current conversation, allowing teams to standardize workflows and operations.\n\nCommands can be **global** (available everywhere in `~/.agent/commands/`) or **project-specific** (shared with team in `.agent/commands/`). This skill teaches you to structure commands with proper formatting (Markdown), YAML frontmatter, dynamic context loading, and intelligent argument handling.\n\n**CRITICAL WORKFLOW**: This skill enforces a mandatory research phase where you MUST:\n\n1. Read all reference documentation\n2. Examine existing slash commands for patterns\n3. Understand syntax and best practices\n4. Only then create the command\n\nThis prevents poorly-structured commands and ensures consistency with established patterns.\n\n## Quick Start\n\n### Workflow\n\n1. Create `.agent/commands/` directory (project) or use `~/.agent/commands/` (personal)\n2. Create `command-name.md` file\n3. Add YAML frontmatter (at minimum: `description`)\n4. Write command prompt\n5. Test with `/command-name [args]`\n\n### Example\n\n**File**: `.agent/commands/optimize.md`\n\n```markdown\n---\ndescription: Analyze this code for performance issues and suggest optimizations\n---\n\nAnalyze the performance of this code and suggest three specific optimizations:\n```\n\n**Usage**: `/optimize`\n\nAntigravity receives the expanded prompt and analyzes the code in context.\n\n## Markdown Structure\n\nSlash commands should use **Markdown headings** (Headers) in the body (after YAML frontmatter).\n\n**Format**:\n\n- **Markdown Headers**: The standard for Antigravity commands (`## Objective`, `## Process`)\n- **Compatibility**: Antigravity parses Markdown headers effectively for instruction structuring.\n\n### Required Sections\n\n**`## Objective`** - What the command does and why it matters\n\n```markdown\n## Objective\n\nWhat needs to happen and why this matters.\nContext about who uses this and what it accomplishes.\n```\n\n**`## Process`** - How to execute the command\n\n```markdown\n## Process\n\n1. First step\n2. Second step\n3. Final step\n```\n\n**`## Success Criteria`** - How to know the command succeeded\n\n```markdown\n## Success Criteria\n\n- Clear, measurable criteria for successful completion.\n```\n\n### Conditional Sections\n\n**`## Context`** - When loading dynamic state or files\n\n```markdown\n## Context\n\nCurrent state: ! `git status`\nRelevant files: @ package.json\n```\n\n(Note: Remove the space after @ in actual usage)\n\n**`## Verification`** - When producing artifacts that need checking\n\n```markdown\n## Verification\n\nBefore completing, verify:\n\n- Specific test or check to perform\n- How to confirm it works\n```\n\n**`## Testing`** - When running tests is part of the workflow\n\n```markdown\n## Testing\n\nRun tests: ! `npm test`\nCheck linting: ! `npm run lint`\n```\n\n**`## Output`** - When creating/modifying specific files\n\n```markdown\n## Output\n\nFiles created/modified:\n\n- `./path/to/file.ext` - Description\n```\n\n### Structure Example\n\n```markdown\n---\nname: example-command\ndescription: Does something useful\nargument-hint: [input]\n---\n\n## Objective\n\nProcess #$ARGUMENTS to accomplish [goal].\n\nThis helps [who] achieve [outcome].\n\n## Context\n\nCurrent state: ! `relevant command`\nFiles: @ relevant/files\n\n## Process\n\n1. Parse #$ARGUMENTS\n2. Execute operation\n3. Verify results\n\n## Success Criteria\n\n- Operation completed without errors\n- Output matches expected format\n```\n\n### Intelligence Rules\n\n**Simple commands** (single operation, no artifacts):\n\n- Required: `## Objective`, `## Process`, `## Success Criteria`\n- Example: `/check-todos`, `/first-principles`\n\n**Complex commands** (multi-step, produces artifacts):\n\n- Required: `## Objective`, `## Process`, `## Success Criteria`\n- Add: `## Context` (if loading state), `## Verification` (if creating files), `## Output` (what gets created)\n- Example: `/commit`, `/create-prompt`, `/run-prompt`\n\n**Commands with dynamic arguments**:\n\n- Use `#$ARGUMENTS` in body\n- Include `argument-hint` in frontmatter\n- Make it clear what the arguments are for\n\n**Commands that produce files**:\n\n- Always include `## Output` section specifying what gets created\n- Always include `## Verification` section with checks to perform\n\n**Commands that run tests/builds**:\n\n- Include `## Testing` section with specific commands\n- Include pass/fail criteria in `## Success Criteria`\n\n## Arguments Intelligence\n\nThe skill should intelligently determine whether a slash command needs arguments.\n\n### Commands That Need Arguments\n\n**User provides specific input:**\n\n- `/fix-issue [issue-number]` - Needs issue number\n- `/review-pr [pr-number]` - Needs PR number\n- `/optimize [file-path]` - Needs file to optimize\n- `/commit [type]` - Needs commit type (optional)\n\n**Pattern:** Task operates on user-specified data\nInclude `argument-hint: [description]` in frontmatter and reference `#$ARGUMENTS` in the body.\n\n### Commands Without Arguments\n\n**Self-contained procedures:**\n\n- `/check-todos` - Operates on known file (TO-DOS.md)\n- `/first-principles` - Operates on current conversation\n- `/whats-next` - Analyzes current context\n\n**Pattern:** Task operates on implicit context (current conversation, known files, project state)\nOmit `argument-hint` and don''t reference `#$ARGUMENTS`.\n\n### Incorporating Arguments\n\n**In Objective:**\n\n```markdown\n## Objective\n\nFix issue #$ARGUMENTS following project conventions.\n```\n\n**In Process:**\n\n```markdown\n## Process\n\n1. Understand issue #$ARGUMENTS from issue tracker\n```\n\n**In Context:**\n\n```markdown\n## Context\n\nIssue details: @ issues/#$ARGUMENTS.md\nRelated files: ! `grep -r \"TODO.*#$ARGUMENTS\" src/`\n```\n\n### Positional Arguments\n\nFor structured input, use `$1`, `$2`, `$3`:\n\n```markdown\n---\nargument-hint: <pr-number> <priority> <assignee>\n---\n\n## Objective\n\nReview PR #$1 with priority $2 and assign to $3.\n```\n\n**Usage:** `/review-pr 456 high alice`\n\n## File Structure\n\n**Project commands**: `.agent/commands/` (in project root)\n\n- Shared with team via version control\n- Project-specific workflows\n- Shows `(project)` in `/help` list\n\n**Global commands**: `~/.agent/commands/` (user home directory)\n\n- Available across all your projects\n- Personal productivity commands\n- Shows `(user)` in `/help` list\n\n**Choosing between global and project**:\n\n- Use **global** for: Personal workflows, general utilities, commands you use everywhere\n- Use **project** for: Team workflows, project-specific operations, shared conventions\n\n## YAML Frontmatter\n\n### Field: description\n\n**Required** - Describes what the command does\n\n```yaml\ndescription: Analyze this code for performance issues and suggest optimizations\n```\n\n### Field: allowed-tools\n\n**Optional** - Restricts which tools Antigravity can use\n\n```yaml\nallowed-tools: [Read, Edit, Write]\n# or\nallowed-tools: Bash(git add:*)\n```\n\n## Arguments Usage\n\n### All Arguments String\n\nUse `#$ARGUMENTS` to capture all arguments strings.\n\n```markdown\nFix issue #$ARGUMENTS following our coding standards\n```\n\n**Usage**: `/fix-issue 123 high-priority`\n**Received**: \"Fix issue #123 high-priority following our coding standards\"\n\n### Positional Arguments\n\nUse `$1`, `$2` for split arguments.\n\n```markdown\nReview PR #$1 with priority $2\n```\n\n**Usage**: `/review-pr 456 high`\n**Received**: \"Review PR #456 with priority high\"\n\n## Dynamic Context\n\nExecute bash commands before the prompt using the exclamation mark prefix directly before backticks `!`.\n\n```markdown\n## Context\n\n- Current git status: ! `git status`\n- Current git diff: ! `git diff HEAD`\n```\n\nUse `@` prefix to reference specific files:\n\n```markdown\nReview the implementation in @ src/utils/helpers.js\n```\n\n## Best Practices\n\n**1. Always use Markdown Structure**\nAfter frontmatter, use standard Markdown headers:\n\n- `## Objective`\n- `## Process`\n- `## Success Criteria`\n\n**2. Clear descriptions**\nWrite descriptive summaries for the `/help` list.\n\n**3. Use dynamic context for state-dependent tasks**\nLoad fresh status for git ops or tests.\n\n**4. Restrict tools when appropriate**\nUse `allowed-tools` to prevent unintended actions (e.g. restrict to Analysis tools only).\n\n**5. Use #$ARGUMENTS for flexibility**\nLet users specify files or IDs at runtime.\n\n**6. Reference relevant files**\nUse `@filename` to load context automatically.\n\n## Common Patterns\n\n### Simple Analysis Command\n\n```markdown\n---\ndescription: Review this code for security vulnerabilities\n---\n\n## Objective\n\nReview code for security vulnerabilities and suggest fixes.\n\n## Process\n\n1. Scan code for common vulnerabilities\n2. Identify specific issues\n3. Suggest remediation\n\n## Success Criteria\n\n- All major vulnerability types checked\n- Issues identified with locations\n```\n\n### Git Workflow with Context\n\n```markdown\n---\ndescription: Create a git commit\nallowed-tools: Bash(git add:*), Bash(git status:*), Bash(git commit:*)\n---\n\n## Objective\n\nCreate a git commit for current changes following repository conventions.\n\n## Context\n\n- Current status: ! `git status`\n- Changes: ! `git diff HEAD`\n- Recent commits: ! `git log --oneline -5`\n\n## Process\n\n1. Review staged and unstaged changes\n2. Stage relevant files\n3. Write commit message\n4. Create commit\n\n## Success Criteria\n\n- Commit created successfully\n- Message follows conventions\n```\n\n## Reference Guides\n\n**Slash command specific references:**\n\n- [arguments.md](resources/arguments.md)\n- [patterns.md](examples/patterns.md)\n- [tool-restrictions.md](resources/tool-restrictions.md)\n- [prompt-examples.md](examples/prompt-examples.md)\n\n**Generation Protocol**\n(See mandatory research steps in previous sections)\n"},"lastSynced":"2026-03-08T02:12:04.891Z","agentAnalysis":{"suitability":{"en":"Perfect for Collaboration Agents needing standardized workflow triggers with slash commands","zh":"适合需要标准化工作流触发器的协作代理，使用斜杠命令","ja":"コラボレーションエージェントが標準化されたワークフローのトリガーを必要とする場合に最適です。スラッシュコマンドを使用します","ko":"표준화된 워크플로우 트리거가 필요한 협업 에이전트에게 적합합니다. 斜杠 명령을 사용합니다","es":"Perfecto para agentes de colaboración que necesitan desencadenadores de flujo de trabajo estandarizados con comandos de barra diagonal","fr":"Parfait pour les agents de collaboration nécessitant des déclencheurs de workflow standardisés avec des commandes de barre oblique","de":"Perfekt für Kollaborationsagenten, die standardisierte Workflow-Trigger mit Schrägstrichbefehlen benötigen","pt":"Perfeito para Agentes de Colaboração que necessitam de gatilhos de fluxo de trabalho padronizados com comandos de barra","ru":"Идеально для агентов сотрудничества, которым необходимы стандартизированные триггеры рабочего процесса с командами слэша","ar":"مثالي لعمليات وكيل التعاون التي تحتاج إلى أسلوب عمل معياري مع أوامر شرطة"},"recommendation":{"en":"Empowers agents to trigger reusable prompts with /command-name syntax, utilizing Markdown formatting and YAML frontmatter for structured commands, and supports both global and project-specific commands","zh":"赋予代理以/command-name 语法触发可重用提示的能力，利用Markdown格式和YAML前置内容进行结构化命令，并支持全局和项目特定命令","ja":"エージェントが/command-name 構文で再利用可能なプロンプトをトリガーする能力を提供し、Markdown形式とYAMLフロントマターを使用して構造化されたコマンドを作成し、グローバルコマンドとプロジェクト特有のコマンドの両方をサポートします","ko":"에이전트가 /command-name 구문으로 재사용 가능한 프롬프트를 트리거하는 기능을 제공하며, 마크다운 형식과 YAML 전면 물자를 사용하여 구조화된 명령을 생성하며, 전역 명령과 프로젝트 특정 명령을 모두 지원합니다","es":"Habilita a los agentes para activar prompts reutilizables con la sintaxis /nombre-de-comando, utilizando formato Markdown y frontmatter YAML para comandos estructurados, y admite comandos tanto globales como específicos del proyecto","fr":"Permet aux agents de déclencher des invites réutilisables avec la syntaxe /nom-de-commande, en utilisant le formatage Markdown et le frontmatter YAML pour des commandes structurées, et prend en charge à la fois les commandes globales et spécifiques au projet","de":"Ermächtigt Agenten, wiederverwendbare Prompts mit der Syntax /befehlsname auszuführen, wobei Markdown-Formatierung und YAML-Frontmatter für strukturierte Befehle verwendet werden, und unterstützt sowohl globale als auch projektspezifische Befehle","pt":"Habilita os agentes a acionar prompts reutilizáveis com a sintaxe /nome-do-comando, utilizando formatação Markdown e frontmatter YAML para comandos estruturados, e suporta comandos globais e específicos do projeto","ru":"Наделяет агентов возможностью запускать многократно используемые подсказки с синтаксисом /имя_команды, используя форматирование Markdown и фронтматер YAML для структурированных команд, и поддерживает как глобальные, так и специфические для проекта команды","ar":"يمنح الوكلاء khảية تشغيل إشارات قابلة لإعادة الاستخدام بناءً على بناء الجملة /اسم_الأمر، باستخدام تنسيق Markdown و YAML للواجهة الأمامية للأوامر المهيكلة، ودعم الأوامر العالمية والمحددة للمشروع"},"useCases":{"en":["Standardizing workflows with global slash commands","Creating project-specific commands for team workflows","Expanding prompts in conversations with reusable commands"],"zh":["使用全局斜杠命令标准化工作流","为团队工作流创建项目特定命令","在对话中使用可重用命令扩展提示"],"ja":["グローバルスラッシュコマンドを使用してワークフローを標準化する","チームのワークフローにプロジェクト特有のコマンドを作成する","会話で再利用可能なコマンドを使用してプロンプトを拡張する"],"ko":["전역 斜杠 명령을 사용하여 워크플ロー를 표준화하는 것","팀 워크플로우를 위한 프로젝트 특정 명령을 생성하는 것","대화에서 재사용 가능한 명령을 사용하여 프롬프트를 확장하는 것"],"es":["Estandarizar flujos de trabajo con comandos de barra diagonal globales","Crear comandos específicos del proyecto para flujos de trabajo de equipo","Ampliar las invitaciones en conversaciones con comandos reutilizables"],"fr":["Standardiser les flux de travail avec des commandes de barre oblique globales","Créer des commandes spécifiques au projet pour les flux de travail d''équipe","Étendre les invites dans les conversations avec des commandes réutilisables"],"de":["Workflows mit globalen Schrägstrichbefehlen standardisieren","Erstellen von projektspezifischen Befehlen für Team-Workflows","Erweitern von Prompts in Konversationen mit wiederverwendbaren Befehlen"],"pt":["Padronizando fluxos de trabalho com comandos de barra globais","Criando comandos específicos do projeto para fluxos de trabalho da equipe","Expandindo prompts em conversas com comandos reutilizáveis"],"ru":["Стандартизация рабочих процессов с глобальными командами слэша","Создание команд, специфичных для проекта, для рабочих процессов команды","Расширение подсказок в разговорах с многократно используемыми командами"],"ar":["تحديد معايير لتدفقات العمل مع أوامر شرطة عالمية","إنشاء أوامر محددة للمشروع لتدفقات عمل الفريق","توسيع الإشارات في المحادثات مع أوامر قابلة لإعادة الاستخدام"]},"limitations":{"en":["Requires proper structuring with Markdown and YAML frontmatter","Commands must be stored in ~/.agent/commands/ for global access or .agent/commands/ for project-specific access"],"zh":["需要使用Markdown和YAML前置内容进行适当的结构化","命令必须存储在 ~/.agent/commands/ 中以实现全局访问，或者存储在 .agent/commands/ 中以实现项目特定访问"],"ja":["MarkdownとYAMLフロントマターを使用して適切な構造化が必要","コマンドはグローバルアクセスするために ~/.agent/commands/ に、またはプロジェクト特有のアクセスするために .agent/commands/ に保存する必要がある"],"ko":["마크다운과 YAML 전면 물자를 사용하여 적절한 구조화가 필요함","명령은 전역 접근을 위해 ~/.agent/commands/에 저장되어야 하거나, 프로젝트 특정 접근을 위해 .agent/commands/에 저장되어야 함"],"es":["Requiere una estructuración adecuada con Markdown y frontmatter YAML","Los comandos deben almacenarse en ~/.agent/commands/ para el acceso global o .agent/commands/ para el acceso específico del proyecto"],"fr":["Nécessite une structuration appropriée avec Markdown et frontmatter YAML","Les commandes doivent être stockées dans ~/.agent/commands/ pour l''accès global ou .agent/commands/ pour l''accès spécifique au projet"],"de":["Erfordert eine ordnungsgemäße Strukturierung mit Markdown und YAML-Frontmatter","Befehle müssen in ~/.agent/commands/ für den globalen Zugriff oder .agent/commands/ für den projektspezifischen Zugriff gespeichert werden"],"pt":["Exige estruturação adequada com Markdown e frontmatter YAML","Os comandos devem ser armazenados em ~/.agent/commands/ para acesso global ou .agent/commands/ para acesso específico do projeto"],"ru":["Требует правильной структуризации с Markdown и фронтматер YAML","Команды должны храниться в ~/.agent/commands/ для глобального доступа или .agent/commands/ для доступа, специфичного для проекта"],"ar":["يتطلب هيكلة مناسبة مع Markdown و YAML للواجهة الأمامية","يجب تخزين الأوامر في ~/.agent/commands/ للوصول العالمي أو .agent/commands/ للوصول المحدد للمشروع"]},"version":4},"contentHash":"09682e024e9b3a84cda9e9771275223388512ab64e36ba77b06edbc9d2f80e5a","qualityScore":60}');
