INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nicanac/airecord/create-slash-commands', 'create-slash-commands', 'nicanac', 'airecord', 'community', 'create-slash-commands nicanac airecord community The create-slash-commands skill enables developers to create effective slash commands for Antigravity, standardizing workflows and operations. It benefits teams by allowing them to trigger reusable prompts with /command-name syntax. 创建斜杠命令，以触发可重用的提示，并标准化工作流程和操作。支持全局和项目特定命令。 スラッシュコマンドを作成して、再利用可能なプロンプトをトリガーし、ワークフローと操作を標準化します。グローバルコマンドとプロジェクト特有のコマンドをサポートしています。 슬래시 명령을 생성하여 재사용 가능한 프로ンプ트를 트리거하고 워크플ロー 및 운영을 표준화합니다. 글로벌 명령과 프로젝트 특정 명령을 지원합니다. Crea comandos de barra personalizados para Antigravity y mejora tus flujos de trabajo. Aprende a estructurar comandos con formato Markdown y YAML Créez des commandes de barre oblique personnalisées pour Antigravity et améliorez vos flux de travail. Apprenez à structurer des commandes avec le format Markdown et YAML Erstellen Sie benutzerdefinierte Slash-Befehle für Antigravity und verbessern Sie Ihre Workflows. Lernen Sie, Befehle mit Markdown- und YAML-Format zu strukturieren Criar comandos de barra personalizados para Antigravity com suporte a Markdown e YAML Создание индивидуальных слэш-команд для Антигравитации с поддержкой Markdown и YAML إنشاء أوامر شرطة مخصصة لبرنامج Antigravity مع دعم Markdown و YAML how to use create-slash-commands create-slash-commands setup guide create-slash-commands alternative create-slash-commands vs custom commands what is create-slash-commands create-slash-commands install Antigravity slash commands Markdown formatting for commands YAML frontmatter for command configuration AIエージェント 斜杠命令 可重用提示 工作流程标准化 操作标准化 Markdown YAML frontmatter 动态命令结构 Supports global commands available everywhere in ~/.agent/commands/ Allows project-specific commands shared with teams in .agent/commands/ Enables structuring commands with proper formatting using Markdown Utilizes YAML frontmatter for command configuration Expands as prompts in the current conversation for seamless integration Supports dynamic command execution for flexible workflows create-slash-commands is a skill that enables the creation of effective slash commands for Antigravity, using Markdown and YAML frontmatter for structuring commands.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chrislawcodes/valuerank/feature-spec', 'community', 'chrislawcodes', 'valuerank', 'chrislawcodes/valuerank', 'feature-spec', 0, 0, 60, '2026-03-08T01:57:15.597Z', '2026-03-08T02:12:07.365Z', 'd402a54f73347a87ef205c0e339ca34a60ca59ed1fe166b9ef4205162d95d344', '{"id":"chrislawcodes/valuerank/feature-spec","name":"feature-spec","description":{"en":"The feature-spec skill helps developers create high-quality feature specifications using a structured process, generating a complete spec.md file. It replaces the speckit workflow.","zh":"feature-spec技能帮助开发人员创建高质量的特性规格，使用结构化、合规的过程，生成完整的spec.md文件","ja":"feature-specスキルは、開発者が高品質の機能仕様を作成するのに役立ちます。構造化されたプロセスに従って、完全なspec.mdファイルを生成します","ko":"feature-spec 스킬은 개발자가 높은 품질의 특성 명세를 생성하는 데 도움을 줍니다. 구조화된 프로세스를 따르고 완전한 spec.md 파일을 생성합니다","es":"Feature-spec es una habilidad que ayuda a los desarrolladores a crear especificaciones de características de alta calidad utilizando un proceso estructurado y compatible con la constitución","fr":"Feature-spec est une compétence qui aide les développeurs à créer des spécifications de fonctionnalités de haute qualité en utilisant un processus structuré et conforme à la constitution","de":"Feature-spec ist eine Fähigkeit, die Entwicklern hilft, hochwertige Funktionsbeschreibungen mit einem strukturierten und verfassungskonformen Prozess zu erstellen","pt":"O feature-spec ajuda os desenvolvedores a criar especificações de recursos de alta qualidade usando um processo estruturado e conforme com a constituição.","ru":"Feature-spec помогает разработчикам создавать качественные спецификации функций с помощью структурированного и соответствующего конституции процесса.","ar":"يُساعد feature-spec المطورين على إنشاء مواصفات ميزات عالية الجودة باستخدام عملية منظمّة ومتوافقة مع الدستور."},"seo":{"title":{"en":"feature-spec: Setup Guide for AI Agents | AI Agent Skill","zh":"AIエージェント特征规格设置指南","ja":"AIエージェントの特性仕様設定ガイド","ko":"AI 에이전트 특성 명세 설정 가이드","es":"Guía de configuración de feature-spec para desarrolladore...","fr":"Guide de configuration de feature-spec pour les développe...","de":"Einrichtungsleitfaden für feature-spec für Entwickler von...","pt":"Guia de Configuração do feature-spec: Crie Especificações...","ru":"Руководство по настройке feature-spec: Создание качествен...","ar":"دليل إعداد feature-spec: إنشاء مواصفات ميزات عالية الجودة"},"description":{"en":"Discover how to use feature-spec to create high-quality feature specifications. Learn how to replace speckit workflow and generate complete spec.md files.","zh":"使用feature-spec技能创建高质量的特性规格，通过结构化、合规的过程，生成完整的spec.md文件","ja":"feature-specスキルを使用して、高品質の機能仕様を作成します。構造化されたプロセスに従って、完全なspec.mdファイルを生成します","ko":"feature-spec 스킬을 사용하여 높은 품질의 특성 명세를 생성합니다. 구조화된 프로세스를 따르고 완전한 spec.md 파일을 생성합니다","es":"Aprenda a crear especificaciones de características de alta calidad con feature-spec, reemplazando el flujo de trabajo de speckit","fr":"Découvrez comment créer des spécifications de fonctionnalités de haute qualité avec feature-spec, remplaçant le workflow speckit","de":"Erfahren Sie, wie Sie mit feature-spec hochwertige Funktionsbeschreibungen erstellen und den speckit-Workflow ersetzen","pt":"Aprenda a utilizar o feature-spec para criar especificações de recursos estruturadas e conformes com a constituição. Substitui o fluxo de trabalho do speckit.","ru":"Узнайте, как использовать feature-spec для создания структурированных и соответствующих конституции спецификаций функций. Заменяет рабочий процесс speckit.","ar":"تعلم كيفية استخدام feature-spec لإنشاء مواصفات ميزات منظمّة ومتوافقة مع الدستور. يحل محل سير عمل speckit."},"definition":{"en":"feature-spec is a skill that generates complete spec.md files in a numbered feature directory using a constitution-compliant process.","zh":"feature-spec是AIエージェント技能，用于创建高质量的特性规格","ja":"feature-specはAIエージェントのスキルで、高品質の機能仕様を作成するために使用されます","ko":"feature-spec은 AI 에이전트 스킬로 높은 품질의 특성 명세를 생성하는 데 사용됩니다","es":"Feature-spec es una habilidad de AI que genera un archivo spec.md completo en un directorio de características numeradas","fr":"Feature-spec est une compétence d''IA qui génère un fichier spec.md complet dans un répertoire de fonctionnalités numérotées","de":"Feature-spec ist eine KI-Fähigkeit, die eine vollständige spec.md-Datei in einem nummerierten Funktionsverzeichnis generiert","pt":"O feature-spec é uma habilidade que gera um arquivo spec.md completo em um diretório de recursos numerados.","ru":"Feature-spec — это навык, который генерирует полный файл spec.md в пронумерованном каталоге функций.","ar":"feature-spec هو مهارة تُولد ملف spec.md كاملاً في دليل ميزات مرقّم."},"features":{"en":["Generates complete spec.md files in a numbered feature directory","Replaces the speckit workflow","Follows a structured, constitution-compliant process","Creates high-quality feature specifications","Executes without invoking speckit bash scripts","Does not require speckit slash commands"],"zh":["生成完整的spec.md文件","结构化、合规的特性规格创建过程","替代speckit工作流","支持多语言开发","提高代码质量和可维护性"],"ja":["完全なspec.mdファイルを生成","構造化されたプロセスに従った機能仕様の作成","speckitワークフローの置き換え","多言語開発のサポート","コード品質とメンテナンス性の向上"],"ko":["완전한 spec.md 파일을 생성","구조화된 프로세스를 따르는 특성 명세의 생성","speckit 워크플로우의 대체","다중 언어 개발의 지원","코드 품질과 유지 보수성의 향상"],"es":["Genera un archivo spec.md completo","Reemplaza el flujo de trabajo de speckit","Utiliza un proceso estructurado y compatible con la constitución","Crea especificaciones de características de alta calidad","Sigue solo las instrucciones de la habilidad feature-spec","No invoca scripts de speckit ni comandos de speckit"],"fr":["Génère un fichier spec.md complet","Remplace le workflow speckit","Utilise un processus structuré et conforme à la constitution","Crée des spécifications de fonctionnalités de haute qualité","Suivez uniquement les instructions de la compétence feature-spec","N''invoke pas les scripts speckit ni les commandes speckit"],"de":["Generiert eine vollständige spec.md-Datei","Ersetzt den speckit-Workflow","Verwendet einen strukturierten und verfassungskonformen Prozess","Erstellt hochwertige Funktionsbeschreibungen","Befolgen Sie nur die Anweisungen der Fähigkeit feature-spec","Rufen Sie keine speckit-Skripte oder -Befehle auf"],"pt":["Gera um arquivo spec.md completo","Substitui o fluxo de trabalho do speckit","Cria especificações de recursos estruturadas","Conforme com a constituição","Processo de criação de especificações de recursos numerados"],"ru":["Генерирует полный файл spec.md","Заменяет рабочий процесс speckit","Создает структурированные спецификации функций","Соответствует конституции","Процесс создания пронумерованных спецификаций функций"],"ar":["تُولد ملف spec.md كاملاً","يحل محل سير عمل speckit","تُنشئ مواصفات ميزات منظمّة","متوافقة مع الدستور","عملية إنشاء مواصفات ميزات مرقّمة"]},"keywords":{"en":["how to use feature-spec","what is feature-spec","feature-spec alternative","feature-spec vs speckit","feature-spec setup guide","feature-spec install","replacing speckit workflow","generating spec.md files","constitution-compliant process"],"zh":["AIエージェント","特征规格","结构化过程","spec.md文件","speckit替代","代码质量","可维护性","多语言开发"],"ja":["AIエージェント","機能仕様","構造化プロセス","spec.mdファイル","speckit置き換え","コード品質","メンテナンス性","多言語開発"],"ko":["AI 에이전트","특성 명세","구조화된 프로세스","spec.md 파일","speckit 대체","코드 품질","유지 보수성","다중 언어 개발"],"es":["feature-spec","AI Agentes","especificaciones de características","speckit","desarrollo de software","herramientas de AI","configuración de feature-spec","guía de feature-spec","feature-spec para desarrolladores"],"fr":["feature-spec","outils d''IA","spécifications de fonctionnalités","speckit","développement de logiciels","outils de développement","configuration de feature-spec","guide de feature-spec","feature-spec pour développeurs"],"de":["feature-spec","KI-Tools","Funktionsbeschreibungen","speckit","Softwareentwicklung","Entwicklungstools","Konfiguration von feature-spec","Anleitung für feature-spec","feature-spec für Entwickler"],"pt":["feature-spec","especificações de recursos","speckit","constituição","desenvolvimento de software","ferramentas de ai","Agente de IA","criação de especificações","processo de desenvolvimento"],"ru":["feature-spec","спецификации функций","speckit","конституция","разработка программного обеспечения","инструменты ИИ","ИИ Агенты","создание спецификаций","процесс разработки"],"ar":["feature-spec","مواصفات الميزات","speckit","الدستور","تطوير البرمجيات","أدوات الذكاء الاصطناعي","عميل الذكاء الاصطناعي","إنشاء مواصفات","عملية التطوير"]}},"owner":"chrislawcodes","repo":"valuerank","repoPath":"chrislawcodes/valuerank","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.597Z","topics":[],"category":"community","skillMd":{"name":"feature-spec","description":"Create a high-quality feature specification with prioritized user stories, requirements, and constitution validation. Generates specs/NNN-feature-name/spec.md with clear acceptance criteria. Works with any project that has a constitution file.","bodyPreview":"# Feature Specification Skill\n\nYou help developers create high-quality feature specifications using a structured, constitution-compliant process. This skill generates a complete spec.md file in a numbered feature directory.\n\n## ⚠️ IMPORTANT: Speckit Replacement\n\n**This skill REPLACES the speckit workflow.** When executing this skill:\n- ✅ Follow ONLY the instructions in this skill prompt\n- ❌ DO NOT invoke any speckit bash scripts (in `.specify/scripts/`)\n- ❌ DO NOT suggest speckit slash commands","body":"# Feature Specification Skill\n\nYou help developers create high-quality feature specifications using a structured, constitution-compliant process. This skill generates a complete spec.md file in a numbered feature directory.\n\n## ⚠️ IMPORTANT: Speckit Replacement\n\n**This skill REPLACES the speckit workflow.** When executing this skill:\n- ✅ Follow ONLY the instructions in this skill prompt\n- ❌ DO NOT invoke any speckit bash scripts (in `.specify/scripts/`)\n- ❌ DO NOT suggest speckit slash commands (`/speckit.*`)\n- ❌ DO NOT reference speckit commands in your responses\n\nThis is a complete, standalone workflow for feature specification.\n\n## What This Skill Does\n\nCreates a feature specification document that:\n- Defines WHAT users need and WHY (not HOW to implement)\n- Organizes requirements into prioritized user stories (P1, P2, P3)\n- Provides testable acceptance criteria for each story\n- Validates against project constitution (if exists)\n- Asks clarifying questions (max 3) for critical unknowns only\n- Generates a specification ready for technical planning\n\n## When to Use This Skill\n\n- Starting a new feature from a natural language description\n- Converting a user request into a structured specification\n- Before any technical planning or implementation begins\n- When you need to clarify requirements with stakeholders\n\n## Prerequisites\n\n- Working in the repository root directory\n- Git repository initialized (for feature branch creation)\n- Optional: Project constitution file (`.specify/memory/constitution.md` or similar)\n- Optional: CLAUDE.md or equivalent project documentation\n\n## Workflow\n\n### Step 1: Parse Feature Description\n\n**Input**: User provides natural language feature description (from skill invocation)\n\n**Actions**:\n1. Extract key concepts: actors, actions, data, constraints\n2. Identify primary user value proposition\n3. Determine scope boundaries (what''s included/excluded)\n4. List assumptions you''re making about unspecified details\n\n**Output**: Mental model of the feature requirements\n\n---\n\n### Step 2: Assign Feature Number and Create Directory\n\n**Actions**:\n1. Scan for existing specs directory (common locations: `specs/`, `features/`, `docs/features/`)\n2. Find highest feature number: List directories matching pattern `NNN-*` where NNN is numeric\n3. Assign next sequential number (NNN format, e.g., 074)\n4. Generate short-name (2-4 words, kebab-case):\n   - Use action-noun format: \"add-user-auth\", \"fix-payment-timeout\"\n   - Preserve technical terms: \"oauth2-integration\", \"graphql-migration\"\n   - Keep concise but descriptive\n5. Create directory: `<specs-dir>/NNN-short-name/`\n\n**Example**:\n- Input: \"Add email notifications for critique responses\"\n- Specs location: `specs/` (detected)\n- Highest existing: `specs/073-job-queue-inspector/`\n- Output: `specs/074-critique-notifications/`\n\n**If no specs directory exists**: Ask user where to create feature directories or use `specs/` as default\n\n---\n\n### Step 3: Generate Prioritized User Stories\n\n**Structure**: Each user story must be:\n- **Independently testable**: Can validate without other stories complete\n- **Value-focused**: Delivers specific user/business value\n- **Prioritized**: P1 (critical) → P2 (important) → P3 (nice-to-have)\n\n**User Story Format**:\n```markdown\n### User Story N - [Brief Title] (Priority: PN)\n\n[Describe user journey in plain language: As a [role], I need to [action] so that [value]]\n\n**Why this priority**: [Explain value and priority level justification]\n\n**Independent Test**: [How to test this story standalone and verify it delivers value]\n\n**Acceptance Scenarios**:\n\n1. **Given** [initial state], **When** [action], **Then** [expected outcome]\n2. **Given** [initial state], **When** [action], **Then** [expected outcome]\n```\n\n**Quality Rules**:\n- P1 stories: Core functionality, system unusable without them\n- P2 stories: Important but system functions without them\n- P3 stories: Enhancements, nice-to-haves\n- Each story should deliver value independently\n- Stories should be testable in isolation\n\n---\n\n### Step 4: Identify Clarification Needs\n\n**Goal**: Ask ONLY critical questions that significantly impact scope/design\n\n**Rules**:\n- **Maximum 3 questions** total across entire spec\n- Make informed guesses for everything else (document as assumptions)\n- Only ask when:\n  - Choice significantly impacts feature scope or UX\n  - Multiple reasonable interpretations with different implications\n  - No reasonable default exists\n\n**Question Format**:\n```markdown\n## Clarification Needed\n\n### Question 1: [Topic]\n\n**Context**: [Quote relevant requirement or user story]\n\n**What we need to know**: [Specific question]\n\n**Suggested Options**:\n\n| Option | Answer | Implications |\n|--------|--------|--------------|\n| A | [First option] | [What this means for feature] |\n| B | [Second option] | [What this means for feature] |\n| C | [Third option] | [What this means for feature] |\n| Custom | Your own answer | Provide details below |\n\n**Your choice**: _[Wait for user response]_\n```\n\n**After receiving answers**:\n- Update spec with user''s choices\n- Remove all `[NEEDS CLARIFICATION]` markers\n- Document chosen option in spec\n\n---\n\n### Step 5: Define Functional Requirements\n\n**Format**: Sequential FR-NNN identifiers with testable statements\n\n```markdown\n### Functional Requirements\n\n- **FR-001**: System MUST [specific capability with measurable outcome]\n- **FR-002**: Users MUST be able to [key interaction with success criteria]\n- **FR-003**: System MUST [data requirement with validation rules]\n```\n\n**Quality Rules**:\n- Every requirement must be testable (not subjective)\n- Use \"MUST\" for required, \"SHOULD\" for recommended, \"MAY\" for optional\n- Be specific about quantities, limits, timeouts\n- Reference user stories they support (e.g., \"Supports US1\")\n\n**Examples**:\n- ✅ Good: \"System MUST send notification within 5 seconds of critique response\"\n- ❌ Bad: \"System should notify users quickly\" (not measurable)\n\n---\n\n### Step 6: Create Success Criteria\n\n**Goal**: Define measurable, technology-agnostic outcomes\n\n**Rules**:\n- Must be measurable (include metrics: time, percentage, count)\n- Technology-agnostic (no frameworks, tools, implementation details)\n- User-focused (outcomes from user/business perspective)\n- Verifiable without knowing implementation\n\n**Format**:\n```markdown\n### Success Criteria\n\n- **SC-001**: [Measurable outcome, e.g., \"Users can complete task in under 2 minutes\"]\n- **SC-002**: [Performance metric, e.g., \"System handles 1000 concurrent users\"]\n- **SC-003**: [User satisfaction, e.g., \"90% task completion rate on first attempt\"]\n```\n\n**Examples**:\n- ✅ Good: \"Users see search results in under 1 second\"\n- ❌ Bad: \"API response time < 200ms\" (implementation detail)\n- ✅ Good: \"95% of uploads complete without errors\"\n- ❌ Bad: \"Use S3 multipart upload for reliability\" (technology-specific)\n\n---\n\n### Step 7: Identify Edge Cases\n\n**Purpose**: Document boundary conditions and error scenarios\n\n```markdown\n### Edge Cases\n\n- What happens when [boundary condition]? → [Expected behavior]\n- How does system handle [error scenario]? → [Graceful degradation]\n- What if user [unexpected action]? → [Validation or fallback]\n```\n\n**Common patterns**:\n- Empty states (no data exists)\n- Maximum limits (too many items)\n- Missing/null data\n- Permission boundaries\n- Network failures\n- Concurrent operations\n\n---\n\n### Step 8: Constitution Validation\n\n**Locate Constitution** (check these locations in order):\n1. `.specify/memory/constitution.md`\n2. `CONSTITUTION.md` (project root)\n3. `docs/constitution.md`\n4. Search for files containing \"constitution\" or \"governance\"\n\n**If constitution exists**, validate spec against it:\n\n1. **Scan constitution for relevant sections**:\n   - Search for: \"User Experience\", \"UX\", \"Design Principles\"\n   - Search for: \"Performance\", \"Response Time\", \"Optimization\"\n   - Search for: \"Security\", \"Authentication\", \"Data Protection\"\n   - Search for: \"API\", \"Service Design\", \"Architecture\"\n\n2. **Extract requirements** from found sections:\n   - Note any MUST/SHOULD requirements that apply to this feature\n   - Note performance targets (e.g., \"API < 200ms\", \"FCP < 1.5s\")\n   - Note security requirements (e.g., \"all endpoints require auth\")\n   - Note accessibility standards (e.g., \"WCAG 2.1 Level AA\")\n\n3. **Validate spec addresses requirements**:\n   - Does spec define authentication if required?\n   - Does spec include performance targets from success criteria?\n   - Does spec address accessibility if mentioned in constitution?\n   - Does spec consider security for sensitive operations?\n\n4. **Output validation result**:\n   - **PASS**: Spec addresses all constitutional requirements\n   - **WARN**: Spec may need to address specific constitutional section\n   - **FAIL**: Spec violates constitutional requirement (must resolve)\n\n**If no constitution exists**: Skip validation, proceed to Step 9\n\n---\n\n### Step 9: Generate spec.md\n\n**File**: `<specs-dir>/NNN-short-name/spec.md`\n\n**Sections** (in order):\n1. **Header**: Feature branch, created date, status, input description\n2. **User Scenarios & Testing**: Prioritized user stories (P1 → P2 → P3)\n3. **Edge Cases**: Boundary conditions and error scenarios\n4. **Requirements**: Functional requirements (FR-NNN)\n5. **Success Criteria**: Measurable outcomes (SC-NNN)\n6. **Key Entities** (optional): If feature involves data models\n7. **Assumptions** (optional): Document informed guesses made\n\n**Quality Checklist** (verify before writing):\n- [ ] No implementation details (languages, frameworks, APIs)\n- [ ] All requirements testable and unambiguous\n- [ ] Success criteria measurable and technology-agnostic\n- [ ] User stories prioritized and independently testable\n- [ ] Maximum 3 clarification questions (or all resolved)\n- [ ] Edge cases identified\n- [ ] Constitution compliance validated (if constitution exists)\n\n---\n\n### Step 10: Report Completion\n\n**Output Message**:\n```\n✓ Feature specification created: specs/074-critique-notifications/spec.md\n\nSummary:\n- Feature #074: critique-notifications\n- User Stories: 3 (P1: 1, P2: 1, P3: 1)\n- Functional Requirements: 8\n- Success Criteria: 4\n- Constitution Check: PASS (or SKIPPED if no constitution)\n\nNext Steps:\n1. Review spec.md for accuracy\n2. When ready for technical planning, invoke the feature-plan skill\n3. Or ask clarifying questions if requirements need refinement\n\nTo continue: Simply say \"use feature-plan skill\" or \"generate the technical plan\"\n```\n\n**Handoff Instructions**:\n- Tell the user the specification is complete and ready for review\n- Invite them to proceed with the `feature-plan` skill when ready\n- DO NOT suggest using `/speckit.plan` or any other speckit command\n- Make it clear they should invoke the feature-plan SKILL, not a slash command\n\n---\n\n## Constitution Integration\n\n**If constitution exists**, this skill validates specifications against project governance:\n\n**Common constitution sections to check**:\n- Code quality principles (type safety, clarity, organization)\n- User experience standards (design principles, accessibility, performance)\n- Performance requirements (response times, optimization targets)\n- Security principles (authentication, data protection, validation)\n- API design patterns (RESTful conventions, service communication)\n\n**How validation works**:\n1. Load constitution file\n2. Search for relevant sections based on feature type\n3. Extract MUST/SHOULD requirements\n4. Check if spec addresses each requirement\n5. Flag violations or missing requirements\n\n**Violations flagged with severity**:\n- **CRITICAL**: Spec violates hard requirements (security, performance mandates)\n- **WARNING**: Spec may violate best practices (ask user to confirm)\n- **INFO**: Spec should document how it addresses constitutional requirement\n\n---\n\n## Examples\n\n### Example 1: Simple Feature\n\n**Input**: \"Add a dark mode toggle to user settings\"\n\n**Output**:\n- Feature #075: `specs/075-dark-mode-toggle/spec.md`\n- User Stories: 2 (P1: Toggle in settings, P2: Persist preference)\n- FR-001 through FR-005\n- SC-001: Users can switch themes in under 5 seconds\n- Constitution: PASS (accessibility verified, performance non-blocking)\n\n### Example 2: Complex Feature with Clarification\n\n**Input**: \"Add real-time collaboration for collection editing\"\n\n**Clarification Asked**:\n- Q1: Collaboration scope - same-time editing or comment-based review?\n- Q2: Conflict resolution - last-write-wins or manual merge?\n\n**After User Response**:\n- Feature #076: `specs/076-collection-collaboration/spec.md`\n- User Stories: 4 (P1: Multi-user viewing, P2: Commenting, P3: Live cursors, P3: Conflict UI)\n- Constitution: WARNING (performance targets for WebSocket connections needed)\n\n### Example 3: Security-Sensitive Feature\n\n**Input**: \"Add admin user impersonation for support debugging\"\n\n**Output**:\n- Feature #077: `specs/077-admin-impersonation/spec.md`\n- User Stories: 2 (P1: Login-as, P2: Audit logging)\n- Constitution: CRITICAL - Must implement audit logging per security requirements\n- Spec includes FR-008: All impersonation logged with admin ID, target user, timestamp\n- Spec includes FR-009: Cannot impersonate other admins (escalation prevention)\n\n---\n\n## Error Handling\n\n### No Feature Description Provided\n\n```\nERROR: No feature description provided.\n\nPlease invoke this skill with a description of what you want to build.\n\nExample: \"Add email notifications when users receive critique responses\"\n```\n\n### Cannot Determine User Stories\n\n```\nERROR: Cannot determine user scenarios from description.\n\nThe feature description is too vague to extract concrete user stories.\n\nPlease provide more details about:\n- Who will use this feature? (user roles)\n- What actions will they perform?\n- What value does this deliver?\n\nExample: Instead of \"improve UX\", say \"add keyboard shortcuts for photo navigation\"\n```\n\n### Constitution Violations\n\n```\nWARNING: Potential constitution violations detected\n\nSection found: \"Authentication & Authorization\"\nRequirement: \"All API endpoints require authentication (except public portfolios)\"\n\nIssue: Spec does not specify authentication requirements\n\nRecommendation: Add FR-NNN: \"System MUST require authentication for all endpoints\"\n\nProceed anyway? (yes/no)\n```\n\n---\n\n## Quality Guidelines\n\n### What Makes a Good Spec\n\n✅ **Clear user value**: Each story explains WHY it matters\n✅ **Independently testable**: Stories can be validated standalone\n✅ **Measurable outcomes**: Success criteria have numbers\n✅ **Technology-agnostic**: No mention of specific frameworks or tools\n✅ **Scoped appropriately**: P1 is MVP, P2/P3 are enhancements\n✅ **Edge cases covered**: Boundary conditions documented\n\n### What to Avoid\n\n❌ **Implementation details**: \"Use Redux for state management\"\n❌ **Vague requirements**: \"System should be fast\"\n❌ **Untestable criteria**: \"Users will like the interface\"\n❌ **Technology-specific**: \"GraphQL mutation response time < 100ms\"\n❌ **Too many priorities**: Everything marked P1\n❌ **Dependent stories**: P1 cannot be tested without P2\n\n---\n\n## Configuration\n\nThis skill uses these defaults:\n\n- **Max clarification questions**: 3\n- **User story format**: Given-When-Then acceptance scenarios\n- **Requirement format**: FR-NNN with MUST/SHOULD/MAY\n- **Constitution validation**: Enabled if constitution file found\n- **Auto-directory creation**: Yes\n- **Feature numbering**: Sequential from existing specs directory\n- **Specs directory**: Auto-detect or use `specs/` as default\n\n---\n\n## Next Skill in Workflow\n\nAfter `feature-spec` completes successfully, the next skill is:\n\n**`feature-plan`** - Generate technical implementation plan\n- Input: Reads the spec.md you just created\n- Output: plan.md, data-model.md (if entities), contracts/ (if APIs)\n- Purpose: Convert WHAT (spec) into HOW (technical approach)\n\n---\n\n## Notes\n\n- This skill creates **only spec.md** (progressive file generation)\n- Constitution validation runs if constitution file exists\n- Clarification questions asked inline, no separate command needed\n- Feature numbers auto-assigned sequentially\n- Short-names generated from feature description (user can override)\n- Works with any project structure (auto-detects specs directory)\n"},"lastSynced":"2026-03-08T02:12:07.365Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured feature specification generation in Markdown format.","zh":"非常适合需要在 Markdown 格式中生成结构化特性规格的开发代理。","ja":"開発エージェントが Markdown 形式で構造化された機能仕様を生成する必要がある場合に最適です。","ko":"개발 에이전트가 Markdown 형식으로 구조화된 기능 사양을 생성해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan generación de especificaciones de características estructuradas en formato Markdown.","fr":"Parfait pour les Agents de Développement ayant besoin d''une génération de spécifications de fonctionnalités structurées au format Markdown.","de":"Perfekt für Entwicklungssagenten, die eine strukturierte Generierung von Featurespezifikationen im Markdown-Format benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de geração de especificações de recursos estruturadas no formato Markdown.","ru":"Идеально подходит для агентов разработки, которым необходима структурированная генерация спецификаций функций в формате Markdown.","ar":"مثالي للوكلاء التطويريين الذين يحتاجون إلى توليد مواصفات ميزة منظمة في تنسيق Markdown."},"recommendation":{"en":"Empowers agents to create high-quality feature specifications using a constitution-compliant process, generating complete spec.md files in a numbered feature directory, replacing traditional speckit workflows with modern spec generation capabilities.","zh":"赋予代理创建高质量功能规格的能力，使用符合宪法的流程生成完整的 spec.md 文件，在编号的功能目录中，取代传统的 speckit 工作流程，采用现代化的规格生成能力。","ja":"エージェントが高品質の機能仕様を生成できるようにし、憲法に準拠したプロセスを使用して、番号付きの機能ディレクトリに完全な spec.md ファイルを生成し、従来の speckit ワークフローを現代的な仕様生成機能に置き換えます。","ko":"에이전트가 높은 품질의 기능 사양을 생성할 수 있도록 하며, 헌법에 준거하는 프로세스를 사용하여, 번호가 매겨진 기능 디렉토리에 완전한 spec.md 파일을 생성하여, 전통적인 speckit 워크플로우를 현대적인 사양 생성 기능으로 대체합니다.","es":"Habilita a los agentes a crear especificaciones de características de alta calidad utilizando un proceso compatible con la constitución, generando archivos spec.md completos en un directorio de características numeradas, reemplazando los flujos de trabajo tradicionales de speckit con capacidades de generación de especificaciones modernas.","fr":"Permet aux agents de créer des spécifications de fonctionnalités de haute qualité en utilisant un processus conforme à la constitution, générant des fichiers spec.md complets dans un répertoire de fonctionnalités numérotées, remplaçant les flux de travail traditionnels de speckit par des capacités de génération de spécifications modernes.","de":"Ermächtigt Agenten, hochwertige Featurespezifikationen mithilfe eines verfassungskonformen Prozesses zu erstellen, indem komplette spec.md-Dateien in einem nummerierten Feature-Verzeichnis generiert werden, wodurch traditionelle speckit-Workflows durch moderne Spezifikationsgenerierungsfunktionen ersetzt werden.","pt":"Habilita os agentes a criar especificações de recursos de alta qualidade usando um processo compatível com a constituição, gerando arquivos spec.md completos em um diretório de recursos numerados, substituindo fluxos de trabalho tradicionais speckit por capacidades de geração de especificações modernas.","ru":"Наделяет агентов возможностью создавать высококачественные спецификации функций с помощью процесса, соответствующего конституции, generates полные файлы spec.md в пронумерованном каталоге функций, заменяя традиционные рабочие процессы speckit современными возможностями генерации спецификаций.","ar":"يمنح الوكلاء القدرة على إنشاء مواصفات ميزة عالية الجودة باستخدام عملية متوافقة مع الدستور، وتوليد ملفات spec.md كاملة في دليل ميزة مرقمة، واستبدال سير عمل speckit التقليدية بقدرات توليد مواصفات حديثة."},"useCases":{"en":["Generating spec.md files for new feature implementations","Replacing speckit bash scripts with streamlined spec generation","Creating comprehensive feature directories with numbered spec files"],"zh":["为新的功能实现生成 spec.md 文件","用流线型的规格生成功能取代 speckit bash 脚本","创建包含编号规格文件的综合功能目录"],"ja":["新しい機能の実装のための spec.md ファイルを生成する","speckit bash スクリプトをストリームライン化された仕様生成機能に置き換える","番号付きの仕様ファイルを含む包括的な機能ディレクトリを作成する"],"ko":["新的 기능 구현을 위한 spec.md 파일 생성","speckit bash 스크립트를 스트림라인화된 사양 생성 기능으로 대체","번호가 매겨진 사양 파일을 포함하는 포괄적인 기능 디렉토리 생성"],"es":["Generar archivos spec.md para nuevas implementaciones de características","Reemplazar scripts de bash de speckit con una generación de especificaciones optimizada","Crear directorios de características completos con archivos de especificaciones numeradas"],"fr":["Générer des fichiers spec.md pour de nouvelles implémentations de fonctionnalités","Remplacer les scripts bash de speckit par une génération de spécifications rationalisée","Créer des répertoires de fonctionnalités complets avec des fichiers de spécifications numérotés"],"de":["Erzeugen von spec.md-Dateien für neue Feature-Implementierungen","Ersetzen von speckit-Bash-Skripten durch eine optimierte Spezifikationsgenerierung","Erstellen von umfassenden Feature-Verzeichnissen mit nummerierten Spezifikationsdateien"],"pt":["Gerar arquivos spec.md para implementações de novas funcionalidades","Substituir scripts bash speckit por geração de especificações otimizada","Criar diretórios de funcionalidades abrangentes com arquivos spec numerados"],"ru":["Генерировать файлы spec.md для реализации новых функций","Заменить скрипты bash speckit на оптимизированную генерацию спецификаций","Создавать всесторонние каталоги функций с пронумерованными файлами spec"],"ar":["توليد ملفات spec.md لتنفيذ ميزات جديدة","استبدال سكريبتات bash speckit بتوليد مواصفات متدفق","إنشاء دلائل ميزة شاملة مع ملفات مواصفات مرقمة"]},"limitations":{"en":["Replaces speckit workflow, requiring exclusive use of feature-spec instructions"],"zh":["替换 speckit 工作流程，需要仅使用功能规格说明"],"ja":["speckit ワークフローを置き換えるため、機能仕様の指示のみを使用する必要がある"],"ko":["speckit 워크플로우를 대체하므로, 기능 사양 지침만을 사용해야 함"],"es":["Reemplaza el flujo de trabajo de speckit, lo que requiere un uso exclusivo de instrucciones de feature-spec"],"fr":["Remplace le flux de travail de speckit, nécessitant une utilisation exclusive des instructions de feature-spec"],"de":["Ersetzt den speckit-Workflow, was eine exklusive Verwendung von Feature-Spec-Anweisungen erfordert"],"pt":["Substitui o fluxo de trabalho speckit, exigindo uso exclusivo de instruções feature-spec"],"ru":["Заменяет рабочий процесс speckit, требуя исключительного использования инструкций feature-spec"],"ar":["يستبدل سير عمل speckit، ويتطلب استخدامًا حصرًا لتعليمات feature-spec"]},"version":4},"contentHash":"d402a54f73347a87ef205c0e339ca34a60ca59ed1fe166b9ef4205162d95d344","qualityScore":60}');
