INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chrislawcodes/valuerank/feature-spec', 'feature-spec', 'chrislawcodes', 'valuerank', 'community', 'feature-spec chrislawcodes valuerank community The feature-spec skill helps developers create high-quality feature specifications using a structured process, generating a complete spec.md file. It replaces the speckit workflow. feature-spec技能帮助开发人员创建高质量的特性规格，使用结构化、合规的过程，生成完整的spec.md文件 feature-specスキルは、開発者が高品質の機能仕様を作成するのに役立ちます。構造化されたプロセスに従って、完全なspec.mdファイルを生成します feature-spec 스킬은 개발자가 높은 품질의 특성 명세를 생성하는 데 도움을 줍니다. 구조화된 프로세스를 따르고 완전한 spec.md 파일을 생성합니다 Feature-spec es una habilidad que ayuda a los desarrolladores a crear especificaciones de características de alta calidad utilizando un proceso estructurado y compatible con la constitución Feature-spec est une compétence qui aide les développeurs à créer des spécifications de fonctionnalités de haute qualité en utilisant un processus structuré et conforme à la constitution Feature-spec ist eine Fähigkeit, die Entwicklern hilft, hochwertige Funktionsbeschreibungen mit einem strukturierten und verfassungskonformen Prozess zu erstellen O feature-spec ajuda os desenvolvedores a criar especificações de recursos de alta qualidade usando um processo estruturado e conforme com a constituição. Feature-spec помогает разработчикам создавать качественные спецификации функций с помощью структурированного и соответствующего конституции процесса. يُساعد feature-spec المطورين على إنشاء مواصفات ميزات عالية الجودة باستخدام عملية منظمّة ومتوافقة مع الدستور. how to use feature-spec what is feature-spec feature-spec alternative feature-spec vs speckit feature-spec setup guide feature-spec install replacing speckit workflow generating spec.md files constitution-compliant process AIエージェント 特征规格 结构化过程 spec.md文件 speckit替代 代码质量 可维护性 多语言开发 Generates complete spec.md files in a numbered feature directory Replaces the speckit workflow Follows a structured, constitution-compliant process Creates high-quality feature specifications Executes without invoking speckit bash scripts Does not require speckit slash commands feature-spec is a skill that generates complete spec.md files in a numbered feature directory using a constitution-compliant process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('s-hiraoku/vscode-sidebar-terminal/synapse-a2a', 'community', 's-hiraoku', 'vscode-sidebar-terminal', 's-hiraoku/vscode-sidebar-terminal', 'synapse-a2a', 0, 0, 60, '2026-03-08T01:57:15.601Z', '2026-03-08T02:12:39.777Z', 'a85f4e8e5e437d738a074029edd57c8196a0fb3acbc72dc131db383fc69a14b2', '{"id":"s-hiraoku/vscode-sidebar-terminal/synapse-a2a","name":"synapse-a2a","description":{"en":"synapse-a2a enables inter-agent communication via Google A2A Protocol, benefiting developers with efficient message sending and reception. It supports commands like synapse list, send, and broadcast.","zh":"Synapse A2A 通信框架是一种基于 Google A2A 协议的 inter-agent 通信框架，提供列表、发送消息、广播和等待回复等功能","ja":"Synapse A2A コミュニケーション フレームワークは、Google A2A プロトコルに基づく inter-agent コミュニケーション フレームワークです。リスト表示、メッセージ送信、ブロードキャスト、応答待ちなどの機能を提供します","ko":"Synapse A2A 통신 프레임워크는 Google A2A 프로토콜을 기반으로 하는 inter-agent 통신 프레임워크로, 목록 표시, 메시지 전송, 방송 및 응답 대기 등의 기능을 제공합니다","es":"Synapse A2A es un framework de comunicación entre agentes que utiliza el protocolo Google A2A. Permite la comunicación entre agentes de inteligencia artificial.","fr":"Synapse A2A est un framework de communication entre agents qui utilise le protocole Google A2A. Il permet la communication entre les agents d''intelligence artificielle.","de":"Synapse A2A ist ein Kommunikationsframework zwischen Agents, das das Google A2A-Protokoll verwendet. Es ermöglicht die Kommunikation zwischen KI-Agents.","pt":"O Synapse A2A é um framework de comunicação entre agentes via protocolo Google A2A, permitindo envio de mensagens e broadcast","ru":"Synapse A2A - это фреймворк для обмена данными между ИИ Агентами через протокол Google A2A, позволяющий отправлять сообщения и вещать","ar":"Synapse A2A هو إطار للتواصل بين وكلاء الذكاء الاصطناعي عبر بروتوكول Google A2A، مما يسمح بإرسال الرسائل والبث"},"seo":{"title":{"en":"synapse-a2a: Inter-Agent Communication Setup Guide | AI A...","zh":"Synapse A2A 通信框架设置指南","ja":"Synapse A2A コミュニケーション フレームワークのベスト プラクティス","ko":"Synapse A2A 통신 프레임워크 가이드","es":"Guía de Configuración de Synapse A2A para Comunicación en...","fr":"Guide de Configuration de Synapse A2A pour la Communicati...","de":"Synapse A2A-Kommunikationsframework: Einrichtungsanleitung","pt":"Guia de Configuração do Synapse A2A para Comunicação entr...","ru":"Настройка Synapse A2A для обмена данными между ИИ Агентами","ar":"دليل إعداد Synapse A2A للتواصل بين وكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how to leverage synapse-a2a for seamless inter-agent communication via Google A2A Protocol. Learn to send messages, broadcast, and wait for replies ...","zh":"了解 Synapse A2A 通信框架的功能和特点，包括列表、发送消息、广播和等待回复等","ja":"Synapse A2A コミュニケーション フレームワークの機能と特徴を紹介します。リスト表示、メッセージ送信、ブロードキャスト、応答待ちなど","ko":"Synapse A2A 통신 프레임워크의 기능과 특징을 소개합니다. 목록 표시, 메시지 전송, 방송 및 응답 대기 등","es":"Aprende a configurar Synapse A2A para habilitar la comunicación entre agentes de inteligencia artificial. Descubre sus características y beneficios.","fr":"Découvrez comment configurer Synapse A2A pour activer la communication entre les agents d''intelligence artificielle. Explorez ses fonctionnalités et avantages.","de":"Erfahren Sie, wie Sie Synapse A2A konfigurieren, um die Kommunikation zwischen KI-Agents zu ermöglichen. Entdecken Sie seine Funktionen und Vorteile.","pt":"Aprenda a configurar o Synapse A2A para comunicação eficaz entre agentes, com recursos como envio de mensagens e broadcast","ru":"Научитесь настраивать Synapse A2A для эффективного обмена данными между ИИ Агентами, с функциями отправки сообщений и вещания","ar":"تعلم كيفية إعداد Synapse A2A للتواصل الفعال بين وكلاء الذكاء الاصطناعي، مع ميزات مثل إرسال الرسائل والبث"},"definition":{"en":"synapse-a2a is an inter-agent communication framework utilizing the Google A2A Protocol for efficient message exchange between agents.","zh":"Synapse A2A 通信框架是一种 inter-agent 通信框架，用于实现 AI エージェント 之间的通信","ja":"Synapse A2A コミュニケーション フレームワークは、AI エージェント間のコミュニケーションを実現する inter-agent コミュニケーション フレームワークです","ko":"Synapse A2A 통신 프레임워크는 AI 에이전트 간의 통신을 실현하는 inter-agent 통신 프레임워크입니다","es":"Synapse A2A es un framework de comunicación que permite a los agentes de inteligencia artificial intercambiar mensajes y datos.","fr":"Synapse A2A est un framework de communication qui permet aux agents d''intelligence artificielle d''échanger des messages et des données.","de":"Synapse A2A ist ein Kommunikationsframework, das es KI-Agents ermöglicht, Nachrichten und Daten auszutauschen.","pt":"Synapse A2A é um framework de comunicação que permite a troca de dados entre agentes via protocolo Google A2A","ru":"Synapse A2A - это фреймворк для обмена данными, который позволяет обмениваться данными между ИИ Агентами через протокол Google A2A","ar":"Synapse A2A هو إطار للتواصل الذي يسمح بالتبادل البيانات بين وكلاء الذكاء الاصطناعي عبر بروتوكول Google A2A"},"features":{"en":["Lists agents using the `synapse list` command with event-driven refresh","Sends messages between agents via `synapse send <target> <message> --from <sender>`","Broadcasts messages to cwd agents using `synapse broadcast <message> --from <sender>`","Waits for replies with the `s` command","Utilizes a file watcher with 10s fallback for efficient communication","Supports filtering by TYPE, NAME, and WORKING_DIR"],"zh":["基于 Google A2A 协议的 inter-agent 通信","列表、发送消息、广播和等待回复等功能","支持 event-driven 刷新和 file watcher","提供 Rich TUI 界面","支持多种命令行参数"],"ja":["Google A2A プロトコルに基づく inter-agent コミュニケーション","リスト表示、メッセージ送信、ブロードキャスト、応答待ちなどの機能","イベント駆動型の更新とファイルウォッチャーをサポート","Rich TUI インターフェイスを提供","複数のコマンドラインパラメーターをサポート"],"ko":["Google A2A 프로토콜을 기반으로 하는 inter-agent 통신","목록 표시, 메시지 전송, 방송 및 응답 대기 등의 기능","이벤트 주도형 갱신과 파일 감시기를 지원","Rich TUI 인터페이스를 제공","다수의 명령어 매개변수를 지원"],"es":["Comunicación entre agentes mediante el protocolo Google A2A","Envío de mensajes entre agentes con el comando `synapse send`","Difusión de mensajes a agentes en el directorio actual con el comando `synapse broadcast`","Espera de respuestas con el comando `s`","Lista de agentes disponibles con el comando `synapse list`"],"fr":["Communication entre agents via le protocole Google A2A","Envoi de messages entre agents avec la commande `synapse send`","Diffusion de messages aux agents dans le répertoire courant avec la commande `synapse broadcast`","Attente de réponses avec la commande `s`","Liste des agents disponibles avec la commande `synapse list`"],"de":["Kommunikation zwischen Agents über das Google A2A-Protokoll","Senden von Nachrichten zwischen Agents mit dem Befehl `synapse send`","Broadcast von Nachrichten an Agents im aktuellen Verzeichnis mit dem Befehl `synapse broadcast`","Warten auf Antworten mit dem Befehl `s`","Liste der verfügbaren Agents mit dem Befehl `synapse list`"],"pt":["Envio de mensagens entre agentes","Broadcast para agentes no diretório atual","Suporte a refresh via file watcher com fallback de 10s","Seleção de agentes via interface de usuário rica","Filtro de agentes por tipo, nome ou diretório de trabalho"],"ru":["Отправка сообщений между ИИ Агентами","Вещание для ИИ Агентов в текущем каталоге","Поддержка обновления через файловый монитор с запасным вариантом 10с","Выбор ИИ Агентов через богатый интерфейс пользователя","Фильтрация ИИ Агентов по типу, имени или рабочему каталогу"],"ar":["إرسال الرسائل بين وكلاء الذكاء الاصطناعي","البث إلى وكلاء الذكاء الاصطناعي في الدليل الحالي","دعم التحديث عبر مراقب الملفات مع خيار احتياطي 10 ثانية","اختيار وكلاء الذكاء الاصطناعي عبر واجهة المستخدم الغنية","تصفية وكلاء الذكاء الاصطناعي حسب النوع أو الاسم أو دليل العمل"]},"keywords":{"en":["how to use synapse-a2a","synapse-a2a setup guide","synapse-a2a alternative","synapse-a2a vs Google A2A Protocol","synapse-a2a install","what is synapse-a2a","inter-agent communication framework","Google A2A Protocol tutorial","synapse-a2a documentation"],"zh":["Synapse A2A","inter-agent 通信","Google A2A 协议","AI エージェント","通信框架","列表","发送消息","广播","等待回复"],"ja":["Synapse A2A","inter-agent コミュニケーション","Google A2A プロトコル","AI エージェント","コミュニケーション フレームワーク","リスト表示","メッセージ送信","ブロードキャスト","応答待ち"],"ko":["Synapse A2A","inter-agent 통신","Google A2A 프로토콜","AI 에이전트","통신 프레임워크","목록 표시","메시지 전송","방송","응답 대기"],"es":["Synapse A2A","comunicación entre agentes","protocolo Google A2A","agentes de inteligencia artificial","envío de mensajes","difusión de mensajes","espera de respuestas","lista de agentes"],"fr":["Synapse A2A","communication entre agents","protocole Google A2A","agents d''intelligence artificielle","envoi de messages","diffusion de messages","attente de réponses","liste des agents"],"de":["Synapse A2A","Kommunikation zwischen Agents","Google A2A-Protokoll","KI-Agents","Nachrichten senden","Nachrichten broadcasten","Antworten warten","Agenten liste"],"pt":["Synapse A2A","comunicação entre agentes","protocolo Google A2A","envio de mensagens","broadcast","CLI","file watcher","interface de usuário rica"],"ru":["Synapse A2A","обмен данными между ИИ Агентами","протокол Google A2A","отправка сообщений","вещание","CLI","файловый монитор","богатый интерфейс пользователя"],"ar":["Synapse A2A","التواصل بين وكلاء الذكاء الاصطناعي","بروتوكول Google A2A","إرسال الرسائل","البث","CLI","مراقب الملفات","واجهة المستخدم الغنية"]}},"owner":"s-hiraoku","repo":"vscode-sidebar-terminal","repoPath":"s-hiraoku/vscode-sidebar-terminal","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.601Z","topics":[],"category":"community","skillMd":{"name":"synapse-a2a","description":"This skill provides comprehensive guidance for inter-agent communication using the Synapse A2A framework. Use this skill when sending messages to other agents via synapse send/reply commands, understanding priority levels, handling A2A protocol operations, managing task history, configuring settings, or using File Safety features for multi-agent coordination. Automatically triggered when agent communication, A2A protocol tasks, history operations, or file safety operations are detected.","bodyPreview":"# Synapse A2A Communication\n\nInter-agent communication framework via Google A2A Protocol.\n\n## Quick Reference\n\n| Task | Command |\n|------|---------|\n| List agents (Rich TUI) | `synapse list` (event-driven refresh via file watcher with 10s fallback, ↑/↓ or 1-9 to select, Enter/j jump, k kill, / filter by TYPE/NAME/WORKING_DIR) |\n| Send message | `synapse send <target> \"<message>\" --from <sender>` |\n| Broadcast to cwd agents | `synapse broadcast \"<message>\" --from <sender>` |\n| Wait for reply | `s","body":"# Synapse A2A Communication\n\nInter-agent communication framework via Google A2A Protocol.\n\n## Quick Reference\n\n| Task | Command |\n|------|---------|\n| List agents (Rich TUI) | `synapse list` (event-driven refresh via file watcher with 10s fallback, ↑/↓ or 1-9 to select, Enter/j jump, k kill, / filter by TYPE/NAME/WORKING_DIR) |\n| Send message | `synapse send <target> \"<message>\" --from <sender>` |\n| Broadcast to cwd agents | `synapse broadcast \"<message>\" --from <sender>` |\n| Wait for reply | `synapse send <target> \"<message>\" --response --from <sender>` |\n| Reply to last message | `synapse reply \"<response>\"` |\n| Reply to specific sender | `synapse reply \"<response>\" --to <sender_id>` |\n| List reply targets | `synapse reply --list-targets` |\n| Emergency stop | `synapse send <target> \"STOP\" --priority 5 --from <sender>` |\n| Stop agent | `synapse stop <profile\\|id>` |\n| Kill agent (graceful) | `synapse kill <target>` (sends shutdown request, 30s timeout, then SIGTERM) |\n| Kill agent (force) | `synapse kill <target> -f` (immediate SIGKILL) |\n| Jump to terminal | `synapse jump <target>` |\n| Rename agent | `synapse rename <target> --name <name> --role <role>` |\n| Check file locks | `synapse file-safety locks` |\n| View history | `synapse history list` |\n| Initialize settings | `synapse init` |\n| Edit settings (TUI) | `synapse config` (includes List Display for column config) |\n| View settings | `synapse config show [--scope user\\|project]` |\n| Reset settings | `synapse reset [--scope user\\|project\\|both]` |\n| Show instructions | `synapse instructions show <agent>` |\n| Send instructions | `synapse instructions send <agent> [--preview]` |\n| View logs | `synapse logs <profile> [-f] [-n <lines>]` |\n| Add external agent | `synapse external add <url> [--alias <name>]` |\n| List external agents | `synapse external list` |\n| External agent info | `synapse external info <alias>` |\n| Send to external | `synapse external send <alias> \"<message>\" [--wait]` |\n| Remove external agent | `synapse external remove <alias>` |\n| Skill Manager (TUI) | `synapse skills` |\n| List skills | `synapse skills list [--scope synapse\\|user\\|project\\|plugin]` |\n| Show skill detail | `synapse skills show <name>` |\n| Deploy skill | `synapse skills deploy <name> --agent claude,codex --scope user` |\n| Import skill | `synapse skills import <name>` |\n| Install from repo | `synapse skills add <repo>` |\n| Create skill | `synapse skills create` |\n| Delete skill | `synapse skills delete <name> [--force]` |\n| Move skill | `synapse skills move <name> --to <scope>` |\n| List skill sets | `synapse skills set list` |\n| Show skill set detail | `synapse skills set show <name>` |\n| Trace task | `synapse trace <task_id>` |\n| Auth setup | `synapse auth setup` (generate keys + instructions) |\n| Generate API key | `synapse auth generate-key [-n <count>] [-e]` |\n| List task board | `synapse tasks list [--status pending] [--agent claude]` |\n| Create task | `synapse tasks create \"subject\" -d \"description\" [--blocked-by ID]` |\n| Assign task | `synapse tasks assign <task_id> <agent>` |\n| Complete task | `synapse tasks complete <task_id>` |\n| Approve plan | `synapse approve <task_id>` |\n| Reject plan | `synapse reject <task_id> --reason \"reason\"` |\n| Start team (CLI) | `synapse team start <spec...> [--layout ...] [--all-new]` (1st=handoff, rest=new panes; `--all-new` for all new) |\n| Start team (API) | `POST /team/start` with `{\"agents\": [...], \"layout\": \"split\"}` |\n| Spawn agent | `synapse spawn <profile> [--port] [--name] [--role] [--skill-set] [--terminal]` |\n| Delegate mode | `synapse claude --delegate-mode [--name coordinator]` |\n| Version info | `synapse --version` |\n\n**Tip:** Run `synapse list` before sending to verify the target agent is READY.\n\n## Sending Messages (Recommended)\n\n**Use `synapse send` command for inter-agent communication.** This works reliably from any environment including sandboxed agents.\n\n```bash\nsynapse send gemini \"Please review this code\" --response --from synapse-claude-8100\nsynapse send claude \"What is the status?\" --response --from synapse-codex-8121\nsynapse send codex-8120 \"Fix this bug\" --response --priority 3 --from synapse-gemini-8110\n```\n\n**Important:**\n- Always use `--from` with your **agent ID** (format: `synapse-<type>-<port>`). Do NOT use custom names or agent types for `--from`.\n- By default, use `--response` to wait for a reply. Only use `--no-response` for notifications or fire-and-forget tasks.\n\n**Target Resolution (Matching Priority):**\n1. Custom name: `my-claude` (highest priority, exact match, case-sensitive)\n2. Exact ID: `synapse-claude-8100` (direct match)\n3. Type-port: `claude-8100`, `codex-8120`, `opencode-8130`, `copilot-8140` (shorthand)\n4. Type only: `claude`, `gemini`, `codex`, `opencode`, `copilot` (only if single instance)\n\n**Note:** When multiple agents of the same type are running, type-only targets (e.g., `claude`) will fail with an ambiguity error. Use custom name (e.g., `my-claude`) or type-port shorthand (e.g., `claude-8100`) instead.\n\n### Choosing --response vs --no-response\n\nAnalyze the message content and determine if a reply is expected:\n- If the message expects or benefits from a reply → use `--response`\n- If the message is purely informational with no reply needed → use `--no-response`\n- **If unsure, use `--response`** (safer default)\n\n```bash\n# Message that expects a reply\nsynapse send gemini \"What is the best approach?\" --response --from synapse-claude-8100\n\n# Purely informational, no reply needed\nsynapse send codex \"FYI: Build completed\" --no-response --from synapse-claude-8100\n```\n\n### Roundtrip Communication (--response)\n\nFor request-response patterns:\n\n```bash\n# Sender: Wait for response (blocks until reply received)\nsynapse send gemini \"Analyze this data\" --response --from synapse-claude-8100\n\n# Receiver: Reply to sender (auto-routes via reply tracking)\nsynapse reply \"Analysis result: ...\"\n```\n\nThe `--response` flag makes the sender wait. The receiver should reply using the `synapse reply` command.\n\n**Reply Tracking:** Synapse automatically tracks senders who expect a reply (`[REPLY EXPECTED]` messages). Use `synapse reply` for responses - it automatically knows who to reply to.\n\n### Broadcasting to All Agents\n\nSend a message to all agents sharing the same working directory:\n\n```bash\n# Broadcast status check to all cwd agents\nsynapse broadcast \"Status check\" --from synapse-claude-8100\n\n# Urgent broadcast\nsynapse broadcast \"Urgent: stop all work\" --priority 4 --from synapse-claude-8100\n\n# Fire-and-forget broadcast\nsynapse broadcast \"FYI: Build completed\" --no-response --from synapse-claude-8100\n```\n\n**Note:** Broadcast only targets agents in the **same working directory** as the sender. This prevents unintended messages to agents working on different projects.\n\n## Receiving and Replying to Messages\n\nWhen you receive an A2A message, it appears with the `A2A:` prefix:\n\n**Message Formats:**\n```\nA2A: [REPLY EXPECTED] <message>   <- Reply is REQUIRED\nA2A: <message>                    <- Reply is optional (one-way notification)\n```\n\nIf `[REPLY EXPECTED]` marker is present, you **MUST** reply using `synapse reply`.\n\n**Reply Tracking:** Synapse stores sender info only for messages with `[REPLY EXPECTED]` marker. Multiple senders can be tracked simultaneously (each sender has one entry).\n\n**Replying to messages:**\n\n```bash\n# Use the reply command (auto-routes to last sender)\nsynapse reply \"Here is my analysis...\"\n\n# When multiple senders are pending, inspect and choose target\nsynapse reply --list-targets\nsynapse reply \"Here is my analysis...\" --to <sender_id>\n\n# In sandboxed environments (like Codex), specify your agent ID\nsynapse reply \"Here is my analysis...\" --from <your_agent_id>\n```\n\n**Example - Question received (MUST reply):**\n```\nReceived: A2A: [REPLY EXPECTED] What is the project structure?\nReply:    synapse reply \"The project has src/, tests/...\"\n```\n\n**Example - Delegation received (no reply needed):**\n```\nReceived: A2A: Run the tests and fix failures\nAction:   Just do the task. No reply needed unless you have questions.\n```\n\n## Priority Levels\n\n| Priority | Description | Use Case |\n|----------|-------------|----------|\n| 1-2 | Low | Background tasks |\n| 3 | Normal | Standard tasks |\n| 4 | Urgent | Follow-ups, status checks |\n| 5 | Interrupt | Emergency (sends SIGINT first) |\n\nDefault priority: `send` = 3 (normal), `broadcast` = 1 (low).\n\n```bash\n# Normal priority (default: 3) - with response\nsynapse send gemini \"Analyze this\" --response --from synapse-claude-8100\n\n# Higher priority - urgent request\nsynapse send claude \"Urgent review needed\" --response --priority 4 --from synapse-codex-8121\n\n# Emergency interrupt\nsynapse send codex \"STOP\" --priority 5 --from synapse-claude-8100\n```\n\n## Agent Status\n\n| Status | Meaning | Color |\n|--------|---------|-------|\n| READY | Idle, waiting for input | Green |\n| WAITING | Awaiting user input (selection, confirmation) | Cyan |\n| PROCESSING | Busy handling a task | Yellow |\n| DONE | Task completed (auto-clears after 10s) | Blue |\n| SHUTTING_DOWN | Graceful shutdown in progress | Red |\n\n**Verify before sending:** Run `synapse list` and confirm the target agent''s Status column shows `READY`:\n\n```bash\nsynapse list\n# Output (NAME column shows custom name if set, otherwise agent ID):\n# NAME        TYPE    STATUS      PORT   WORKING_DIR\n# my-claude   claude  READY       8100   my-project      # <- has custom name\n# gemini      gemini  WAITING     8110   my-project      # <- no custom name, shows type\n# codex       codex   PROCESSING  8120   my-project      # <- busy\n```\n\n**Status meanings:**\n- `READY`: Safe to send messages\n- `WAITING`: Agent needs user input - use terminal jump (see below) to respond\n- `PROCESSING`: Busy, wait or use `--priority 5` for emergency interrupt\n- `DONE`: Recently completed, will return to READY shortly\n\n## Interactive Controls\n\nIn `synapse list`, you can interact with agents:\n\n| Key | Action |\n|-----|--------|\n| `1-9` | Select agent row (direct) |\n| `↑/↓` | Navigate agent rows |\n| `Enter` or `j` | Jump to selected agent''s terminal |\n| `k` | Kill selected agent (with confirmation) |\n| `/` | Filter by TYPE, NAME, or WORKING_DIR |\n| `ESC` | Clear filter first, then selection |\n| `q` | Quit |\n\n**Supported Terminals:**\n- iTerm2 (macOS) - Switches to correct tab/pane\n- Terminal.app (macOS) - Switches to correct tab\n- Ghostty (macOS) - Activates application\n- VS Code integrated terminal - Opens to working directory\n- tmux - Switches to agent''s session\n- Zellij - Activates terminal app (direct pane focus not supported via CLI)\n\n**Use case:** When an agent shows `WAITING` status, use terminal jump to quickly respond to its selection prompt.\n\n## Agent Naming\n\nAssign custom names and roles to agents for easier identification:\n\n```bash\n# Start with name and role\nsynapse claude --name my-claude --role \"code reviewer\"\n\n# Skip interactive name/role setup\nsynapse claude --no-setup\n\n# Update name/role after agent is running\nsynapse rename synapse-claude-8100 --name my-claude --role \"test writer\"\nsynapse rename my-claude --role \"documentation\"  # Change role only\nsynapse rename my-claude --clear                 # Clear name and role\n```\n\nOnce named, use the custom name for all operations:\n\n```bash\nsynapse send my-claude \"Review this code\" --from synapse-codex-8121\nsynapse jump my-claude\nsynapse kill my-claude\n```\n\n**Name vs ID:**\n- **Display/Prompts**: Shows name if set, otherwise ID (e.g., `Kill my-claude (PID: 1234)?`)\n- **Internal processing**: Always uses agent ID (`synapse-claude-8100`)\n- **Target resolution**: Name has highest priority when matching targets\n\n## External Agent Management\n\nConnect to external A2A-compatible agents over HTTP/HTTPS:\n\n```bash\n# Discover and add an external agent\nsynapse external add https://agent.example.com --alias myagent\n\n# List registered external agents\nsynapse external list\n\n# Show agent details (capabilities, skills)\nsynapse external info myagent\n\n# Send message to external agent\nsynapse external send myagent \"Analyze this data\"\nsynapse external send myagent \"Process file\" --wait  # Wait for completion\n\n# Remove agent\nsynapse external remove myagent\n```\n\nExternal agents are stored persistently in `~/.a2a/external/`.\n\n## Authentication\n\nSecure A2A communication with API key authentication:\n\n```bash\n# Interactive setup (generates keys + shows instructions)\nsynapse auth setup\n\n# Generate API key(s)\nsynapse auth generate-key\nsynapse auth generate-key -n 3 -e  # 3 keys in export format\n\n# Enable authentication\nexport SYNAPSE_AUTH_ENABLED=true\nexport SYNAPSE_API_KEYS=<key>\nexport SYNAPSE_ADMIN_KEY=<admin_key>\nsynapse claude\n```\n\n## Resume Mode\n\nStart agents without sending initial instructions (for session recovery):\n\n```bash\nsynapse claude -- --resume\nsynapse gemini -- --resume\nsynapse codex -- resume        # Codex: resume is a subcommand\nsynapse opencode -- --continue\nsynapse copilot -- --continue\n```\n\nTo inject instructions later: `synapse instructions send <agent>`.\n\n## Key Features\n\n- **Agent Naming**: Custom names and roles for easy identification\n- **Agent Communication**: `synapse send` command, `synapse broadcast` for cwd-scoped messaging, priority control, response handling\n- **Task History**: Search, export, statistics (`synapse history`)\n- **File Safety**: Lock files to prevent conflicts (`synapse file-safety`); active locks shown in `synapse list` EDITING_FILE column\n- **External Agents**: Connect to external A2A agents (`synapse external`)\n- **Authentication**: API key-based security (`synapse auth`)\n- **Skill Management**: Central skill store, deploy, import, create, skill sets (`synapse skills`). Skill set details (name, description, skills) are included in agent initial instructions when selected.\n- **Settings**: Configure via `settings.json` (`synapse init`)\n- **Approval Mode**: Control initial instruction approval (`approvalMode` in settings)\n- **Shared Task Board**: Create, claim, and complete tasks with dependency tracking (`synapse tasks`)\n- **Quality Gates**: Configurable hooks (`on_idle`, `on_task_completed`) that gate status transitions\n- **Plan Approval**: Plan-mode workflow with `synapse approve/reject` for review\n- **Graceful Shutdown**: `synapse kill` sends shutdown request before SIGTERM (30s timeout)\n- **Delegate Mode**: `--delegate-mode` creates a coordinator that delegates instead of editing files\n- **Auto-Spawn Panes**: `synapse team start` — 1st agent takes over current terminal (handoff), others in new panes. `--all-new` for all new panes. Supports `profile:name:role:skill_set` spec (tmux/iTerm2/Terminal.app/zellij)\n- **Spawn Single Agent**: `synapse spawn <profile>` — Spawn a single agent in a new terminal pane or window. Automatically uses `--headless` mode.\n\n## Spawning Agents\n\nSpawn a single agent in a new terminal pane or window.\n\n```bash\nsynapse spawn claude                          # Spawn Claude in a new pane\nsynapse spawn gemini --port 8115              # Spawn with explicit port\nsynapse spawn claude --name Tester --role \"test writer\"  # With name/role\nsynapse spawn claude --terminal tmux          # Use specific terminal\n```\n\n**Headless Mode:**\nWhen an agent is started via `synapse spawn`, it automatically runs with the `--headless` flag. This skips all interactive setup (name/role prompts, startup animations, and initial instruction approval prompts) to allow for smooth programmatic orchestration. The A2A server remains active, and initial instructions are still sent to enable communication.\n\n**Note:** The spawning agent is responsible for the lifecycle of the spawned agent. Ensure you terminate spawned agents using `synapse kill <target> -f` when their task is complete.\n\n**Pane Auto-Close:** When an agent process terminates, the pane/tab/window closes automatically in all supported terminals. Zellij uses `--close-on-exit`; iTerm2, Terminal.app, and Ghostty use `exec` to replace the shell process; tmux `split-window` closes natively on process exit.\n\n## Path Overrides\n\nWhen running multiple environments or tests, override storage paths via env vars:\n\n- `SYNAPSE_REGISTRY_DIR` (default: `~/.a2a/registry`)\n- `SYNAPSE_EXTERNAL_REGISTRY_DIR` (default: `~/.a2a/external`)\n- `SYNAPSE_HISTORY_DB_PATH` (default: `~/.synapse/history/history.db`)\n- `SYNAPSE_SKILLS_DIR` (default: `~/.synapse/skills`)\n\n## References\n\nFor detailed documentation, read:\n\n- `references/commands.md` - Full CLI command reference\n- `references/file-safety.md` - File Safety detailed guide\n- `references/api.md` - A2A endpoints and message format\n- `references/examples.md` - Multi-agent workflow examples\n"},"lastSynced":"2026-03-08T02:12:39.777Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code requiring seamless inter-agent communication via Google A2A Protocol.","zh":"适合于像 Cursor、Windsurf 和 Claude Code 这样的 AI Agents，它们需要通过 Google A2A Protocol 实现无缝的互相通信。","ja":"Cursor、Windsurf、Claude Code などの AI エージェントに適しています。これらは Google A2A Protocol 経由でエージェント間のシームレスな通信を必要とします。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. 이들은 Google A2A Protocol을 통해 에이전트 간의 무결점 통신을 필요로 합니다.","es":"Ideal para Agentes de IA como Cursor, Windsurf y Claude Code que requieren una comunicación entre agentes sin problemas a través del Protocolo Google A2A.","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant une communication inter-agents sans accroc via le Protocole Google A2A.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die eine nahtlose Kommunikation zwischen den Agents über das Google A2A-Protokoll erfordern.","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que requerem comunicação inter-agente sem interrupções via Protocolo Google A2A.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих бесшовного взаимодействия между агентами через протокол Google A2A.","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذين يتطلبون اتصال وسيط بين العوامل بدون انقطاع عبر بروتوكول Google A2A."},"recommendation":{"en":"Empowers agents to efficiently send and receive messages using commands like synapse list, send, and broadcast, leveraging the Google A2A Protocol for robust communication, and supporting event-driven refresh and file watcher functionality.","zh":"赋予代理人使用诸如 synapse list、send 和 broadcast 之类的命令，利用 Google A2A Protocol 实现强大的通信，并支持事件驱动的刷新和文件监视器功能，从而高效地发送和接收消息。","ja":"エージェントは、synapse list、send、broadcast などのコマンドを使用してメッセージを効率的に送信および受信できます。Google A2A Protocol を使用した強力なコミュニケーションと、イベント駆動のリフレッシュおよびファイルウォッチャー機能をサポートします。","ko":"에이전트는 synapse list, send, broadcast와 같은 명령을 사용하여 메시지를 효율적으로 보내고 받을 수 있으며, Google A2A Protocol을 사용한 강력한 통신과 이벤트 驱动의刷新 및 파일 감시기 기능을 지원합니다.","es":"Habilita a los agentes a enviar y recibir mensajes de forma eficiente utilizando comandos como synapse list, send y broadcast, aprovechando el Protocolo Google A2A para una comunicación robusta y admitiendo la funcionalidad de actualización y vigilancia de archivos basada en eventos.","fr":"Permet aux agents d''envoyer et de recevoir des messages de manière efficace en utilisant des commandes comme synapse list, send et broadcast, en exploitant le Protocole Google A2A pour une communication robuste et en prenant en charge la fonctionnalité de rafraîchissement et de surveillance de fichiers basée sur les événements.","de":"Ermöglicht es den Agents, Nachrichten effizient zu senden und zu empfangen, indem sie Befehle wie synapse list, send und broadcast verwenden, das Google A2A-Protokoll für eine robuste Kommunikation nutzt und die Funktionalität für ereignisgesteuerte Aktualisierung und Dateiüberwachung unterstützt.","pt":"Habilite os agentes a enviar e receber mensagens de forma eficiente usando comandos como synapse list, send e broadcast, aproveitando o Protocolo Google A2A para comunicação robusta e suportando funcionalidade de refresh baseada em eventos e file watcher.","ru":"Позволяет агентам эффективно отправлять и получать сообщения, используя команды, такие как synapse list, send и broadcast, используя протокол Google A2A для надежной связи и поддерживая функциональность обновления на основе событий и наблюдателя за файлами.","ar":"تمكين الوكلاء من إرسال واستلام الرسائل بفعالية باستخدام أوامر مثل synapse list و send و broadcast، والاستفادة من بروتوكول Google A2A للاتصال القوي ودعم ميزة تحديث قائم على الأحداث ومشاهدة الملفات."},"useCases":{"en":["Listing available agents with synapse list","Sending targeted messages using synapse send","Broadcasting messages to multiple agents in the current working directory with synapse broadcast"],"zh":["使用 synapse list 列出可用的代理人","使用 synapse send 发送目标消息","使用 synapse broadcast 将消息广播到当前工作目录中的多个代理人"],"ja":["synapse list を使用して利用可能なエージェントをリストする","synapse send を使用して対象メッセージを送信する","synapse broadcast を使用して現在の作業ディレクトリ内の複数のエージェントにメッセージをブロードキャストする"],"ko":["synapse list를 사용하여 사용 가능한 에이전트를 목록화する","synapse send를 사용하여 대상 메시지를 전송하는","synapse broadcast를 사용하여 현재 작업 디렉토리 내의 여러 에이전트에 메시지를 방송하는"],"es":["Listar agentes disponibles con synapse list","Enviar mensajes dirigidos utilizando synapse send","Transmitir mensajes a varios agentes en el directorio de trabajo actual con synapse broadcast"],"fr":["Lister les agents disponibles avec synapse list","Envoyer des messages ciblés en utilisant synapse send","Diffuser des messages à plusieurs agents dans le répertoire de travail actuel avec synapse broadcast"],"de":["Verfügbare Agents mit synapse list auflisten","Gezielte Nachrichten mit synapse send senden","Nachrichten an mehrere Agents im aktuellen Arbeitsverzeichnis mit synapse broadcast übertragen"],"pt":["Listar agentes disponíveis com synapse list","Enviar mensagens direcionadas usando synapse send","Transmitir mensagens para vários agentes no diretório de trabalho atual com synapse broadcast"],"ru":["Перечисление доступных агентов с помощью synapse list","Отправка целевых сообщений с помощью synapse send","Трансляция сообщений нескольким агентам в текущем рабочем каталоге с помощью synapse broadcast"],"ar":["استعراض العوامل المتاحة باستخدام synapse list","إرسال رسائل مستهدفة باستخدام synapse send","بث الرسائل إلى العديد من العوامل في الدليل الحالي للعمل باستخدام synapse broadcast"]},"limitations":{"en":["Requires Google A2A Protocol compatibility","Depends on file watcher with 10s fallback for event-driven refresh"],"zh":["需要 Google A2A Protocol 兼容性","依赖于文件监视器，具有 10 秒的回退功能，用于事件驱动的刷新"],"ja":["Google A2A Protocol の互換性が必要","ファイルウォッチャーに依存しており、イベント駆動のリフレッシュ用に 10 秒のフォールバック機能があります"],"ko":["Google A2A Protocol 호환성이 필요합니다","파일 감시기에 의존하며, 이벤트駆動의 리フレ시를 위한 10초의 폴백 기능이 있습니다"],"es":["Requiere compatibilidad con el Protocolo Google A2A","Depende de file watcher con un tiempo de espera de 10 s para la actualización basada en eventos"],"fr":["Nécessite la compatibilité avec le Protocole Google A2A","Dépend de file watcher avec un délai de 10 s pour le rafraîchissement basé sur les événements"],"de":["Benötigt Kompatibilität mit dem Google A2A-Protokoll","Hängt von file watcher mit einer Auszeit von 10 s für die ereignisgesteuerte Aktualisierung ab"],"pt":["Requer compatibilidade com Protocolo Google A2A","Depende do file watcher com fallback de 10s para refresh baseado em eventos"],"ru":["Требует совместимости с протоколом Google A2A","Зависит от наблюдателя за файлами с запасом 10 секунд для обновления на основе событий"],"ar":["يتطلب توافقًا مع بروتوكول Google A2A","يعتمد على مراقب الملفات معallback لمدة 10 ثوانٍ لتحديث قائم على الأحداث"]},"version":4},"contentHash":"a85f4e8e5e437d738a074029edd57c8196a0fb3acbc72dc131db383fc69a14b2","qualityScore":60}');
