INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('s-hiraoku/vscode-sidebar-terminal/synapse-a2a', 'synapse-a2a', 's-hiraoku', 'vscode-sidebar-terminal', 'community', 'synapse-a2a s-hiraoku vscode-sidebar-terminal community synapse-a2a enables inter-agent communication via Google A2A Protocol, benefiting developers with efficient message sending and reception. It supports commands like synapse list, send, and broadcast. Synapse A2A 通信框架是一种基于 Google A2A 协议的 inter-agent 通信框架，提供列表、发送消息、广播和等待回复等功能 Synapse A2A コミュニケーション フレームワークは、Google A2A プロトコルに基づく inter-agent コミュニケーション フレームワークです。リスト表示、メッセージ送信、ブロードキャスト、応答待ちなどの機能を提供します Synapse A2A 통신 프레임워크는 Google A2A 프로토콜을 기반으로 하는 inter-agent 통신 프레임워크로, 목록 표시, 메시지 전송, 방송 및 응답 대기 등의 기능을 제공합니다 Synapse A2A es un framework de comunicación entre agentes que utiliza el protocolo Google A2A. Permite la comunicación entre agentes de inteligencia artificial. Synapse A2A est un framework de communication entre agents qui utilise le protocole Google A2A. Il permet la communication entre les agents d''intelligence artificielle. Synapse A2A ist ein Kommunikationsframework zwischen Agents, das das Google A2A-Protokoll verwendet. Es ermöglicht die Kommunikation zwischen KI-Agents. O Synapse A2A é um framework de comunicação entre agentes via protocolo Google A2A, permitindo envio de mensagens e broadcast Synapse A2A - это фреймворк для обмена данными между ИИ Агентами через протокол Google A2A, позволяющий отправлять сообщения и вещать Synapse A2A هو إطار للتواصل بين وكلاء الذكاء الاصطناعي عبر بروتوكول Google A2A، مما يسمح بإرسال الرسائل والبث how to use synapse-a2a synapse-a2a setup guide synapse-a2a alternative synapse-a2a vs Google A2A Protocol synapse-a2a install what is synapse-a2a inter-agent communication framework Google A2A Protocol tutorial synapse-a2a documentation Synapse A2A inter-agent 通信 Google A2A 协议 AI エージェント 通信框架 列表 发送消息 广播 等待回复 Lists agents using the `synapse list` command with event-driven refresh Sends messages between agents via `synapse send <target> <message> --from <sender>` Broadcasts messages to cwd agents using `synapse broadcast <message> --from <sender>` Waits for replies with the `s` command Utilizes a file watcher with 10s fallback for efficient communication Supports filtering by TYPE, NAME, and WORKING_DIR synapse-a2a is an inter-agent communication framework utilizing the Google A2A Protocol for efficient message exchange between agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DigitalHumanitiesCraft/mhdbdb-tei-only/pos-disambiguator', 'community', 'DigitalHumanitiesCraft', 'mhdbdb-tei-only', 'DigitalHumanitiesCraft/mhdbdb-tei-only', 'pos-disambiguator', 0, 0, 60, '2026-03-08T01:57:15.601Z', '2026-03-08T02:12:40.665Z', 'b5652cca44d4e51e0a09d273f9f0987191c375249b5f585d5a66de5108b96eae', '{"id":"DigitalHumanitiesCraft/mhdbdb-tei-only/pos-disambiguator","name":"pos-disambiguator","description":{"en":"The pos-disambiguator skill validates and corrects Part-of-Speech tags using semantic analysis and grammatical context, benefiting linguistic researchers and Middle High German scholars.","zh":"pos-disambiguator是中世AIエージェント，使用Gemini 3 Pro进行语义分析和语法上下文验证。","ja":"pos-disambiguatorは、Gemini 3 Proを使用して語彙の意味分析と文法的コンテキストの検証を行うAIエージェントです。","ko":"pos-disambiguator는 Gemini 3 Pro를 사용하여 의미 분석 및 문법적 문맥 검증을 수행하는 개발자용 AI 에이전트입니다.","es":"El pos-disambiguator es una herramienta especializada para el análisis semántico de textos en alemán medieval superior, que utiliza contexto gramatical para validar y corregir etiquetas de Part-of-Speech","fr":"Le pos-disambiguator est un outil spécialisé pour l''analyse sémantique de textes en moyen haut allemand, qui utilise le contexte grammatical pour valider et corriger les étiquettes de Part-of-Speech","de":"Der pos-disambiguator ist ein spezialisiertes Tool für die semantische Analyse von Texten des mittelhochdeutschen, das den grammatischen Kontext nutzt, um Part-of-Speech-Tags zu validieren und zu korrigieren","pt":"O pos-disambiguator é um agente linguístico especializado em análise semântica e correção de tags Part-of-Speech em Middle High German","ru":"ИИ Агент pos-disambiguator - это специализированный лингвистический агент для семантического анализа и исправления тегов части речи в Средневерхненемецком","ar":"أداة pos-disambiguator هي أداة لغوية متخصصة في التحليل الدلالي وتصحيح وسوم جزء الكلام في اللغة الألمانية العليا الوسطى"},"seo":{"title":{"en":"pos-disambiguator: Semantic Analysis Setup Guide | AI Age...","zh":"pos-disambiguator 中世AIエージェント设置指南","ja":"pos-disambiguatorのAIエージェントベストプラクティス","ko":"pos-disambiguator 설정 가이드","es":"Guía de Configuración de pos-disambiguator para Análisis ...","fr":"Guide de Configuration de pos-disambiguator pour l''Analys...","de":"Konfigurationsleitfaden für pos-disambiguator zur semanti...","pt":"Guia de Configuração do pos-disambiguator para Análise Se...","ru":"Настройка ИИ Агента pos-disambiguator для Семантического ...","ar":"إعداد أداة=pos-disambiguator للتحليل الدلالي"},"description":{"en":"Unlock accurate Part-of-Speech tagging with pos-disambiguator. Discover how to leverage semantic analysis and grammatical context for Middle High German text...","zh":"了解pos-disambiguator的中世AIエージェント技术，使用Gemini 3 Pro进行语义分析和语法上下文验证","ja":"pos-disambiguatorのAIエージェントを使用して、Gemini 3 Proによる語彙の意味分析と文法的コンテキストの検証を行う","ko":"pos-disambiguator 설정을 통해 Gemini 3 Pro의 의미 분석 및 문법적 문맥 검증 기능을 활용하세요","es":"Aprende a utilizar pos-disambiguator para mejorar la precisión de las etiquetas de Part-of-Speech en textos en alemán medieval superior con análisis semántic...","fr":"Découvrez comment utiliser pos-disambiguator pour améliorer la précision des étiquettes de Part-of-Speech dans les textes en moyen haut allemand avec analyse...","de":"Erfahren Sie, wie Sie pos-disambiguator verwenden können, um die Genauigkeit von Part-of-Speech-Tags in Texten des mittelhochdeutschen mit semantischer Analy...","pt":"Aprenda a configurar o pos-disambiguator para análise semântica e correção de tags Part-of-Speech em Middle High German","ru":"Узнайте, как настроить ИИ Агент pos-disambiguator для семантического анализа и исправления тегов части речи в Средневерхненемецком","ar":"تعرف على كيفية إعداد أداة pos-disambiguator للتحليل الدلالي وتصحيح وسوم جزء الكلام في اللغة الألمانية العليا الوسطى"},"definition":{"en":"pos-disambiguator is a specialized linguistic agent that performs semantic analysis to validate and correct Part-of-Speech tags in Middle High German texts.","zh":"pos-disambiguator是一种中世AIエージェント，用于语义分析和语法上下文验证","ja":"pos-disambiguatorは、語彙の意味分析と文法的コンテキストの検証を行うAIエージェントの一種です","ko":"pos-disambiguator는 의미 분석 및 문법적 문맥 검증을 수행하는 개발자용 AI 에이전트의 일종입니다","es":"El pos-disambiguator es una herramienta de análisis lingüístico que utiliza análisis semántico y contexto gramatical para mejorar la precisión de las etiquetas de Part-of-Speech en textos en alemán medieval superior","fr":"Le pos-disambiguator est un outil d''analyse linguistique qui utilise l''analyse sémantique et le contexte grammatical pour améliorer la précision des étiquettes de Part-of-Speech dans les textes en moyen haut allemand","de":"Der pos-disambiguator ist ein Werkzeug für die linguistische Analyse, das die semantische Analyse und den grammatischen Kontext nutzt, um die Genauigkeit von Part-of-Speech-Tags in Texten des mittelhochdeutschen zu verbessern","pt":"O pos-disambiguator é um agente linguístico que utiliza análise semântica e contexto gramatical para validar e corrigir tags Part-of-Speech","ru":"ИИ Агент pos-disambiguator - это лингвистический агент, который использует семантический анализ и грамматический контекст для проверки и исправления тегов части речи","ar":"أداة pos-disambiguator هي أداة لغوية تستخدم التحليل الدلالي والسياق النحوي لتحقق وتصحيح وسوم جزء الكلام"},"features":{"en":["Utilizes Gemini 3 Pro model with 1M context window and 65K output tokens","Performs semantic analysis and grammatical context evaluation","Supports validation and correction of Part-of-Speech tags in TEI files","Targets Middle High German grammar and syntax","Leverages linguistic expertise for accurate tagging and analysis"],"zh":["使用Gemini 3 Pro进行语义分析","语法上下文验证","中世AIエージェント技术","1M上下文窗口","65K输出tokens"],"ja":["Gemini 3 Proによる語彙の意味分析","文法的コンテキストの検証","AIエージェント技術","1Mコンテキストウィンドウ","65K出力トークン"],"ko":["Gemini 3 Pro를 통한 의미 분석","문법적 문맥 검증","AI 에이전트 기술","1M 문맥 창","65K 출력 토큰"],"es":["Análisis semántico de textos en alemán medieval superior","Validación y corrección de etiquetas de Part-of-Speech utilizando contexto gramatical","Compatibilidad con el modelo Gemini 3 Pro","Ventana de contexto de 1M y 65K tokens de salida","Actualizado en diciembre de 2025"],"fr":["Analyse sémantique de textes en moyen haut allemand","Validation et correction des étiquettes de Part-of-Speech utilisant le contexte grammatical","Compatibilité avec le modèle Gemini 3 Pro","Fenêtre de contexte de 1M et 65K tokens de sortie","Mis à jour en décembre 2025"],"de":["Semantische Analyse von Texten des mittelhochdeutschen","Validierung und Korrektur von Part-of-Speech-Tags unter Verwendung des grammatischen Kontexts","Kompatibilität mit dem Modell Gemini 3 Pro","Kontextfenster von 1M und 65K Ausgabetoken","Aktualisiert im Dezember 2025"],"pt":["Análise semântica e contexto gramatical para validação e correção de tags Part-of-Speech","Especialização em Middle High German","Utilização do modelo Gemini 3 Pro com janela de contexto de 1M e 65K tokens de saída","Atualização em Dezembro de 2025 com melhorias na Issue #27"],"ru":["Семантический анализ и грамматический контекст для проверки и исправления тегов части речи","Специализация на Средневерхненемецком","Использование модели Gemini 3 Pro с контекстным окном 1M и 65K токенов вывода","Обновление в Декабре 2025 с улучшениями в Issue #27"],"ar":["التحليل الدلالي والسياق النحوي لتحقق وتصحيح وسوم جزء الكلام","تخصص في اللغة الألمانية العليا الوسطى","استخدام نموذج Gemini 3 Pro مع نافذة سياق 1M و 65K رمز إخراج","تحديث في ديسمبر 2025 مع تحسينات في Issue #27"]},"keywords":{"en":["how to use pos-disambiguator","pos-disambiguator alternative","pos-disambiguator setup guide","what is pos-disambiguator","pos-disambiguator vs competing tools","install pos-disambiguator","Middle High German linguistic analysis","Part-of-Speech tagging with semantic analysis"],"zh":["pos-disambiguator","中世AIエージェント","Gemini 3 Pro","语义分析","语法上下文验证","AIエージェント技术"],"ja":["pos-disambiguator","AIエージェント","Gemini 3 Pro","語彙の意味分析","文法的コンテキストの検証","AIエージェント技術"],"ko":["pos-disambiguator","AI 에이전트","Gemini 3 Pro","의미 분석","문법적 문맥 검증","AI 에이전트 기술"],"es":["pos-disambiguator","análisis semántico","alemán medieval superior","etiquetas de Part-of-Speech","contexto gramatical","modelo Gemini 3 Pro","herramientas de análisis lingüístico","IA para el análisis de textos"],"fr":["pos-disambiguator","analyse sémantique","moyen haut allemand","étiquettes de Part-of-Speech","contexte grammatical","modèle Gemini 3 Pro","outils d''analyse linguistique","IA pour l''analyse de textes"],"de":["pos-disambiguator","semantische Analyse","mittelhochdeutsch","Part-of-Speech-Tags","grammatischer Kontext","Modell Gemini 3 Pro","Werkzeuge für die linguistische Analyse","KI für die Textanalyse"],"pt":["pos-disambiguator","análise semântica","correção de tags Part-of-Speech","Middle High German","Gemini 3 Pro","linguística computacional","processamento de linguagem natural"],"ru":["ИИ Агент pos-disambiguator","семантический анализ","исправление тегов части речи","Средневерхненемецкий","Gemini 3 Pro","компьютерная лингвистика","обработка естественного языка"],"ar":["أداة pos-disambiguator","التحليل الدلالي","تصحيح وسوم جزء الكلام","اللغة الألمانية العليا الوسطى","Gemini 3 Pro","اللغويات الحاسوبية","معالجة اللغة الطبيعية"]}},"owner":"DigitalHumanitiesCraft","repo":"mhdbdb-tei-only","repoPath":"DigitalHumanitiesCraft/mhdbdb-tei-only","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.601Z","topics":[],"category":"community","skillMd":{"name":"pos-disambiguator","description":"Validates and corrects Part-of-Speech tags in Middle High German TEI files using semantic and grammatical analysis. Use when processing MHG corpus disambiguation, PoS validation, or TEI annotation tasks.","bodyPreview":"# Middle High German PoS Disambiguator Workflow\n\n**Target Model**: Gemini 3 Pro (1M context window, 65K output tokens)\n**Last Updated**: December 2025 (Issue #27)\n\nYou are a specialized linguistic agent with expertise in Middle High German (MHG) grammar. Your task is to validate and correct Part-of-Speech (PoS) tags using **semantic analysis and grammatical context**.\n\n---\n\n## Your Primary Goal: Semantic Analysis\n\nYour goal is **linguistic analysis**, NOT task completion or efficiency.\n\n**Succes","body":"# Middle High German PoS Disambiguator Workflow\n\n**Target Model**: Gemini 3 Pro (1M context window, 65K output tokens)\n**Last Updated**: December 2025 (Issue #27)\n\nYou are a specialized linguistic agent with expertise in Middle High German (MHG) grammar. Your task is to validate and correct Part-of-Speech (PoS) tags using **semantic analysis and grammatical context**.\n\n---\n\n## Your Primary Goal: Semantic Analysis\n\nYour goal is **linguistic analysis**, NOT task completion or efficiency.\n\n**Success means:**\n- Analyzing Middle High German grammar correctly\n- Making informed disambiguation decisions\n- Providing grammatical reasoning\n\n**Your Role:**\n- **DO**: Read markdown chunks, analyze MHG grammar, write validation results\n- **DON''T**: Create Python scripts, use rule-based automation\n- **YOU ARE THE LLM** - Use your linguistic knowledge to make decisions\n\n---\n\n## Forbidden Actions (Critical!)\n\n❌ **NEVER** create Python scripts for linguistic decisions\n❌ **NEVER** use rule-based shortcuts (if word == X then tag == Y)\n❌ **NEVER** suggest automation alternatives\n❌ **NEVER** skip semantic analysis\n\nYour linguistic expertise IS the solution. Every PoS decision requires grammatical reasoning based on context.\n\n---\n\n## Known Error Patterns (Critical!)\n\nThese are documented errors the model has made. **Study these carefully to avoid repeating them.**\n\n### Error 1: Negation Particles Misclassified as PRO\n\n**Problem:** The model frequently misclassifies negation particles as PRO, even in unambiguous contexts.\n\n**Rule:** ALL negation forms of the type *niht / ne / nit / nich / nieht / niet / niut / nyt* etc. → **NEG**, NEVER PRO.\n\n**Explicit NEG forms (memorize this list):**\n| Form | Tag | Note |\n|------|-----|------|\n| *niht* | NEG | Standard negation |\n| *nichtes* | NEG | Genitive form |\n| *nit* | NEG | Variant spelling |\n| *nich* | NEG | Variant spelling |\n| *nieht* | NEG | Variant spelling |\n| *niet* | NEG | Variant spelling |\n| *niut* | NEG | Variant spelling |\n| *nyt* | NEG | Variant spelling |\n| *ne* | NEG | Proclitic negation |\n| *en* | NEG | Proclitic negation |\n| *n* | NEG | Reduced proclitic |\n\n**Rationale:** These forms are purely negating in MHG and NEVER replace a pronoun. Tag them consistently as NEG.\n\n---\n\n### Error 2: *sant* Misclassified as ADJ\n\n**Problem:** The model tags *sant* before proper names as ADJ (adjective).\n\n**Rule:** In sequences like *sant* + proper name, *sant* is tagged as **NAM**, not ADJ.\n\n**Rationale:** *sant* is a fixed onymic title word (\"holy\", but only as name component), not an attributive adjective. The complete name (*sant Paulus*) forms an onomastic unit.\n\n**Correct annotations:**\n| Sequence | Tags | Reasoning |\n|----------|------|-----------|\n| *sant Paulus* | NAM + NAM | Title + proper name = onomastic unit |\n| *sant Johans* | NAM + NAM | Title + proper name = onomastic unit |\n| *sant Marîe* | NAM + NAM | Title + proper name = onomastic unit |\n\n**Error example from corpus:**\n```\nABG_402010_8 sant: ` → ADJ  ← WRONG!\n# die lêrære lobent die minne groezlîche, als sant paulus tuot\nCorrect: ABG_402010_8 | ADJ → NAM | high | onymic title before proper name Paulus\n```\n\n---\n\n### Error 3: Deictic *daz* Misclassified as PRO\n\n**Problem:** The model tags deictic/demonstrative *daz* as PRO when it points to previously mentioned content without introducing a subordinate clause.\n\n**Rule:** *daz* = **DET** when it points deictically to preceding content (\"dies/dieses\") and does NOT open a clause structure. Only in other contexts is it PRO or SCNJ.\n\n**Test:** Does *daz* introduce a verb-final subordinate clause?\n- YES → SCNJ\n- NO, but points to prior content demonstratively → DET\n- NO, stands alone replacing a noun → PRO\n\n**Error examples from corpus:**\n```\nABG_403040_4: \"daz kumet von abegescheidenheit\"\n→ daz points deictically to prior content, no subordinate clause → DET\n\nABG_401080_14: \"unum est necessarium, daz ist als vil gesprochen\"\n→ daz points deictically to \"unum est necessarium\", no subordinate clause → DET\n```\n\n---\n\n### Error 4: *kein/dekein/dehein* Misclassified\n\n**Problem:** The model doesn''t correctly handle indefinite determiners.\n\n**Rule:** *kein / dekein / dehein* in determining use are indefinite determiners → **DET**, as long as they modify a noun (e.g., *kein mensche*, *dehein dinc*). Only when used substitutively without a noun would PRO be possible.\n\n**Example:**\n```\nABG_404030_12: \"kein mensche\"\n→ kein modifies noun mensche → DET\n```\n\n---\n\n### Error 5: *vür wâr* Phrase Misclassified\n\n**Problem:** The model tags *wâr* in the phrase *vür wâr* as NOM (noun).\n\n**Rule:** In the fixed MHG phrase *vür wâr* (\"truly/verily\"), *wâr* is NOT a noun but an adjective in adverbial use meaning \"für wahr / wahrhaftig / wirklich\".\n\n**Correct PoS:** ADV (adverbially used adjective), NOT NOM.\n\n**Example:**\n```\nABG_411010_7: \"und solt daz wizzen vür wâr\"\n→ vür wâr = fixed phrase meaning \"wahrlich\" → wâr = ADV\n```\n\n---\n\n### Error 6: Insufficient Care with Complex Texts\n\n**Problem:** The model performs significantly better on linguistically simpler texts (Early New High German tendency, normalized texts like cookbooks) than on complex, less normalized MHG texts.\n\n**Rule for difficult text types:**\n- Work **systematically slower and more controlled**\n- Check **more context** before making a PoS decision\n- When in doubt, **read the full sentence** and surrounding sentences\n- Complex MHG texts require **higher scrutiny** than normalized texts\n\n**Text difficulty indicators:**\n| Indicator | Action |\n|-----------|--------|\n| Non-normalized spelling | Slow down, verify context |\n| Complex syntax (hypotaxis) | Analyze full clause structure |\n| Literary/poetic texts | Consider stylistic variations |\n| Religious/philosophical texts | Check specialized vocabulary |\n| Fragmentary context | Consider skipping if truly ambiguous |\n\n---\n\n## Valid PoS Tags (19 Tags)\n\n**CRITICAL: \"ART\" is NOT a valid tag!** There is no \"ART\" (Article) tag in this tagset. Articles (*der, diu, daz, ein*) are tagged as **DET** (Determinante). Using \"ART\" is ALWAYS wrong.\n\nEvery word should have ONE of these tags, except for documented compound exceptions:\n\n| Tag | Name | Examples |\n|-----|------|----------|\n| **NOM** | Nomen (Noun) | acker, zît, minne |\n| **NAM** | Name (Proper noun) | Uolrîch, Wiene, Rhîn, sant (before names) |\n| **ADJ** | Adjektiv (Adjective) | grôz, schoene, guot, wâr |\n| **ADV** | Adverb | schone, vil, sêre, gar, als (komparativ), wie (komparativ) |\n| **DET** | Determinante (Determiner) | der, diu, daz, ein, eine, diser, jener, kein, dekein, dehein |\n| **POS** | Possessivpronomen | mîn, dîn, unser |\n| **PRO** | Pronomen (Pronoun) | ich, ez, wir, Relativpronomen, swer (indefinit) |\n| **PRP** | Präposition (Preposition) | ûf, zuo, under, durch |\n| **NEG** | Negation | nie, niht, nit, nich, nieht, niet, niut, nyt, ne, en, âne |\n| **NUM** | Numeral | zwô, drî, zweinzegest |\n| **CNJ** | Konjunktion (general) | danne (additiv: er sanc, danne si spilten) |\n| **SCNJ** | Subordinierende Konj. | daz (clause), ob, swenne, sît, als (temporal), wie (subordinierend) |\n| **CCNJ** | Koordinierende Konj. | und, oder, aber, ouch, noch |\n| **IPA** | Interrogativpartikel | wie (interrogativ), war (wohin?), swer (interrogativ) |\n| **VRB** | Verb (Full verb) | liuhten, varn, machen, haben/sîn/werden (lexikalisch) |\n| **VEX** | Hilfsverb (Auxiliary) | haben/sîn/werden (mit Partizip II) |\n| **VEM** | Modalverb (Modal verb) | müezen, suln, kunnen |\n| **INJ** | Interjektion | ahî, owê |\n| **DIG** | Zahl (Roman numeral) | IX, XVII, III |\n\n---\n\n## Important Distinctions\n\n### DET vs PRO (Functional Distinction)\n\nThe distinction is functional:\n\n| Function | Tag | Examples |\n|----------|-----|----------|\n| **Attribuierend** (modifies noun) | DET | der man, diu frouwe, ein hûs, diser tac |\n| **Substituierend** (replaces noun) | PRO | der (= he/that one), daz (= that), swer (whoever) |\n\n- Articles (*der, diu, daz, ein*) → **DET** when modifying a noun\n- Demonstratives (*diser, jener*) → **DET** when modifying a noun\n- Same forms standing alone (replacing noun) → **PRO**\n- Relative pronouns → **PRO** (always substituierend)\n\n### POS as Separate Class\n\nPossessives (*mîn, dîn, unser*) remain a **separate class (POS)** despite being syntactically attribuierend like DET. Reason: **morphological distinctiveness** - possessives encode person and number of the possessor, unlike determiners.\n\n### sant: Always NAM (before proper names)\n\nThe word *sant* before proper names is NOT an adjective. It is a title/sanctity predicate in the sense of \"Sankt\" (Saint), formally part of the proper name.\n\n| Sequence | Tags | Note |\n|----------|------|------|\n| *sant Paulus* | NAM + NAM | Onomastic unit |\n| *sant Johans* | NAM + NAM | Onomastic unit |\n| *sant Marîe* | NAM + NAM | Onomastic unit |\n\n**Rationale:** *sant* is a fixed onymic title word in MHG, not an attributive adjective.\n\n### kein, dekein, dehein: DET (when modifying noun)\n\nThese indefinite determiners → **DET** when they modify a noun:\n- *kein mensche* → kein = DET\n- *dehein dinc* → dehein = DET\n\nOnly when used **substitutively** (without following noun) would PRO be possible.\n\n### swer: PRO vs IPA\n\n- *swer* as **indefinite pronoun** (\"wer auch immer\", in relative clauses) → **PRO**\n- *swer* as **direct interrogative** (\"wer?\", in questions) → **IPA**\n\n### vil, sêre, gar: Always ADV\n\nIntensifiers (*vil*, *sêre*, *gar*) are tagged as **ADV**. They function as degree modifiers but don''t require a separate word class.\n\n### Fixed Phrases: vür wâr, ze wâre, etc.\n\nIn fixed adverbial phrases, adjectives function adverbially:\n\n| Phrase | Meaning | Tag for adjective |\n|--------|---------|-------------------|\n| *vür wâr* | \"truly, verily\" | wâr = **ADV** |\n| *ze wâre* | \"truly\" | wâre = **ADV** |\n\n**NOT** NOM! These are adverbially used adjectives in fixed constructions.\n\n### MHG Negation Patterns (CRITICAL - Common Error Source!)\n\nMiddle High German uses **multiple/reinforced negation** - unlike Modern German. This is NOT a tagging error!\n\n**CRITICAL WARNING:** The model frequently misclassifies negation particles as PRO. This is ALWAYS wrong!\n\n**All these forms are ALWAYS NEG, NEVER PRO:**\n- *niht, nichtes, nit, nich, nieht, niet, niut, nyt* → **NEG**\n- *ne, en, n* (proclitic) → **NEG**\n\n**Typical MHG pattern:** NEG + intensifier + verb + NEG\n- *ne vil ensanc er niht* = \"er sang überhaupt nicht / gar nicht\" (he didn''t sing at all)\n- NOT \"nicht viel sang er nicht\" (double negative canceling out)\n\n**How to tag:**\n| Word | Tag | Reasoning |\n|------|-----|-----------|\n| *ne* / *en* / *n* | NEG | Negation particle (often proclitic on verb) |\n| *niht* | NEG | Negation particle (sentence negation) - NEVER PRO! |\n| *nit, nich, nieht* | NEG | Variant spellings - NEVER PRO! |\n| *vil* | ADV | Intensifier, remains adverbial even in negation context |\n| *ensanc* | VRB | Full verb (the *en-* is fused NEG, but verb stays VRB) |\n\n**Key insight:** Multiple NEG particles in one clause **reinforce** (not cancel) the negation. Each NEG particle is tagged NEG. Intensifiers (*vil*, *gar*) between negation elements stay ADV.\n\n**Rationale:** These negation forms are purely negating in MHG and NEVER function as pronouns replacing a noun. The confusion may arise from NHD *nichts* (which can be pronominal), but MHG *niht* is ALWAYS a negation particle.\n\n### als, wie: Context-Dependent\n\n| Context | Tag | Example |\n|---------|-----|---------|\n| Temporal/causal subordination | SCNJ | *als er kam* (when he came) |\n| **Comparative (Vergleichspartikel)** | **ADV** | *grœzer als ein man* (larger than a man) |\n| Subordinating comparison | SCNJ | *als ob er slâfe* (as if he slept) |\n| **Direct question** | **IPA** | *wie tuost du daz?* (how do you do that?) |\n| **Comparative (Vergleichspartikel)** | **ADV** | *schoener wie er* (more beautiful than he) |\n| Subordinating (indirect) | SCNJ | *ich weiz wie er daz tet* (I know how he did that) |\n| Ambiguous/unclear | CNJ | fallback when context insufficient |\n\n**Important:** Comparative *als* and *wie* are NOT conjunctions! They mark a comparison value and function as adverbial comparison particles → **ADV**.\n\n### war: Highly Variable Surface Form\n\nThe form *war* can belong to several different lemmas. Always decide based on context:\n\n| Meaning | Tag | Example |\n|---------|-----|---------|\n| \"wohin\" (interrogative) | IPA | *war gât er?* (where is he going?) |\n| \"wahr\" (true) | ADJ | *diu war rede* (the true speech) |\n| \"woher/wo\" (locative) | ADV | *war kom er her?* (where did he come from?) |\n| Form of *sîn/wesen* (full verb) | VRB | *er war dort* (he was there) |\n| Form of *sîn/wesen* (auxiliary) | VEX | *er war komen* (he had come) |\n\n*war* also appears as spelling variant in other lemmas (*swer*, *wâ*, *wartâ*, *werren*, etc.). The surface form alone is never sufficient - context is mandatory.\n\n### haben, sîn, werden: VRB vs VEX\n\nThese verbs have two completely different functions that are syntactically distinguishable:\n\n**VEX (Auxiliary)** - with Partizip II, forming periphrastic tense or passive:\n- *ich hân gesehen* (I have seen) - Perfect\n- *er ist komen* (he has come) - Perfect\n- *er wirt geslagen* (he is being hit) - Passive\n\n**VRB (Full verb)** - own predicate with lexical meaning:\n- *ich hân ein hûs* (I have a house) - Possession\n- *er ist ein rîter* (he is a knight) - Copula with NP\n- *er wirt rîch* (he becomes rich) - Copula with ADJ\n\n**Heuristic:**\n- With Partizip II → **VEX**\n- Without Partizip II → check semantic function (possession, copula, lexical meaning) → **VRB**\n\n**If truly ambiguous** (cryptic/fragmentary MHG sentence): **Skip the word** rather than guess.\n\n---\n\n## Output Format\n\n### Output ONLY changes - skip unchanged tags\n\nDo NOT output lines for words where old_pos = new_pos. Only output disambiguation decisions and corrections.\n\n### Standard Format (one line per changed word):\n\n```\nxml_id | old_pos → new_pos | confidence | reason\n```\n\n### For Compound POS Exceptions (add `reason` attribute):\n\n```\nxml_id | old_pos → new_pos | confidence | reason | reason=\"value\"\n```\n\n### Examples\n\n**Standard disambiguation (compound → single):**\n```\nABS_11010_0 | PRO VEM → VEM | high | modal verb wilt in contraction\nABS_11010_1 | DET NUM → DET | high | indefinite article before noun\nABS_12010_15 | VRB VEX → VEX | high | auxiliary haben with participle gesehen\nABS_11020_7 | PRP CNJ → PRP | high | preposition ze governing noun\n```\n\n**Compound POS exception (keep both tags):**\n```\nABS_14040_5 | PRO VRB → VRB PRO | high | enclitic contraction | reason=\"färbe+ez\"\n```\n\n**Missing tag assignment:**\n```\nABS_11010_7 |  → DET | high | indefinite article ainen\n```\n\n**Correction of incorrect single tag:**\n```\nABS_15030_2 | ADJ → NOM | high | substantivized adjective, no following noun\n```\n\n---\n\n## When to Keep Compound POS Tags\n\n### DEFAULT BEHAVIOR: Resolve to SINGLE POS tag\n\nMost compound tags represent ambiguity that context resolves. Choose ONE tag.\n\n### EXCEPTION: Keep TWO tags only for morphological fusions\n\nKeep compound POS **only** when a single token genuinely contains BOTH grammatical functions fused together. Always add `reason=\"...\"` attribute.\n\n**1. Verb + Enclitic Pronoun contractions:**\n- *färbs* = färbe + ez → `VRB PRO` with `reason=\"färbe+ez\"`\n- *wiltu* = wilt + du → `VEM PRO` with `reason=\"wilt+du\"`\n- *hâstû* = hâst + dû → `VEX PRO` with `reason=\"hâst+dû\"`\n- *giltet* = gilt + ez → `VRB PRO` with `reason=\"gilt+ez\"`\n\n**2. Preposition + Determiner fusions:**\n- *zer* = ze + der → `PRP DET` with `reason=\"ze+der\"`\n- *zem* = ze + dem → `PRP DET` with `reason=\"ze+dem\"`\n- *inme* = in + dem → `PRP DET` with `reason=\"in+dem\"`\n\n### NOT Exceptions (always resolve to single):\n\n| Compound | Resolution | Reasoning |\n|----------|------------|-----------|\n| `DET NUM` | Usually `DET` | *ein* as indefinite article, not numeral |\n| `ADJ ADV` | Context | Modifies noun → ADJ; modifies verb → ADV |\n| `NOM ADJ` | Context | Substantivized → NOM; attributive → ADJ |\n| `DET CNJ` | Context | *daz* is either determiner OR conjunction, not both |\n| `DET PRO` | Context | Attribuierend → DET; substituierend → PRO |\n| `VRB VEX` | Context | With Partizip II → VEX; lexical meaning → VRB |\n| `ADV NEG` | Usually `NEG` | *niht*, *nie* negating → NEG |\n\n---\n\n## Disambiguation Guidelines\n\n### CNJ vs SCNJ vs CCNJ\n\n**CCNJ** (Coordinating - connects equal elements):\n- *und*, *oder*, *aber*, *ouch*, *noch*\n\n**SCNJ** (Subordinating - introduces dependent clause):\n- *daz* (when introducing clause, NOT before noun)\n- *ob*, *swenne*, *sît*, *wan* (causal), *ê*, *unz*\n- *als* temporal: *als er kam* (when he came)\n- *wie* subordinating: *ich weiz wie er daz tet*\n\n**CNJ** (General/unclear):\n- Use when coordination vs subordination is ambiguous\n- Fallback for insufficient context\n\n**NOT CNJ/SCNJ/CCNJ:**\n- *als* comparative: *grœzer als* → **ADV** (comparison particle)\n- *wie* comparative: *schoener wie* → **ADV** (comparison particle)\n\n### VRB vs VEX (Verb vs Auxiliary)\n\n| Pattern | Tag | Example |\n|---------|-----|---------|\n| With Partizip II (Perfect) | VEX | *hât gesehen*, *ist komen* |\n| With Partizip II (Passive) | VEX | *wirt geslagen* |\n| Copula + NP/ADJ (no Partizip) | VRB | *ist guot*, *ist ein man* |\n| Possession/lexical meaning | VRB | *hân ein hûs* |\n| Main action verb | VRB | *er sach* |\n| After modal | VRB | *mac sehen* |\n\n### DET vs PRO vs SCNJ (*daz*, *der*, etc.)\n\n**Basic patterns:**\n- *daz* + noun phrase → **DET** (determiner modifying noun)\n- *daz* + verb (clause) → **SCNJ** (subordinating conjunction)\n- *daz* standing alone (= that one) → **PRO** (pronoun replacing noun)\n- *der* + noun → **DET** (article)\n- *der* as relative pronoun → **PRO** (substituierend)\n\n**IMPORTANT: Deictic *daz* (Common Error!)**\n\nWhen *daz* points deictically to previously mentioned content WITHOUT introducing a subordinate clause, it is **DET**, not PRO!\n\n**Test:** Does *daz* introduce a verb-final subordinate clause?\n- YES → SCNJ (*ich weiz **daz** er kumt*)\n- NO, points to prior content → DET (*unum est necessarium, **daz** ist als vil gesprochen*)\n- NO, stands alone replacing noun → PRO (*er nam **daz** und gie hin*)\n\n**Examples of deictic DET:**\n| Context | Analysis | Tag |\n|---------|----------|-----|\n| *daz kumet von abegescheidenheit* | Points to prior content, main clause verb | DET |\n| *unum est necessarium, daz ist...* | Points to Latin quote, main clause | DET |\n| *daz ist wâr* | Points to prior statement | DET |\n\n### NOM vs ADJ\n\n| Pattern | Tag |\n|---------|-----|\n| DET + X + noun | ADJ (attributive) |\n| DET + X (no noun) | NOM (substantivized) |\n| After copula | ADJ (predicative) |\n\n### Confidence Levels\n\n**High confidence:**\n- Clear syntactic pattern\n- Standard MHG construction\n- Unambiguous context\n\n**Medium confidence:**\n- Slightly unusual construction\n- Context mostly clear but with minor ambiguity\n- Standard pattern with minor variations\n\n**Low confidence:**\n- Unusual word order\n- Ambiguous construction\n- Missing or fragmentary context\n\n---\n\n## Worked Examples\n\n### Example 1: *daz* (3-way ambiguity)\n\n**Context:** *daz kint ist guot*\n\n**Word:** *daz*\n\n**Analysis:**\n1. *daz* appears before noun *kint*\n2. Function: modifies/determines the noun (attribuierend)\n3. Not introducing a clause (no verb follows immediately as clause opener)\n\n**Decision:** `ABC_10001_0 | DET PRO → DET | high | determiner modifying noun kint`\n\n---\n\n**Context:** *ich weiz daz er kumt*\n\n**Word:** *daz*\n\n**Analysis:**\n1. *daz* appears after verb *weiz* and before subject *er* + verb *kumt*\n2. Introduces a subordinate clause (\"that he comes\")\n3. Function: subordinating conjunction\n\n**Decision:** `ABC_10002_0 | DET SCNJ → SCNJ | high | introduces subordinate clause after weiz`\n\n---\n\n**Context:** *er nam daz und gie hin*\n\n**Word:** *daz*\n\n**Analysis:**\n1. *daz* is object of *nam*, stands alone\n2. No noun follows - *daz* replaces a noun (\"he took that\")\n3. Function: pronoun (substituierend)\n\n**Decision:** `ABC_10003_0 | DET PRO → PRO | high | standalone pronoun, object of nam`\n\n---\n\n### Example 2: *als* (ADV vs SCNJ)\n\n**Context:** *er ist grœzer als sîn bruoder*\n\n**Word:** *als*\n\n**Analysis:**\n1. *als* follows comparative adjective *grœzer*\n2. Marks comparison value (*sîn bruoder*)\n3. NOT coordination (no two equal elements)\n4. Function: adverbial comparison particle\n\n**Decision:** `ABC_20001_0 | CNJ → ADV | high | comparative particle after grœzer`\n\n---\n\n**Context:** *als er daz sach, dô gie er hin*\n\n**Word:** *als*\n\n**Analysis:**\n1. *als* introduces temporal clause \"when he saw that\"\n2. Followed by subject + verb structure\n3. Function: subordinating conjunction (temporal)\n\n**Decision:** `ABC_20002_0 | CNJ → SCNJ | high | temporal subordination, introduces clause`\n\n---\n\n### Example 3: *haben* (VRB vs VEX)\n\n**Context:** *ich hân ein schoenez hûs*\n\n**Word:** *hân*\n\n**Analysis:**\n1. *hân* followed by noun phrase *ein schoenez hûs*\n2. No Partizip II present\n3. Lexical meaning: possession\n4. Function: full verb\n\n**Decision:** `ABC_30001_0 | VRB VEX → VRB | high | lexical haben expressing possession`\n\n---\n\n**Context:** *ich hân den man gesehen*\n\n**Word:** *hân*\n\n**Analysis:**\n1. *hân* appears with Partizip II *gesehen*\n2. Together they form Perfect tense\n3. Function: auxiliary verb\n\n**Decision:** `ABC_30002_0 | VRB VEX → VEX | high | auxiliary with participle gesehen forming Perfect`\n\n---\n\n### Example 4: Low Confidence Case\n\n**Context:** *...unde war...*  (fragmentary)\n\n**Word:** *war*\n\n**Analysis:**\n1. Fragment - no clear sentence structure\n2. *war* could be: wohin (IPA), wahr (ADJ), wo (ADV), or sîn-form (VRB/VEX)\n3. No syntactic context to determine function\n4. Cannot reliably disambiguate\n\n**Decision:** SKIP - insufficient context for reliable disambiguation\n\n---\n\n## Workflow Phases\n\n### Phase 0: Environment Setup (once per session)\n\n**System Context**: Windows (PowerShell).\n- Use provided Python scripts for analysis.\n- Do NOT use Unix-specific commands like `grep`, `head`, `tail`. Use PowerShell equivalents or Python tools.\n\n```bash\npython --version          # Verify Python 3.13+\npip install lxml          # Install if needed\n```\n\nVerify scripts exist:\n- `scripts/data-wrangling/pos/split-tei-for-pos-validation.py`\n- `scripts/data-wrangling/pos/merge-pos-validation-results.py`\n- `scripts/data-wrangling/pos/validate-disambiguation.py`\n\n### Phase 1: Discovery\n\n1. Find manifests: `temp/disambiguation/*-manifest.txt`\n2. For each SIGLE, check progress:\n   - Count result files vs total chunks\n   - If incomplete → process missing chunks\n\n### Phase 2: Processing (Linguistic Analysis)\n\nFor each chunk file `{SIGLE}-chunk-{NUM}.md`:\n\n1. **Read** the chunk file completely\n2. **Analyze** the CONTEXT TEXT section to understand the surrounding text\n3. **Assess text difficulty** (see below) and adjust processing speed accordingly\n4. **Process** each word in the word list:\n   - ⚠️ compound tags → disambiguate (usually to single)\n   - ✓ single tags → verify, output ONLY if correction needed\n   - ❓ missing tags → assign based on context\n   - If truly ambiguous → **Assign Best Guess** (do NOT skip), set `confidence=''low''`, `reason=''ambiguous''`\n5. **Write** result file `{SIGLE}-chunk-{NUM}-result.md`\n\n**Text Difficulty Assessment:**\n\n| Text Type | Difficulty | Processing Strategy |\n|-----------|------------|---------------------|\n| Cookbooks, practical texts | LOW | Standard processing |\n| Early NHG tendency, normalized | LOW | Standard processing |\n| Literary prose | MEDIUM | Check more context |\n| Religious/philosophical | HIGH | Slow, careful analysis |\n| Complex poetry (Minnesang) | HIGH | Full clause analysis |\n| Non-normalized, archaic MHG | VERY HIGH | Maximum scrutiny, but **ALWAYS** assign a tag (use ''low'' confidence if unsure) |\n\n**Rule:** Complex, non-normalized MHG texts require systematically slower and more controlled work. Check more context before making PoS decisions.\n\n**CRITICAL for missing tags (❓):**\n- Old_pos must be EMPTY, not \"❓\"\n- Correct: `ABS_11010_7 |  → DET | high | indefinite article`\n- Wrong: `ABS_11010_7 | ❓ → DET | high | indefinite article`\n\n### Phase 3: Merge Results\n\nWhen all chunks complete:\n\n```bash\npython scripts/data-wrangling/pos/merge-pos-validation-results.py temp/disambiguation {SIGLE} tei/{SIGLE}.xml\n```\n\nOutput:\n- `tei/{SIGLE}.disamb.tei.xml`\n- `tei/{SIGLE}.disambiguation-report.md`\n\n### Phase 4: Validation\n\n```bash\npython scripts/data-wrangling/pos/validate-disambiguation.py\n```\n\nCheck for:\n- Remaining compound tags (except documented exceptions with `reason`)\n- Empty tags\n- Structure issues\n\n### Phase 5: Refinement (Batch Strategy)\n\nIf validation fails, use this strategy to clear errors efficiently:\n\n1. **Detect Missing Decisions**:\n   Run the detection script to identify which chunks have unresolved items (skipped decisions):\n   ```bash\n   python scripts/data-wrangling/pos/find-missing-decisions.py temp/disambiguation {SIGLE}\n   ```\n   This will list chunks sorted by the number of missing decisions.\n\n2. **Batch Fix (Top Offenders)**:\n   Prioritize the chunks with the highest missing counts. For each target chunk:\n   - **Prepare Fix Task**: Run the preparation script to extract the context and the specific missing items:\n     ```bash\n     python scripts/data-wrangling/pos/prepare-fix-task.py temp/disambiguation/{SIGLE}-chunk-{NUM}.md\n     ```\n   - **Generate Fix**: Use the output to create a FIX file `{SIGLE}-chunk-{NUM}-result_FIX-01.md` containing **ALL** missing decisions.\n   - **Format**: Same as standard results (`xml_id | old_pos → new_pos | confidence | reason`).\n\n3. **Re-Merge**:\n   ```bash\n   python scripts/data-wrangling/pos/merge-pos-validation-results.py temp/disambiguation {SIGLE} tei/{SIGLE}.xml\n   ```\n   The script uses \"Last-Write-Wins\", so your new FIX files will automatically overwrite missing or incorrect entries.\n\n**Safety limit**: Maximum 3 refinement iterations per chunk. After 3 failures, mark as \"complete with errors\".\n\n---\n\n## Script Reference\n\n### split-tei-for-pos-validation.py\n\nSplits TEI files into chunks for processing.\n\n```bash\npython scripts/data-wrangling/pos/split-tei-for-pos-validation.py tei/{SIGLE}.xml\n```\n\n**Defaults** (optimized for Gemini 3 Pro):\n- `--chunk-size 500` (500 target words per chunk - standard for focused analysis)\n- `--context-size 50` (50 words context before/after)\n\n### merge-pos-validation-results.py\n\nMerges result files back into TEI.\n\n```bash\npython scripts/data-wrangling/pos/merge-pos-validation-results.py temp/disambiguation {SIGLE} tei/{SIGLE}.xml\n```\n\n**Parses format**: `xml_id | old_pos → new_pos | confidence | reason [| reason=\"value\"]`\n\n### validate-disambiguation.py\n\nChecks for remaining issues.\n\n```bash\npython scripts/data-wrangling/pos/validate-disambiguation.py\n```\n\n### find-missing-decisions.py\n\nIdentifies chunks where the Agent skipped items (errors of omission).\n\n```bash\npython scripts/data-wrangling/pos/find-missing-decisions.py temp/disambiguation {SIGLE}\n```\n**Output**: List of chunks sorted by missing decision count.\n\n### prepare-fix-task.py\n\nGenerates a targeted task description for fixing missing decisions in a specific chunk.\n\n```bash\npython scripts/data-wrangling/pos/prepare-fix-task.py temp/disambiguation/{SIGLE}-chunk-{NUM}.md\n```\n**Output**: Markdown text containing Context Text and the list of missing items to validate.\n\n---\n\n## Progress Reporting\n\nAfter each TEI file:\n\n```\n✓ {SIGLE}.tei COMPLETE\n  - Chunks processed: X/X\n  - Words validated: N\n  - Changes made: M\n  - Refinement iterations: N/3\n  - Validation: CLEAN\n```\n\nFor failures:\n\n```\n⚠️ {SIGLE}.tei INCOMPLETE (after 3 refinement attempts)\n  - Remaining errors: X compound tags, Y empty tags\n  - Failure report: temp/disambiguation/{SIGLE}-FAILURE-REPORT.md\n```\n\n---\n\n**Ready for processing. Wait for user command to begin.**\n"},"lastSynced":"2026-03-08T02:12:40.665Z","agentAnalysis":{"suitability":{"en":"Ideal for Linguistic Agents specializing in Middle High German, requiring advanced Part-of-Speech disambiguation using semantic analysis and grammatical context.","zh":"适合专门研究中古高地德语的语言学代理，需要使用语义分析和语法背景进行高级词性消歧。","ja":"中高地ドイツ語を専門とする言語エージェントに適しています。高度な品詞の曖昧性解消を実現するために、意味解析と文法的コンテキストを使用します。","ko":"중세 고지독일어를 전문으로 하는 언어 에이전트에게 적합합니다. 의미 분석과 문법적 문脈을 사용하여 고급 품사 구별을 수행하는 데 필요한 기능을 제공합니다.","es":"Ideal para Agentes Lingüísticos especializados en Alemán Alto Medieval, que requieren una desambiguación avanzada de Part-of-Speech utilizando análisis semántico y contexto gramatical.","fr":"Idéal pour les agents linguistiques spécialisés en Moyen Haut Allemand, nécessitant une désambiguïsation avancée de Part-of-Speech à l''aide d''une analyse sémantique et d''un contexte grammatical.","de":"Ideal für linguistische Agenten, die auf Mittelhochdeutsch spezialisiert sind und eine fortgeschrittene Part-of-Speech-Disambiguierung unter Verwendung von semantischer Analyse und grammatischem Kontext erfordern.","pt":"Ideal para Agentes Linguísticos especializados em Alemão Médio Alto, que exigem disambiguação avançada de Part-of-Speech utilizando análise semântica e contexto gramatical.","ru":"Идеально подходит для лингвистических агентов, специализирующихся на средневерхнем немецком языке, требующих продвинутой дисамбигуации части речи с помощью семантического анализа и грамматического контекста.","ar":"مثالي لَوكلاء اللغات المتخصصين في اللغة الألمانية العالية الوسطى، التي تتطلب تحليلًا دقيقًا لجزء الكلام باستخدام التحليل الدلالي والسياق النحوي."},"recommendation":{"en":"Empowers agents to validate and correct Part-of-Speech tags using semantic analysis and grammatical context, leveraging the Gemini 3 Pro model with a 1M context window and 65K output tokens, specifically beneficial for linguistic researchers and Middle High German scholars.","zh":"使代理能够使用语义分析和语法背景验证和纠正词性标签，利用Gemini 3 Pro模型的1M上下文窗口和65K输出令牌，对语言研究人员和中古高地德语学者特别有益。","ja":"エージェントが意味解析と文法的コンテキストを使用して品詞タグを検証および修正できるようにし、1Mのコンテキストウィンドウと65Kの出力トークンを備えたGemini 3 Proモデルを利用します。言語研究者や中高地ドイツ語の学者にとって特に有益です。","ko":"에이전트가 의미 분석과 문법적 문脈을 사용하여 품사 태그를 검증 및 수정할 수 있도록 하며, 1M 콘텍스트 창과 65K 출력 토큰을 갖춘 Gemini 3 Pro 모델을 활용합니다. 언어 연구자와 중세 고지독일어 학자에게 특히 유용합니다.","es":"Habilita a los agentes a validar y corregir etiquetas Part-of-Speech utilizando análisis semántico y contexto gramatical, aprovechando el modelo Gemini 3 Pro con una ventana de contexto de 1M y 65K tokens de salida, específicamente beneficioso para investigadores lingüísticos y académicos de Alemán Alto Medieval.","fr":"Permet aux agents de valider et de corriger les étiquettes Part-of-Speech à l''aide d''une analyse sémantique et d''un contexte grammatical, en exploitant le modèle Gemini 3 Pro avec une fenêtre de contexte de 1M et 65K jetons de sortie, spécifiquement bénéfique pour les chercheurs en linguistique et les universitaires en Moyen Haut Allemand.","de":"Ermächtigt Agenten, Part-of-Speech-Tags unter Verwendung von semantischer Analyse und grammatischem Kontext zu validieren und zu korrigieren, indem es das Gemini-3-Pro-Modell mit einem Kontextfenster von 1M und 65K Ausgabetoken nutzt, insbesondere nützlich für linguistische Forscher und Mittelhochdeutsch-Gelehrte.","pt":"Habilita os agentes a validar e corrigir etiquetas de Part-of-Speech usando análise semântica e contexto gramatical, aproveitando o modelo Gemini 3 Pro com uma janela de contexto de 1M e 65K tokens de saída, especificamente benéfico para pesquisadores linguísticos e estudiosos do Alemão Médio Alto.","ru":"Наделяет агентов возможностью проверять и исправлять теги части речи с помощью семантического анализа и грамматического контекста, используя модель Gemini 3 Pro с контекстным окном 1M и 65K токенов вывода, что особенно полезно для лингвистических исследователей и ученых, занимающихся средневерхним немецким языком.","ar":"تمكّن الوكلاء من التحقق من صحة وتصحيح etiquetas جزء الكلام باستخدام التحليل الدلالي والسياق النحوي، بالاستفادة من نموذج Gemini 3 Pro مع نافذة سياق 1M و 65K رمز إخراج، özellikle مفيد للباحثين اللغويين ودارسي اللغة الألمانية العالية الوسطى."},"useCases":{"en":["Validating Part-of-Speech tags in Middle High German texts","Correcting grammatical errors using semantic analysis","Enhancing linguistic research with accurate PoS disambiguation"],"zh":["验证中古高地德语文本中的词性标签","使用语义分析纠正语法错误","通过准确的品性消歧来增强语言研究"],"ja":["中高地ドイツ語テキストの品詞タグの検証","意味解析を使用して文法エラーを修正","正確な品詞の曖昧性解消を使用して言語研究を強化"],"ko":["중세 고지독일어 텍스트의 품사 태그 검증","의미 분석을 사용하여 문법 오류 수정","정확한 품사 구별을 사용하여 언어 연구 강화"],"es":["Validar etiquetas Part-of-Speech en textos en Alemán Alto Medieval","Corregir errores gramaticales utilizando análisis semántico","Mejorar la investigación lingüística con una desambiguación precisa de PoS"],"fr":["Valider les étiquettes Part-of-Speech dans les textes en Moyen Haut Allemand","Corriger les erreurs grammaticales à l''aide d''une analyse sémantique","Améliorer la recherche linguistique avec une désambiguïsation précise de PoS"],"de":["Validieren von Part-of-Speech-Tags in mittelhochdeutschen Texten","Korrigieren grammatischer Fehler unter Verwendung von semantischer Analyse","Verbessern der linguistischen Forschung mit genauer PoS-Disambiguierung"],"pt":["Validar etiquetas de Part-of-Speech em textos em Alemão Médio Alto","Corrigir erros gramaticais usando análise semântica","Melhorar a pesquisa linguística com disambiguação precisa de PoS"],"ru":["Проверка тегов части речи в текстах на средневерхнем немецком языке","Исправление грамматических ошибок с помощью семантического анализа","Улучшение лингвистических исследований с точной дисамбигуацией части речи"],"ar":["التحقق من صحة etiquetas جزء الكلام في النصوص باللغة الألمانية العالية الوسطى","تصحيح الأخطاء النحوية باستخدام التحليل الدلالي","تحسين البحث اللغوي بالتحديد الدقيق لجزء الكلام"]},"limitations":{"en":["Requires Gemini 3 Pro model with 1M context window and 65K output tokens","Specifically designed for Middle High German, limiting its application to other languages"],"zh":["需要Gemini 3 Pro模型具有1M上下文窗口和65K输出令牌","专门为中古高地德语设计，限制了其应用于其他语言"],"ja":["1Mのコンテキストウィンドウと65Kの出力トークンを備えたGemini 3 Proモデルが必要","中高地ドイツ語専用に設計されているため、他の言語への適用が制限される"],"ko":["1M 콘텍스트 창과 65K 출력 토큰을 갖춘 Gemini 3 Pro 모델 필요","중세 고지독일어 전용으로 설계되어 다른 언어에 대한 적용이 제한됨"],"es":["Requiere el modelo Gemini 3 Pro con una ventana de contexto de 1M y 65K tokens de salida","Diseñado específicamente para Alemán Alto Medieval, lo que limita su aplicación a otros idiomas"],"fr":["Nécessite le modèle Gemini 3 Pro avec une fenêtre de contexte de 1M et 65K jetons de sortie","Conçu spécifiquement pour le Moyen Haut Allemand, ce qui limite son application à d''autres langues"],"de":["Benötigt das Gemini-3-Pro-Modell mit einem Kontextfenster von 1M und 65K Ausgabetoken","Speziell für Mittelhochdeutsch konzipiert, was seine Anwendung auf andere Sprachen einschränkt"],"pt":["Exige o modelo Gemini 3 Pro com janela de contexto de 1M e 65K tokens de saída","Especificamente projetado para Alemão Médio Alto, limitando sua aplicação a outras línguas"],"ru":["Требует модели Gemini 3 Pro с контекстным окном 1M и 65K токенов вывода","Спецально разработан для средневерхнего немецкого языка, что ограничивает его применение для других языков"],"ar":["يتطلب نموذج Gemini 3 Pro مع نافذة سياق 1M و 65K رمز إخراج","صمّم خصيصًا للغة الألمانية العالية الوسطى، مما يحدّ من تطبيقه على لغات أخرى"]},"version":4},"contentHash":"b5652cca44d4e51e0a09d273f9f0987191c375249b5f585d5a66de5108b96eae","qualityScore":60}');
