INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DigitalHumanitiesCraft/mhdbdb-tei-only/pos-disambiguator', 'pos-disambiguator', 'DigitalHumanitiesCraft', 'mhdbdb-tei-only', 'community', 'pos-disambiguator DigitalHumanitiesCraft mhdbdb-tei-only community The pos-disambiguator skill validates and corrects Part-of-Speech tags using semantic analysis and grammatical context, benefiting linguistic researchers and Middle High German scholars. pos-disambiguator是中世AIエージェント，使用Gemini 3 Pro进行语义分析和语法上下文验证。 pos-disambiguatorは、Gemini 3 Proを使用して語彙の意味分析と文法的コンテキストの検証を行うAIエージェントです。 pos-disambiguator는 Gemini 3 Pro를 사용하여 의미 분석 및 문법적 문맥 검증을 수행하는 개발자용 AI 에이전트입니다. El pos-disambiguator es una herramienta especializada para el análisis semántico de textos en alemán medieval superior, que utiliza contexto gramatical para validar y corregir etiquetas de Part-of-Speech Le pos-disambiguator est un outil spécialisé pour l''analyse sémantique de textes en moyen haut allemand, qui utilise le contexte grammatical pour valider et corriger les étiquettes de Part-of-Speech Der pos-disambiguator ist ein spezialisiertes Tool für die semantische Analyse von Texten des mittelhochdeutschen, das den grammatischen Kontext nutzt, um Part-of-Speech-Tags zu validieren und zu korrigieren O pos-disambiguator é um agente linguístico especializado em análise semântica e correção de tags Part-of-Speech em Middle High German ИИ Агент pos-disambiguator - это специализированный лингвистический агент для семантического анализа и исправления тегов части речи в Средневерхненемецком أداة pos-disambiguator هي أداة لغوية متخصصة في التحليل الدلالي وتصحيح وسوم جزء الكلام في اللغة الألمانية العليا الوسطى how to use pos-disambiguator pos-disambiguator alternative pos-disambiguator setup guide what is pos-disambiguator pos-disambiguator vs competing tools install pos-disambiguator Middle High German linguistic analysis Part-of-Speech tagging with semantic analysis pos-disambiguator 中世AIエージェント Gemini 3 Pro 语义分析 语法上下文验证 AIエージェント技术 Utilizes Gemini 3 Pro model with 1M context window and 65K output tokens Performs semantic analysis and grammatical context evaluation Supports validation and correction of Part-of-Speech tags in TEI files Targets Middle High German grammar and syntax Leverages linguistic expertise for accurate tagging and analysis pos-disambiguator is a specialized linguistic agent that performs semantic analysis to validate and correct Part-of-Speech tags in Middle High German texts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('feniix/kinemotion/mediapipe-pose-detection', 'community', 'feniix', 'kinemotion', 'feniix/kinemotion', 'mediapipe-pose-detection', 0, 0, 60, '2026-03-08T01:57:15.606Z', '2026-03-08T02:13:09.611Z', '9dbaba81c1377a7cd98a7822fe0498c2731aa99d80cdbe3208a2fd46a3ba75f2', '{"id":"feniix/kinemotion/mediapipe-pose-detection","name":"mediapipe-pose-detection","description":{"en":"mediapipe-pose-detection analyzes video-based athletic performance, tracking key landmarks like hip, knee, and ankle movement for coaches and athletes.","zh":"MediaPipe Pose Detection是一种视频运动分析工具，用于检测关键身体部位如髋部、膝盖、脚踝等","ja":"MediaPipe Pose Detectionは、ヒップ、膝、踝などの重要な身体部位を検出するためのビデオ運動分析ツールです","ko":"MediaPipe Pose Detection은 髋部, 무릎,踝关节 등의 주요 신체 부위를 감지하는 비디오 운동 분석 도구입니다","es":"MediaPipe Pose Detection es una herramienta de análisis de video para evaluar el rendimiento atlético, utilizando la detección de posturas para analizar saltos y movimientos","fr":"MediaPipe Pose Detection est un outil d''analyse de vidéo pour évaluer la performance athlétique, en utilisant la détection de poses pour analyser les sauts et les mouvements","de":"MediaPipe Pose Detection ist ein Videoanalyse-Tool zur Bewertung der athletischen Leistung, das die Erkennung von Körperhaltungen zur Analyse von Sprüngen und Bewegungen verwendet","pt":"O MediaPipe Pose Detection é uma ferramenta de análise de desempenho atlético baseada em vídeo que identifica pontos-chave como altura de salto e contato com o solo","ru":"MediaPipe Pose Detection - это инструмент для анализа спортивных результатов на основе видео, который определяет ключевые точки, такие как высота прыжка и контакт с землей","ar":"MediaPipe Pose Detection هو أداة لتحليل الأداء الرياضي بالفيديو التي تحدد النقاط الرئيسية مثل ارتفاع القفز وتماس الأرض"},"seo":{"title":{"en":"mediapipe-pose-detection: Video Analysis Setup Guide | AI...","zh":"MediaPipe Pose Detection Setup Guide","ja":"MediaPipe Pose Detectionベストプラクティス","ko":"MediaPipe Pose Detection 사용자 가이드","es":"Guía de configuración de MediaPipe Pose Detection para an...","fr":"Guide de configuration de MediaPipe Pose Detection pour l...","de":"Einrichtungsleitfaden für MediaPipe Pose Detection zur An...","pt":"Guia de Configuração do MediaPipe Pose Detection para Aná...","ru":"Установка MediaPipe Pose Detection для анализа спортивных...","ar":"دليل إعداد MediaPipe Pose Detection لتحليل الأداء الرياضي..."},"description":{"en":"Unlock athletic performance insights with mediapipe-pose-detection. Discover how to analyze jump kinematics and optimize training - get started now!","zh":"使用MediaPipe Pose Detection进行视频运动分析，检测关键身体部位如髋部、膝盖、脚踝","ja":"MediaPipe Pose Detectionを使用して、ヒップ、膝、踝などの重要な身体部位を検出します","ko":"MediaPipe Pose Detection을 사용하여 髋部, 무릎,踝关节 등의 주요 신체 부위를 감지","es":"Aprende a utilizar MediaPipe Pose Detection para analizar el rendimiento atlético en videos, con un enfoque en la detección de posturas y el análisis de saltos","fr":"Découvrez comment utiliser MediaPipe Pose Detection pour analyser la performance athlétique dans les vidéos, avec un focus sur la détection de poses et l''ana...","de":"Erfahren Sie, wie Sie MediaPipe Pose Detection verwenden können, um die athletische Leistung in Videos zu analysieren, mit einem Schwerpunkt auf der Erkennun...","pt":"Aprenda a utilizar o MediaPipe Pose Detection para análise de desempenho atlético em vídeos, identificando pontos-chave como altura de salto e contato com o ...","ru":"Изучите возможности MediaPipe Pose Detection для анализа спортивных результатов в видео, включая определение высоты прыжка и контакта с землей с помощью ИИ А...","ar":"تعرف على كيفية استخدام MediaPipe Pose Detection لتحليل الأداء الرياضي في مقاطع الفيديو، بما في ذلك تحديد ارتفاع القفز وتماس الأرض باستخدام أدوات الذكاء الاصط..."},"definition":{"en":"mediapipe-pose-detection is a video-based kinematic analysis tool for evaluating athletic performance, particularly jump analysis.","zh":"MediaPipe Pose Detection是一种AI工具，用于分析视频中的运动并检测关键身体部位","ja":"MediaPipe Pose Detectionは、ビデオ内の動きを分析し、重要な身体部位を検出するAIエージェントです","ko":"MediaPipe Pose Detection은 비디오 내의 동작을 분석하여 주요 신체 부위를 감지하는 AI 도구입니다","es":"MediaPipe Pose Detection es una técnica de análisis de video que utiliza la detección de posturas para evaluar el rendimiento atlético","fr":"MediaPipe Pose Detection est une technique d''analyse de vidéo qui utilise la détection de poses pour évaluer la performance athlétique","de":"MediaPipe Pose Detection ist eine Videoanalysetechnik, die die Erkennung von Körperhaltungen zur Bewertung der athletischen Leistung verwendet","pt":"O MediaPipe Pose Detection é uma técnica de análise de movimento que utiliza pontos de referência para detectar a pose humana em vídeos","ru":"MediaPipe Pose Detection - это метод анализа движений, который использует ориентиры для обнаружения позы человека на видео с помощью ИИ Агентов","ar":"MediaPipe Pose Detection هو تقنية لتحليل الحركة التي تستخدم نقاط المرجعية لاكتشاف وضع الجسم البشري في مقاطع الفيديو باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Tracks lower body landmarks, including hip, knee, and ankle movement","Analyzes jump height and triple extension using landmark indices 23-30","Detects ground contact and takeoff using heel landmarks 29 and 30","Supports kinematic analysis for athletic performance optimization","Identifies center of mass and jump height using hip landmarks 23 and 24"],"zh":["检测髋部、膝盖、脚踝等关键身体部位","支持视频运动分析","可用于跳跃分析","提供左、右身体部位的索引","支持Ground contact detection"],"ja":["ヒップ、膝、踝などの重要な身体部位を検出","ビデオ運動分析をサポート","ジャンプ分析に使用できる","左、右身体部位のインデックスを提供","Ground contact detectionをサポート"],"ko":["髋部, 무릎,踝关节 등의 주요 신체 부위를 감지","비디오 운동 분석을 지원","점프 분석에 사용할 수 있음","왼쪽, 오른쪽 신체 부위의 인덱스를 제공","Ground contact detection을 지원"],"es":["Detección de posturas para analizar saltos y movimientos","Análisis de la cinemática del cuerpo humano","Identificación de puntos de referencia como caderas, rodillas y tobillos","Detección de contacto con el suelo y seguimiento de la trayectoria del movimiento","Análisis de la altura de salto y la técnica de aterrizaje","Integración con herramientas de análisis de video para una evaluación más detallada"],"fr":["Détection de poses pour analyser les sauts et les mouvements","Analyse de la cinématique du corps humain","Identification de points de référence tels que les hanches, les genoux et les chevilles","Détection du contact avec le sol et suivi de la trajectoire du mouvement","Analyse de la hauteur de saut et de la technique d''atterrissage","Intégration avec des outils d''analyse de vidéo pour une évaluation plus détaillée"],"de":["Erkennung von Körperhaltungen zur Analyse von Sprüngen und Bewegungen","Analyse der Kinematik des menschlichen Körpers","Identifizierung von Referenzpunkten wie Hüften, Knien und Knöcheln","Erkennung des Bodenkontakts und Verfolgung der Bewegungsbahn","Analyse der Sprunghöhe und der Landetechnik","Integration mit Videoanalyse-Tools für eine detailliertere Auswertung"],"pt":["Detecção de pontos de referência para análise de desempenho atlético","Análise de altura de salto e contato com o solo","Identificação de pontos-chave para triple extension e landing","Utilização de tecnologias de visão computacional para análise de vídeo"],"ru":["Обнаружение ориентиров для анализа спортивных результатов","Анализ высоты прыжка и контакта с землей","Определение ключевых точек для тройного расширения и приземления","Использование технологий компьютерного зрения для анализа видео с помощью ИИ Агентов"],"ar":["اكتشاف نقاط المرجعية لتحليل الأداء الرياضي","تحليل ارتفاع القفز وتماس الأرض","تحديد النقاط الرئيسية لتمديد ثلاثي والهبوط","استخدام تقنيات رؤية الكمبيوتر لتحليل الفيديو باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use mediapipe-pose-detection","mediapipe-pose-detection alternative","mediapipe-pose-detection install","what is mediapipe-pose-detection","mediapipe-pose-detection vs openpose","mediapipe-pose-detection setup guide","mediapipe-pose-detection for athletic performance","video analysis with mediapipe-pose-detection","kinematic analysis using mediapipe-pose-detection"],"zh":["MediaPipe Pose Detection","视频运动分析","AI工具","运动检测","跳跃分析","身体部位检测"],"ja":["MediaPipe Pose Detection","ビデオ運動分析","AIエージェント","動き検出","ジャンプ分析","身体部位検出"],"ko":["MediaPipe Pose Detection","비디오 운동 분석","AI 도구","운동 감지","점프 분석","신체 부위 감지"],"es":["MediaPipe Pose Detection","análisis de video","rendimiento atlético","detección de posturas","análisis de saltos","cinemática del cuerpo humano","herramientas de análisis de video","evaluación de la técnica deportiva","análisis de movimiento","reconocimiento de patrones de movimiento"],"fr":["MediaPipe Pose Detection","analyse de vidéo","performance athlétique","détection de poses","analyse de sauts","cinématique du corps humain","outils d''analyse de vidéo","évaluation de la technique sportive","analyse de mouvement","reconnaissance de patterns de mouvement"],"de":["MediaPipe Pose Detection","Videoanalyse","athletische Leistung","Erkennung von Körperhaltungen","Analyse von Sprüngen","Kinematik des menschlichen Körpers","Videoanalyse-Tools","Bewertung der Sporttechnik","Bewegungsanalyse","Mustererkennung von Bewegungen"],"pt":["MediaPipe Pose Detection","análise de desempenho atlético","detecção de pontos de referência","visão computacional","análise de vídeo","desempenho esportivo","treinamento esportivo"],"ru":["MediaPipe Pose Detection","анализ спортивных результатов","обнаружение ориентиров","компьютерное зрение","анализ видео","спортивные результаты","тренировка спортсменов","ИИ Агенты"],"ar":["MediaPipe Pose Detection","تحليل الأداء الرياضي","اكتشاف نقاط المرجعية","رؤية الكمبيوتر","تحليل الفيديو","الأداء الرياضي","تدريب رياضي","أدوات الذكاء الاصطناعي"]}},"owner":"feniix","repo":"kinemotion","repoPath":"feniix/kinemotion","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.606Z","topics":[],"category":"community","skillMd":{"name":"mediapipe-pose-detection","description":"MediaPipe pose detection expertise. Use when debugging landmark tracking, adjusting confidence thresholds, fixing pose detection issues, working with pose.py and video_io.py, or validating pose detection with manual observation.","bodyPreview":"# MediaPipe Pose Detection\n\n## Key Landmarks for Jump Analysis\n\n### Lower Body (Primary for Jumps)\n\n| Landmark | Left Index | Right Index | Use Case                    |\n| -------- | ---------- | ----------- | --------------------------- |\n| Hip      | 23         | 24          | Center of mass, jump height |\n| Knee     | 25         | 26          | Triple extension, landing   |\n| Ankle    | 27         | 28          | Ground contact detection    |\n| Heel     | 29         | 30          | Takeoff/la","body":"# MediaPipe Pose Detection\n\n## Key Landmarks for Jump Analysis\n\n### Lower Body (Primary for Jumps)\n\n| Landmark | Left Index | Right Index | Use Case                    |\n| -------- | ---------- | ----------- | --------------------------- |\n| Hip      | 23         | 24          | Center of mass, jump height |\n| Knee     | 25         | 26          | Triple extension, landing   |\n| Ankle    | 27         | 28          | Ground contact detection    |\n| Heel     | 29         | 30          | Takeoff/landing timing      |\n| Toe      | 31         | 32          | Forefoot contact            |\n\n### Upper Body (Secondary)\n\n| Landmark | Left Index | Right Index | Use Case           |\n| -------- | ---------- | ----------- | ------------------ |\n| Shoulder | 11         | 12          | Arm swing tracking |\n| Elbow    | 13         | 14          | Arm action         |\n| Wrist    | 15         | 16          | Arm swing timing   |\n\n### Reference Points\n\n| Landmark  | Index | Use Case         |\n| --------- | ----- | ---------------- |\n| Nose      | 0     | Head position    |\n| Left Eye  | 2     | Face orientation |\n| Right Eye | 5     | Face orientation |\n\n## Confidence Thresholds\n\n### Default Settings\n\n```python\nmin_detection_confidence = 0.5  # Initial pose detection\nmin_tracking_confidence = 0.5   # Frame-to-frame tracking\n```\n\n### Quality Presets (auto_tuning.py)\n\n| Preset     | Detection | Tracking | Use Case                           |\n| ---------- | --------- | -------- | ---------------------------------- |\n| `fast`     | 0.3       | 0.3      | Quick processing, tolerates errors |\n| `balanced` | 0.5       | 0.5      | Default, good accuracy             |\n| `accurate` | 0.7       | 0.7      | Best accuracy, slower              |\n\n### Tuning Guidelines\n\n- **Increase thresholds** when: Jittery landmarks, false detections\n- **Decrease thresholds** when: Missing landmarks, tracking loss\n- **Typical adjustment**: ±0.1 increments\n\n## Common Issues and Solutions\n\n### Landmark Jitter\n\n**Symptoms**: Landmarks jump erratically between frames\n\n**Solutions**:\n\n1. Apply Butterworth low-pass filter (cutoff 6-10 Hz)\n2. Increase tracking confidence\n3. Use One-Euro filter for real-time applications\n\n```python\n# Butterworth filter (filtering.py)\nfrom kinemotion.core.filtering import butterworth_filter\nsmoothed = butterworth_filter(landmarks, cutoff=8.0, fps=30)\n\n# One-Euro filter (smoothing.py)\nfrom kinemotion.core.smoothing import one_euro_filter\nsmoothed = one_euro_filter(landmarks, min_cutoff=1.0, beta=0.007)\n```\n\n### Left/Right Confusion\n\n**Symptoms**: MediaPipe swaps left and right landmarks mid-video\n\n**Cause**: Occlusion at 90° lateral camera angle\n\n**Solutions**:\n\n1. Use 45° oblique camera angle (recommended)\n2. Post-process to detect and correct swaps\n3. Use single-leg tracking when possible\n\n### Tracking Loss\n\n**Symptoms**: Landmarks disappear for several frames\n\n**Causes**:\n\n- Athlete moves out of frame\n- Fast motion blur\n- Occlusion by equipment/clothing\n\n**Solutions**:\n\n1. Ensure full athlete visibility throughout video\n2. Use higher frame rate (60+ fps)\n3. Interpolate missing frames (up to 3-5 frames)\n\n```python\n# Simple linear interpolation for gaps\nimport numpy as np\ndef interpolate_gaps(landmarks, max_gap=5):\n    # Fill NaN gaps with linear interpolation\n    for i in range(landmarks.shape[1]):\n        mask = np.isnan(landmarks[:, i])\n        if mask.sum() > 0 and mask.sum() <= max_gap:\n            landmarks[:, i] = np.interp(\n                np.arange(len(landmarks)),\n                np.where(~mask)[0],\n                landmarks[~mask, i]\n            )\n    return landmarks\n```\n\n### Low Confidence Scores\n\n**Symptoms**: Visibility scores consistently below threshold\n\n**Causes**:\n\n- Poor lighting (backlighting, shadows)\n- Low contrast clothing vs background\n- Partial occlusion\n\n**Solutions**:\n\n1. Improve lighting (front-lit, even)\n2. Ensure clothing contrasts with background\n3. Remove obstructions from camera view\n\n## Video Processing (video_io.py)\n\n### Rotation Handling\n\nMobile videos often have rotation metadata that must be handled:\n\n```python\n# video_io.py handles this automatically\n# Reads EXIF rotation and applies correction\nfrom kinemotion.core.video_io import read_video_frames\n\nframes, fps, dimensions = read_video_frames(\"mobile_video.mp4\")\n# Frames are correctly oriented regardless of source\n```\n\n### Manual Rotation (if needed)\n\n```bash\n# FFmpeg rotation options\nffmpeg -i input.mp4 -vf \"transpose=1\" output.mp4  # 90° clockwise\nffmpeg -i input.mp4 -vf \"transpose=2\" output.mp4  # 90° counter-clockwise\nffmpeg -i input.mp4 -vf \"hflip\" output.mp4        # Horizontal flip\n```\n\n### Frame Dimensions\n\nAlways read actual frame dimensions from first frame, not metadata:\n\n```python\n# Correct approach\ncap = cv2.VideoCapture(video_path)\nret, frame = cap.read()\nheight, width = frame.shape[:2]\n\n# Incorrect (may be wrong for rotated videos)\nwidth = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))\nheight = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))\n```\n\n## Coordinate Systems\n\n### MediaPipe Output\n\n- Normalized coordinates: (0.0, 0.0) to (1.0, 1.0)\n- Origin: Top-left corner\n- X: Left to right\n- Y: Top to bottom\n- Z: Depth (relative, camera-facing is negative)\n\n### Conversion to Pixels\n\n```python\ndef normalized_to_pixel(landmark, width, height):\n    x = int(landmark.x * width)\n    y = int(landmark.y * height)\n    return x, y\n```\n\n### Visibility Score\n\nEach landmark has a visibility score (0.0-1.0):\n\n- > 0.5: Likely visible and accurate\n- < 0.5: May be occluded or estimated\n- = 0.0: Not detected\n\n## Debug Overlay (debug_overlay.py)\n\n### Skeleton Drawing\n\n```python\n# Key connections for jump visualization\nPOSE_CONNECTIONS = [\n    (23, 25), (25, 27), (27, 29), (27, 31),  # Left leg\n    (24, 26), (26, 28), (28, 30), (28, 32),  # Right leg\n    (23, 24),                                  # Hips\n    (11, 23), (12, 24),                       # Torso\n]\n```\n\n### Color Coding\n\n| Element        | Color (BGR)   | Meaning                   |\n| -------------- | ------------- | ------------------------- |\n| Skeleton       | (0, 255, 0)   | Green - normal tracking   |\n| Low confidence | (0, 165, 255) | Orange - visibility < 0.5 |\n| Key angles     | (255, 0, 0)   | Blue - measured angles    |\n| Phase markers  | (0, 0, 255)   | Red - takeoff/landing     |\n\n## Performance Optimization\n\n### Reducing Latency\n\n1. Use `model_complexity=0` for fastest inference\n2. Process every Nth frame for batch analysis\n3. Use GPU acceleration if available\n\n```python\nimport mediapipe as mp\n\npose = mp.solutions.pose.Pose(\n    model_complexity=0,      # 0=Lite, 1=Full, 2=Heavy\n    min_detection_confidence=0.5,\n    min_tracking_confidence=0.5,\n    static_image_mode=False  # False for video (uses tracking)\n)\n```\n\n### Memory Management\n\n- Release pose estimator after processing: `pose.close()`\n- Process videos in chunks for large files\n- Use generators for frame iteration\n\n## Integration with kinemotion\n\n### File Locations\n\n- Pose estimation: `src/kinemotion/core/pose.py`\n- Video I/O: `src/kinemotion/core/video_io.py`\n- Filtering: `src/kinemotion/core/filtering.py`\n- Smoothing: `src/kinemotion/core/smoothing.py`\n- Auto-tuning: `src/kinemotion/core/auto_tuning.py`\n\n### Typical Pipeline\n\n```text\nVideo → read_video_frames() → pose.process() → filter/smooth → analyze\n```\n\n## Manual Observation for Validation\n\nDuring development, use manual frame-by-frame observation to establish ground truth and validate pose detection accuracy.\n\n### When to Use Manual Observation\n\n1. **Algorithm development**: Validating new phase detection methods\n2. **Parameter tuning**: Comparing detected vs actual frames\n3. **Debugging**: Investigating pose detection failures\n4. **Ground truth collection**: Building validation datasets\n\n### Ground Truth Data Collection Protocol\n\n**Step 1: Generate Debug Video**\n\n```bash\nuv run kinemotion cmj-analyze video.mp4 --output debug.mp4\n```\n\n**Step 2: Manual Frame-by-Frame Analysis**\n\nOpen debug video in a frame-stepping tool (QuickTime, VLC with frame advance, or video editor).\n\n**Step 3: Record Observations**\n\nFor each key phase, record the frame number where the event occurs:\n\n```text\n=== MANUAL OBSERVATION: PHASE DETECTION ===\n\nVideo: ________________________\nFPS: _____ Total Frames: _____\n\nPHASE DETECTION (frame numbers)\n| Phase | Detected | Manual | Error | Notes |\n|-------|----------|--------|-------|-------|\n| Standing End | ___ | ___ | ___ | |\n| Lowest Point | ___ | ___ | ___ | |\n| Takeoff | ___ | ___ | ___ | |\n| Peak Height | ___ | ___ | ___ | |\n| Landing | ___ | ___ | ___ | |\n\nLANDMARK QUALITY (per phase)\n| Phase | Hip Visible | Knee Visible | Ankle Visible | Notes |\n|-------|-------------|--------------|---------------|-------|\n| Standing | Y/N | Y/N | Y/N | |\n| Countermovement | Y/N | Y/N | Y/N | |\n| Flight | Y/N | Y/N | Y/N | |\n| Landing | Y/N | Y/N | Y/N | |\n```\n\n### Phase Detection Criteria\n\n**Standing End**: Last frame before downward hip movement begins\n\n- Look for: Hip starts descending, knees begin flexing\n\n**Lowest Point**: Frame where hip reaches minimum height\n\n- Look for: Deepest squat position, hip at lowest Y coordinate\n\n**Takeoff**: First frame where both feet leave ground\n\n- Look for: Toe/heel landmarks separate from ground plane\n- Note: May be 1-2 frames after visible liftoff due to detection lag\n\n**Peak Height**: Frame where hip reaches maximum height\n\n- Look for: Hip at highest Y coordinate during flight\n\n**Landing**: First frame where foot contacts ground\n\n- Look for: Heel or toe landmark touches ground plane\n- Note: Algorithm may detect 1-2 frames late (velocity-based)\n\n### Landmark Quality Assessment\n\nFor each landmark, observe:\n\n| Quality     | Criteria                                             |\n| ----------- | ---------------------------------------------------- |\n| **Good**    | Landmark stable, positioned correctly on body part   |\n| **Jittery** | Landmark oscillates ±5-10 pixels between frames      |\n| **Offset**  | Landmark consistently displaced from actual position |\n| **Lost**    | Landmark missing or wildly incorrect                 |\n| **Swapped** | Left/right landmarks switched                        |\n\n### Recording Observations Format\n\nWhen validating, provide structured data:\n\n```text\n## Ground Truth: [video_name]\n\n**Video Info:**\n- Frames: 215\n- FPS: 60\n- Duration: 3.58s\n- Camera: 45° oblique\n\n**Phase Detection Comparison:**\n\n| Phase | Detected | Manual | Error (frames) | Error (ms) |\n|-------|----------|--------|----------------|------------|\n| Standing End | 64 | 64 | 0 | 0 |\n| Lowest Point | 91 | 88 | +3 (late) | +50 |\n| Takeoff | 104 | 104 | 0 | 0 |\n| Landing | 144 | 142 | +2 (late) | +33 |\n\n**Error Analysis:**\n- Mean absolute error: 1.25 frames (21ms)\n- Bias detected: Landing consistently late\n- Accuracy: 2/4 perfect, 4/4 within ±3 frames\n\n**Landmark Issues Observed:**\n- Frame 87-92: Hip jitter during lowest point\n- Frame 140-145: Ankle tracking unstable at landing\n```\n\n### Acceptable Error Thresholds\n\nAt 60fps (16.67ms per frame):\n\n| Error Level | Frames | Time  | Interpretation                    |\n| ----------- | ------ | ----- | --------------------------------- |\n| Perfect     | 0      | 0ms   | Exact match                       |\n| Excellent   | ±1     | ±17ms | Within human observation variance |\n| Good        | ±2     | ±33ms | Acceptable for most metrics       |\n| Acceptable  | ±3     | ±50ms | May affect precise timing metrics |\n| Investigate | >3     | >50ms | Algorithm may need adjustment     |\n\n### Bias Detection\n\nLook for systematic patterns across multiple videos:\n\n| Pattern              | Meaning                 | Action                   |\n| -------------------- | ----------------------- | ------------------------ |\n| Consistent +N frames | Algorithm detects late  | Adjust threshold earlier |\n| Consistent -N frames | Algorithm detects early | Adjust threshold later   |\n| Variable ±N frames   | Normal variance         | No action needed         |\n| Increasing error     | Tracking degrades       | Check landmark quality   |\n\n### Integration with Serena (Memory)\n\nStore ground truth observations using `write_note` (Serena):\n\n```python\n# Save validation results\nwrite_note(\n    title=\"CMJ Phase Detection Validation - [video_name]\",\n    content=\"[structured observation data]\",\n    folder=\"biomechanics\"\n)\n\n# Search previous validations\nsearch_notes(query=\"phase detection ground truth\")\n\n# Build context for analysis\nbuild_context(url=\"memory://biomechanics/*\")\n```\n\n### Example: CMJ Validation Study Reference\n\nSee basic-memory (Serena) for complete validation study:\n\n- `biomechanics/cmj-phase-detection-validation-45deg-oblique-view-ground-truth`\n- `biomechanics/cmj-landing-detection-bias-root-cause-analysis`\n- `biomechanics/cmj-landing-detection-impact-vs-contact-method-comparison`\n\nKey findings from validation:\n\n- Standing End: 100% accuracy (0 frame error)\n- Takeoff: ~0.7 frame mean error (excellent)\n- Lowest Point: ~2.3 frame mean error (variable)\n- Landing: +1-2 frame consistent bias (investigate)\n"},"lastSynced":"2026-03-08T02:13:09.611Z","agentAnalysis":{"suitability":{"en":"Perfect for Computer Vision Agents needing advanced pose detection and athletic performance analysis capabilities.","zh":"非常适合需要高级姿势检测和运动表现分析能力的计算机视觉代理。","ja":"高度な姿勢検出と運動性能分析機能を必要とするコンピュータビジョンエージェントに最適です。","ko":"고급 자세検출 및 운동 성능 분석 기능이 필요한 컴퓨터 비전 에이전트에 적합합니다.","es":"Perfecto para agentes de Visión por Computadora que necesitan detección de postura avanzada y capacidades de análisis de rendimiento atlético.","fr":"Parfait pour les agents de Vision par Ordinateur nécessitant une détection de pose avancée et des capacités d''analyse de performance athlétique.","de":"Perfekt für Computer-Vision-Agents, die erweiterte Pose-Erkennung und Leistungsanalyse-Fähigkeiten für Athleten benötigen.","pt":"Perfeito para Agentes de Visão Computacional que necessitam de detecção de pose avançada e capacidades de análise de desempenho atlético.","ru":"Идеально подходит для агентов компьютерного зрения, которым требуются продвинутые возможности обнаружения позы и анализа спортивных результатов.","ar":"مثالي للوكلاء الرؤية الحاسوبية الذين يحتاجون إلى كشف الموقف المتقدم وقدرات تحليل الأداء الرياضي."},"recommendation":{"en":"Empowers agents to track key landmarks like hip, knee, and ankle movement using MediaPipe Pose Detection, providing valuable insights for coaches and athletes through video-based analysis, and supporting protocols like video processing and landmark detection.","zh":"使代理能够使用MediaPipe Pose Detection跟踪关键的身体部位，如髋部、膝盖和脚踝的运动，为教练和运动员提供基于视频的分析和有价值的见解，并支持诸如视频处理和特征点检测等协议。","ja":"MediaPipe Pose Detectionを使用して、エージェントがヒップ、膝、足首などの重要な身体部位の動きを追跡できるようにし、ビデオベースの分析を通じてコーチとアスリートに有価値な洞察を提供し、ビデオ処理や特徴点検出などのプロトコルをサポートします。","ko":"MediaPipe Pose Detection를 사용하여 에이전트가 중요한 신체 부위인 엉덩이, 무릎, 발목 등 движения를 추적할 수 있도록 하여 비디오 기반 분석을 통해 코치와 운동 선수에게 유용한 정보를 제공하며 비디오 처리 및 랜드마크 감지와 같은 프로토콜을 지원합니다.","es":"Habilita a los agentes para rastrear puntos de referencia clave como el movimiento de cadera, rodilla y tobillo utilizando la detección de pose de MediaPipe, proporcionando información valiosa para entrenadores y atletas a través del análisis basado en video y admitiendo protocolos como el procesamiento de video y la detección de puntos de referencia.","fr":"Permet aux agents de suivre des repères clés tels que le mouvement des hanches, des genoux et des chevilles en utilisant la détection de pose MediaPipe, fournissant des informations précieuses pour les entraîneurs et les athlètes grâce à l''analyse basée sur la vidéo et en prenant en charge des protocoles tels que le traitement vidéo et la détection de repères.","de":"Ermöglicht es Agents, wichtige Referenzpunkte wie Hüft-, Knie- und Knöchelbewegung mit der MediaPipe Pose Detection zu verfolgen, wodurch wertvolle Erkenntnisse für Trainer und Athleten durch video-basierte Analyse bereitgestellt werden und Protokolle wie Videoverarbeitung und Referenzpunkterkennung unterstützt werden.","pt":"Habilita os agentes a rastrear pontos de referência importantes como o movimento do quadril, joelho e tornozelo usando a detecção de pose MediaPipe, fornecendo insights valiosos para treinadores e atletas por meio de análise baseada em vídeo e suportando protocolos como processamento de vídeo e detecção de pontos de referência.","ru":"Наделяет агентов возможностью отслеживать ключевые ориентиры, такие как движение таза, колена и лодыжки, с помощью обнаружения позы MediaPipe, обеспечивая ценные сведения для тренеров и спортсменов посредством видеоанализа и поддержки протоколов, таких как обработка видео и обнаружение ориентиров.","ar":"يمكّن الوكلاء من تتبع معالم رئيسية مثل حركة الورك والركبة والكعب باستخدام كشف الوضع MediaPipe ، مما يوفر رؤى قيمة للمدربين والرياضيين من خلال التحليل القائم على الفيديو ودعم بروتوكولات مثل معالجة الفيديو وكشف المعالم."},"useCases":{"en":["Analyzing jump performance by tracking hip, knee, and ankle movement","Detecting ground contact and takeoff points for athletic training","Tracking center of mass and jump height for personalized coaching"],"zh":["通过跟踪髋部、膝盖和脚踝的运动来分析跳跃表现","检测接触地面和起跳点以进行运动训练","跟踪重心和跳跃高度以进行个性化指导"],"ja":["ヒップ、膝、足首の動きを追跡してジャンプ性能を分析する","接地と起跳点を検出して運動トレーニングを行う","重心とジャンプ高度を追跡して個別の指導を行う"],"ko":["엉덩이, 무릎, 발목의 동작을 추적하여 점프 성능을 분석한다","운동 훈련을 위한 접지점 및 이륜점을 감지한다","중심과 점프 높이를 추적하여 개인 맞춤형 코칭을 지원한다"],"es":["Análisis del rendimiento de salto mediante el seguimiento del movimiento de cadera, rodilla y tobillo","Detección de puntos de contacto con el suelo y despegue para el entrenamiento atlético","Seguimiento del centro de masa y la altura del salto para la orientación personalizada"],"fr":["Analyse de la performance de saut en suivant le mouvement des hanches, des genoux et des chevilles","Détection des points de contact avec le sol et de décollage pour l''entraînement athlétique","Suivi du centre de masse et de la hauteur de saut pour une orientation personnalisée"],"de":["Analyse der Sprungleistung durch Verfolgung der Hüft-, Knie- und Knöchelbewegung","Ermittlung der Bodenkontakt- und Abhebepunkte für das athletische Training","Verfolgung des Schwerpunkts und der Sprunghöhe für eine personalisierte Betreuung"],"pt":["Analisar o desempenho do salto rastreando o movimento do quadril, joelho e tornozelo","Detectar os pontos de contato com o solo e decolagem para treinamento atlético","Rastrear o centro de massa e a altura do salto para treinamento personalizado"],"ru":["Анализировать результаты прыжка, отслеживая движение таза, колена и лодыжки","Обнаруживать точки контакта с землей и взлета для спортивной тренировки","Отслеживать центр массы и высоту прыжка для индивидуальной тренировки"],"ar":["تحليل أداء القفز عن طريق تتبع حركة الورك والركبة والكعب","كشف نقاط الاتصال بالأرض وانطلاقها للتدريب الرياضي","تتبع مركز الكتلة وارتفاع القفز للتدريب الشخصي"]},"limitations":{"en":["Requires video input for analysis","Limited to tracking specific landmarks like hip, knee, and ankle","May require additional processing for complex athletic movements"],"zh":["需要视频输入进行分析","仅限于跟踪特定的身体部位，如髋部、膝盖和脚踝","可能需要额外的处理来分析复杂的运动"],"ja":["分析のためにビデオ入力が必要","ヒップ、膝、足首などの特定の身体部位のみを追跡する","複雑な運動の分析には追加の処理が必要になる場合がある"],"ko":["분석을 위해 비디오 입력이 필요합니다","엉덩이, 무릎, 발목 등 특정 신체 부위만을 추적합니다","복잡한 운동의 분석에는 추가적인 처리가 필요할 수 있습니다"],"es":["Requiere entrada de video para el análisis","Limitado a la detección de puntos de referencia específicos como cadera, rodilla y tobillo","Puede requerir procesamiento adicional para movimientos atléticos complejos"],"fr":["Nécessite une entrée vidéo pour l''analyse","Limité à la détection de repères spécifiques tels que les hanches, les genoux et les chevilles","Peut nécessiter un traitement supplémentaire pour les mouvements athlétiques complexes"],"de":["Benötigt Videoeingabe für die Analyse","Begrenzt auf die Erkennung spezifischer Referenzpunkte wie Hüfte, Knie und Knöchel","Kann zusätzliche Verarbeitung für komplexe athletische Bewegungen erfordern"],"pt":["Requer entrada de vídeo para análise","Limitado ao rastreamento de pontos de referência específicos como quadril, joelho e tornozelo","Pode requerer processamento adicional para movimentos atléticos complexos"],"ru":["Требует видеовхода для анализа","Ограничен отслеживанием конкретных ориентиров, таких как таз, колено и лодыжка","Может потребовать дополнительной обработки для сложных спортивных движений"],"ar":["يتطلب إدخال فيديو للتحليل","محدود لتتبع معالم محددة مثل الورك والركبة والكعب","يمكن أن يتطلب معالجة إضافية للحركات الرياضية المعقدة"]},"version":4},"contentHash":"9dbaba81c1377a7cd98a7822fe0498c2731aa99d80cdbe3208a2fd46a3ba75f2","qualityScore":60}');
