INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('feniix/kinemotion/mediapipe-pose-detection', 'mediapipe-pose-detection', 'feniix', 'kinemotion', 'community', 'mediapipe-pose-detection feniix kinemotion community mediapipe-pose-detection analyzes video-based athletic performance, tracking key landmarks like hip, knee, and ankle movement for coaches and athletes. MediaPipe Pose Detection是一种视频运动分析工具，用于检测关键身体部位如髋部、膝盖、脚踝等 MediaPipe Pose Detectionは、ヒップ、膝、踝などの重要な身体部位を検出するためのビデオ運動分析ツールです MediaPipe Pose Detection은 髋部, 무릎,踝关节 등의 주요 신체 부위를 감지하는 비디오 운동 분석 도구입니다 MediaPipe Pose Detection es una herramienta de análisis de video para evaluar el rendimiento atlético, utilizando la detección de posturas para analizar saltos y movimientos MediaPipe Pose Detection est un outil d''analyse de vidéo pour évaluer la performance athlétique, en utilisant la détection de poses pour analyser les sauts et les mouvements MediaPipe Pose Detection ist ein Videoanalyse-Tool zur Bewertung der athletischen Leistung, das die Erkennung von Körperhaltungen zur Analyse von Sprüngen und Bewegungen verwendet O MediaPipe Pose Detection é uma ferramenta de análise de desempenho atlético baseada em vídeo que identifica pontos-chave como altura de salto e contato com o solo MediaPipe Pose Detection - это инструмент для анализа спортивных результатов на основе видео, который определяет ключевые точки, такие как высота прыжка и контакт с землей MediaPipe Pose Detection هو أداة لتحليل الأداء الرياضي بالفيديو التي تحدد النقاط الرئيسية مثل ارتفاع القفز وتماس الأرض how to use mediapipe-pose-detection mediapipe-pose-detection alternative mediapipe-pose-detection install what is mediapipe-pose-detection mediapipe-pose-detection vs openpose mediapipe-pose-detection setup guide mediapipe-pose-detection for athletic performance video analysis with mediapipe-pose-detection kinematic analysis using mediapipe-pose-detection MediaPipe Pose Detection 视频运动分析 AI工具 运动检测 跳跃分析 身体部位检测 Tracks lower body landmarks, including hip, knee, and ankle movement Analyzes jump height and triple extension using landmark indices 23-30 Detects ground contact and takeoff using heel landmarks 29 and 30 Supports kinematic analysis for athletic performance optimization Identifies center of mass and jump height using hip landmarks 23 and 24 mediapipe-pose-detection is a video-based kinematic analysis tool for evaluating athletic performance, particularly jump analysis.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yaleh/meta-cc/Testing Strategy', 'community', 'yaleh', 'meta-cc', 'yaleh/meta-cc', 'Testing Strategy', 0, 0, 60, '2026-03-08T01:57:15.614Z', '2026-03-08T02:13:18.853Z', '80b4d2d8247ed3cdaeec72afb0ee9a3da09744256cf810fdc76074780281a1e5', '{"id":"yaleh/meta-cc/Testing Strategy","name":"Testing Strategy","description":{"en":"Testing Strategy is a Meta-Cognition tool for Claude Code that analyzes session history for workflow optimization, helping developers achieve systematic testing from day one.","zh":"测试策略是Meta-Cognition工具，用于分析会话历史以优化工作流程。它可以将随机测试转换为系统化的、覆盖驱动的测试策略，实现15倍的速度提升","ja":"テスト戦略はMeta-Cognitionツールであり、セッション履歴を分析してワークフローを最適化します。ランダムテストを体系的なカバレッジ駆動型テスト戦略に変換し、15倍の高速化を実現します","ko":"테스트 전략은 메타-인지 도구로, 세션 기록을 분석하여 워크플ロー 최적화를 제공합니다. 임의 테스트를 체계적인 커버리지 주도 테스트 전략으로 변환하여 15배의 속도 향상을 달성합니다","es":"La Estrategia de Pruebas es una herramienta de meta-cognición para Claude Code que analiza el historial de sesiones para optimizar el flujo de trabajo","fr":"La Stratégie de Test est un outil de meta-cognition pour Claude Code qui analyse l''historique des sessions pour optimiser le flux de travail","de":"Die Teststrategie ist ein Meta-Cognition-Tool für Claude Code, das die Sitzungshistorie analysiert, um den Workflow zu optimieren","pt":"A estratégia de testes da ferramenta de meta-cognição para Claude Code transforma testes ad-hoc em estratégias sistemáticas e coverage-driven com 15x de aceleração","ru":"Стратегия тестирования инструмента мета-когниции для Claude Code преобразует ад-хок тестирование в системную стратегию и coverage-driven с 15-кратным ускорением","ar":"istratijia al-ightiyar lil adat al-ma''rifa al-''ali lil Claude Code tusawir al-ightiyar al-''urfy ila istratijiat nizamiyah wa muhayminah bi-tasri'' 15 marah"},"seo":{"title":{"en":"Testing Strategy: Coverage-Driven Setup Guide | AI Agent ...","zh":"AIエージェント测试策略设置指南","ja":"AIエージェントのテスト戦略ベストプラクティス","ko":"AI 에이전트 테스트 전략 구축 가이드","es":"Estrategia de Pruebas: Guía de Configuración para Desarro...","fr":"Stratégie de Test: Guide de Mise en Place pour les Dévelo...","de":"Teststrategie: Einrichtungsleitfaden für Entwickler","pt":"Estratégia de Testes: Guia de Configuração para Ferrament...","ru":"Стратегия Тестирования: Настройка для ИИ Агентов","ar":"stratejia al-ightiyar: daleel ta''seel lil adawat al-''i"},"description":{"en":"Unlock systematic testing with 15x speedup. Discover how to transform ad-hoc testing into a coverage-driven strategy and reach 80%+ coverage","zh":"通过AIエージェント的测试策略，实现代码测试的15倍速度提升，达到80%以上的代码覆盖率","ja":"AIエージェントのテスト戦略を使用して、コードのテストを15倍高速化し、80%以上のコードカバー率を達成","ko":"AI 에이전트의 테스트 전략을 통해 코드 테스트를 15배 속도 향상시키고 80% 이상의 코드 커버리지 달성","es":"Aprende a transformar pruebas ad-hoc en estrategias sistemáticas con nuestra herramienta de meta-cognición para Claude Code","fr":"Découvrez comment transformer les tests ad-hoc en stratégies systématiques avec notre outil de meta-cognition pour Claude Code","de":"Erfahren Sie, wie Sie ad-hoc-Tests in systematische Strategien mit unserem Meta-Cognition-Tool für Claude Code umwandeln","pt":"Aprenda a transformar testes ad-hoc em estratégias sistemáticas com 15x de aceleração. Descubra como otimizar workflows com a ferramenta de meta-cognição par...","ru":"Преобразуйте ад-хок тестирование в системную стратегию с 15-кратным ускорением. Узнайте, как оптимизировать рабочие процессы с помощью инструмента мета-когни...","ar":"ta''alim kayfa tusawir al-ightiyar al-''urfy ila istratijiat nizamiyah bi-tasri'' 15 marah. iktashif kayfa tuhaymin al-sawar'' al-''amaliyah bi-istikhdam adat al-..."},"definition":{"en":"Testing Strategy is a systematic approach to testing that transforms ad-hoc testing into a coverage-driven strategy for quality assurance","zh":"测试策略是指通过AIエージェント分析会话历史以优化工作流程的方法","ja":"テスト戦略とは、AIエージェントを使用してセッション履歴を分析し、ワークフローを最適化する方法","ko":"테스트 전략은 AI 에이전트를 사용하여 세션 기록을 분석하여 워