INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yaleh/meta-cc/Testing Strategy', 'Testing Strategy', 'yaleh', 'meta-cc', 'community', 'Testing Strategy yaleh meta-cc community Testing Strategy is a Meta-Cognition tool for Claude Code that analyzes session history for workflow optimization, helping developers achieve systematic testing from day one. 测试策略是Meta-Cognition工具，用于分析会话历史以优化工作流程。它可以将随机测试转换为系统化的、覆盖驱动的测试策略，实现15倍的速度提升 テスト戦略はMeta-Cognitionツールであり、セッション履歴を分析してワークフローを最適化します。ランダムテストを体系的なカバレッジ駆動型テスト戦略に変換し、15倍の高速化を実現します 테스트 전략은 메타-인지 도구로, 세션 기록을 분석하여 워크플ロー 최적화를 제공합니다. 임의 테스트를 체계적인 커버리지 주도 테스트 전략으로 변환하여 15배의 속도 향상을 달성합니다 La Estrategia de Pruebas es una herramienta de meta-cognición para Claude Code que analiza el historial de sesiones para optimizar el flujo de trabajo La Stratégie de Test est un outil de meta-cognition pour Claude Code qui analyse l''historique des sessions pour optimiser le flux de travail Die Teststrategie ist ein Meta-Cognition-Tool für Claude Code, das die Sitzungshistorie analysiert, um den Workflow zu optimieren A estratégia de testes da ferramenta de meta-cognição para Claude Code transforma testes ad-hoc em estratégias sistemáticas e coverage-driven com 15x de aceleração Стратегия тестирования инструмента мета-когниции для Claude Code преобразует ад-хок тестирование в системную стратегию и coverage-driven с 15-кратным ускорением istratijia al-ightiyar lil adat al-ma''rifa al-''ali lil Claude Code tusawir al-ightiyar al-''urfy ila istratijiat nizamiyah wa muhayminah bi-tasri'' 15 marah how to use Testing Strategy what is Testing Strategy Testing Strategy alternative Testing Strategy vs heroic testing Testing Strategy setup guide Testing Strategy install for Claude Code AIエージェント测试策略 代码测试优化 覆盖驱动测试 CLI应用程序测试 代码覆盖率 新项目测试 测试基础设施 测试速度提升 Analyzes session history for workflow optimization Provides a systematic approach to testing for new projects Helps reach 80%+ coverage systematically Supports building fixtures, mocks, and test helpers for test infrastructure Optimizes testing for CLI applications Testing Strategy is a systematic approach to testing that transforms ad-hoc testing into a coverage-driven strategy for quality assurance');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('spraby/api/ai-factory.fix', 'community', 'spraby', 'api', 'spraby/api', 'ai-factory.fix', 0, 0, 60, '2026-03-08T01:57:15.615Z', '2026-03-08T02:13:21.233Z', '58b114db016cdbd2a7cb7a2a76687b18740d0ded513f4c9f47c6d95fbb2706b5', '{"id":"spraby/api/ai-factory.fix","name":"ai-factory.fix","description":{"en":"ai-factory.fix is a skill that enables AI agents to quickly fix specific bugs or problems by analyzing the codebase directly. It benefits developers by providing a direct and efficient bug-fixing workflow.","zh":"ai-factory.fix 是一种快速的bug修复工作流程，通过分析代码库直接修复特定bug或问题","ja":"ai-factory.fix は、コードベースを直接分析して特定のバグまたは問題を修正する迅速なバグ修正ワークフローです","ko":"ai-factory.fix는 코드베이스를 직접 분석하여 특정 버그 또는 문제를 수정하는 빠른 버그 수정 워크플로입니다","es":"ai-factory.fix es una herramienta que soluciona errores de forma rápida analizando el código y la experiencia pasada. Mejora tu flujo de trabajo","fr":"ai-factory.fix est un outil qui résout les bogues de manière rapide en analysant le code et l''expérience passée. Améliorez votre flux de travail","de":"ai-factory.fix ist ein Tool, das Fehler schnell behebt, indem es den Code und die Erfahrung analysiert. Verbessern Sie Ihren Workflow","pt":"O ai-factory.fix é uma ferramenta para correção rápida de bugs, analisando o código e utilizando patches. Ele carrega o contexto do projeto e patches anteriores para corrigir problemas de forma eficiente","ru":"ai-factory.fix - это инструмент для быстрого исправления ошибок, анализирующий код и использующий патчи. Он загружает контекст проекта и предыдущие патчи для эффективного исправления проблем","ar":"ai-factory.fix هو أداة لتصحيح الأخطاء بسرعة، حيث يقوم بتحليل الكود واستخدام باتشات. يقوم بتحميل سياق المشروع وباتشات سابقة لتصحيح المشاكل بفعالية"},"seo":{"title":{"en":"ai-factory.fix: Quick Bug Fix Workflow Setup Guide | AI A...","zh":"AI工具快速修复指南 - ai-factory.fix","ja":"AIエージェントの迅速なバグ修正ワークフロー - ai-factory.fix","ko":"AI 도구 빠른 버그 수정 가이드 - ai-factory.fix","es":"Configuración de ai-factory.fix: Guía de solución de errores","fr":"Mise en place d''ai-factory.fix: Guide de dépannage","de":"Einrichtung von ai-factory.fix: Fehlerbehebungs-Workflow","pt":"Guia de Configuração do ai-factory.fix para Desenvolvedores","ru":"Настройка ai-factory.fix: Инструмент для Быстрого Исправл...","ar":"دليل إعداد ai-factory.fix لتصحيح الأخطاء بسرعة"},"description":{"en":"Discover how ai-factory.fix streamlines bug fixing by analyzing codebases directly. Learn how to set it up and start resolving issues efficiently today!","zh":"ai-factory.fix 自动化代码分析和修复，实现快速高效的bug解决","ja":"ai-factory.fix はコード分析と修正を自動化し、迅速なバグ解決を実現します","ko":"ai-factory.fix는 코드 분석 및 수정을 자동화하여 빠른 버그 해결을 가능하게 합니다","es":"Descubre cómo ai-factory.fix resuelve errores de forma rápida analizando el código y la experiencia pasada. Mejora tu flujo de trabajo","fr":"Découvrez comment ai-factory.fix résout les bogues de manière rapide en analysant le code et l''expérience passée. Améliorez votre flux de travail","de":"Erfahren Sie, wie ai-factory.fix Fehler schnell behebt, indem es den Code und die Erfahrung analysiert. Verbessern Sie Ihren Workflow","pt":"Aprenda a configurar o ai-factory.fix para corrigir bugs rapidamente, analisando o código e utilizando patches","ru":"Узнайте, как настроить ai-factory.fix для быстрого исправления ошибок, анализируя код и используя патчи","ar":"تعلم كيفية إعداد ai-factory.fix لتصحيح الأخطاء بسرعة عن طريق تحليل الكود واستخدام باتشات"},"definition":{"en":"ai-factory.fix is a workflow-based skill that analyzes codebases to fix bugs, using project context and past experience from files like .ai-factory/DESCRIPTION.md and .ai-factory/patches/","zh":"ai-factory.fix 是一种AI工具，用于快速修复代码中的bug或问题","ja":"ai-factory.fix は、バグまたは問題を迅速に修正するためのAIエージェントです","ko":"ai-factory.fix는 버그 또는 문제를 빠르게 수정하기 위한 AI 도구입니다","es":"ai-factory.fix es un agente de inteligencia artificial que soluciona errores de código","fr":"ai-factory.fix est un agent d''intelligence artificielle qui résout les bogues de code","de":"ai-factory.fix ist ein KI-Tool, das Codefehler behebt","pt":"O que é ai-factory.fix? É uma ferramenta de correção de bugs que analisa o código e utiliza patches para corrigir problemas","ru":"Что такое ai-factory.fix? Это инструмент для исправления ошибок, анализирующий код и использующий патчи для исправления проблем","ar":"ما هو ai-factory.fix؟ هو أداة لتصحيح الأخطاء التي تقوم بتحليل الكود واستخدام باتشات لتصحيح المشاكل"},"features":{"en":["Loads project context from .ai-factory/DESCRIPTION.md to understand tech stack, architecture, and coding conventions","Reads all patches from .ai-factory/patches/ directory using Glob to find *.md files","Analyzes codebase directly to fix specific bugs or problems","Uses past experience from patch files to inform bug-fixing decisions","Streamlines bug-fixing workflow by eliminating the need for plans and reports"],"zh":["加载项目上下文和过去的经验","读取`.ai-factory/DESCRIPTION.md`文件以理解技术栈和项目架构","读取`.ai-factory/patches/`目录中的所有补丁文件","使用Glob找到所有`*.md`文件","直接分析代码库以修复特定bug或问题"],"ja":["プロジェクトのコンテキストと過去の経験をロードする","`.ai-factory/DESCRIPTION.md`ファイルを読み取り、テクノロジースタックとプロジェクトアーキテクチャを理解する","`.ai-factory/patches/`ディレクトリ内のすべてのパッチファイルを読み取り","Globを使用してすべての`*.md`ファイルを見つける","コードベースを直接分析して特定のバグまたは問題を修正する"],"ko":["프로젝트 컨텍스트와 과거의 경험을 로드합니다","`.ai-factory/DESCRIPTION.md` 파일을 읽어 기술 스택과 프로젝트 아키텍처를 이해합니다","`.ai-factory/patches/` 디렉토리 내의 모든 패치 파일을 읽습니다","Glob를 사용하여 모든 `*.md` 파일을 찾습니다","코드베이스를 직접 분석하여 특정 버그 또는 문제를 수정합니다"],"es":["Análisis de código y experiencia pasada","Carga de contexto de proyecto y patches","Compatibilidad con Glob para encontrar archivos de parches","Lectura de archivos de parches en formato Markdown","Soporte para múltiples tecnologías y frameworks"],"fr":["Analyse de code et d''expérience passée","Chargement du contexte de projet et des patches","Compatibilité avec Glob pour trouver les fichiers de patches","Lecture de fichiers de patches au format Markdown","Prise en charge de plusieurs technologies et frameworks"],"de":["Analyse von Code und Erfahrung","Laden von Projektcontext und Patches","Unterstützung von Glob zum Finden von Patch-Dateien","Lesen von Patch-Dateien im Markdown-Format","Unterstützung für mehrere Technologien und Frameworks"],"pt":["Carregamento de contexto do projeto a partir de `.ai-factory/DESCRIPTION.md`","Leitura de patches anteriores em `.ai-factory/patches/`","Análise de código para correção de bugs","Utilização de Glob para encontrar arquivos de patch","Compatibilidade com diferentes tecnologias e frameworks","Integração com ferramentas de desenvolvimento"],"ru":["Загрузка контекста проекта из `.ai-factory/DESCRIPTION.md`","Чтение предыдущих патчей в `.ai-factory/patches/`","Анализ кода для исправления ошибок","Использование Glob для поиска файлов патчей","Совместимость с разными технологиями и фреймворками","Интеграция с инструментами разработки"],"ar":["تحميل سياق المشروع من `.ai-factory/DESCRIPTION.md`","قراءة باتشات سابقة في `.ai-factory/patches/`","تحليل الكود لتصحيح الأخطاء","استخدام Glob للعثور على ملفات باتش","التكامل مع مختلف التكنولوجيات والإطارات","دمج أدوات التطوير"]},"keywords":{"en":["how to use ai-factory.fix","ai-factory.fix setup guide","ai-factory.fix alternative","ai-factory.fix vs traditional bug fixing","what is ai-factory.fix","ai-factory.fix install","ai-factory.fix workflow","bug fixing with ai-factory.fix","ai-factory.fix for developers"],"zh":["AI工具","快速修复","代码分析","bug修复","自动化","代码库","技术栈","项目架构"],"ja":["AIエージェント","迅速なバグ修正","コード分析","バグ修正","自動化","コードベース","テクノロジースタック","プロジェクトアーキテクチャ"],"ko":["AI 도구","빠른 버그 수정","코드 분석","버그 수정","자동화","코드베이스","기술 스택","프로젝트 아키텍처"],"es":["ai-factory.fix","herramientas de inteligencia artificial","solución de errores","análisis de código","flujo de trabajo de desarrollo","desarrollo de software","tecnologías de desarrollo","frameworks de desarrollo"],"fr":["ai-factory.fix","outils d''intelligence artificielle","résolution de bogues","analyse de code","flux de travail de développement","développement de logiciels","technologies de développement","frameworks de développement"],"de":["ai-factory.fix","KI-Tools","Fehlerbehebung","Code-Analyse","Entwicklungs-Workflow","Software-Entwicklung","Entwicklungstechnologien","Entwicklungs-Frameworks"],"pt":["ai-factory.fix","correção de bugs","análise de código","patches","desenvolvimento de software","ferramentas de desenvolvimento","tecnologias de desenvolvimento","frameworks de desenvolvimento","ai agents","ferramentas de ai"],"ru":["ai-factory.fix","исправление ошибок","анализ кода","патчи","разработка программного обеспечения","инструменты разработки","технологии разработки","фреймворки разработки","ИИ агенты","инструменты ИИ"],"ar":["ai-factory.fix","تصحيح الأخطاء","تحليل الكود","باتشات","تطوير البرمجيات","أدوات التطوير","تكنولوجيا التطوير","إطارات التطوير","وكلاء الذكاء الاصطناعي","أدوات الذكاء الاصطناعي"]}},"owner":"spraby","repo":"api","repoPath":"spraby/api","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.615Z","topics":[],"category":"community","skillMd":{"name":"ai-factory.fix","description":"Fix a specific bug or problem in the codebase. Analyzes code to find and fix issues without creating plans. Use when user reports a bug, error, or something not working. Always suggests test coverage and adds logging.","bodyPreview":"# Fix - Quick Bug Fix Workflow\n\nFix a specific bug or problem by analyzing the codebase directly. No plans, no reports.\n\n## Workflow\n\n### Step 0: Load Project Context & Past Experience\n\n**Read `.ai-factory/DESCRIPTION.md`** if it exists to understand:\n- Tech stack (language, framework, database)\n- Project architecture\n- Coding conventions\n\n**Read all patches from `.ai-factory/patches/`** if the directory exists:\n- Use `Glob` to find all `*.md` files in `.ai-factory/patches/`\n- Read each patch fi","body":"# Fix - Quick Bug Fix Workflow\n\nFix a specific bug or problem by analyzing the codebase directly. No plans, no reports.\n\n## Workflow\n\n### Step 0: Load Project Context & Past Experience\n\n**Read `.ai-factory/DESCRIPTION.md`** if it exists to understand:\n- Tech stack (language, framework, database)\n- Project architecture\n- Coding conventions\n\n**Read all patches from `.ai-factory/patches/`** if the directory exists:\n- Use `Glob` to find all `*.md` files in `.ai-factory/patches/`\n- Read each patch file to learn from past fixes\n- Pay attention to recurring patterns, root causes, and solutions\n- If the current problem resembles a past patch — apply the same approach or avoid the same mistakes\n- This is your accumulated experience. Use it.\n\n### Step 1: Understand the Problem\n\nFrom `$ARGUMENTS`, identify:\n- Error message or unexpected behavior\n- Where it occurs (file, function, endpoint)\n- Steps to reproduce (if provided)\n\nIf unclear, ask:\n```\nTo fix this effectively, I need more context:\n\n1. What is the expected behavior?\n2. What actually happens?\n3. Can you share the error message/stack trace?\n4. When did this start happening?\n```\n\n### Step 2: Investigate the Codebase\n\n**Search for the problem:**\n- Find relevant files using Glob/Grep\n- Read the code around the issue\n- Trace the data flow\n- Check for similar patterns elsewhere\n\n**Look for:**\n- The root cause (not just symptoms)\n- Related code that might be affected\n- Existing error handling\n\n### Step 3: Implement the Fix\n\n**Apply the fix with logging:**\n\n```typescript\n// ✅ REQUIRED: Add logging around the fix\nconsole.log(''[FIX] Processing user input'', { userId, input });\n\ntry {\n  // The actual fix\n  const result = fixedLogic(input);\n  console.log(''[FIX] Success'', { userId, result });\n  return result;\n} catch (error) {\n  console.error(''[FIX] Error in fixedLogic'', {\n    userId,\n    input,\n    error: error.message,\n    stack: error.stack\n  });\n  throw error;\n}\n```\n\n**Logging is MANDATORY because:**\n- User needs to verify the fix works\n- If it doesn''t work, logs help debug further\n- Feedback loop: user provides logs → we iterate\n\n### Step 4: Verify the Fix\n\n- Check the code compiles/runs\n- Verify the logic is correct\n- Ensure no regressions introduced\n\n### Step 5: Suggest Test Coverage\n\n**ALWAYS suggest covering this case with a test:**\n\n```\n## Fix Applied ✅\n\nThe issue was: [brief explanation]\nFixed by: [what was changed]\n\n### Logging Added\nThe fix includes logging with prefix `[FIX]`.\nPlease test and share any logs if issues persist.\n\n### Recommended: Add a Test\n\nThis bug should be covered by a test to prevent regression:\n\n\\`\\`\\`typescript\ndescribe(''functionName'', () => {\n  it(''should handle [the edge case that caused the bug]'', () => {\n    // Arrange\n    const input = /* the problematic input */;\n\n    // Act\n    const result = functionName(input);\n\n    // Assert\n    expect(result).toBe(/* expected */);\n  });\n});\n\\`\\`\\`\n\nWould you like me to create this test?\n- [ ] Yes, create the test\n- [ ] No, skip for now\n```\n\n## Logging Requirements\n\n**All fixes MUST include logging:**\n\n1. **Log prefix**: Use `[FIX]` or `[FIX:<issue-id>]` for easy filtering\n2. **Log inputs**: What data was being processed\n3. **Log success**: Confirm the fix worked\n4. **Log errors**: Full context if something fails\n5. **Configurable**: Use LOG_LEVEL if available\n\n```typescript\n// Pattern for fixes\nconst LOG_FIX = process.env.LOG_LEVEL === ''debug'' || process.env.DEBUG_FIX;\n\nfunction fixedFunction(input) {\n  if (LOG_FIX) console.log(''[FIX] Input:'', input);\n\n  // ... fix logic ...\n\n  if (LOG_FIX) console.log(''[FIX] Output:'', result);\n  return result;\n}\n```\n\n## Examples\n\n### Example 1: Null Reference Error\n\n**User:** `/fix TypeError: Cannot read property ''name'' of undefined in UserProfile`\n\n**Actions:**\n1. Search for UserProfile component/function\n2. Find where `.name` is accessed\n3. Add null check with logging\n4. Suggest test for null user case\n\n### Example 2: API Returns Wrong Data\n\n**User:** `/fix /api/orders returns empty array for authenticated users`\n\n**Actions:**\n1. Find orders API endpoint\n2. Trace the query logic\n3. Find the bug (e.g., wrong filter)\n4. Fix with logging\n5. Suggest integration test\n\n### Example 3: Form Validation Not Working\n\n**User:** `/fix email validation accepts invalid emails`\n\n**Actions:**\n1. Find email validation logic\n2. Check regex or validation library usage\n3. Fix the validation\n4. Add logging for validation failures\n5. Suggest unit test with edge cases\n\n## Important Rules\n\n1. **NO plans** - This is a direct fix, not planned work\n2. **NO reports** - Don''t create summary documents\n3. **ALWAYS log** - Every fix must have logging for feedback\n4. **ALWAYS suggest tests** - Help prevent regressions\n5. **Root cause** - Fix the actual problem, not symptoms\n6. **Minimal changes** - Don''t refactor unrelated code\n7. **One fix at a time** - Don''t scope creep\n\n## After Fixing\n\n```\n## Fix Applied ✅\n\n**Issue:** [what was broken]\n**Cause:** [why it was broken]\n**Fix:** [what was changed]\n\n**Files modified:**\n- path/to/file.ts (line X)\n\n**Logging added:** Yes, prefix `[FIX]`\n**Test suggested:** Yes\n\nPlease test the fix and share logs if any issues.\n\nTo add the suggested test:\n- [ ] Yes, create test\n- [ ] No, skip\n```\n\n### Step 6: Create Self-Improvement Patch\n\n**ALWAYS create a patch after every fix.** This builds a knowledge base for future fixes.\n\n**Create the patch:**\n\n1. Create directory if it doesn''t exist:\n   ```bash\n   mkdir -p .ai-factory/patches\n   ```\n\n2. Create a patch file with the current timestamp as filename.\n   **Format:** `YYYY-MM-DD-HH.mm.md` (e.g., `2026-02-07-14.30.md`)\n\n3. Use this template:\n\n```markdown\n# [Brief title describing the fix]\n\n**Date:** YYYY-MM-DD HH:mm\n**Files:** list of modified files\n**Severity:** low | medium | high | critical\n\n## Problem\n\nWhat was broken. How it manifested (error message, wrong behavior).\nBe specific — include the actual error or symptom.\n\n## Root Cause\n\nWHY the problem occurred. This is the most valuable part.\nNot \"what was wrong\" but \"why it was wrong\":\n- Logic error? Why was the logic incorrect?\n- Missing check? Why was it missing?\n- Wrong assumption? What was assumed?\n- Race condition? What sequence caused it?\n\n## Solution\n\nHow the fix was implemented. Key code changes and reasoning.\nInclude the approach, not just \"changed line X\".\n\n## Prevention\n\nHow to prevent this class of problems in the future:\n- What pattern/practice should be followed?\n- What should be checked during code review?\n- What test would catch this?\n\n## Tags\n\nSpace-separated tags for categorization, e.g.:\n`#null-check` `#async` `#validation` `#typescript` `#api` `#database`\n```\n\n**Example patch:**\n\n```markdown\n# Null reference in UserProfile when user has no avatar\n\n**Date:** 2026-02-07 14:30\n**Files:** src/components/UserProfile.tsx\n**Severity:** medium\n\n## Problem\n\nTypeError: Cannot read property ''url'' of undefined when rendering\nUserProfile for users without an uploaded avatar.\n\n## Root Cause\n\nThe `user.avatar` field is optional in the database schema but the\ncomponent accessed `user.avatar.url` without a null check. This was\nintroduced in commit abc123 when avatar display was added — the\ndeveloper tested only with users that had avatars.\n\n## Solution\n\nAdded optional chaining: `user.avatar?.url` with a fallback to a\ndefault avatar URL. Also added a null check in the Avatar sub-component.\n\n## Prevention\n\n- Always check if database fields marked as `nullable` / `optional`\n  are handled with null checks in the UI layer\n- Add test cases for \"empty state\" — user with minimal data\n- Consider a lint rule for accessing nested optional properties\n\n## Tags\n\n`#null-check` `#react` `#optional-field` `#typescript`\n```\n\n**This is NOT optional.** Every fix generates a patch. The patch is your learning.\n\n---\n\n**DO NOT:**\n- ❌ Create PLAN.md or any plan files\n- ❌ Generate reports or summaries (patches are NOT reports — they are learning artifacts)\n- ❌ Refactor unrelated code\n- ❌ Add features while fixing\n- ❌ Skip logging\n- ❌ Skip test suggestion\n- ❌ Skip patch creation\n"},"lastSynced":"2026-03-08T02:13:21.233Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing efficient bug-fixing workflows with direct codebase analysis.","zh":"非常适合需要高效的bug修复工作流程和直接代码库分析的代码分析Agent。","ja":"コード分析エージェントが効率的なバグ修正のワークフローと直接のコードベース分析を必要とする場合に最適です。","ko":"코드 분석 에이전트가 효율적인 버그 수정 워크플로우와 직접 코드베이스 분석을 필요로 하는 경우에 완벽합니다.","es":"Perfecto para Agentes de Análisis de Código que necesitan flujos de trabajo de solución de errores eficientes con análisis directo de la base de código.","fr":"Parfait pour les Agents d''Analyse de Code nécessitant des flux de travail de correction de bogues efficaces avec une analyse directe de la base de code.","de":"Perfekt für Code-Analyse-Agents, die effiziente Fehlerbehebungs-Workflows mit direkter Codebasis-Analyse benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de fluxos de trabalho de correção de bugs eficientes com análise direta do código-fonte.","ru":"Идеально подходит для агентов анализа кода, которым необходимы эффективные рабочие процессы исправления ошибок с прямым анализом кодовой базы.","ar":"مثالي لعمليات تقييم الوكيل للكود التي تحتاج إلى تدفقات عمل كفؤة لتصحيح الأخطاء مع تحليل مباشر لقاعدة الشفرة."},"recommendation":{"en":"Empowers agents to directly fix specific bugs or problems by analyzing the codebase, utilizing project context from `.ai-factory/DESCRIPTION.md` and patch history from `.ai-factory/patches/` directory, streamlining the debugging process with Glob for patch file discovery.","zh":"赋予代理直接修复特定bug或问题的能力，通过分析代码库，利用`.ai-factory/DESCRIPTION.md`中的项目上下文和`.ai-factory/patches/`目录中的补丁历史，利用Glob进行补丁文件发现，从而简化调试过程。","ja":"エージェントが特定のバグや問題を直接修正できるようにし、コードベースを分析し、`.ai-factory/DESCRIPTION.md`からのプロジェクトコンテキストと`.ai-factory/patches/`ディレクトリからのパッチ履歴を利用し、Globを使用してパッチファイルを検出してデバッグプロセスを最適化します。","ko":"에이전트가 특정 버그 또는 문제를 직접 수정할 수 있도록 하며, 코드베이스를 분석하고 `.ai-factory/DESCRIPTION.md`의 프로젝트 컨텍스트와 `.ai-factory/patches/` 디렉토리의 패치 기록을 활용하여 Glob를 사용하여 패치 파일을 발견하여 디버깅 프로세스를 간소화합니다.","es":"Habilita a los agentes a solucionar directamente errores o problemas específicos analizando la base de código, utilizando el contexto del proyecto desde `.ai-factory/DESCRIPTION.md` y el historial de parches desde el directorio `.ai-factory/patches/`, optimizando el proceso de depuración con Glob para el descubrimiento de archivos de parches.","fr":"Permet aux agents de corriger directement des bogues ou des problèmes spécifiques en analysant la base de code, en utilisant le contexte du projet à partir de `.ai-factory/DESCRIPTION.md` et l''historique des correctifs à partir du répertoire `.ai-factory/patches/`, en rationalisant le processus de débogage avec Glob pour la découverte de fichiers de correctifs.","de":"Ermöglicht es den Agents, direkt bestimmte Fehler oder Probleme zu beheben, indem sie die Codebasis analysieren, den Projektkontext aus `.ai-factory/DESCRIPTION.md` und die Patch-Historie aus dem Verzeichnis `.ai-factory/patches/` verwenden, um den Debug-Prozess mit Glob für die Patch-Datei-Erkennung zu optimieren.","pt":"Habilita os agentes a corrigir diretamente bugs ou problemas específicos analisando a base de código, utilizando o contexto do projeto de `.ai-factory/DESCRIPTION.md` e o histórico de patches do diretório `.ai-factory/patches/`, racionalizando o processo de depuração com Glob para a descoberta de arquivos de patch.","ru":"Наделяет агентов возможностью直接 исправлять конкретные ошибки или проблемы, анализируя кодовую базу, используя контекст проекта из `.ai-factory/DESCRIPTION.md` и историю патчей из директории `.ai-factory/patches/`, оптимизируя процесс отладки с помощью Glob для обнаружения файлов патчей.","ar":"تمكّن الوكيل من إصلاح العيوب أو المشاكل المحددة مباشرة عن طريق تحليل قاعدة الشفرة، واستخدام سياق المشروع من `.ai-factory/DESCRIPTION.md` وتاريخ التصحيحات من دليل `.ai-factory/patches/`، وتبسيط عملية تصحيح الأخطاء باستخدام Glob لاكتشاف ملفات التصحيحات."},"useCases":{"en":["Debugging code issues with direct patch application","Analyzing project architecture for bug fixing","Applying coding conventions for consistent fixes"],"zh":["使用直接补丁应用程序调试代码问题","分析项目架构以修复bug","应用编码约定以实现一致的修复"],"ja":["直接パッチ適用によるコードの問題のデバッグ","バグ修正のためのプロジェクトアーキテクチャの分析","一貫した修正のためのコード規約の適用"],"ko":["직접 패치 적용을 통한 코드 문제 디버깅","버그 수정을 위한 프로젝트 아키텍처 분석","일관된 수정을 위한 코딩 규약 적용"],"es":["Depuración de problemas de código con aplicación directa de parches","Análisis de la arquitectura del proyecto para la solución de errores","Aplicación de convenciones de codificación para soluciones coherentes"],"fr":["Débogage des problèmes de code avec application directe de correctifs","Analyse de l''architecture du projet pour la correction de bogues","Application de conventions de codage pour des corrections cohérentes"],"de":["Fehlerbehebung von Codeproblemen mit direkter Patchanwendung","Analyse der Projektarchitektur zur Fehlerbehebung","Anwendung von Codierkonventionen für konsistente Fehlerbehebungen"],"pt":["Depuração de problemas de código com aplicação direta de patches","Análise da arquitetura do projeto para correção de bugs","Aplicação de convenções de codificação para correções consistentes"],"ru":["Отладка проблем кода с прямым применением патчей","Анализ архитектуры проекта для исправления ошибок","Применение соглашений о кодировании для последовательных исправлений"],"ar":["تصحيح مشاكل الشفرة مع تطبيق مباشر للتصحيحات","تحليل هيكل المشروع لتصحيح الأخطاء","تطبيق اتفاقيات الكتابة البرمجية لتصحيحات منتظمة"]},"limitations":{"en":["Requires `.ai-factory/DESCRIPTION.md` and `.ai-factory/patches/` directory for context","Limited to projects with accessible codebase and patch history"],"zh":["需要`.ai-factory/DESCRIPTION.md`和`.ai-factory/patches/`目录来提供上下文","仅限于具有可访问代码库和补丁历史的项目"],"ja":["`.ai-factory/DESCRIPTION.md`と`.ai-factory/patches/`ディレクトリがコンテキストを提供する必要がある","アクセス可能なコードベースとパッチ履歴を持つプロジェクトに限定される"],"ko":["`.ai-factory/DESCRIPTION.md`와 `.ai-factory/patches/` 디렉토리가 컨텍스트를 제공해야 함","액세스 가능한 코드베이스와 패치 기록을 가진 프로젝트에만 제한됨"],"es":["Requiere `.ai-factory/DESCRIPTION.md` y el directorio `.ai-factory/patches/` para el contexto","Limitado a proyectos con base de código y historial de parches accesibles"],"fr":["Nécessite `.ai-factory/DESCRIPTION.md` et le répertoire `.ai-factory/patches/` pour le contexte","Limité à des projets avec une base de code et un historique de correctifs accessibles"],"de":["Benötigt `.ai-factory/DESCRIPTION.md` und das Verzeichnis `.ai-factory/patches/` für den Kontext","Begrenzt auf Projekte mit zugänglicher Codebasis und Patch-Historie"],"pt":["Requer `.ai-factory/DESCRIPTION.md` e diretório `.ai-factory/patches/` para contexto","Limitado a projetos com código-fonte e histórico de patches acessíveis"],"ru":["Требует `.ai-factory/DESCRIPTION.md` и директории `.ai-factory/patches/` для контекста","Ограничен проектами с доступной кодовой базой и историей патчей"],"ar":["يتطلب `.ai-factory/DESCRIPTION.md` ودليل `.ai-factory/patches/` للسياق","محدود بالمشاريع التي تحتوي على قاعدة شفرة و历史 تصحيحات يمكن الوصول إليها"]},"version":4},"contentHash":"58b114db016cdbd2a7cb7a2a76687b18740d0ded513f4c9f47c6d95fbb2706b5","qualityScore":60}');
