INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('spraby/api/ai-factory.fix', 'ai-factory.fix', 'spraby', 'api', 'community', 'ai-factory.fix spraby api community ai-factory.fix is a skill that enables AI agents to quickly fix specific bugs or problems by analyzing the codebase directly. It benefits developers by providing a direct and efficient bug-fixing workflow. ai-factory.fix 是一种快速的bug修复工作流程，通过分析代码库直接修复特定bug或问题 ai-factory.fix は、コードベースを直接分析して特定のバグまたは問題を修正する迅速なバグ修正ワークフローです ai-factory.fix는 코드베이스를 직접 분석하여 특정 버그 또는 문제를 수정하는 빠른 버그 수정 워크플로입니다 ai-factory.fix es una herramienta que soluciona errores de forma rápida analizando el código y la experiencia pasada. Mejora tu flujo de trabajo ai-factory.fix est un outil qui résout les bogues de manière rapide en analysant le code et l''expérience passée. Améliorez votre flux de travail ai-factory.fix ist ein Tool, das Fehler schnell behebt, indem es den Code und die Erfahrung analysiert. Verbessern Sie Ihren Workflow O ai-factory.fix é uma ferramenta para correção rápida de bugs, analisando o código e utilizando patches. Ele carrega o contexto do projeto e patches anteriores para corrigir problemas de forma eficiente ai-factory.fix - это инструмент для быстрого исправления ошибок, анализирующий код и использующий патчи. Он загружает контекст проекта и предыдущие патчи для эффективного исправления проблем ai-factory.fix هو أداة لتصحيح الأخطاء بسرعة، حيث يقوم بتحليل الكود واستخدام باتشات. يقوم بتحميل سياق المشروع وباتشات سابقة لتصحيح المشاكل بفعالية how to use ai-factory.fix ai-factory.fix setup guide ai-factory.fix alternative ai-factory.fix vs traditional bug fixing what is ai-factory.fix ai-factory.fix install ai-factory.fix workflow bug fixing with ai-factory.fix ai-factory.fix for developers AI工具 快速修复 代码分析 bug修复 自动化 代码库 技术栈 项目架构 Loads project context from .ai-factory/DESCRIPTION.md to understand tech stack, architecture, and coding conventions Reads all patches from .ai-factory/patches/ directory using Glob to find *.md files Analyzes codebase directly to fix specific bugs or problems Uses past experience from patch files to inform bug-fixing decisions Streamlines bug-fixing workflow by eliminating the need for plans and reports ai-factory.fix is a workflow-based skill that analyzes codebases to fix bugs, using project context and past experience from files like .ai-factory/DESCRIPTION.md and .ai-factory/patches/');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('POWERFULMOVES/PMOVES-BoTZ/hugging-face-dataset-creator', 'community', 'POWERFULMOVES', 'PMOVES-BoTZ', 'POWERFULMOVES/PMOVES-BoTZ', 'hugging-face-dataset-creator', 0, 0, 60, '2026-03-08T01:57:15.617Z', '2026-03-08T02:13:23.646Z', '101464dab8917c3796b2924d5bd9d9cfdbb523545ea385de198286dabed86c6e', '{"id":"POWERFULMOVES/PMOVES-BoTZ/hugging-face-dataset-creator","name":"hugging-face-dataset-creator","description":{"en":"The hugging-face-dataset-creator skill provides tools for managing datasets on the Hugging Face Hub, focusing on creation, configuration, and content management. It benefits developers and data scientists working with Hugging Face datasets.","zh":"Hugging Face 数据集创建工具提供数据集创建、配置和内容管理的功能，补充了 Hugging Face MCP 服务器的功能","ja":"Hugging Face データセット作成ツールは、データセットの作成、構成、コンテンツ管理機能を提供し、Hugging Face MCP サーバーの機能を補完する","ko":"Hugging Face 데이터셋 생성 도구는 데이터셋 생성, 구성, 콘텐츠 관리 기능을 제공하여 Hugging Face MCP 서버의 기능을 보완합니다","es":"Hugging Face Dataset Creator es una habilidad que proporciona herramientas para gestionar datasets en Hugging Face Hub, con enfoque en creación, configuración y gestión de contenido.","fr":"Hugging Face Dataset Creator est une compétence qui fournit des outils pour gérer des datasets sur Hugging Face Hub, avec un focus sur la création, la configuration et la gestion de contenu.","de":"Hugging Face Dataset Creator ist eine Fähigkeit, die Tools zur Verwaltung von Datensätzen im Hugging Face Hub bereitstellt, mit Fokus auf Erstellung, Konfiguration und Inhaltsverwaltung.","pt":"O hugging-face-dataset-creator é uma ferramenta para gerenciar conjuntos de dados no Hugging Face Hub, com foco em criação, configuração e gerenciamento de conteúdo","ru":"hugging-face-dataset-creator - это инструмент для управления наборами данных на Hugging Face Hub, с фокусом на создании, конфигурации и управлении контентом","ar":"hugging-face-dataset-creator هو أداة لإدارة مجموعات البيانات على منصة Hugging Face Hub مع التركيز على إنشاء وتفضيل المحتوى"},"seo":{"title":{"en":"hugging-face-dataset-creator: Dataset Management Setup Gu...","zh":"Hugging Face 数据集创建工具 Setup Guide","ja":"Hugging Face データセット作成ツールのベストプラクティス","ko":"Hugging Face 데이터셋 생성 도구 설정 가이드","es":"Guía de configuración de hugging-face-dataset-creator par...","fr":"Configurer hugging-face-dataset-creator : Meilleures prat...","de":"Einrichten von hugging-face-dataset-creator: Leitfaden fü...","pt":"Guia de Configuração do hugging-face-dataset-creator","ru":"Настройка hugging-face-dataset-creator: Лучшие Практики","ar":"دليل إعداد hugging-face-dataset-creator لل AI الإداريين"},"description":{"en":"Discover how to manage datasets on Hugging Face Hub with the hugging-face-dataset-creator skill. Learn to create, configure, and edit datasets with ease. Get...","zh":"使用 Hugging Face 数据集创建工具管理和配置数据集，实现数据集编辑和内容管理的自动化","ja":"Hugging Face データセット作成ツールを使用してデータセットを管理および構成し、データセット編集とコンテンツ管理を自動化する","ko":"Hugging Face 데이터셋 생성 도구를 사용하여 데이터셋을 관리하고 구성하여 데이터셋 편집 및 콘텐츠 관리를 자동화합니다","es":"Aprende a crear y configurar datasets en Hugging Face Hub con hugging-face-dataset-creator. Descubre cómo complementar el servidor MCP de Hugging Face.","fr":"Découvrez comment créer et configurer des datasets sur Hugging Face Hub avec hugging-face-dataset-creator. Complétez le serveur MCP de Hugging Face.","de":"Erfahren Sie, wie Sie Datensätze im Hugging Face Hub mit hugging-face-dataset-creator erstellen und konfigurieren. Ergänzen Sie den Hugging Face MCP-Server.","pt":"Aprenda a utilizar o hugging-face-dataset-creator para gerenciar conjuntos de dados no Hugging Face Hub com foco em criação e edição de conteúdo","ru":"Узнайте, как использовать hugging-face-dataset-creator для управления наборами данных на Hugging Face Hub с фокусом на создании и редактировании контента","ar":"اكتشف كيفية استخدام hugging-face-dataset-creator لإدارة مجموعات البيانات على منصة Hugging Face Hub مع التركيز على إنشاء وتحرير المحتوى"},"definition":{"en":"hugging-face-dataset-creator is a skill designed to manage datasets on the Hugging Face Hub, providing capabilities for dataset creation, editing, and configuration management.","zh":"Hugging Face 数据集创建工具是一种用于管理和配置 Hugging Face Hub 数据集的工具","ja":"Hugging Face データセット作成ツールは、Hugging Face Hub のデータセットを管理および構成するためのツールです","ko":"Hugging Face 데이터셋 생성 도구는 Hugging Face Hub의 데이터셋을 관리하고 구성하기 위한 도구입니다","es":"Hugging Face Dataset Creator es una herramienta de AI que permite a los desarrolladores crear y gestionar datasets en Hugging Face Hub.","fr":"Hugging Face Dataset Creator est un outil d''IA qui permet aux développeurs de créer et de gérer des datasets sur Hugging Face Hub.","de":"Hugging Face Dataset Creator ist ein AI-Tool, das Entwicklern ermöglicht, Datensätze im Hugging Face Hub zu erstellen und zu verwalten.","pt":"O que é hugging-face-dataset-creator? É uma ferramenta para criar e gerenciar conjuntos de dados no Hugging Face Hub","ru":"Что такое hugging-face-dataset-creator? Это инструмент для создания и управления наборами данных на Hugging Face Hub","ar":"ما هو hugging-face-dataset-creator؟ إنه أداة لإنشاء وإدارة مجموعات البيانات على منصة Hugging Face Hub"},"features":{"en":["Provides dataset creation capabilities","Offers content editing and configuration management","Complements the existing Hugging Face MCP server","Enables dataset discovery, search, and metadata retrieval via HF MCP Server","Supports structuring and organizing datasets on the Hugging Face Hub"],"zh":["数据集创建和配置","内容管理和编辑","与 Hugging Face MCP 服务器集成","数据集发现和搜索","元数据检索"],"ja":["データセットの作成と構成","コンテンツ管理と編集","Hugging Face MCP サーバーとの統合","データセットの検索と発見","メタデータの取得"],"ko":["데이터셋 생성 및 구성","콘텐츠 관리 및 편집","Hugging Face MCP 서버와의 통합","데이터셋 검색 및 발견","메타데이터 조회"],"es":["Creación de datasets en Hugging Face Hub","Configuración y gestión de contenido de datasets","Integración con el servidor MCP de Hugging Face","Edición de datasets","Gestión de metadatos de datasets"],"fr":["Création de datasets sur Hugging Face Hub","Configuration et gestion de contenu de datasets","Intégration avec le serveur MCP de Hugging Face","Édition de datasets","Gestion de métadonnées de datasets"],"de":["Erstellung von Datensätzen im Hugging Face Hub","Konfiguration und Verwaltung von Datensatzinhalten","Integration mit dem Hugging Face MCP-Server","Bearbeitung von Datensätzen","Verwaltung von Metadaten von Datensätzen"],"pt":["Criação de conjuntos de dados no Hugging Face Hub","Edição de conteúdo de conjuntos de dados","Configuração de conjuntos de dados","Gerenciamento de estrutura de conjuntos de dados","Integração com o servidor HF MCP"],"ru":["Создание наборов данных на Hugging Face Hub","Редактирование контента наборов данных","Конфигурация наборов данных","Управление структурой наборов данных","Интеграция с сервером HF MCP"],"ar":["إنشاء مجموعات البيانات على منصة Hugging Face Hub","تحرير المحتوى لمجموعات البيانات","تكوين مجموعات البيانات","إدارة هيكل مجموعات البيانات","التكامل مع خادم HF MCP"]},"keywords":{"en":["how to use hugging-face-dataset-creator","hugging-face-dataset-creator setup guide","hugging-face-dataset-creator alternative","hugging-face-dataset-creator vs HF MCP Server","hugging-face-dataset-creator install","managing datasets on Hugging Face Hub"],"zh":["Hugging Face 数据集创建工具","AI 工具","数据集管理","内容管理","Hugging Face MCP 服务器","数据集编辑","Python","CLI"],"ja":["Hugging Face データセット作成ツール","AI エージェント","データセット管理","コンテンツ管理","Hugging Face MCP サーバー","データセット編集","Python","CLI"],"ko":["Hugging Face 데이터셋 생성 도구","AI 도구","데이터셋 관리","콘텐츠 관리","Hugging Face MCP 서버","데이터셋 편집","Python","CLI"],"es":["hugging face dataset creator","creación de datasets","gestión de datasets","Hugging Face Hub","servidor MCP de Hugging Face","edición de datasets","gestión de metadatos","herramientas de AI para desarrolladores"],"fr":["hugging face dataset creator","création de datasets","gestion de datasets","Hugging Face Hub","serveur MCP de Hugging Face","édition de datasets","gestion de métadonnées","outils d''IA pour développeurs"],"de":["hugging face dataset creator","erstellung von datensätzen","verwaltung von datensätzen","Hugging Face Hub","Hugging Face MCP-Server","bearbeitung von datensätzen","verwaltung von metadaten","AI-Tools für Entwickler"],"pt":["hugging face dataset creator","gerenciamento de conjuntos de dados","criação de conjuntos de dados","edição de conteúdo de conjuntos de dados","configuração de conjuntos de dados","integração com servidor HF MCP","ferramentas de AI","hugging face hub"],"ru":["hugging face dataset creator","управление наборами данных","создание наборов данных","редактирование контента наборов данных","конфигурация наборов данных","интеграция с сервером HF MCP","инструменты ИИ","hugging face hub"],"ar":["hugging face dataset creator","إدارة مجموعات البيانات","إنشاء مجموعات البيانات","تحرير المحتوى لمجموعات البيانات","تكوين مجموعات البيانات","التكامل مع خادم HF MCP","أدوات الذكاء الاصطناعي","منصة Hugging Face Hub"]}},"owner":"POWERFULMOVES","repo":"PMOVES-BoTZ","repoPath":"POWERFULMOVES/PMOVES-BoTZ","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.617Z","topics":[],"category":"community","skillMd":{"name":"hugging-face-dataset-creator","description":"Create and manage datasets on Hugging Face Hub. Supports initializing repos, defining configs/system prompts, and streaming row updates. Designed to work alongside HF MCP server for comprehensive dataset workflows.","bodyPreview":"# Overview\nThis skill provides tools to manage datasets on the Hugging Face Hub with a focus on creation, configuration, and content management. It is designed to complement the existing Hugging Face MCP server by providing dataset editing capabilities that the MCP server doesn''t offer.\n\n## Integration with HF MCP Server\n- **Use HF MCP Server for**: Dataset discovery, search, and metadata retrieval\n- **Use This Skill for**: Dataset creation, content editing, configuration management, and structu","body":"# Overview\nThis skill provides tools to manage datasets on the Hugging Face Hub with a focus on creation, configuration, and content management. It is designed to complement the existing Hugging Face MCP server by providing dataset editing capabilities that the MCP server doesn''t offer.\n\n## Integration with HF MCP Server\n- **Use HF MCP Server for**: Dataset discovery, search, and metadata retrieval\n- **Use This Skill for**: Dataset creation, content editing, configuration management, and structured data formatting\n\n# Version\n2.0.0\n\n# Dependencies\n- huggingface_hub\n- json (built-in)\n- time (built-in)\n\n# Core Capabilities\n\n## 1. Dataset Lifecycle Management\n- **Initialize**: Create new dataset repositories with proper structure\n- **Configure**: Store detailed configuration including system prompts and metadata\n- **Stream Updates**: Add rows efficiently without downloading entire datasets\n\n## 2. Multi-Format Dataset Support\nSupports diverse dataset types through template system:\n- **Chat/Conversational**: Chat templating, multi-turn dialogues, tool usage examples\n- **Text Classification**: Sentiment analysis, intent detection, topic classification\n- **Question-Answering**: Reading comprehension, factual QA, knowledge bases\n- **Text Completion**: Language modeling, code completion, creative writing\n- **Tabular Data**: Structured data for regression/classification tasks\n- **Custom Formats**: Flexible schema definition for specialized needs\n\n## 3. Quality Assurance Features\n- **JSON Validation**: Ensures data integrity during uploads\n- **Batch Processing**: Efficient handling of large datasets\n- **Error Recovery**: Graceful handling of upload failures and conflicts\n\n# Usage Instructions\n\nThe skill includes a Python script `scripts/dataset_manager.py` to perform operations.\n\n### Prerequisites\n- `huggingface_hub` library must be installed via `uv add huggingface_hub`\n- `HF_TOKEN` environment variable must be set with a Write-access token\n- Activate virtual environment: `source .venv/bin/activate`\n\n### Recommended Workflow\n\n**1. Discovery (Use HF MCP Server):**\n```python\n# Use HF MCP tools to find existing datasets\nsearch_datasets(\"conversational AI training\")\nget_dataset_details(\"username/dataset-name\")\n```\n\n**2. Creation (Use This Skill):**\n```bash\n# Initialize new dataset\npython scripts/dataset_manager.py init --repo_id \"your-username/dataset-name\" [--private]\n\n# Configure with detailed system prompt\npython scripts/dataset_manager.py config --repo_id \"your-username/dataset-name\" --system_prompt \"$(cat system_prompt.txt)\"\n```\n\n**3. Content Management (Use This Skill):**\n```bash\n# Quick setup with any template\npython scripts/dataset_manager.py quick_setup \\\n  --repo_id \"your-username/dataset-name\" \\\n  --template classification\n\n# Add data with template validation\npython scripts/dataset_manager.py add_rows \\\n  --repo_id \"your-username/dataset-name\" \\\n  --template qa \\\n  --rows_json \"$(cat your_qa_data.json)\"\n```\n\n### Template-Based Data Structures\n\n**1. Chat Template (`--template chat`)**\n```json\n{\n  \"messages\": [\n    {\"role\": \"user\", \"content\": \"Natural user request\"},\n    {\"role\": \"assistant\", \"content\": \"Response with tool usage\"},\n    {\"role\": \"tool\", \"content\": \"Tool response\", \"tool_call_id\": \"call_123\"}\n  ],\n  \"scenario\": \"Description of use case\",\n  \"complexity\": \"simple|intermediate|advanced\"\n}\n```\n\n**2. Classification Template (`--template classification`)**\n```json\n{\n  \"text\": \"Input text to be classified\",\n  \"label\": \"classification_label\",\n  \"confidence\": 0.95,\n  \"metadata\": {\"domain\": \"technology\", \"language\": \"en\"}\n}\n```\n\n**3. QA Template (`--template qa`)**\n```json\n{\n  \"question\": \"What is the question being asked?\",\n  \"answer\": \"The complete answer\",\n  \"context\": \"Additional context if needed\",\n  \"answer_type\": \"factual|explanatory|opinion\",\n  \"difficulty\": \"easy|medium|hard\"\n}\n```\n\n**4. Completion Template (`--template completion`)**\n```json\n{\n  \"prompt\": \"The beginning text or context\",\n  \"completion\": \"The expected continuation\",\n  \"domain\": \"code|creative|technical|conversational\",\n  \"style\": \"description of writing style\"\n}\n```\n\n**5. Tabular Template (`--template tabular`)**\n```json\n{\n  \"columns\": [\n    {\"name\": \"feature1\", \"type\": \"numeric\", \"description\": \"First feature\"},\n    {\"name\": \"target\", \"type\": \"categorical\", \"description\": \"Target variable\"}\n  ],\n  \"data\": [\n    {\"feature1\": 123, \"target\": \"class_a\"},\n    {\"feature1\": 456, \"target\": \"class_b\"}\n  ]\n}\n```\n\n### Advanced System Prompt Template\n\nFor high-quality training data generation:\n```text\nYou are an AI assistant expert at using MCP tools effectively.\n\n## MCP SERVER DEFINITIONS\n[Define available servers and tools]\n\n## TRAINING EXAMPLE STRUCTURE\n[Specify exact JSON schema for chat templating]\n\n## QUALITY GUIDELINES\n[Detail requirements for realistic scenarios, progressive complexity, proper tool usage]\n\n## EXAMPLE CATEGORIES\n[List development workflows, debugging scenarios, data management tasks]\n```\n\n### Example Categories & Templates\n\nThe skill includes diverse training examples beyond just MCP usage:\n\n**Available Example Sets:**\n- `training_examples.json` - MCP tool usage examples (debugging, project setup, database analysis)\n- `diverse_training_examples.json` - Broader scenarios including:\n  - **Educational Chat** - Explaining programming concepts, tutorials\n  - **Git Workflows** - Feature branches, version control guidance\n  - **Code Analysis** - Performance optimization, architecture review\n  - **Content Generation** - Professional writing, creative brainstorming\n  - **Codebase Navigation** - Legacy code exploration, systematic analysis\n  - **Conversational Support** - Problem-solving, technical discussions\n\n**Using Different Example Sets:**\n```bash\n# Add MCP-focused examples\npython scripts/dataset_manager.py add_rows --repo_id \"your-username/dataset-name\" \\\n  --rows_json \"$(cat examples/training_examples.json)\"\n\n# Add diverse conversational examples\npython scripts/dataset_manager.py add_rows --repo_id \"your-username/dataset-name\" \\\n  --rows_json \"$(cat examples/diverse_training_examples.json)\"\n\n# Mix both for comprehensive training data\npython scripts/dataset_manager.py add_rows --repo_id \"your-username/dataset-name\" \\\n  --rows_json \"$(jq -s ''.[0] + .[1]'' examples/training_examples.json examples/diverse_training_examples.json)\"\n```\n\n### Commands Reference\n\n**List Available Templates:**\n```bash\npython scripts/dataset_manager.py list_templates\n```\n\n**Quick Setup (Recommended):**\n```bash\npython scripts/dataset_manager.py quick_setup --repo_id \"your-username/dataset-name\" --template classification\n```\n\n**Manual Setup:**\n```bash\n# Initialize repository\npython scripts/dataset_manager.py init --repo_id \"your-username/dataset-name\" [--private]\n\n# Configure with system prompt\npython scripts/dataset_manager.py config --repo_id \"your-username/dataset-name\" --system_prompt \"Your prompt here\"\n\n# Add data with validation\npython scripts/dataset_manager.py add_rows \\\n  --repo_id \"your-username/dataset-name\" \\\n  --template qa \\\n  --rows_json ''[{\"question\": \"What is AI?\", \"answer\": \"Artificial Intelligence...\"}]''\n```\n\n**View Dataset Statistics:**\n```bash\npython scripts/dataset_manager.py stats --repo_id \"your-username/dataset-name\"\n```\n\n### Error Handling\n- **Repository exists**: Script will notify and continue with configuration\n- **Invalid JSON**: Clear error message with parsing details\n- **Network issues**: Automatic retry for transient failures\n- **Token permissions**: Validation before operations begin\n"},"lastSynced":"2026-03-08T02:13:23.646Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents working with Hugging Face datasets needing advanced dataset creation and management capabilities.","zh":"适合需要高级数据集创建和管理能力的 AI Agent，与 Hugging Face 数据集合作。","ja":"Hugging Face データセットを使用して高度なデータセット作成および管理機能を必要とする AI エージェントに適しています。","ko":"Hugging Face 데이터셋과 함께 고급 데이터셋 생성 및 관리 기능이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que trabajan con conjuntos de datos de Hugging Face que necesitan capacidades avanzadas de creación y administración de conjuntos de datos.","fr":"Parfait pour les agents IA travaillant avec les jeux de données Hugging Face nécessitant des capacités de création et de gestion de jeux de données avancées.","de":"Perfekt für KI-Agents, die mit Hugging Face-Datensätzen arbeiten und erweiterte Datensatz-Erstellungs- und Verwaltungsfunktionen benötigen.","pt":"Perfeito para Agentes de IA que trabalham com conjuntos de dados do Hugging Face e necessitam de capacidades avançadas de criação e gerenciamento de conjuntos de dados.","ru":"Идеально подходит для агентов ИИ, работающих с наборами данных Hugging Face, требующих расширенных возможностей создания и управления наборами данных.","ar":"مثالي للوكلاء الذكاء الاصطناعي العاملين مع مجموعات البيانات Hugging Face التي تحتاج إلى возможات متقدمة لإنشاء وإدارة مجموعات البيانات."},"recommendation":{"en":"Empowers agents to manage datasets on the Hugging Face Hub, providing dataset creation, content editing, configuration management, and structure capabilities, leveraging the Hugging Face MCP server for dataset discovery and metadata retrieval.","zh":"赋予代理管理 Hugging Face Hub 上的数据集的能力，提供数据集创建、内容编辑、配置管理和结构功能，利用 Hugging Face MCP 服务器进行数据集发现和元数据检索。","ja":"エージェントが Hugging Face Hub 上のデータセットを管理する能力を提供し、データセットの作成、コンテンツの編集、構成管理、および構造機能を提供し、Hugging Face MCP サーバーを使用してデータセットの発見とメタデータの取得を行います。","ko":"에이전트가 Hugging Face Hub上的 데이터셋을 관리할 수 있는 능력을 제공하며, 데이터셋 생성, 콘텐츠 편집, 구성 관리 및 구조 기능을 제공하며, Hugging Face MCP 서버를 사용하여 데이터셋 검색 및 메타데이터 검색을 수행합니다.","es":"Habilita a los agentes a administrar conjuntos de datos en el Hub de Hugging Face, proporcionando creación de conjuntos de datos, edición de contenido, administración de configuraciones y capacidades de estructura, aprovechando el servidor Hugging Face MCP para el descubrimiento de conjuntos de datos y la recuperación de metadatos.","fr":"Permet aux agents de gérer les jeux de données sur le Hub Hugging Face, en fournissant la création de jeux de données, l''édition de contenu, la gestion de configurations et les capacités de structure, en exploitant le serveur Hugging Face MCP pour la découverte de jeux de données et la récupération de métadonnées.","de":"Ermöglicht es Agenten, Datensätze im Hugging Face-Hub zu verwalten und bietet Datensatzerstellung, Inhaltsbearbeitung, Konfigurationsverwaltung und Strukturkapazitäten, indem es den Hugging Face-MCP-Server für die Datensatzentdeckung und die Metadatenrückgewinnung nutzt.","pt":"Habilita os agentes a gerenciar conjuntos de dados no Hugging Face Hub, fornecendo criação de conjuntos de dados, edição de conteúdo, gerenciamento de configuração e capacidades de estrutura, utilizando o servidor Hugging Face MCP para descoberta de conjuntos de dados e recuperação de metadados.","ru":"Наделяет агентов возможностью управлять наборами данных на Hugging Face Hub, предоставляя создание наборов данных, редактирование контента, управление конфигурацией и структурами, используя сервер Hugging Face MCP для обнаружения наборов данных и извлечения метаданных.","ar":"يتمكّن الوكلاء من إدارة مجموعات البيانات على Hugging Face Hub، ويتضمن ذلك إنشاء مجموعات البيانات، وتحرير المحتوى، وإدارة التكوين، والهياكل، مستخدمين خادم Hugging Face MCP للكشف عن مجموعات البيانات واسترجاع البيانات الوصفية."},"useCases":{"en":["Creating and configuring datasets for machine learning model training","Editing and updating dataset content on the Hugging Face Hub","Managing dataset structures and configurations for optimal performance"],"zh":["为机器学习模型训练创建和配置数据集","在 Hugging Face Hub 上编辑和更新数据集内容","管理数据集结构和配置以实现最佳性能"],"ja":["機械学習モデル訓練用のデータセットの作成と構成","Hugging Face Hub 上のデータセットコンテンツの編集と更新","データセット構造と構成の管理による最適なパフォーマンスの実現"],"ko":["기계 학습 모델 훈련을 위한 데이터셋 생성 및 구성","Hugging Face Hub上的 데이터셋 콘텐츠 편집 및 업데이트","데이터셋 구조 및 구성 관리를 통한 최적의 성능 달성"],"es":["Creación y configuración de conjuntos de datos para el entrenamiento de modelos de aprendizaje automático","Edición y actualización de contenido de conjuntos de datos en el Hub de Hugging Face","Administración de estructuras y configuraciones de conjuntos de datos para un rendimiento óptimo"],"fr":["Création et configuration de jeux de données pour la formation de modèles d''apprentissage automatique","Édition et mise à jour de contenu de jeux de données sur le Hub Hugging Face","Gestion de structures et de configurations de jeux de données pour des performances optimales"],"de":["Erstellung und Konfiguration von Datensätzen für die Schulung von Machine-Learning-Modellen","Bearbeitung und Aktualisierung von Datensatzinhalten im Hugging Face-Hub","Verwaltung von Datensatzstrukturen und -konfigurationen für optimale Leistung"],"pt":["Criar e configurar conjuntos de dados para treinamento de modelos de aprendizado de máquina","Editar e atualizar o conteúdo do conjunto de dados no Hugging Face Hub","Gerenciar estruturas e configurações de conjuntos de dados para desempenho ótimo"],"ru":["Создание и конфигурирование наборов данных для обучения моделей машинного обучения","Редактирование и обновление содержимого набора данных на Hugging Face Hub","Управление структурами и конфигурациями наборов данных для оптимальной производительности"],"ar":["إنشاء وتكوين مجموعات البيانات لتدريب نماذج التعلم الالي","تحرير وتحديث المحتوى لمجموعة البيانات على Hugging Face Hub","إدارة الهياكل والتكوينات لمجموعات البيانات من أجل الأداء الأمثل"]},"limitations":{"en":["Requires access to the Hugging Face Hub","Intended for use with Hugging Face datasets only"],"zh":["需要访问 Hugging Face Hub","仅适用于 Hugging Face 数据集"],"ja":["Hugging Face Hub へのアクセスが必要","Hugging Face データセットのみを使用するように設計"],"ko":["Hugging Face Hub 접근 필요","Hugging Face 데이터셋만을 사용하기 위한 것으로 설계됨"],"es":["Requiere acceso al Hub de Hugging Face","Está destinado a ser utilizado solo con conjuntos de datos de Hugging Face"],"fr":["Nécessite un accès au Hub Hugging Face","Conçu pour être utilisé uniquement avec les jeux de données Hugging Face"],"de":["Erfordert Zugriff auf den Hugging Face-Hub","Bestimmt für die Verwendung nur mit Hugging Face-Datensätzen"],"pt":["Requer acesso ao Hugging Face Hub","Destina-se apenas ao uso com conjuntos de dados do Hugging Face"],"ru":["Требует доступа к Hugging Face Hub","Предназначен только для использования с наборами данных Hugging Face"],"ar":["يتطلب الوصول إلى Hugging Face Hub","مصمم فقط للاستخدام مع مجموعات البيانات Hugging Face"]},"version":4},"contentHash":"101464dab8917c3796b2924d5bd9d9cfdbb523545ea385de198286dabed86c6e","qualityScore":60}');
