INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('POWERFULMOVES/PMOVES-BoTZ/hugging-face-dataset-creator', 'hugging-face-dataset-creator', 'POWERFULMOVES', 'PMOVES-BoTZ', 'community', 'hugging-face-dataset-creator POWERFULMOVES PMOVES-BoTZ community The hugging-face-dataset-creator skill provides tools for managing datasets on the Hugging Face Hub, focusing on creation, configuration, and content management. It benefits developers and data scientists working with Hugging Face datasets. Hugging Face 数据集创建工具提供数据集创建、配置和内容管理的功能，补充了 Hugging Face MCP 服务器的功能 Hugging Face データセット作成ツールは、データセットの作成、構成、コンテンツ管理機能を提供し、Hugging Face MCP サーバーの機能を補完する Hugging Face 데이터셋 생성 도구는 데이터셋 생성, 구성, 콘텐츠 관리 기능을 제공하여 Hugging Face MCP 서버의 기능을 보완합니다 Hugging Face Dataset Creator es una habilidad que proporciona herramientas para gestionar datasets en Hugging Face Hub, con enfoque en creación, configuración y gestión de contenido. Hugging Face Dataset Creator est une compétence qui fournit des outils pour gérer des datasets sur Hugging Face Hub, avec un focus sur la création, la configuration et la gestion de contenu. Hugging Face Dataset Creator ist eine Fähigkeit, die Tools zur Verwaltung von Datensätzen im Hugging Face Hub bereitstellt, mit Fokus auf Erstellung, Konfiguration und Inhaltsverwaltung. O hugging-face-dataset-creator é uma ferramenta para gerenciar conjuntos de dados no Hugging Face Hub, com foco em criação, configuração e gerenciamento de conteúdo hugging-face-dataset-creator - это инструмент для управления наборами данных на Hugging Face Hub, с фокусом на создании, конфигурации и управлении контентом hugging-face-dataset-creator هو أداة لإدارة مجموعات البيانات على منصة Hugging Face Hub مع التركيز على إنشاء وتفضيل المحتوى how to use hugging-face-dataset-creator hugging-face-dataset-creator setup guide hugging-face-dataset-creator alternative hugging-face-dataset-creator vs HF MCP Server hugging-face-dataset-creator install managing datasets on Hugging Face Hub Hugging Face 数据集创建工具 AI 工具 数据集管理 内容管理 Hugging Face MCP 服务器 数据集编辑 Python CLI Provides dataset creation capabilities Offers content editing and configuration management Complements the existing Hugging Face MCP server Enables dataset discovery, search, and metadata retrieval via HF MCP Server Supports structuring and organizing datasets on the Hugging Face Hub hugging-face-dataset-creator is a skill designed to manage datasets on the Hugging Face Hub, providing capabilities for dataset creation, editing, and configuration management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shynlee04/idumb-v2/agent-architect', 'community', 'shynlee04', 'idumb-v2', 'shynlee04/idumb-v2', 'agent-architect', 0, 0, 60, '2026-03-08T01:57:15.621Z', '2026-03-08T02:13:30.907Z', '136aea6f6d264ae1b7fd82ba124657a3fb9995f9fc1faa868dbbd87bb87343c7', '{"id":"shynlee04/idumb-v2/agent-architect","name":"agent-architect","description":{"en":"The agent-architect skill enables users to create and refine open-code agents through a guided Q&A process, allowing for tailored agent development. It benefits developers seeking to build customized AI agents.","zh":"Agent Architect是一个构建和完善开源代码AI代理的工具，通过对话式的配置和创建来实现用户需求","ja":"Agent Architectは、オープンソースのAIエージェントを構築して完善するためのツールで、対話式の構成と作成を実現する","ko":"Agent Architect는 오픈소스 AI 에이전트를 구축하고 완善하는 도구로, 대화형 구성과 생성을 통해 사용자需求을 충족합니다","es":"Agent Architect es una herramienta que permite crear y refinar agentes de código abierto a través de un proceso de preguntas y respuestas guiado. El enfoque es conversacional, no transaccional","fr":"Agent Architect est un outil qui permet de créer et d''affiner des agents open source via un processus de Q&R guidé. L''approche est conversationnelle, et non transactionnelle","de":"Agent Architect ist ein Tool, mit dem Sie Open-Source-Agents erstellen und verfeinern können, indem Sie einen guidierten Q&A-Prozess durchlaufen. Der Ansatz ist konversationell, nicht transaktional","pt":"O Agent Architect é uma ferramenta de inteligência artificial que permite criar agentes personalizados através de um processo de perguntas e respostas guiado.","ru":"Agent Architect - это инструмент ИИ, который позволяет создавать индивидуальных агентов через проводимый процесс вопросов и ответов.","ar":"معماري الوكيل هو أداة ذكاء اصطناعي تمكن من إنشاء عملاء مخصصين من خلال عملية أسئلة وأجوبة موجهة."},"seo":{"title":{"en":"agent-architect: Guided Q&A Agent Creation | AI Agent Skill","zh":"AIエージェント构建指南 - Agent Architect","ja":"AIエージェントの作成 - Agent Architectベストプラクティス","ko":"AI 에이전트 아키텍트 설정 가이드 - Agent Architect","es":"Guía de configuración de Agentes de Inteligencia Artifici...","fr":"Guide de démarrage rapide pour les Agents d''Intelligence ...","de":"Einrichtungsleitfaden für KI-Agents mit Agent Architect","pt":"Guia de Configuração do Agent Architect: Crie Agente de I...","ru":"ИИ Агенты: Настройка Agent Architect для Оптимальной Работы","ar":"دليل إنشاء وتنقيح العميل الذكي: معماري الوكيل"},"description":{"en":"Discover how agent-architect simplifies AI agent development with conversational creation and refinement - start building your custom agents today!","zh":"通过Agent Architect构建和完善开源代码AI代理，实现对话式的配置和创建","ja":"Agent Architectを使用して、対話式の構成と作成でオープンソースのAIエージェントを構築して完善する","ko":"Agent Architect를 사용하여 대화형 구성과 생성으로 오픈소스 AI 에이전트를 구축하고完善하십시오","es":"Crea y refina agentes de código abierto a través de un proceso de preguntas y respuestas guiado con Agent Architect. Aprende a configurar agentes de IA de ma...","fr":"Créez et affinez des agents open source via un processus de Q&R guidé avec Agent Architect. Découvrez comment configurer des agents d''IA de manière conversat...","de":"Erstellen und verfeinern Sie Open-Source-Agents mithilfe eines guidierten Q&A-Prozesses mit Agent Architect. Erfahren Sie, wie Sie KI-Agents konversationell ...","pt":"Descubra como criar agentes personalizados com o Agent Architect, uma ferramenta de inteligência artificial que oferece uma abordagem conversacional para con...","ru":"Узнайте, как создать индивидуальных агентов с помощью Agent Architect, ИИ инструмента, который обеспечивает разговорный подход к настройке","ar":"اكتشف كيفية إنشاء عملاء مخصصين باستخدام معماري الوكيل، أداة ذكاء اصطناعي تقدم نهجًا محادثيًا لضبط الإعدادات"},"definition":{"en":"agent-architect is a skill that facilitates the creation and refinement of open-code agents using a conversational, guided Q&A approach.","zh":"Agent Architect是一种AI代理构建工具，实现对话式配置和创建","ja":"Agent Architectは、対話式の構成と作成を実現するAIエージェント構築ツール","ko":"Agent Architect는 대화형 구성과 생성을 통해 AI 에이전트를 구축하는 도구입니다","es":"Agent Architect es una herramienta de creación de agentes de Inteligencia Artificial que utiliza un enfoque conversacional para configurar agentes personalizados","fr":"Agent Architect est un outil de création d''agents d''Intelligence Artificielle qui utilise une approche conversationnelle pour configurer des agents personnalisés","de":"Agent Architect ist ein Tool zur Erstellung von KI-Agents, das einen konversationellen Ansatz zur Konfiguration von benutzerdefinierten Agents verwendet","pt":"O que é Agent Architect? É uma ferramenta de inteligência artificial para criar agentes personalizados.","ru":"Что такое Agent Architect? Это инструмент ИИ для создания индивидуальных агентов.","ar":"ما هو معماري الوكيل؟ هو أداة ذكاء اصطناعي لإنشاء عملاء مخصصين."},"features":{"en":["Conversational agent creation through a guided Q&A process","Supports broad questions with iterative drilling into details","Allows users to skip unnecessary configuration options","Provides drafts and iterates based on user feedback","Enables the creation of customized agents fitting specific user needs"],"zh":["对话式配置","开源代码AI代理构建","用户反馈迭代","广泛的配置选项","可跳过不必要的配置","实时草稿展示"],"ja":["対話式の構成","オープンソースのAIエージェント構築","ユーザーフィードバックによる反復","広範な構成オプション","不要な構成をスキップ可能","リアルタイムの草稿表示"],"ko":["대화형 구성","오픈소스 AI 에이전트 구축","사용자 피드백 반복","넓은 구성 옵션","필요 없는 구성 건너뛰기","실시간 초안 표시"],"es":["Creación de agentes de código abierto a través de un proceso de preguntas y respuestas guiado","Enfoque conversacional, no transaccional, para la configuración de agentes","Permite a los usuarios omitir la configuración que no les interesa","Muestra borradores y itera en función de la retroalimentación del usuario","Inicia con preguntas generales y se enfoca en detalles solo si es necesario"],"fr":["Création d''agents open source via un processus de Q&R guidé","Approche conversationnelle, et non transactionnelle, pour la configuration des agents","Permet aux utilisateurs de sauter la configuration qui ne les intéresse pas","Affiche des brouillons et itère en fonction de la rétroaction de l''utilisateur","Commence par des questions générales et se concentre sur les détails seulement si nécessaire"],"de":["Erstellung von Open-Source-Agents mithilfe eines guidierten Q&A-Prozesses","Konversationeller Ansatz, nicht transaktional, für die Konfiguration von Agents","Ermöglicht es Benutzern, die Konfiguration zu überspringen, die sie nicht interessiert","Zeigt Entwürfe an und iteriert auf der Grundlage der Benutzerfeedback","Beginnt mit allgemeinen Fragen und konzentriert sich auf Details nur wenn erforderlich"],"pt":["Abordagem conversacional para configuração","Perguntas amplas que se aprofundam em detalhes apenas quando necessário","Opção de pular configurações não desejadas","Exibição de rascunhos e iteração com base em feedback"],"ru":["Разговорный подход к настройке","Широкие вопросы, которые углубляются в детали только при необходимости","Возможность пропустить ненужные настройки","Показ черновиков и итерация на основе обратной связи"],"ar":["نهج محادثي لضبط الإعدادات","أسئلة واسعة تتعمق في التفاصيل فقط عند الحاجة","خيار تخطي الإعدادات غير المرغوب فيها","عرض المسودات وتنقيحها بناءً على التغذية الراجعة"]},"keywords":{"en":["how to use agent-architect","what is agent-architect","agent-architect alternative","agent-architect vs other AI agents","agent-architect setup guide","agent-architect install","guided Q&A agent development","custom AI agent creation","open-code agent refinement"],"zh":["AIエージェント","Agent Architect","开源代码AI代理","对话式配置","用户反馈迭代","AI工具","AI代理构建","开源AI代理","对话式AI构建"],"ja":["AIエージェント","Agent Architect","オープンソースのAIエージェント","対話式の構成","ユーザーフィードバックによる反復","AIツール","AIエージェント構築","オープンソースのAIエージェント","対話式のAI構築"],"ko":["AI 에이전트","Agent Architect","오픈소스 AI 에이전트","대화형 구성","사용자 피드백 반복","AI 도구","AI 에이전트 구축","오픈소스 AI 에이전트","대화형 AI 구축"],"es":["Agentes de Inteligencia Artificial","creación de agentes","configuración de agentes","proceso de preguntas y respuestas","enfoque conversacional","agentes de código abierto","herramientas de IA","desarrollo de agentes"],"fr":["Agents d''Intelligence Artificielle","création d''agents","configuration d''agents","processus de Q&R","approche conversationnelle","agents open source","outils d''IA","développement d''agents"],"de":["KI-Agents","Erstellung von Agents","Konfiguration von Agents","Q&A-Prozess","konversationeller Ansatz","Open-Source-Agents","KI-Tools","Entwicklung von Agents"],"pt":["agentes de inteligência artificial","ferramentas de ia","configuração de agentes","desenvolvimento de agentes","ia para desenvolvedores","agent architect"],"ru":["ИИ агенты","инструменты ИИ","настройка агентов","разработка агентов","ИИ для разработчиков","agent architect"],"ar":["عملاء الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","ضبط الإعدادات للعملاء","تنمية العملاء","الذكاء الاصطناعي للمطورين","معماري الوكيل"]}},"owner":"shynlee04","repo":"idumb-v2","repoPath":"shynlee04/idumb-v2","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.621Z","topics":[],"category":"community","skillMd":{"name":"agent-architect","description":"|-","bodyPreview":"# Agent Architect\n\nCreate and refine opencode agents through a guided Q&A process.\n\n<core_approach>\n\n**Agent creation is conversational, not transactional.**\n\n- MUST NOT assume what the user wants—ask\n- SHOULD start with broad questions, drill into details only if needed\n- Users MAY skip configuration they don''t care about\n- MUST always show drafts and iterate based on feedback\n\nThe goal is to help users create agents that fit their needs, not to dump every possible configuration option on them.","body":"# Agent Architect\n\nCreate and refine opencode agents through a guided Q&A process.\n\n<core_approach>\n\n**Agent creation is conversational, not transactional.**\n\n- MUST NOT assume what the user wants—ask\n- SHOULD start with broad questions, drill into details only if needed\n- Users MAY skip configuration they don''t care about\n- MUST always show drafts and iterate based on feedback\n\nThe goal is to help users create agents that fit their needs, not to dump every possible configuration option on them.\n\n</core_approach>\n\n<question_tool>\n\n**Batching:** Use the `question` tool for 2+ related questions. Single questions → plain text.\n\n**Syntax:** `header` ≤12 chars, `label` 1-5 words, add \"(Recommended)\" to default.\n\n**CRITICAL Permission Logic:**\n- You MUST ask the user about permissions explicitly.\n- If user selects \"Standard/Default\" or \"No extra\", do NOT list `bash`, `read`, `write`, `edit` permissions. Rely on system defaults.\n- Only add explicit permission blocks for tools when the user requests NON-STANDARD access (e.g., restrictive, or specific allows).\n- **EXCEPTION:** Skills MUST ALWAYS be configured with `\"*\": \"deny\"` and explicit allows, regardless of tool permissions.\n\n</question_tool>\n\n<reference>\n\n## Agent Locations\n\n| Scope | Path |\n|-------|------|\n| Project | `.opencode/agent/<name>.md` |\n| Global | `~/.config/opencode/agent/<name>.md` |\n\n## Agent File Format\n\n```yaml\n---\ndescription: When to use this agent. Include trigger examples.\nmodel: anthropic/claude-sonnet-4-20250514  # Optional\nmode: subagent                   # Optional (defaults to undefined/standard)\npermission:\n  skill: { \"*\": \"deny\", \"my-skill\": \"allow\" }\n  bash: { \"*\": \"ask\", \"git *\": \"allow\" }\n---\nSystem prompt in markdown body (second person).\n```\n\n**Full schema:** See `references/opencode-config.md`\n\n## Agent Modes\n\n| Mode | Description |\n|------|-------------|\n| `(undefined)` | Standard agent, visible to user and tools (Default) |\n| `subagent` | specialized task tool agent, hidden from main list |\n\n</reference>\n\n<workflow>\n\n## Phase 1: Core Purpose (Required)\n\nAsk these first—they shape everything else:\n\n1. **\"What should this agent do?\"**\n   - Get the core task/domain\n   - Examples: \"review code\", \"help with deployments\", \"research topics\"\n\n2. **\"What should trigger this agent?\"**\n   - Specific phrases, contexts, file types\n   - Becomes the `description` field\n\n3. **\"What expertise/persona should it have?\"**\n   - Tone, boundaries, specialization\n   - Shapes the system prompt\n\n## Phase 1.5: Research the Domain\n\n**MUST NOT assume knowledge is current.** After understanding the broad strokes:\n\n- Search for current best practices in the domain\n- Check for updates to frameworks, tools, or APIs the agent will work with\n- Look up documentation for any unfamiliar technologies mentioned\n- Find examples of how experts approach similar tasks\n\nThis research informs better questions in Phase 2 and produces a more capable agent.\n\n**Example:** User wants an agent for \"Next.js deployments\" → Research current Next.js deployment patterns, Vercel vs self-hosted, App Router vs Pages Router, common pitfalls, etc.\n\n## Phase 2: Capabilities (Ask broadly, then drill down)\n\n4. **\"What permissions does this agent need?\"** (Use Question Tool)\n   - Options: \"Standard (Recommended)\", \"Read-Only\", \"Full Access\", \"Custom\"\n   - **Standard**: Do NOT add `bash`, `read`, `write`, `edit` to config. Rely on defaults.\n   - **Read-Only**: Explicitly deny write/edit/bash.\n   - **Full Access**: Allow bash `*` if needed.\n   - **Custom**: Ask specific follow-ups.\n\n5. **\"Should this agent use any skills?\"**\n   - If yes: \"Which ones?\"\n   - ALWAYS configure `permission.skill` with `\"*\": \"deny\"` and explicit allows.\n   - This applies even if other permissions are standard.\n\n6. **\"Is this a subagent?\"**\n   - If yes: set `mode: subagent`\n   - If no: leave `mode` undefined (standard)\n\n## Phase 3: Details (Optional—user MAY skip)\n\n7. **\"Any specific model preference?\"** (most users skip)\n8. **\"Custom temperature/sampling?\"** (most users skip)\n9. **\"Maximum steps before stopping?\"** (most users skip)\n\n## Phase 4: Review & Refine\n\n10. **Show the draft config and prompt, ask for feedback**\n    - \"Here''s what I''ve created. Anything you''d like to change?\"\n    - Iterate until user is satisfied\n\n**Key principle:** Start broad, get specific only where the user shows interest. MUST NOT overwhelm with options like `top_p` unless asked.\n\n**Be flexible:** If the user provides lots of info upfront, adapt—MUST NOT rigidly follow the phases. If they say \"I want a code review agent that can''t run shell commands\", you already have answers to multiple questions.\n\n</workflow>\n\n<system_prompt_structure>\n\n## Recommended Structure\n\n ```markdown\n# Role and Objective\n[Agent purpose and scope]\n\n# Instructions\n- Core behavioral rules\n- What to always/never do\n\n## Sub-instructions (optional)\nMore detailed guidance for specific areas.\n\n# Workflow\n1. First, [step]\n2. Then, [step]\n3. Finally, [step]\n\n# Output Format\nSpecify exact format expected.\n\n# Examples (optional)\n<examples>\n<example>\n<input>User request</input>\n<output>Expected response</output>\n</example>\n</examples>\n```\n\n## XML Tags (Recommended)\n\nXML tags improve clarity and parseability across all models:\n\n| Tag | Purpose |\n|-----|---------|\n| `<instructions>` | Core behavioral rules |\n| `<context>` | Background information |\n| `<examples>` | Few-shot demonstrations |\n| `<thinking>` | Chain-of-thought reasoning |\n| `<output>` | Final response format |\n\n**Best practices:**\n- Be consistent with tag names throughout\n- Nest tags for hierarchy: `<outer><inner></inner></outer>`\n- Reference tags in instructions: \"Using the data in `<context>` tags...\"\n\n**Example:**\n```xml\n<instructions>\n1. Analyze the code in <code> tags\n2. List issues in <findings> tags\n3. Suggest fixes in <recommendations> tags\n</instructions>\n```\n\n## Description Field (Critical)\n\nThe `description` determines when the agent triggers.\n\n**Primary Agents**: Keep it extremely concise (PRECISELY 3 words). The user selects these manually or via very clear intent.\n**Any Other Agents**: Must be specific and exhaustive to ensure correct routing by the task tool.\n**Template (Any Other Agents)**: `[Role/Action]. Use when [triggers]. Examples: - user: \"trigger\" -> action`\n\n**Good (Primary)**:\n```\nCode review expert.\n```\n\n**Good (Any Other Agents)**:\n```\nCode review specialist. Use when user says \"review this PR\", \"check my code\", \n\"find bugs\".\n\nExamples:\n- user: \"review\" -> check code\n- user: \"scan\" -> check code\n```\n\n## Prompt Altitude\n\nFind the balance between too rigid and too vague:\n\n| ❌ Too Rigid | ✅ Right Altitude | ❌ Too Vague |\n|-------------|-------------------|-------------|\n| Hardcoded if-else logic | Clear heuristics + flexibility | \"Be helpful\" |\n| \"If X then always Y\" | \"Generally prefer X, but use judgment\" | No guidance |\n\n</system_prompt_structure>\n\n<agentic_components>\n\nFor agents that use tools in a loop, SHOULD include these reminders:\n\n```markdown\n# Persistence\nKeep working until the user''s request is fully resolved. Only yield \ncontrol when you''re confident the task is complete.\n\n# Tool Usage  \nIf unsure about something, use tools to gather information. \nDo NOT guess or make up answers.\n\n# Planning (optional)\nThink step-by-step before each action. Reflect on results before \nproceeding.\n```\n\n</agentic_components>\n\n<permissions>\n\nControl what agents can access.\n\n**CRITICAL: Avoid Overengineering**\n- Do NOT list permissions for standard tools (`read`, `write`, `edit`, `bash`) unless the user explicitly asks for restrictions or non-standard access.\n- Rely on system defaults for most agents.\n- **Skills are the exception**: You MUST always configure `permission.skill` to whitelist specific skills and deny others.\n\n```yaml\n# Standard Agent (minimal config)\npermission:\n  skill:\n    \"*\": \"deny\"\n    \"my-skill\": \"allow\"\n\n# Restricted Agent (explicit config)\npermission:\n  edit: \"ask\"\n  bash:\n    \"*\": \"deny\"\n  skill:\n    \"*\": \"deny\"\n```\n\n**Full reference:** See `references/opencode-config.md`\n\n## Legacy Configuration\n\nAgents may occasionally work on legacy projects using outdated frontmatter (e.g., `tools:`, `maxSteps:`). You MUST correct these to the modern `permission:` and `steps:` fields when encountered.\n\n</permissions>\n\n<enhancement_workflow>\n\nWhen improving an agent, diagnose through questions:\n\n1. **\"What''s not working well?\"** — Get specific symptoms\n2. **\"Can you show me an example where it failed?\"** — Understand the gap\n3. **\"What should it have done instead?\"** — Define success\n\nThen propose targeted fixes:\n\n| Symptom | Likely Cause | Fix |\n|---------|--------------|-----|\n| Triggers too often | Description too broad | Add specific contexts |\n| Misses triggers | Description too narrow | Add trigger phrases |\n| Wrong outputs | Prompt ambiguous | Add explicit instructions |\n| Executes dangerous commands | Loose bash permissions | Restrict with patterns |\n| Uses wrong skills | No skill restrictions | Configure `permission.skill` |\n\nMUST show proposed changes and ask for confirmation before applying.\n\n</enhancement_workflow>\n\n<examples>\n\n## Restricted Code Review Agent\n\n```yaml\n---\ndescription: Safe code reviewer.\nmode: primary\npermission:\n  edit: \"ask\"\n  bash: \"deny\"\n  write: \"deny\"\n  external_directory: \"deny\"\n---\nYou are a code review specialist. Analyze code for bugs, security issues,\nand improvements. Never modify files directly.\n```\n\n## Deployment Agent (Any Other Agents)\n\n```yaml\n---\ndescription: |-\n  Deployment helper. Use when user says \"deploy to staging\", \"push to prod\", \n  \"release version\".\n  \n  Examples:\n  - user: \"deploy\" -> run deployment\n  - user: \"release\" -> run deployment\nmode: subagent\npermission:\n  bash:\n    \"*\": \"deny\"\n    \"git *\": \"allow\"\n    \"npm run build\": \"allow\"\n    \"npm run deploy:*\": \"ask\"\n  skill:\n    \"*\": \"deny\"\n    \"deploy-checklist\": \"allow\"\n---\nYou are a deployment specialist...\n```\n\n</examples>\n\n<quality_checklist>\n\nBefore showing the final agent to the user:\n\n- [ ] Asked about core purpose and triggers\n- [ ] Researched the domain (MUST NOT assume knowledge is current)\n- [ ] `description` has concrete trigger examples\n- [ ] `mode` discussed and set appropriately\n- [ ] System prompt uses second person\n- [ ] Asked about tool/permission needs (MUST NOT assume)\n- [ ] Output format is specified if relevant\n- [ ] Showed draft to user and got feedback\n- [ ] User confirmed they''re happy with result\n\n</quality_checklist>\n\n## References\n\n- `references/agent-patterns.md` - Design patterns and prompt engineering\n- `references/opencode-config.md` - Full frontmatter schema, tools, permissions\n"},"lastSynced":"2026-03-08T02:13:30.907Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing customized open-code development through conversational Q&A processes.","zh":"非常适合需要通过对话式 Q&A 过程进行定制开源代码开发的 AI Agents。","ja":"会話式 Q&A プロセスを通じてカスタマイズされたオープンソースコード開発を必要とする AI エージェントに最適です。","ko":"대화형 Q&A 프로세스를 통해 사용자 지정 오픈 소스 코드 개발이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de IA que necesitan un desarrollo de código abierto personalizado a través de procesos de preguntas y respuestas conversacionales.","fr":"Parfait pour les agents IA ayant besoin d''un développement de code ouvert personnalisé via des processus de questions et réponses conversationnels.","de":"Perfekt für KI-Agents, die ein benutzerdefiniertes Open-Code-Entwicklung durch konversationale Q&A-Prozesse benötigen.","pt":"Perfeito para Agentes de IA que precisam de desenvolvimento de código aberto personalizado por meio de processos de Q&A conversacionais.","ru":"Идеально для агентов ИИ, которым требуется индивидуальное развитие открытого кода через разговорные процессы вопросов и ответов.","ar":"مثالي لعميل الذكاء الاصطناعي الذين يحتاجون إلى تطوير برمجي مفتوح مخصص من خلال عمليات أسئلة وأجوبة محادثية."},"recommendation":{"en":"Empowers agents to create and refine tailored open-code agents using a guided Q&A approach, enabling iterative development based on user feedback and draft reviews, leveraging conversational configuration and flexible user input.","zh":"赋予代理创建和改进定制的开源代码代理的能力，使用引导式 Q&A 方法，能够基于用户反馈和草稿审查实现迭代开发，利用对话式配置和灵活的用户输入。","ja":"カスタマイズされたオープンソースコードエージェントを作成および改良するためのエージェントを可能にし、ガイド付き Q&A アプローチを使用して、ユーザーのフィードバックと下書きのレビューに基づいて開発を繰り返し行い、会話形式の構成と柔軟なユーザー入力を活用します。","ko":"사용자 피드백과 초안 검토를 기반으로 반복 개발을 가능하게 하는 대화형 Q&A 접근 방식을 사용하여 사용자 지정된 오픈 소스 코드 에이전트를 만들고 개선할 수 있는 에이전트를 가능하게 합니다. 대화형 구성과 유연한 사용자 입력을 활용합니다.","es":"Habilita a los agentes a crear y perfeccionar agentes de código abierto personalizados utilizando un enfoque guiado de preguntas y respuestas, lo que permite un desarrollo iterativo basado en la retroalimentación del usuario y las revisiones de borradores, aprovechando la configuración conversacional y la entrada flexible del usuario.","fr":"Permet aux agents de créer et d''affiner des agents de code ouvert personnalisés en utilisant une approche guidée de questions et réponses, ce qui permet un développement itératif basé sur les commentaires des utilisateurs et les examens de brouillons, en exploitant la configuration conversationnelle et la saisie flexible de l''utilisateur.","de":"Ermächtigt Agents, maßgeschneiderte Open-Code-Agents unter Verwendung eines geleiteten Q&A-Ansatzes zu erstellen und zu verfeinern, was eine iterative Entwicklung auf der Grundlage von Benutzerfeedback und Entwurfsüberprüfungen ermöglicht, die konversationale Konfiguration und flexible Benutzereingaben nutzt.","pt":"Habilita os agentes a criarem e aperfeiçoarem agentes de código aberto personalizados usando uma abordagem de Q&A guiada, permitindo o desenvolvimento iterativo com base em feedback do usuário e revisões de rascunho, aproveitando a configuração conversacional e a entrada flexível do usuário.","ru":"Позволяет агентам создавать и совершенствовать индивидуальных агентов с открытым кодом, используя руководимый подход вопросов и ответов, обеспечивая итеративное развитие на основе обратной связи пользователей и обзоров черновиков, используя разговорную конфигурацию и гибкий ввод пользователя.","ar":"تمكين الوكلاء من إنشاء و tinhاء وتطوير عميل مفتوح مخصص باستخدام نهج إرشادي لأسئلة وأجوبة، وتمكين التطوير التكراري بناءً على ملاحظات المستخدم ومراجعة المسودات، واستخدام التكوين المحادثي ومدخلات المستخدم المرنة."},"useCases":{"en":["Creating customized AI agents through interactive Q&A sessions","Refining open-code agents based on user feedback and draft iterations","Developing tailored agent configurations without assuming user requirements"],"zh":["通过交互式 Q&A 会话创建自定义 AI 代理","基于用户反馈和草稿迭代来改进开源代码代理","在不假设用户需求的情况下开发定制的代理配置"],"ja":["インタラクティブな Q&A セッションを通じてカスタマイズされた AI エージェントを作成する","ユーザーのフィードバックと下書きの反復に基づいてオープンソースコードエージェントを改良する","ユーザーの要件を仮定せずにカスタマイズされたエージェント構成を開発する"],"ko":["대화형 Q&A 세션을 통해 사용자 지정 AI 에이전트を作成한다","사용자의 피드백과 초안 반복에 따라 오픈 소스 코드 에이전트를 개선한다","사용자의 요구 사항을 가정하지 않고 사용자 지정 에이전트 구성 개발"],"es":["Crear agentes de IA personalizados a través de sesiones de preguntas y respuestas interactivas","Perfeccionar agentes de código abierto basados en la retroalimentación del usuario y las iteraciones de borradores","Desarrollar configuraciones de agentes personalizadas sin suponer los requisitos del usuario"],"fr":["Créer des agents IA personnalisés via des sessions de questions et réponses interactives","Affiner des agents de code ouvert basés sur les commentaires des utilisateurs et les itérations de brouillons","Développer des configurations d''agents personnalisées sans supposer les exigences de l''utilisateur"],"de":["Erstellen von maßgeschneiderten KI-Agents durch interaktive Q&A-Sitzungen","Verfeinern von Open-Code-Agents basierend auf Benutzerfeedback und Entwurfsiterationen","Entwickeln von maßgeschneiderten Agentenkonfigurationen ohne Annahme von Benutzeranforderungen"],"pt":["Criação de agentes de IA personalizados por meio de sessões interativas de Q&A","Aperfeiçoamento de agentes de código aberto com base em feedback do usuário e iterações de rascunho","Desenvolvimento de configurações de agente personalizadas sem supor requisitos do usuário"],"ru":["Создание индивидуальных агентов ИИ через интерактивные сессии вопросов и ответов","Усовершенствование агентов с открытым кодом на основе обратной связи пользователей и итераций черновиков","Разработка индивидуальных конфигураций агентов без предположения требований пользователя"],"ar":["إنشاء عميل ذكاء اصطناعي مخصص من خلال جلسات محادثية تفاعلية لأسئلة وأجوبة","تحسين عميل برمجي مفتوح بناءً على ملاحظات المستخدم ومراجعة المسودات","تطوير تكوينات عميل مخصص دون افتراض متطلبات المستخدم"]},"limitations":{"en":["Requires user engagement in the Q&A process","Might necessitate iterative refinement based on user feedback","Should start with broad questions and drill into details only as needed"],"zh":["需要用户在 Q&A 过程中参与","可能需要根据用户反馈进行迭代改进","应该从广泛的问题开始，只有在需要时才深入细节"],"ja":["Q&A プロセスにユーザーの関与が必要","ユーザーのフィードバックに基づいて反復改良が必要となる可能性がある","広範な質問から始めて、必要な場合のみ詳細に深入する"],"ko":["Q&A 과정에서 사용자의 참여가 필요함","사용자의 피드백에 따라 반복적인 개선이 필요할 수 있음","넓은 질문으로 시작하여 필요할 때만 세부 사항으로 들어감"],"es":["Requiere la participación del usuario en el proceso de preguntas y respuestas","Puede necesitar un perfeccionamiento iterativo basado en la retroalimentación del usuario","Debería comenzar con preguntas generales y profundizar en los detalles solo según sea necesario"],"fr":["Nécessite la participation de l''utilisateur dans le processus de questions et réponses","Peut nécessiter un affinement itératif basé sur les commentaires des utilisateurs","Devrait commencer par des questions générales et ne s''intéresser aux détails que si nécessaire"],"de":["Benutzerbeteiligung im Q&A-Prozess erforderlich","Kann iteratives Verfeinern auf der Grundlage von Benutzerfeedback erfordern","Sollte mit allgemeinen Fragen beginnen und sich nur bei Bedarf auf Details einlassen"],"pt":["Exige engajamento do usuário no processo de Q&A","Pode necessitar de aperfeiçoamento iterativo com base em feedback do usuário","Deve começar com perguntas amplas e penetrar nos detalhes apenas quando necessário"],"ru":["Требует участия пользователя в процессе вопросов и ответов","Может потребовать итеративного усовершенствования на основе обратной связи пользователей","Должен начинаться с широких вопросов и углубляться в детали только по мере необходимости"],"ar":["يتطلب مشاركة المستخدم في عملية أسئلة وأجوبة","قد يحتاج إلى تحسين تكراري بناءً على ملاحظات المستخدم","يجب أن يبدأ بسؤال واسع ويتعمق في التفاصيل فقط عند الحاجة"]},"version":4},"contentHash":"136aea6f6d264ae1b7fd82ba124657a3fb9995f9fc1faa868dbbd87bb87343c7","qualityScore":60}');
