INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shynlee04/idumb-v2/agent-architect', 'agent-architect', 'shynlee04', 'idumb-v2', 'community', 'agent-architect shynlee04 idumb-v2 community The agent-architect skill enables users to create and refine open-code agents through a guided Q&A process, allowing for tailored agent development. It benefits developers seeking to build customized AI agents. Agent Architect是一个构建和完善开源代码AI代理的工具，通过对话式的配置和创建来实现用户需求 Agent Architectは、オープンソースのAIエージェントを構築して完善するためのツールで、対話式の構成と作成を実現する Agent Architect는 오픈소스 AI 에이전트를 구축하고 완善하는 도구로, 대화형 구성과 생성을 통해 사용자需求을 충족합니다 Agent Architect es una herramienta que permite crear y refinar agentes de código abierto a través de un proceso de preguntas y respuestas guiado. El enfoque es conversacional, no transaccional Agent Architect est un outil qui permet de créer et d''affiner des agents open source via un processus de Q&R guidé. L''approche est conversationnelle, et non transactionnelle Agent Architect ist ein Tool, mit dem Sie Open-Source-Agents erstellen und verfeinern können, indem Sie einen guidierten Q&A-Prozess durchlaufen. Der Ansatz ist konversationell, nicht transaktional O Agent Architect é uma ferramenta de inteligência artificial que permite criar agentes personalizados através de um processo de perguntas e respostas guiado. Agent Architect - это инструмент ИИ, который позволяет создавать индивидуальных агентов через проводимый процесс вопросов и ответов. معماري الوكيل هو أداة ذكاء اصطناعي تمكن من إنشاء عملاء مخصصين من خلال عملية أسئلة وأجوبة موجهة. how to use agent-architect what is agent-architect agent-architect alternative agent-architect vs other AI agents agent-architect setup guide agent-architect install guided Q&A agent development custom AI agent creation open-code agent refinement AIエージェント Agent Architect 开源代码AI代理 对话式配置 用户反馈迭代 AI工具 AI代理构建 开源AI代理 对话式AI构建 Conversational agent creation through a guided Q&A process Supports broad questions with iterative drilling into details Allows users to skip unnecessary configuration options Provides drafts and iterates based on user feedback Enables the creation of customized agents fitting specific user needs agent-architect is a skill that facilitates the creation and refinement of open-code agents using a conversational, guided Q&A approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nguyendinhquocx/code-ai/nx-workspace-patterns', 'community', 'nguyendinhquocx', 'code-ai', 'nguyendinhquocx/code-ai', 'nx-workspace-patterns', 0, 0, 60, '2026-03-08T01:57:15.635Z', '2026-03-08T02:13:37.067Z', '6286fae01303804282fedd8b858cd8312e0637126abe6b8f3d01eab19e9777a0', '{"id":"nguyendinhquocx/code-ai/nx-workspace-patterns","name":"nx-workspace-patterns","description":{"en":"The nx-workspace-patterns skill provides production patterns for Nx monorepo management, benefiting developers setting up new workspaces, configuring project boundaries, and optimizing CI/CD pipelines.","zh":"Nx 工作空间模式提供了一种优化 Nx 项目管理的方法，通过设置项目边界、CI 优化和依赖管理来提高开发效率","ja":"Nx ワークスペースパターンは、プロジェクト境界、CI 最適化、依存関係管理を設定することで、Nx プロジェクト管理を最適化する方法を提供します","ko":"Nx 작업공간 패턴은 프로젝트 경계, CI 최적화, 의존성 관리를 설정하여 Nx 프로젝트 관리를 최적화하는 방법을 제공합니다","es":"nx-workspace-patterns es un conjunto de patrones de producción para la administración de monorepo con Nx. Ayuda a configurar y optimizar tu entorno de desarrollo.","fr":"nx-workspace-patterns est un ensemble de modèles de production pour la gestion de monorepo avec Nx. Il aide à configurer et optimiser votre environnement de développement.","de":"nx-workspace-patterns ist eine Sammlung von Produktionsmustern für die Verwaltung von Monorepo mit Nx. Es hilft bei der Konfiguration und Optimierung Ihrer Entwicklungsumgebung.","pt":"O Nx Workspace Patterns é um conjunto de padrões para gerenciar monorepos com o Nx. Aprenda a configurar e otimizar seu workspace.","ru":"Шаблоны рабочего пространства Nx - это набор шаблонов для управления монорепозиториями с помощью Nx. Узнайте, как настроить и оптимизировать ваше рабочее пространство.","ar":"أنماط مساحة العمل Nx هو مجموعة من الأنماط لتدارة مستودعات الموحدة مع Nx. تعرف على كيفية ضبط وتحسين مساحة العمل الخاصة بك"},"seo":{"title":{"en":"nx-workspace-patterns: Nx Monorepo Management Setup Guide...","zh":"Nx 工作空间模式设置指南 - 优化 Nx 项目管理","ja":"Nx ワークスペースパターン設定ガイド - AIエージェントによるプロジェクト管理最適化","ko":"Nx 작업공간 패턴 설정 가이드 - 개발자 위한 Nx 프로젝트 최적화","es":"Guía de Configuración de nx-workspace-patterns para Admin...","fr":"nx-workspace-patterns : Meilleures Pratiques pour la Gest...","de":"Einrichtungsleitfaden für nx-workspace-patterns zur Monor...","pt":"Guia de Configuração do Nx Workspace Patterns","ru":"Настройка шаблонов рабочего пространства Nx: ИИ Агенты","ar":"دليل إعداد أنماط مساحة العمل Nx"},"description":{"en":"Discover how to optimize your Nx workspace with production-ready patterns. Learn to configure project boundaries, implement remote caching, and more. Get sta...","zh":"学习 Nx 工作空间模式，优化 Nx 项目管理，提高开发效率。了解 Nx 架构、项目边界、CI 优化等","ja":"Nx ワークスペースパターンを学び、Nx プロジェクト管理を最適化して開発効率を向上させます。Nx アーキテクチャ、プロジェクト境界、CI 最適化など","ko":"Nx 작업공간 패턴을 öğren고 Nx 프로젝트 관리를 최적화하여 개발 효율성을 향상시키세요. Nx 아키텍처, 프로젝트 경계, CI 최적화 등","es":"Aprende a configurar y optimizar tu monorepo con nx-workspace-patterns. Mejora la productividad y la colaboración en tu equipo de desarrollo.","fr":"Découvrez comment configurer et optimiser votre monorepo avec nx-workspace-patterns. Améliorez la productivité et la collaboration au sein de votre équipe de...","de":"Erfahren Sie, wie Sie Ihr Monorepo mit nx-workspace-patterns konfigurieren und optimieren können. Steigern Sie die Produktivität und Zusammenarbeit in Ihrem ...","pt":"Aprenda a configurar e otimizar o seu monorepo com os padrões de workspace do Nx. Descubra como melhorar a produtividade e a escalabilidade.","ru":"Узнайте, как настроить и оптимизировать ваш монорепозиторий с помощью шаблонов рабочего пространства Nx. ИИ Агенты для разработчиков.","ar":"تعرف على كيفية ضبط وتحسين مستودعك الموحد باستخدام أنماط مساحة العمل Nx. تحسين الإنتاجية وال قابلية للتوسع"},"definition":{"en":"nx-workspace-patterns is a set of production patterns for managing Nx monorepos, covering setup, configuration, and optimization of workspace architecture.","zh":"Nx 工作空间模式是一种用于优化 Nx 项目管理的生产模式，包括 Nx 架构、项目边界、CI 优化等","ja":"Nx ワークスペースパターンは、Nx プロジェクト管理を最適化するための生産パターンであり、Nx アーキテクチャ、プロジェクト境界、CI 最適化などを含みます","ko":"Nx 작업공간 패턴은 Nx 프로젝트 관리를 최적화하기 위한 생산 패턴으로, Nx 아키텍처, 프로젝트 경계, CI 최적화 등을 포함합니다","es":"nx-workspace-patterns es un conjunto de patrones de producción para la administración de monorepo con Nx","fr":"nx-workspace-patterns est un ensemble de modèles de production pour la gestion de monorepo avec Nx","de":"nx-workspace-patterns ist eine Sammlung von Produktionsmustern für die Verwaltung von Monorepo mit Nx","pt":"O Nx Workspace Patterns é um conjunto de padrões para gerenciar monorepos com o Nx, incluindo configuração de projetos e otimização de CI.","ru":"Шаблоны рабочего пространства Nx - это набор шаблонов для управления монорепозиториями с помощью Nx, включая настройку проектов и оптимизацию CI.","ar":"أنماط مساحة العمل Nx هو مجموعة من الأنماط لتدارة مستودعات الموحدة مع Nx, بما في ذلك ضبط المشاريع وتحسين CI"},"features":{"en":["Configures project boundaries using Nx workspace architecture","Optimizes CI/CD pipelines with affected commands","Implements remote caching for improved performance","Manages dependencies between projects in the Nx workspace","Supports migration to Nx for existing projects","Organizes code into deployable applications and shared libraries"],"zh":["Nx 架构设置","项目边界配置","CI 优化","依赖管理","远程缓存实现","Nx 迁移支持"],"ja":["Nx アーキテクチャ設定","プロジェクト境界構成","CI 最適化","依存関係管理","リモートキャッシュ実装","Nx 移行サポート"],"ko":["Nx 아키텍처 설정","프로젝트 경계 구성","CI 최적화","의존성 관리","원격 캐시 구현","Nx 이주 지원"],"es":["Configuración de nuevos espacios de trabajo Nx","Optimización de la integración continua con comandos afectados","Implementación de caché remota","Gestión de dependencias entre proyectos","Migración a Nx","Arquitectura de workspace de Nx"],"fr":["Configuration de nouveaux espaces de travail Nx","Optimisation de l''intégration continue avec des commandes affectées","Implémentation de cache distant","Gestion des dépendances entre les projets","Migration vers Nx","Architecture de l''espace de travail Nx"],"de":["Konfiguration neuer Nx-Arbeitsbereiche","Optimierung der kontinuierlichen Integration mit betroffenen Befehlen","Implementierung von Remote-Caching","Verwaltung von Abhängigkeiten zwischen Projekten","Migration zu Nx","Nx-Arbeitsbereichsarchitektur"],"pt":["Configuração de projetos e boundaries","Otimização de CI com comandos affected","Implementação de cache remoto","Gerenciamento de dependências entre projetos","Migração para o Nx","Arquitetura do Nx"],"ru":["Настройка проектов и границ","Оптимизация CI с помощью команд affected","Реализация удаленного кэширования","Управление зависимостями между проектами","Миграция на Nx","Архитектура Nx"],"ar":["ضبط المشاريع والحدود","تحسين CI مع أوامر المتأثر","تنفيذ ذاكرة التخزين المؤقت عن بعد","إدارة الاعتماديات بين المشاريع","هجرة إلى Nx","بنية Nx"]},"keywords":{"en":["nx-workspace-patterns setup guide","nx monorepo management best practices","how to use nx-workspace-patterns","nx-workspace-patterns vs lerna","nx-workspace-patterns install","nx workspace architecture tutorial","nx affected commands example","nx remote caching setup","nx workspace patterns documentation"],"zh":["Nx 工作空间模式","Nx 项目管理","CI 优化","依赖管理","远程缓存","Nx 迁移","Nx 架构","项目边界","开发效率"],"ja":["Nx ワークスペースパターン","Nx プロジェクト管理","CI 最適化","依存関係管理","リモートキャッシュ","Nx 移行","Nx アーキテクチャ","プロジェクト境界","開発効率"],"ko":["Nx 작업공간 패턴","Nx 프로젝트 관리","CI 최적화","의존성 관리","원격 캐시","Nx 이주","Nx 아키텍처","프로젝트 경계","개발 효율성"],"es":["nx-workspace-patterns","administración de monorepo","Nx","configuración de espacios de trabajo","optimización de integración continua","caché remota","gestión de dependencias","migración a Nx"],"fr":["nx-workspace-patterns","gestion de monorepo","Nx","configuration d''espaces de travail","optimisation de l''intégration continue","cache distant","gestion des dépendances","migration vers Nx"],"de":["nx-workspace-patterns","Monorepo-Verwaltung","Nx","Konfiguration von Arbeitsbereichen","Optimierung der kontinuierlichen Integration","Remote-Caching","Verwaltung von Abhängigkeiten","Migration zu Nx"],"pt":["nx workspace patterns","monorepo management","configuração de projetos","otimização de ci","cache remoto","gerenciamento de dependências","migração para o nx","arquitetura do nx","desenvolvimento de software"],"ru":["nx workspace patterns","управление монорепозиториями","настройка проектов","оптимизация ci","удаленное кэширование","управление зависимостями","миграция на nx","архитектура nx","разработка программного обеспечения","ИИ Агенты"],"ar":["أنماط مساحة العمل nx","إدارة مستودعات الموحدة","ضبط المشاريع","تحسين ci","ذاكرة التخزين المؤقت عن بعد","إدارة الاعتماديات","هجرة إلى nx","بنية nx","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"nguyendinhquocx","repo":"code-ai","repoPath":"nguyendinhquocx/code-ai","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.635Z","topics":[],"category":"community","skillMd":{"name":"nx-workspace-patterns","description":"Configure and optimize Nx monorepo workspaces. Use when setting up Nx, configuring project boundaries, optimizing build caching, or implementing affected commands.","bodyPreview":"# Nx Workspace Patterns\n\nProduction patterns for Nx monorepo management.\n\n## When to Use This Skill\n\n- Setting up new Nx workspaces\n- Configuring project boundaries\n- Optimizing CI with affected commands\n- Implementing remote caching\n- Managing dependencies between projects\n- Migrating to Nx\n\n## Core Concepts\n\n### 1. Nx Architecture\n\n```\nworkspace/\n├── apps/              # Deployable applications\n│   ├── web/\n│   └── api/\n├── libs/              # Shared libraries\n│   ├── shared/\n│   │   ├── ui/","body":"# Nx Workspace Patterns\n\nProduction patterns for Nx monorepo management.\n\n## When to Use This Skill\n\n- Setting up new Nx workspaces\n- Configuring project boundaries\n- Optimizing CI with affected commands\n- Implementing remote caching\n- Managing dependencies between projects\n- Migrating to Nx\n\n## Core Concepts\n\n### 1. Nx Architecture\n\n```\nworkspace/\n├── apps/              # Deployable applications\n│   ├── web/\n│   └── api/\n├── libs/              # Shared libraries\n│   ├── shared/\n│   │   ├── ui/\n│   │   └── utils/\n│   └── feature/\n│       ├── auth/\n│       └── dashboard/\n├── tools/             # Custom executors/generators\n├── nx.json            # Nx configuration\n└── workspace.json     # Project configuration\n```\n\n### 2. Library Types\n\n| Type | Purpose | Example |\n|------|---------|---------|\n| **feature** | Smart components, business logic | `feature-auth` |\n| **ui** | Presentational components | `ui-buttons` |\n| **data-access** | API calls, state management | `data-access-users` |\n| **util** | Pure functions, helpers | `util-formatting` |\n| **shell** | App bootstrapping | `shell-web` |\n\n## Templates\n\n### Template 1: nx.json Configuration\n\n```json\n{\n  \"$schema\": \"./node_modules/nx/schemas/nx-schema.json\",\n  \"npmScope\": \"myorg\",\n  \"affected\": {\n    \"defaultBase\": \"main\"\n  },\n  \"tasksRunnerOptions\": {\n    \"default\": {\n      \"runner\": \"nx/tasks-runners/default\",\n      \"options\": {\n        \"cacheableOperations\": [\n          \"build\",\n          \"lint\",\n          \"test\",\n          \"e2e\",\n          \"build-storybook\"\n        ],\n        \"parallel\": 3\n      }\n    }\n  },\n  \"targetDefaults\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"inputs\": [\"production\", \"^production\"],\n      \"cache\": true\n    },\n    \"test\": {\n      \"inputs\": [\"default\", \"^production\", \"{workspaceRoot}/jest.preset.js\"],\n      \"cache\": true\n    },\n    \"lint\": {\n      \"inputs\": [\"default\", \"{workspaceRoot}/.eslintrc.json\"],\n      \"cache\": true\n    },\n    \"e2e\": {\n      \"inputs\": [\"default\", \"^production\"],\n      \"cache\": true\n    }\n  },\n  \"namedInputs\": {\n    \"default\": [\"{projectRoot}/**/*\", \"sharedGlobals\"],\n    \"production\": [\n      \"default\",\n      \"!{projectRoot}/**/?(*.)+(spec|test).[jt]s?(x)?(.snap)\",\n      \"!{projectRoot}/tsconfig.spec.json\",\n      \"!{projectRoot}/jest.config.[jt]s\",\n      \"!{projectRoot}/.eslintrc.json\"\n    ],\n    \"sharedGlobals\": [\n      \"{workspaceRoot}/babel.config.json\",\n      \"{workspaceRoot}/tsconfig.base.json\"\n    ]\n  },\n  \"generators\": {\n    \"@nx/react\": {\n      \"application\": {\n        \"style\": \"css\",\n        \"linter\": \"eslint\",\n        \"bundler\": \"webpack\"\n      },\n      \"library\": {\n        \"style\": \"css\",\n        \"linter\": \"eslint\"\n      },\n      \"component\": {\n        \"style\": \"css\"\n      }\n    }\n  }\n}\n```\n\n### Template 2: Project Configuration\n\n```json\n// apps/web/project.json\n{\n  \"name\": \"web\",\n  \"$schema\": \"../../node_modules/nx/schemas/project-schema.json\",\n  \"sourceRoot\": \"apps/web/src\",\n  \"projectType\": \"application\",\n  \"tags\": [\"type:app\", \"scope:web\"],\n  \"targets\": {\n    \"build\": {\n      \"executor\": \"@nx/webpack:webpack\",\n      \"outputs\": [\"{options.outputPath}\"],\n      \"defaultConfiguration\": \"production\",\n      \"options\": {\n        \"compiler\": \"babel\",\n        \"outputPath\": \"dist/apps/web\",\n        \"index\": \"apps/web/src/index.html\",\n        \"main\": \"apps/web/src/main.tsx\",\n        \"tsConfig\": \"apps/web/tsconfig.app.json\",\n        \"assets\": [\"apps/web/src/assets\"],\n        \"styles\": [\"apps/web/src/styles.css\"]\n      },\n      \"configurations\": {\n        \"development\": {\n          \"extractLicenses\": false,\n          \"optimization\": false,\n          \"sourceMap\": true\n        },\n        \"production\": {\n          \"optimization\": true,\n          \"outputHashing\": \"all\",\n          \"sourceMap\": false,\n          \"extractLicenses\": true\n        }\n      }\n    },\n    \"serve\": {\n      \"executor\": \"@nx/webpack:dev-server\",\n      \"defaultConfiguration\": \"development\",\n      \"options\": {\n        \"buildTarget\": \"web:build\"\n      },\n      \"configurations\": {\n        \"development\": {\n          \"buildTarget\": \"web:build:development\"\n        },\n        \"production\": {\n          \"buildTarget\": \"web:build:production\"\n        }\n      }\n    },\n    \"test\": {\n      \"executor\": \"@nx/jest:jest\",\n      \"outputs\": [\"{workspaceRoot}/coverage/{projectRoot}\"],\n      \"options\": {\n        \"jestConfig\": \"apps/web/jest.config.ts\",\n        \"passWithNoTests\": true\n      }\n    },\n    \"lint\": {\n      \"executor\": \"@nx/eslint:lint\",\n      \"outputs\": [\"{options.outputFile}\"],\n      \"options\": {\n        \"lintFilePatterns\": [\"apps/web/**/*.{ts,tsx,js,jsx}\"]\n      }\n    }\n  }\n}\n```\n\n### Template 3: Module Boundary Rules\n\n```json\n// .eslintrc.json\n{\n  \"root\": true,\n  \"ignorePatterns\": [\"**/*\"],\n  \"plugins\": [\"@nx\"],\n  \"overrides\": [\n    {\n      \"files\": [\"*.ts\", \"*.tsx\", \"*.js\", \"*.jsx\"],\n      \"rules\": {\n        \"@nx/enforce-module-boundaries\": [\n          \"error\",\n          {\n            \"enforceBuildableLibDependency\": true,\n            \"allow\": [],\n            \"depConstraints\": [\n              {\n                \"sourceTag\": \"type:app\",\n                \"onlyDependOnLibsWithTags\": [\n                  \"type:feature\",\n                  \"type:ui\",\n                  \"type:data-access\",\n                  \"type:util\"\n                ]\n              },\n              {\n                \"sourceTag\": \"type:feature\",\n                \"onlyDependOnLibsWithTags\": [\n                  \"type:ui\",\n                  \"type:data-access\",\n                  \"type:util\"\n                ]\n              },\n              {\n                \"sourceTag\": \"type:ui\",\n                \"onlyDependOnLibsWithTags\": [\"type:ui\", \"type:util\"]\n              },\n              {\n                \"sourceTag\": \"type:data-access\",\n                \"onlyDependOnLibsWithTags\": [\"type:data-access\", \"type:util\"]\n              },\n              {\n                \"sourceTag\": \"type:util\",\n                \"onlyDependOnLibsWithTags\": [\"type:util\"]\n              },\n              {\n                \"sourceTag\": \"scope:web\",\n                \"onlyDependOnLibsWithTags\": [\"scope:web\", \"scope:shared\"]\n              },\n              {\n                \"sourceTag\": \"scope:api\",\n                \"onlyDependOnLibsWithTags\": [\"scope:api\", \"scope:shared\"]\n              },\n              {\n                \"sourceTag\": \"scope:shared\",\n                \"onlyDependOnLibsWithTags\": [\"scope:shared\"]\n              }\n            ]\n          }\n        ]\n      }\n    }\n  ]\n}\n```\n\n### Template 4: Custom Generator\n\n```typescript\n// tools/generators/feature-lib/index.ts\nimport {\n  Tree,\n  formatFiles,\n  generateFiles,\n  joinPathFragments,\n  names,\n  readProjectConfiguration,\n} from ''@nx/devkit'';\nimport { libraryGenerator } from ''@nx/react'';\n\ninterface FeatureLibraryGeneratorSchema {\n  name: string;\n  scope: string;\n  directory?: string;\n}\n\nexport default async function featureLibraryGenerator(\n  tree: Tree,\n  options: FeatureLibraryGeneratorSchema\n) {\n  const { name, scope, directory } = options;\n  const projectDirectory = directory\n    ? `${directory}/${name}`\n    : `libs/${scope}/feature-${name}`;\n\n  // Generate base library\n  await libraryGenerator(tree, {\n    name: `feature-${name}`,\n    directory: projectDirectory,\n    tags: `type:feature,scope:${scope}`,\n    style: ''css'',\n    skipTsConfig: false,\n    skipFormat: true,\n    unitTestRunner: ''jest'',\n    linter: ''eslint'',\n  });\n\n  // Add custom files\n  const projectConfig = readProjectConfiguration(tree, `${scope}-feature-${name}`);\n  const projectNames = names(name);\n\n  generateFiles(\n    tree,\n    joinPathFragments(__dirname, ''files''),\n    projectConfig.sourceRoot,\n    {\n      ...projectNames,\n      scope,\n      tmpl: '''',\n    }\n  );\n\n  await formatFiles(tree);\n}\n```\n\n### Template 5: CI Configuration with Affected\n\n```yaml\n# .github/workflows/ci.yml\nname: CI\n\non:\n  push:\n    branches: [main]\n  pull_request:\n    branches: [main]\n\nenv:\n  NX_CLOUD_ACCESS_TOKEN: ${{ secrets.NX_CLOUD_ACCESS_TOKEN }}\n\njobs:\n  main:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20\n          cache: ''npm''\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Derive SHAs for affected commands\n        uses: nrwl/nx-set-shas@v4\n\n      - name: Run affected lint\n        run: npx nx affected -t lint --parallel=3\n\n      - name: Run affected test\n        run: npx nx affected -t test --parallel=3 --configuration=ci\n\n      - name: Run affected build\n        run: npx nx affected -t build --parallel=3\n\n      - name: Run affected e2e\n        run: npx nx affected -t e2e --parallel=1\n```\n\n### Template 6: Remote Caching Setup\n\n```typescript\n// nx.json with Nx Cloud\n{\n  \"tasksRunnerOptions\": {\n    \"default\": {\n      \"runner\": \"nx-cloud\",\n      \"options\": {\n        \"cacheableOperations\": [\"build\", \"lint\", \"test\", \"e2e\"],\n        \"accessToken\": \"your-nx-cloud-token\",\n        \"parallel\": 3,\n        \"cacheDirectory\": \".nx/cache\"\n      }\n    }\n  },\n  \"nxCloudAccessToken\": \"your-nx-cloud-token\"\n}\n\n// Self-hosted cache with S3\n{\n  \"tasksRunnerOptions\": {\n    \"default\": {\n      \"runner\": \"@nx-aws-cache/nx-aws-cache\",\n      \"options\": {\n        \"cacheableOperations\": [\"build\", \"lint\", \"test\"],\n        \"awsRegion\": \"us-east-1\",\n        \"awsBucket\": \"my-nx-cache-bucket\",\n        \"awsProfile\": \"default\"\n      }\n    }\n  }\n}\n```\n\n## Common Commands\n\n```bash\n# Generate new library\nnx g @nx/react:lib feature-auth --directory=libs/web --tags=type:feature,scope:web\n\n# Run affected tests\nnx affected -t test --base=main\n\n# View dependency graph\nnx graph\n\n# Run specific project\nnx build web --configuration=production\n\n# Reset cache\nnx reset\n\n# Run migrations\nnx migrate latest\nnx migrate --run-migrations\n```\n\n## Best Practices\n\n### Do''s\n- **Use tags consistently** - Enforce with module boundaries\n- **Enable caching early** - Significant CI savings\n- **Keep libs focused** - Single responsibility\n- **Use generators** - Ensure consistency\n- **Document boundaries** - Help new developers\n\n### Don''ts\n- **Don''t create circular deps** - Graph should be acyclic\n- **Don''t skip affected** - Test only what changed\n- **Don''t ignore boundaries** - Tech debt accumulates\n- **Don''t over-granularize** - Balance lib count\n\n## Resources\n\n- [Nx Documentation](https://nx.dev/getting-started/intro)\n- [Module Boundaries](https://nx.dev/core-features/enforce-module-boundaries)\n- [Nx Cloud](https://nx.app/)\n"},"lastSynced":"2026-03-08T02:13:37.067Z","agentAnalysis":{"suitability":{"en":"Ideal for Monorepo Management Agents needing advanced Nx workspace configuration and optimization capabilities.","zh":"适用于需要高级Nx工作空间配置和优化能力的Monorepo管理代理。","ja":"Nxワークスペースの高度な構成と最適化機能を必要とするモノレポ管理エージェントに適しています。","ko":"고급 Nx 작업공간 구성 및 최적화 기능을 필요로 하는 모노레포 관리 에이전트에게 적합합니다.","es":"Ideal para agentes de gestión de monorepo que necesitan capacidades avanzadas de configuración y optimización del espacio de trabajo de Nx.","fr":"Idéal pour les agents de gestion de monorepo nécessitant des capacités de configuration et d''optimisation avancées de l''espace de travail Nx.","de":"Ideal für Monorepo-Management-Agents, die erweiterte Nx-Arbeitsbereichskonfigurations- und Optimierungsfunktionen benötigen.","pt":"Ideal para Agentes de Gerenciamento de Monorepo que necessitam de configuração avançada do espaço de trabalho Nx e capacidades de otimização.","ru":"Идеально для агентов управления монорепозиторием, которым необходимы расширенные возможности конфигурации рабочего пространства Nx и оптимизации.","ar":"مثالي لمحлати إدارة مونوريبو الذين يحتاجون إلى تكوين متقدم لمساحة عمل Nx وقدرات تحسين الأداء."},"recommendation":{"en":"Empowers agents to efficiently set up new Nx workspaces, configure project boundaries, and optimize CI/CD pipelines using affected commands and remote caching, while managing dependencies between projects and migrating to Nx.","zh":"赋予代理高效地设置新的Nx工作空间、配置项目边界、使用受影响的命令和远程缓存优化CI/CD管道的能力，同时管理项目之间的依赖关系并迁移到Nx。","ja":"エージェントが新しいNxワークスペースを効率的に設定し、プロジェクトの境界を構成し、影響を受けたコマンドとリモートキャッシングを使用してCI/CDパイプラインを最適化する能力を与え、プロジェクト間の依存関係を管理し、Nxに移行します。","ko":"에이전트가 새로운 Nx 작업공간을 효율적으로 설정하고 프로젝트 경계를 구성하며 影響を受けた 명령어와 원격 캐싱을 사용하여 CI/CD 파이프라인을 최적화하는 기능을 부여하며, 프로젝트 간의 의존 관계를 관리하고 Nx로 마이그레이션합니다.","es":"Permite a los agentes configurar de manera eficiente nuevos espacios de trabajo de Nx, configurar límites de proyecto y optimizar tuberías de CI/CD utilizando comandos afectados y caché remota, mientras gestiona dependencias entre proyectos y migra a Nx.","fr":"Permet aux agents de configurer efficacement de nouveaux espaces de travail Nx, de configurer les limites de projet et d''optimiser les pipelines de CI/CD en utilisant des commandes affectées et un cache distant, tout en gérant les dépendances entre les projets et en migrant vers Nx.","de":"Ermächtigt Agenten, neue Nx-Arbeitsbereiche effizient einzurichten, Projektgrenzen zu konfigurieren und CI/CD-Pipelines mit betroffenen Befehlen und Remote-Caching zu optimieren, während sie Abhängigkeiten zwischen Projekten verwalten und zu Nx migrieren.","pt":"Habilita os agentes a configurar novos espaços de trabalho Nx de forma eficiente, configurar limites de projeto e otimizar pipelines de CI/CD usando comandos afetados e cache remoto, enquanto gerencia dependências entre projetos e migra para o Nx.","ru":"Наделяет агентов возможностью эффективно настраивать новые рабочие пространства Nx, конфигурировать границы проектов и оптимизировать конвейеры CI/CD с помощью затронутых команд и удаленного кэширования, а также управлять зависимостями между проектами и мигрировать в Nx.","ar":"يمنح الوكلاء القدرة على ضبط مساحات العمل الجديدة Nx بفعالية، وتكوين حدود المشروع، وتحسين خطوط أنابيب CI/CD باستخدام أوامر متأثرة وتخزين مؤقت عن بعد، وفي الوقت نفسه إدارة التبعيات بين المشاريع والهجرة إلى Nx."},"useCases":{"en":["Configuring project boundaries for efficient monorepo management","Optimizing CI/CD pipelines with affected commands and remote caching","Migrating existing projects to Nx for improved scalability and maintainability"],"zh":["为高效的モノレポ管理配置项目边界","使用受影响的命令和远程缓存优化CI/CD管道","将现有的项目迁移到Nx以提高可扩展性和可维护性"],"ja":["効率的なモノレポ管理のためにプロジェクトの境界を構成する","影響を受けたコマンドとリモートキャッシングを使用してCI/CDパイプラインを最適化する","既存のプロジェクトをNxに移行して拡張性と保守性を向上させる"],"ko":["효율적인 모노레포 관리를 위한 프로젝트 경계 구성","영향받은 명령어와 원격 캐싱을 사용하여 CI/CD 파이프라인 최적화","기존 프로젝트를 Nx로 마이그레이션하여 확장성과 유지보수성을 향상"],"es":["Configuración de límites de proyecto para una gestión de monorepo eficiente","Optimización de tuberías de CI/CD con comandos afectados y caché remota","Migración de proyectos existentes a Nx para mejorar la escalabilidad y la mantenibilidad"],"fr":["Configuration des limites de projet pour une gestion de monorepo efficace","Optimisation des pipelines de CI/CD avec des commandes affectées et un cache distant","Migration de projets existants vers Nx pour améliorer la scalabilité et la maintenabilité"],"de":["Konfiguration von Projektgrenzen für eine effiziente Monorepo-Verwaltung","Optimierung von CI/CD-Pipelines mit betroffenen Befehlen und Remote-Caching","Migration von bestehenden Projekten zu Nx für verbesserte Skalierbarkeit und Wartbarkeit"],"pt":["Configurando limites de projeto para gerenciamento eficiente de monorepo","Otimizando pipelines de CI/CD com comandos afetados e cache remoto","Migrando projetos existentes para o Nx para melhorar a escalabilidade e a manutenção"],"ru":["Настройка границ проектов для эффективного управления монорепозиторием","Оптимизация конвейеров CI/CD с помощью затронутых команд и удаленного кэширования","Миграция существующих проектов в Nx для улучшения масштабируемости и поддерживаемости"],"ar":["تكوين حدود المشروع لتحقيق إدارة مونوريبو فعالة","تحسين خطوط أنابيب CI/CD باستخدام أوامر متأثرة وتخزين مؤقت عن بعد","هجرة المشاريع الحالية إلى Nx لتحسين القابلية للتوسع والصيانة"]},"limitations":{"en":["Requires Nx monorepo setup","Limited to Nx ecosystem and compatible tools"],"zh":["需要Nxモノレポ设置","仅限于Nx生态系统和兼容工具"],"ja":["Nxモノレポ設定が必要","Nxエコシステムと互換性のあるツールに限定"],"ko":["Nx 모노레포 설정이 필요","Nx 생态계와 호환되는 툴만 해당"],"es":["Requiere configuración de monorepo de Nx","Limitado al ecosistema de Nx y herramientas compatibles"],"fr":["Nécessite une configuration de monorepo Nx","Limité à l''écosystème Nx et aux outils compatibles"],"de":["Benötigt Nx-Monorepo-Setup","Begrenzt auf Nx-Ökosystem und kompatible Tools"],"pt":["Requer configuração de monorepo do Nx","Limitado ao ecossistema Nx e ferramentas compatíveis"],"ru":["Требуется настройка монорепозитория Nx","Ограничен экосистемой Nx и совместимыми инструментами"],"ar":["يتطلب إعداد مونوريبو Nx","محدود بنظام البيئة Nx والأدوات المتوافقة"]},"version":4},"contentHash":"6286fae01303804282fedd8b858cd8312e0637126abe6b8f3d01eab19e9777a0","qualityScore":60}');
