INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nguyendinhquocx/code-ai/nx-workspace-patterns', 'nx-workspace-patterns', 'nguyendinhquocx', 'code-ai', 'community', 'nx-workspace-patterns nguyendinhquocx code-ai community The nx-workspace-patterns skill provides production patterns for Nx monorepo management, benefiting developers setting up new workspaces, configuring project boundaries, and optimizing CI/CD pipelines. Nx 工作空间模式提供了一种优化 Nx 项目管理的方法，通过设置项目边界、CI 优化和依赖管理来提高开发效率 Nx ワークスペースパターンは、プロジェクト境界、CI 最適化、依存関係管理を設定することで、Nx プロジェクト管理を最適化する方法を提供します Nx 작업공간 패턴은 프로젝트 경계, CI 최적화, 의존성 관리를 설정하여 Nx 프로젝트 관리를 최적화하는 방법을 제공합니다 nx-workspace-patterns es un conjunto de patrones de producción para la administración de monorepo con Nx. Ayuda a configurar y optimizar tu entorno de desarrollo. nx-workspace-patterns est un ensemble de modèles de production pour la gestion de monorepo avec Nx. Il aide à configurer et optimiser votre environnement de développement. nx-workspace-patterns ist eine Sammlung von Produktionsmustern für die Verwaltung von Monorepo mit Nx. Es hilft bei der Konfiguration und Optimierung Ihrer Entwicklungsumgebung. O Nx Workspace Patterns é um conjunto de padrões para gerenciar monorepos com o Nx. Aprenda a configurar e otimizar seu workspace. Шаблоны рабочего пространства Nx - это набор шаблонов для управления монорепозиториями с помощью Nx. Узнайте, как настроить и оптимизировать ваше рабочее пространство. أنماط مساحة العمل Nx هو مجموعة من الأنماط لتدارة مستودعات الموحدة مع Nx. تعرف على كيفية ضبط وتحسين مساحة العمل الخاصة بك nx-workspace-patterns setup guide nx monorepo management best practices how to use nx-workspace-patterns nx-workspace-patterns vs lerna nx-workspace-patterns install nx workspace architecture tutorial nx affected commands example nx remote caching setup nx workspace patterns documentation Nx 工作空间模式 Nx 项目管理 CI 优化 依赖管理 远程缓存 Nx 迁移 Nx 架构 项目边界 开发效率 Configures project boundaries using Nx workspace architecture Optimizes CI/CD pipelines with affected commands Implements remote caching for improved performance Manages dependencies between projects in the Nx workspace Supports migration to Nx for existing projects Organizes code into deployable applications and shared libraries nx-workspace-patterns is a set of production patterns for managing Nx monorepos, covering setup, configuration, and optimization of workspace architecture.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('overcut-ai/overcut-playbooks/Template Variables Reference', 'community', 'overcut-ai', 'overcut-playbooks', 'overcut-ai/overcut-playbooks', 'Template Variables Reference', 0, 0, 60, '2026-03-08T01:57:15.635Z', '2026-03-08T02:13:37.499Z', 'efda58bc558050fc659840838de41a3f597981451b1bc5b3f3152c498c71fe90', '{"id":"overcut-ai/overcut-playbooks/Template Variables Reference","name":"Template Variables Reference","description":{"en":"Template Variables Reference utilizes Handlebars to resolve templates in step params fields, benefiting developers by streamlining runtime execution. It supports infrastructure steps like git.clone and repo.identify.","zh":"Overcut使用Handlebars作为模板引擎，允许在步骤参数中使用模板变量，实现动态输出","ja":"AIエージェントのテンプレート変数リファレンスは、Handlebarsを使用してテンプレートエンジンを提供し、動的な出力を実現します","ko":"Overcut의 템플릿 변수 참조는 Handlebars 템플릿 엔진을 사용하여 동적 출력을 제공합니다","es":"Overcut utiliza Handlebars como motor de plantillas. Las plantillas se resuelven en tiempo de ejecución para steps como git.clone y repo.identify.","fr":"Overcut utilise Handlebars comme moteur de modèles. Les modèles sont résolus à l''exécution pour les étapes comme git.clone et repo.identify","de":"Overcut verwendet Handlebars als Template-Engine. Vorlagen werden zur Laufzeit für Schritte wie git.clone und repo.identify aufgelöst","pt":"O Overcut usa Handlebars como mecanismo de template. As variáveis de modelo são resolvidas em tempo de execução antes de cada etapa ser executada","ru":"Overcut использует Handlebars в качестве механизма шаблонов. Шаблонные переменные разрешаются во время выполнения перед выполнением каждой стадии","ar":"يستخدم Overcut Handlebars كآلية نمطية. يتم حل متغيرات القالب في وقت التشغيل قبل تنفيذ كل مرحلة"},"seo":{"title":{"en":"Template Variables Reference: Handlebars Setup Guide | AI...","zh":"模板变量参考指南 - Handlebars 设置","ja":"テンプレート変数リファレンスガイド - 