INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('overcut-ai/overcut-playbooks/Template Variables Reference', 'Template Variables Reference', 'overcut-ai', 'overcut-playbooks', 'community', 'Template Variables Reference overcut-ai overcut-playbooks community Template Variables Reference utilizes Handlebars to resolve templates in step params fields, benefiting developers by streamlining runtime execution. It supports infrastructure steps like git.clone and repo.identify. Overcut使用Handlebars作为模板引擎，允许在步骤参数中使用模板变量，实现动态输出 AIエージェントのテンプレート変数リファレンスは、Handlebarsを使用してテンプレートエンジンを提供し、動的な出力を実現します Overcut의 템플릿 변수 참조는 Handlebars 템플릿 엔진을 사용하여 동적 출력을 제공합니다 Overcut utiliza Handlebars como motor de plantillas. Las plantillas se resuelven en tiempo de ejecución para steps como git.clone y repo.identify. Overcut utilise Handlebars comme moteur de modèles. Les modèles sont résolus à l''exécution pour les étapes comme git.clone et repo.identify Overcut verwendet Handlebars als Template-Engine. Vorlagen werden zur Laufzeit für Schritte wie git.clone und repo.identify aufgelöst O Overcut usa Handlebars como mecanismo de template. As variáveis de modelo são resolvidas em tempo de execução antes de cada etapa ser executada Overcut использует Handlebars в качестве механизма шаблонов. Шаблонные переменные разрешаются во время выполнения перед выполнением каждой стадии يستخدم Overcut Handlebars كآلية نمطية. يتم حل متغيرات القالب في وقت التشغيل قبل تنفيذ كل مرحلة how to use Template Variables Reference what is Template Variables Reference Template Variables Reference Handlebars setup Template Variables Reference alternative Template Variables Reference vs other template engines Template Variables Reference install guide Handlebars template engine tutorial Handlebars模板引擎 Overcut模板变量 AI工具模板变量 模板变量参考指南 Handlebars设置 输出语法 基础结构步骤 Utilizes Handlebars as its template engine Resolves templates in step params fields at runtime Supports infrastructure steps like git.clone and repo.identify Produces structured output for reference Allows referencing entire output object using {{outputs.step-id}} syntax Template Variables Reference is a skill that utilizes Handlebars as its template engine to resolve templates at runtime before each step executes.');
